<?php

declare(strict_types=1);

namespace MathPHP\Solver;

use MathPHP\Ast\BinaryOperationNode;
use MathPHP\Ast\BinaryOperator;
use MathPHP\Ast\ConstantNode;
use MathPHP\Ast\FactorialNode;
use MathPHP\Ast\FunctionCallNode;
use MathPHP\Ast\GroupingNode;
use MathPHP\Ast\Node;
use MathPHP\Ast\NumberNode;
use MathPHP\Ast\RationalLiteral;
use MathPHP\Ast\UnaryOperationNode;
use MathPHP\Ast\UnaryOperator;
use MathPHP\Ast\VariableNode;
use MathPHP\Configuration\EvaluationOptions;
use MathPHP\Evaluator\Environment;
use MathPHP\Exception\LexicalException;
use MathPHP\Exception\ParseException;
use MathPHP\Function\SpecialFunctions;
use MathPHP\Parser\Lexer;
use MathPHP\Parser\Parser;
use MathPHP\Source\SourceSpan;

/**
 * @phpstan-type AffineRationalPowerTransform array{
 *   denominator: int,
 *   slope: array{string, string},
 *   intercept: array{string, string}
 * }
 * @phpstan-type RationalMatrix3 array{
 *   array{array{string, string}, array{string, string}, array{string, string}},
 *   array{array{string, string}, array{string, string}, array{string, string}},
 *   array{array{string, string}, array{string, string}, array{string, string}}
 * }
 * @phpstan-type RationalMatrix4 array{
 *   array{array{string, string}, array{string, string}, array{string, string}, array{string, string}},
 *   array{array{string, string}, array{string, string}, array{string, string}, array{string, string}},
 *   array{array{string, string}, array{string, string}, array{string, string}, array{string, string}},
 *   array{array{string, string}, array{string, string}, array{string, string}, array{string, string}}
 * }
 * @phpstan-type RationalMatrix list<list<array{string, string}>>
 */
final class PolynomialRootCountingSolver
{
    private const MAX_EXACT_ROOT_DEGREE = 1024;

    private const MAX_SPECIAL_ZERO_LEVELS = 65_536;

    private const MAX_RATIONAL_RANGE_SUBDIVISION_DEPTH = 16;

    /** @var array{key: string, options: EvaluationOptions, roots: list<RationalRootInterval>, width: array{string, string}, maxDepth: int}|null */
    private ?array $countedIsolationCache = null;

    /** @var array<string, list<array{string, string, string, string}>|null> */
    private static array $polynomialCriticalPointCache = [];

    private static ?ExactRationalInterval $polynomialTrigPiEnclosure = null;

    /** @var array<int, ExactRationalInterval> */
    private static array $piEnclosures = [];

    private static ?ExactRationalInterval $eEnclosure = null;

    private static ?ExactRationalInterval $phiEnclosure = null;

    /** @var array{int, int}|null */
    private static ?array $cosineSelfRootSeedSigns = null;

    /** @var array<string, array{int, int}> */
    private static array $acotSelfRootSeedSigns = [];

    /** @var array{int, int}|null */
    private static ?array $asecSelfRootSeedSigns = null;

    /** @var array{int, int}|null */
    private static ?array $asechSelfRootSeedSigns = null;

    /** @var array<string, array{int, int}> */
    private static array $erfcSelfRootSeedSigns = [];

    /** @var array{int, int}|null */
    private static ?array $erfSelfRootSeedSigns = null;

    /** @var array<string, array{int, int}> */
    private static array $reciprocalHyperbolicSelfRootSeedSigns = [];

    /** @var array<string, ExactRationalInterval|null> */
    private static array $inverseErrorFunctionLevelCache = [];

    /** @var array<string, list<ExactRationalInterval>|null> */
    private static array $inverseDawsonLevelCache = [];

    /**
     * Isolate every distinct real root of an exact rational polynomial or
     * rational-function equation, excluding roots where the denominator vanishes.
     *
     * @param array<string, int|float> $parameters
     * @return list<RationalRootInterval>|null
     */
    public function isolateAllReal(
        string $equation,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        SolverOptions $solverOptions,
        int $maxDepth,
        string $maximumWidth,
    ): ?array {
        if ($maxDepth < 1 || $maxDepth > 4096) {
            throw new \InvalidArgumentException('maxDepth must be between 1 and 4096 inclusive.');
        }
        $width = $this->rationalBound($maximumWidth, $evaluationOptions);
        if ($width === null || $width[0] === '0' || str_starts_with($width[0], '-')) {
            return null;
        }
        if (
            preg_match('/\A[A-Za-z_][A-Za-z0-9_]*\z/D', $variable) !== 1
            || in_array($variable, ['pi', 'e', 'tau', 'phi', 'eulerGamma', 'catalan', 'apery'], true)
            || array_key_exists($variable, $parameters)
        ) {
            throw new \InvalidArgumentException('The root-count variable must be a non-reserved identifier.');
        }
        if (strlen($equation) > $evaluationOptions->limits->maxExpressionLength) {
            $position = $evaluationOptions->limits->maxExpressionLength;
            throw new LexicalException(
                'Equation exceeds the configured byte limit',
                'limit.expression_length',
                new SourceSpan($position, $position + 1),
            );
        }
        if (substr_count($equation, '=') > 1) {
            $coefficients = $this->chainedRationalPolynomialCoefficients(
                $equation,
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions,
            );
            if ($coefficients === null) {
                return null;
            }
            if ($coefficients === ['0']) {
                throw new InfiniteSolutionSetException('The equation has infinitely many real solutions.');
            }
            $roots = (new ExactPolynomialRootCounter())->isolateAllRealRoots($coefficients, $maxDepth, $width);
            if ($roots === null) {
                return null;
            }

            return array_map(
                static fn (array $root): RationalRootInterval => new RationalRootInterval(
                    $root[0],
                    $root[1],
                    $root[2],
                    $root[3],
                    $root[0] === $root[2] && $root[1] === $root[3],
                ),
                $roots,
            );
        }
        if (substr_count($equation, '=') !== 1) {
            throw new \InvalidArgumentException('A root-isolation equation must contain exactly one equals sign.');
        }
        new Environment($parameters, $evaluationOptions->functions);
        [$leftSource, $rightSource] = explode('=', $equation, 2);
        $left = (new Parser(
            (new Lexer($leftSource, $evaluationOptions->limits, true))->tokenize(),
            $evaluationOptions->limits,
            $evaluationOptions->functions,
        ))->parse();
        $right = (new Parser(
            (new Lexer($rightSource, $evaluationOptions->limits, true))->tokenize(),
            $evaluationOptions->limits,
            $evaluationOptions->functions,
        ))->parse();
        if ($this->containsOversizedIntegerLiteral($left) || $this->containsOversizedIntegerLiteral($right)) {
            return null;
        }
        if (
            $this->exceedsConstantExponentLimit($left, $variable, $parameters, $evaluationOptions)
            || $this->exceedsConstantExponentLimit($right, $variable, $parameters, $evaluationOptions)
        ) {
            return null;
        }
        if ($this->powerIdentityHasInterior($left, $right, $variable, $parameters, $evaluationOptions)) {
            throw new InfiniteSolutionSetException('The equation has infinitely many real solutions.');
        }
        if ($this->exponentialTargetExceedsExponentLimit($left, $right, $variable, $parameters, $evaluationOptions)) {
            return [];
        }
        [$left, $right] = $this->reduceExactRationalExponentLevel(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
        );
        $reciprocalAcoshBoundary = $this->reciprocalAcoshAsechBoundaryPolynomial(
            $left,
            $right,
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
        );
        if ($reciprocalAcoshBoundary !== null) {
            [$boundaryPolynomial, $positivePolynomial, $domainDenominator] = $reciprocalAcoshBoundary;
            $hasPositiveRegion = $this->polynomialHasPositiveValueOnRealLine($positivePolynomial);
            if ($hasPositiveRegion === null) {
                return null;
            }
            if ($boundaryPolynomial === ['0'] || $hasPositiveRegion) {
                throw new InfiniteSolutionSetException('The equation has infinitely many real solutions.');
            }
            $counter = new ExactPolynomialRootCounter();
            $boundaryRoots = $counter->isolateAllRealRoots(
                $boundaryPolynomial,
                $maxDepth,
                $width,
            );
            if ($boundaryRoots === null) {
                return null;
            }
            $boundaryRoots = $this->excludeCommonDenominatorRoots(
                $counter,
                $boundaryPolynomial,
                $domainDenominator,
                $boundaryRoots,
            );

            return $boundaryRoots === null
                ? null
                : $this->rationalRootIntervalsFromExactPolynomial($boundaryRoots);
        }
        [$left, $right] = $this->reduceRationalHyperbolicEquality(
            $left,
            $right,
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        );
        if (!$this->containsVariable($left, $variable) && !$this->containsVariable($right, $variable)) {
            throw new \InvalidArgumentException('The equation does not contain the root-isolation variable.');
        }
        $constantSquareRootSumRoots = $this->constantSquareRootSumRoots(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            $maxDepth,
            $width,
            null,
        );
        if ($constantSquareRootSumRoots !== null) {
            return $constantSquareRootSumRoots;
        }
        $additiveTerms = [];
        $this->appendAdditiveEquationTerms($left, 1, $additiveTerms);
        $this->appendAdditiveEquationTerms($right, -1, $additiveTerms);
        $twoRadicalRoots = $this->isolateTwoAdditiveSquareRootPolynomialEquationInInterval(
            $additiveTerms,
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            null,
            null,
            $maxDepth,
            $width,
        );
        if ($twoRadicalRoots !== null) {
            return $twoRadicalRoots;
        }
        $threeRadicalRoots = $this->isolateThreeAdditiveSquareRootPolynomialEquationInInterval(
            $additiveTerms,
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            null,
            null,
            $maxDepth,
            $width,
        );
        if ($threeRadicalRoots !== null) {
            return $threeRadicalRoots;
        }
        $radicalTermCount = 0;
        foreach ($additiveTerms as [$term]) {
            if ($this->additiveSquareRootTerm($term) !== null) {
                ++$radicalTermCount;
            }
        }
        if ($radicalTermCount === 1) {
            $singleRadicalRoots = $this->isolateSingleAbsoluteOrSquareRootPolynomialEquationInInterval(
                $left,
                $right,
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions->maxPolynomialDegree,
                null,
                null,
                $maxDepth,
                $width,
            );
            if ($singleRadicalRoots !== null) {
                return $singleRadicalRoots;
            }
        }
        $affinePiRoots = $this->isolateAffinePiMultipleAllReal(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            $width,
        );
        if ($affinePiRoots !== null) {
            return $affinePiRoots;
        }
        $affineERoots = $this->isolateAffineNamedConstantAllReal(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            'e',
            $width,
        );
        if ($affineERoots !== null) {
            return $affineERoots;
        }
        $affinePhiRoots = $this->isolateAffineNamedConstantAllReal(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            'phi',
            $width,
        );
        if ($affinePhiRoots !== null) {
            return $affinePhiRoots;
        }
        if ($this->hasAffineHyperbolicSymmetricFunction($left, $right, $evaluationOptions)) {
            $affineHyperbolicCount = $this->countAffineMonotoneFunctionRoots(
                $left,
                $right,
                $variable,
                $parameters,
                $evaluationOptions,
            );
            if ($affineHyperbolicCount !== null) {
                return $this->isolateAffineHyperbolicCosineAllReal(
                    $left,
                    $right,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                    $width,
                    $maxDepth,
                    $affineHyperbolicCount,
                );
            }
        }
        $acoshAsechRoots = $this->isolateAcoshAsechFiniteRoots(
            $left,
            $right,
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            null,
            null,
            $maxDepth,
            $width,
        );
        if ($acoshAsechRoots !== null) {
            return $acoshAsechRoots;
        }
        $inverseHyperbolicMixedRoots = $this->isolateAcoshAsinhRootsInInterval(
            $left,
            $right,
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            null,
            null,
            $maxDepth,
            $width,
        );
        if ($inverseHyperbolicMixedRoots !== null) {
            return $inverseHyperbolicMixedRoots;
        }
        $atanhAsinhRoots = $this->isolateAtanhAsinhRoots(
            $left,
            $right,
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            null,
            null,
            $maxDepth,
            $width,
        );
        if ($atanhAsinhRoots !== null) {
            return $atanhAsinhRoots;
        }
        $atanhAcoshRoots = $this->isolateAtanhAcoshRoots(
            $left,
            $right,
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            null,
            null,
            $maxDepth,
            $width,
        );
        if ($atanhAcoshRoots !== null) {
            return $atanhAcoshRoots;
        }
        $positiveInverseTrigRoots = $this->isolatePositiveInverseTrigRoots(
            $left,
            $right,
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            null,
            null,
            $maxDepth,
            $width,
        );
        if ($positiveInverseTrigRoots !== null) {
            return $positiveInverseTrigRoots;
        }
        $complementaryInverseTrigRoots = $this->isolateComplementaryInverseTrigRoots(
            $left,
            $right,
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            null,
            null,
            $maxDepth,
            $width,
        );
        if ($complementaryInverseTrigRoots !== null) {
            return $complementaryInverseTrigRoots;
        }
        $atanAcotRoots = $this->isolateAtanAcotRoots(
            $left,
            $right,
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            null,
            null,
            $maxDepth,
            $width,
        );
        if ($atanAcotRoots !== null) {
            return $atanAcotRoots;
        }
        $reciprocalInverseTrigRoots = $this->isolateReciprocalInverseTrigRoots(
            $left,
            $right,
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            null,
            null,
            $maxDepth,
            $width,
        );
        if ($reciprocalInverseTrigRoots !== null) {
            return $reciprocalInverseTrigRoots;
        }
        $reciprocalAtanhAcothRoots = $this->isolateReciprocalAtanhAcothRootsInInterval(
            $left,
            $right,
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            null,
            null,
            $maxDepth,
            $width,
        );
        if ($reciprocalAtanhAcothRoots !== null) {
            return $reciprocalAtanhAcothRoots;
        }
        $constantRadicalRoots = $this->constantRadicalEquationRoots(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
            $maxDepth,
            $width,
        );
        if ($constantRadicalRoots !== null) {
            return $constantRadicalRoots;
        }
        if (
            $this->hasInfiniteRestrictedInverseIdentity(
                $left,
                $right,
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions->maxPolynomialDegree,
            )
            || $this->hasInfiniteIdenticalFunctionEquation(
                $left,
                $right,
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions->maxPolynomialDegree,
            )
        ) {
            throw new InfiniteSolutionSetException('The equation has infinitely many real solutions.');
        }
        $selfEquationRoots = $this->elementarySelfEquationRootCount(
            $left,
            $right,
            $variable,
            $evaluationOptions,
        );
        if ($selfEquationRoots !== null) {
            if ($selfEquationRoots['count'] === 0) {
                return [];
            }
            if ($selfEquationRoots['rootKind'] === 'erf-triple') {
                return $this->isolateErfFixedPointRootsInInterval(
                    ['-1', '1'],
                    ['1', '1'],
                    $maxDepth,
                    $width,
                );
            }
            if (\in_array($selfEquationRoots['rootKind'], ['coth-pair', 'csch-pair'], true)) {
                return $this->isolateReciprocalHyperbolicSelfRootsInInterval(
                    $selfEquationRoots['rootKind'] === 'coth-pair' ? 'coth' : 'csch',
                    ['-2', '1'],
                    ['2', '1'],
                    $maxDepth,
                    $width,
                );
            }
            if ($selfEquationRoots['rootSign'] === 0) {
                return [new RationalRootInterval('0', '1', '0', '1', true)];
            }
            $root = $selfEquationRoots['rootKind'] === 'lambert'
                ? $this->isolateLambertSelfRootInOpenInterval(
                    $selfEquationRoots['rootSign'],
                    $selfEquationRoots['rootSign'] > 0 ? ['0', '1'] : ['-1', '1'],
                    ['1', '1'],
                    $maxDepth,
                    $width,
                )
                : ($selfEquationRoots['rootKind'] === 'cosine'
                    ? $this->isolateCosineSelfRootInOpenInterval(
                        $selfEquationRoots['rootSign'],
                        $selfEquationRoots['rootSign'] > 0 ? ['0', '1'] : ['-1', '1'],
                        ['1', '1'],
                        $maxDepth,
                        $width,
                    )
                    : ($selfEquationRoots['rootKind'] === 'asec-reflected'
                        ? $this->isolateAsecSelfRootInOpenInterval(
                            $selfEquationRoots['rootSign'],
                            ['-3', '1'],
                            ['3', '1'],
                            $maxDepth,
                            $width,
                        )
                        : ($selfEquationRoots['rootKind'] === 'asech'
                            ? $this->isolateAsechSelfRootInOpenInterval(
                                $selfEquationRoots['rootSign'],
                                ['-1', '1'],
                                ['1', '1'],
                                $maxDepth,
                                $width,
                            )
                            : (\in_array($selfEquationRoots['rootKind'], ['erfc-positive', 'erfc-reflected'], true)
                                ? $this->isolateErfcSelfRootInOpenInterval(
                                    $selfEquationRoots['rootSign'],
                                    $selfEquationRoots['rootKind'] === 'erfc-positive' ? 1 : -1,
                                    ['-2', '1'],
                                    ['2', '1'],
                                    $maxDepth,
                                    $width,
                                )
                                : $this->isolateAcotSelfRootInOpenInterval(
                                    $selfEquationRoots['rootSign'],
                                    $selfEquationRoots['rootKind'] === 'acot' ? 1 : -1,
                                    ['-3', '1'],
                                    ['3', '1'],
                                    $maxDepth,
                                    $width,
                                )))));
            if ($root === null) {
                return null;
            }
            if ($root === false) {
                return [];
            }

            return [$this->selfEquationRootInterval($root, $selfEquationRoots['rootSign'])];
        }
        $unitExponentialPolynomial = $this->unitExponentialPolynomial(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        if ($unitExponentialPolynomial !== null) {
            if ($this->isZeroCoefficientList($unitExponentialPolynomial)) {
                throw new InfiniteSolutionSetException('The exponential equation has infinitely many roots.');
            }
            $rawRoots = (new ExactPolynomialRootCounter())->isolateAllRealRoots(
                $unitExponentialPolynomial,
                $maxDepth,
                $width,
            );
            if ($rawRoots === null) {
                return null;
            }

            return \array_map(
                static fn (array $root): RationalRootInterval => new RationalRootInterval(
                    $root[0],
                    $root[1],
                    $root[2],
                    $root[3],
                    $root[0] === $root[2] && $root[1] === $root[3],
                ),
                $rawRoots,
            );
        }
        $polynomialExponentialRoots = $this->isolatePolynomialExponentialRootsOnRealLine(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
            $maxDepth,
            $width,
        );
        if ($polynomialExponentialRoots !== null) {
            return $polynomialExponentialRoots;
        }
        $polynomialLogarithmRoots = $this->isolateMonotonePolynomialLogarithmRootsOnRealLine(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
            $maxDepth,
            $width,
        );
        if ($polynomialLogarithmRoots !== null) {
            return $polynomialLogarithmRoots;
        }
        $logarithmRoots = $this->sameMonotonePolynomialRootIntervals(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
            $maxDepth,
            $width,
        );
        if ($logarithmRoots !== null) {
            return $logarithmRoots === false ? null : $logarithmRoots;
        }
        $containsOddRootPower = false;
        if (
            $this->isOddRootPowerArithmetic($left, $containsOddRootPower)
            && $this->isOddRootPowerArithmetic($right, $containsOddRootPower)
            && $containsOddRootPower
        ) {
            $rationalPowerTransform = null;
            $rationalPowerPolynomial = $this->directEquationPolynomial(
                $left,
                $right,
                $variable,
                $parameters,
                $evaluationOptions,
                $solverOptions->maxPolynomialDegree,
                true,
                $rationalPowerTransform,
            );
            if ($rationalPowerPolynomial === false) {
                return [];
            }
            if ($rationalPowerPolynomial !== null) {
                return $this->isolateDirectPolynomial(
                    $rationalPowerPolynomial,
                    $rationalPowerTransform,
                    $maxDepth,
                    $width,
                );
            }
        }
        $unattainableHyperbolicTarget = $this->hasUnattainableHyperbolicTarget(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
        );
        if ($unattainableHyperbolicTarget) {
            return [];
        }
        $reciprocalErrorRoots = $this->reciprocalErrorFunctionRoots(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            $width,
        );
        if ($reciprocalErrorRoots !== null) {
            return $reciprocalErrorRoots;
        }
        $affineMonotoneCount = $this->countAffineMonotoneFunctionRoots(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
        );
        $quadraticExponentialCount = $this->countQuadraticExponentialRoots(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
        );
        if ($quadraticExponentialCount !== null) {
            return $this->isolateQuadraticExponentialAllReal(
                $left,
                $right,
                $variable,
                $parameters,
                $evaluationOptions,
                $width,
                $maxDepth,
                $quadraticExponentialCount,
            );
        }
        $quadraticLogarithmCount = $this->countQuadraticLogarithmRoots(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
        );
        if ($quadraticLogarithmCount !== null) {
            return $this->isolateQuadraticLogarithmAllReal(
                $left,
                $right,
                $variable,
                $parameters,
                $evaluationOptions,
                $width,
                $maxDepth,
                $quadraticLogarithmCount,
            );
        }
        $quadraticHyperbolicCount = $this->countQuadraticHyperbolicRoots(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
        );
        if ($quadraticHyperbolicCount !== null) {
            return $this->isolateQuadraticHyperbolicAllReal(
                $left,
                $right,
                $variable,
                $parameters,
                $evaluationOptions,
                $width,
                $quadraticHyperbolicCount,
            );
        }
        $monotoneHyperbolicCount = $this->countMonotonePolynomialHyperbolicRoots(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
        );
        if ($monotoneHyperbolicCount !== null) {
            return $this->isolateMonotonePolynomialHyperbolicAllReal(
                $left,
                $right,
                $variable,
                $parameters,
                $evaluationOptions,
                $width,
                $maxDepth,
            );
        }
        $criticalHyperbolicCount = $this->countPolynomialHyperbolicRootsAtCriticalLevels(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
        );
        if ($criticalHyperbolicCount !== null) {
            return $this->isolatePolynomialHyperbolicRootsAtCriticalLevelsAllReal(
                $left,
                $right,
                $variable,
                $parameters,
                $evaluationOptions,
                $width,
                $maxDepth,
                $criticalHyperbolicCount,
            );
        }
        $polynomialInverseTrigCount = $this->countPolynomialInverseTrigonometricRootsAllReal(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
        );
        if ($polynomialInverseTrigCount !== null) {
            return $this->isolatePolynomialInverseTrigonometricRootsAllReal(
                $left,
                $right,
                $variable,
                $parameters,
                $evaluationOptions,
                $width,
                $maxDepth,
                $polynomialInverseTrigCount,
            );
        }
        if (
            $affineMonotoneCount !== null
            && $this->hasAffineHyperbolicSingleBranchFunction($left, $right, $evaluationOptions)
        ) {
            return $this->isolateAffineHyperbolicSingleBranchAllReal(
                $left,
                $right,
                $variable,
                $parameters,
                $evaluationOptions,
                $width,
                $maxDepth,
                $affineMonotoneCount,
            );
        }
        if ($affineMonotoneCount === 0) {
            return [];
        }
        if (
            $affineMonotoneCount === 1
            && $this->hasFiniteAffineMonotoneIsolator($left, $right, $evaluationOptions)
        ) {
            if ($this->hasAffineArctangent($left, $right, $evaluationOptions)) {
                return $this->isolateAffineArctangentRoot(
                    $left,
                    $right,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                    $width,
                );
            }
            if ($this->hasAffineInverseSine($left, $right, $evaluationOptions)) {
                return $this->isolateAffineInverseSineRoot(
                    $left,
                    $right,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                    $width,
                );
            }
            if ($this->hasAffineInverseCosine($left, $right, $evaluationOptions)) {
                return $this->isolateAffineInverseCosineRoot(
                    $left,
                    $right,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                    $width,
                );
            }
            if ($this->hasAffineInverseCotangent($left, $right, $evaluationOptions)) {
                return $this->isolateAffineInverseCotangentRoot(
                    $left,
                    $right,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                    $width,
                );
            }
            if ($this->hasAffineReciprocalInverseTrig($left, $right, $evaluationOptions)) {
                return $this->isolateAffineReciprocalInverseTrigRoot(
                    $left,
                    $right,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                    $width,
                );
            }
            if ($this->hasAffineAtan2($left, $right, $evaluationOptions)) {
                return $this->isolateAffineAtan2Root(
                    $left,
                    $right,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                    $width,
                );
            }
            if ($this->hasAffineInverseErrorFunction($left, $right, $evaluationOptions)) {
                return $this->isolateAffineInverseErrorFunctionRoot(
                    $left,
                    $right,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                    $width,
                );
            }
            if ($this->hasAffineErrorFunction($left, $right, $evaluationOptions)) {
                return $this->isolateAffineErrorFunctionRoot(
                    $left,
                    $right,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                    $width,
                );
            }
            if ($this->hasAffineRationalBaseExponentialOrLogarithm($left, $right, $evaluationOptions)) {
                return $this->isolateAffineRationalBaseExponentialOrLogarithm(
                    $left,
                    $right,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                    $width,
                );
            }
            $bound = '1';
            for ($expansion = 0; $expansion < 4096; ++$expansion) {
                $roots = $this->isolateAffineMonotoneFunctionInInterval(
                    $left,
                    $right,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                    ['-' . $bound, '1'],
                    [$bound, '1'],
                    $width,
                    $maxDepth,
                );
                if ($roots === null) {
                    return null;
                }
                if ($roots !== []) {
                    return count($roots) === 1 ? $roots : null;
                }
                $bound .= '0';
            }
        }
        $betaRoots = $this->exactBetaZeroRoots(
            $left,
            $right,
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
        );
        if ($betaRoots !== null) {
            return $this->exactRootIntervals($betaRoots);
        }
        $periodicBetaHasRoots = $this->periodicBetaZeroHasInfiniteRoots(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        if ($periodicBetaHasRoots === true) {
            throw new InfiniteSolutionSetException('The beta equation has infinitely many real roots.');
        }
        if ($periodicBetaHasRoots === false) {
            return [];
        }
        $polynomialBetaRoots = $this->isolateRationalBetaVariableLevels(
            $left,
            $right,
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            null,
            null,
            $maxDepth,
            $width,
        );
        if ($polynomialBetaRoots !== null) {
            return $polynomialBetaRoots;
        }
        $zetaRoots = $this->exactZetaTrivialZeroRoots(
            $left,
            $right,
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            null,
            null,
        );
        if ($zetaRoots !== null) {
            return $this->exactRootIntervals($zetaRoots);
        }
        $zetaLevelPolynomials = $this->polynomialZetaAllRealLevels(
            $left,
            $right,
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
        );
        if ($zetaLevelPolynomials !== null) {
            return $this->isolateBetaLevelPolynomials($zetaLevelPolynomials, $maxDepth, $width);
        }
        $rationalZetaLevelPolynomials = $this->rationalZetaAllRealLevels(
            $left,
            $right,
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
        );
        if ($rationalZetaLevelPolynomials !== null) {
            return $this->isolateBetaLevelPolynomials($rationalZetaLevelPolynomials, $maxDepth, $width);
        }
        $betaLevelPolynomials = $this->polynomialBetaZeroLevels(
            $left,
            $right,
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
        );
        if ($betaLevelPolynomials !== null) {
            return $this->isolateBetaLevelPolynomials($betaLevelPolynomials, $maxDepth, $width);
        }
        $squareRoundingPolynomial = $this->roundingEvenPowerZeroPolynomial(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        if ($squareRoundingPolynomial !== null) {
            $exactRoots = (new ExactPolynomialRootCounter())->isolateAllRealRoots(
                $squareRoundingPolynomial,
                $maxDepth,
                $width,
            );

            return $this->rationalRootIntervalsFromExactPolynomial($exactRoots);
        }
        $quadraticRoundingRoots = $this->quadraticRoundingZeroRoots(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        if ($quadraticRoundingRoots !== null) {
            return $quadraticRoundingRoots;
        }
        $this->throwIfInfinitePolynomialZeroSet(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        $directPolynomial = $this->directEquationPolynomial(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
            true,
            $rationalPowerTransform,
        );
        if ($directPolynomial === false) {
            return [];
        }
        if ($directPolynomial !== null) {
            return $this->isolateDirectPolynomial(
                $directPolynomial,
                $rationalPowerTransform,
                $maxDepth,
                $width,
            );
        }
        $directRoot = $this->directRationalPowerRoot(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            $solverOptions->maxPolynomialDegree,
        );
        if ($directRoot === false) {
            return [];
        }
        if ($directRoot !== null) {
            return \array_map(
                static fn (array $root): RationalRootInterval => new RationalRootInterval(
                    $root[0],
                    $root[1],
                    $root[0],
                    $root[1],
                    true,
                ),
                $directRoot,
            );
        }
        $rationalForm = (new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $solverOptions->maxPolynomialDegree,
            $evaluationOptions,
        ))->rationalDifference($left, $right);
        if ($rationalForm === null) {
            return null;
        }
        [$coefficients, $denominator] = $rationalForm;
        while (count($coefficients) > 1 && $coefficients[array_key_last($coefficients)] === '0') {
            array_pop($coefficients);
        }
        if (count($coefficients) === 1) {
            if ($coefficients[0] === '0') {
                throw new InfiniteSolutionSetException('The rational equation has infinitely many roots.');
            }

            return [];
        }

        $counter = new ExactPolynomialRootCounter();
        $commonFactor = $counter->greatestCommonDivisor($coefficients, $denominator);
        if ($commonFactor === null) {
            return null;
        }
        $rawIntervals = $counter->isolateAllRealRoots(
            $coefficients,
            $maxDepth,
            $width,
        );
        if ($rawIntervals === null) {
            return null;
        }

        $hasCommonRoots = count($commonFactor) > 1;
        $intervals = [];
        foreach ($rawIntervals as [$lowerNumerator, $lowerDenominator, $upperNumerator, $upperDenominator]) {
            $isExactRoot = $lowerNumerator === $upperNumerator
                && $lowerDenominator === $upperDenominator;
            if ($hasCommonRoots) {
                $commonRoot = $isExactRoot
                    ? $counter->isRootAt($commonFactor, [$lowerNumerator, $lowerDenominator])
                    : $counter->countOpenInterval(
                        $commonFactor,
                        $lowerNumerator,
                        $lowerDenominator,
                        $upperNumerator,
                        $upperDenominator,
                    );
                if ($commonRoot === null) {
                    return null;
                }
                if ($commonRoot === true || $commonRoot > 0) {
                    continue;
                }
            }
            $intervals[] = new RationalRootInterval(
                $lowerNumerator,
                $lowerDenominator,
                $upperNumerator,
                $upperDenominator,
                $isExactRoot,
            );
        }

        return $intervals;
    }

    private function hasFiniteAffineMonotoneIsolator(
        Node $left,
        Node $right,
        EvaluationOptions $evaluationOptions,
    ): bool {
        $supported = [
            'exp', 'expm1', 'ln', 'log1p', 'sinh', 'cosh', 'tanh', 'sech',
            'csch', 'coth', 'asinh', 'arcsinh', 'acosh', 'arccosh', 'atanh',
            'arctanh', 'asech', 'acsch', 'acoth', 'erfinv', 'erfcinv', 'log', 'log2', 'log10',
            'erf', 'erfc', 'erfi', 'atan', 'arctan', 'asin', 'arcsin', 'acos', 'arccos', 'acot', 'asec', 'acsc',
            'atan2',
        ];
        foreach ([$left, $right] as $side) {
            $side = $this->unwrapGrouping($side);
            if ($side instanceof BinaryOperationNode && $side->operator === BinaryOperator::Power) {
                return true;
            }
            if (
                $side instanceof FunctionCallNode
                && \in_array($side->name, $supported, true)
                && $evaluationOptions->functions->isBuiltIn($side->name)
            ) {
                return true;
            }
        }

        return false;
    }

    private function hasAffineRationalBaseExponentialOrLogarithm(
        Node $left,
        Node $right,
        EvaluationOptions $evaluationOptions,
    ): bool {
        foreach ([$left, $right] as $side) {
            $side = $this->unwrapGrouping($side);
            if ($side instanceof BinaryOperationNode && $side->operator === BinaryOperator::Power) {
                return true;
            }
            if (
                $side instanceof FunctionCallNode
                && \in_array($side->name, ['log', 'log2', 'log10'], true)
                && $evaluationOptions->functions->isBuiltIn($side->name)
            ) {
                return true;
            }
        }

        return false;
    }

