    /**
     * @param array{string, string} $fixedCoordinate
     * @param array{string, string} $target
     */
    private function affineAtan2TargetIsInRange(
        array $fixedCoordinate,
        array $target,
        bool $variableIsOrdinate,
    ): ?bool {
        $fixedSign = (new ExactRationalInterval($fixedCoordinate, $fixedCoordinate))
            ->compareLowerToRational('0', '1');
        $targetInterval = new ExactRationalInterval($target, $target);
        if ($fixedSign === 0) {
            return null;
        }
        $precision = 40;
        if (!$variableIsOrdinate) {
            if ($fixedSign > 0) {
                if ($targetInterval->compareLowerToRational('0', '1') <= 0) {
                    return false;
                }
                while (true) {
                    $comparison = $this->compareRationalToInterval($target, self::certifiedPiEnclosure($precision));
                    if ($comparison !== 0) {
                        return $comparison < 0;
                    }
                    if ($precision >= 1000) {
                        return null;
                    }
                    $precision = min(1000, max($precision + 20, $precision * 2));
                }
            }
            if ($targetInterval->compareUpperToRational('0', '1') >= 0) {
                return false;
            }
            while (true) {
                $comparison = $this->compareRationalToInterval(
                    $target,
                    self::certifiedPiEnclosure($precision)->negateInterval(),
                );
                if ($comparison !== 0) {
                    return $comparison > 0;
                }
                if ($precision >= 1000) {
                    return null;
                }
                $precision = min(1000, max($precision + 20, $precision * 2));
            }
        }
        if ($fixedSign > 0) {
            return $this->principalPiHalfTargetIsInRange($targetInterval);
        }
        if ($targetInterval->compareLowerToRational('0', '1') > 0) {
            if ($this->compareRationalToInterval($target, self::certifiedPiEnclosure($precision)) > 0) {
                return false;
            }
            while (true) {
                $pi = self::certifiedPiEnclosure($precision);
                $halfPi = $pi->divide(new ExactRationalInterval(['2', '1'], ['2', '1']));
                $halfPiComparison = $this->compareRationalToInterval($target, $halfPi);
                $piComparison = $this->compareRationalToInterval($target, $pi);
                if ($halfPiComparison > 0 && $piComparison < 0) {
                    return true;
                }
                if ($halfPiComparison < 0 || $piComparison > 0) {
                    return false;
                }
                if ($precision >= 1000) {
                    return null;
                }
                $precision = min(1000, max($precision + 20, $precision * 2));
            }
        }
        if ($targetInterval->compareUpperToRational('0', '1') < 0) {
            while (true) {
                $pi = self::certifiedPiEnclosure($precision);
                $negativePi = $pi->negateInterval();
                $negativeHalfPi = $pi->divide(
                    new ExactRationalInterval(['2', '1'], ['2', '1']),
                )->negateInterval();
                $negativeHalfPiComparison = $this->compareRationalToInterval($target, $negativeHalfPi);
                $negativePiComparison = $this->compareRationalToInterval($target, $negativePi);
                if ($negativeHalfPiComparison < 0 && $negativePiComparison > 0) {
                    return true;
                }
                if ($negativeHalfPiComparison > 0 || $negativePiComparison < 0) {
                    return false;
                }
                if ($precision >= 1000) {
                    return null;
                }
                $precision = min(1000, max($precision + 20, $precision * 2));
            }
        }

        return false;
    }

    /**
     * Compare a rational with an interval, returning zero if it overlaps the interval.
     *
     * @param array{string, string} $rational
     */
    private function compareRationalToInterval(array $rational, ExactRationalInterval $interval): int
    {
        $point = new ExactRationalInterval($rational, $rational);
        if ($interval->compareUpperToRational($rational[0], $rational[1]) < 0) {
            return 1;
        }
        if ($point->compareLowerEndpoint($interval) < 0) {
            return -1;
        }

        return 0;
    }

    private function hasAffineInverseSine(
        Node $left,
        Node $right,
        EvaluationOptions $evaluationOptions,
    ): bool {
        foreach ([$left, $right] as $side) {
            $side = $this->unwrapGrouping($side);
            if (
                $side instanceof FunctionCallNode
                && in_array($side->name, ['asin', 'arcsin'], true)
                && $evaluationOptions->functions->isBuiltIn($side->name)
            ) {
                return true;
            }
        }

        return false;
    }

    /**
     * Isolate asin(a*x+b)=q by certifying the inverse sine level's rational bracket.
     *
     * @param array<string, int|float> $parameters
     * @param array{string, string} $maximumWidth
     * @return list<RationalRootInterval>|null
     */
    private function isolateAffineInverseSineRoot(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        array $maximumWidth,
    ): ?array {
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            256,
            $evaluationOptions,
        );
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || !in_array($candidate->name, ['asin', 'arcsin'], true)
                || !$evaluationOptions->functions->isBuiltIn($candidate->name)
                || count($candidate->arguments) !== 1
            ) {
                continue;
            }
            $targetPolynomial = $extractor->polynomial($target);
            $argument = $extractor->polynomial($candidate->arguments[0]);
            if (
                $targetPolynomial === null
                || count($targetPolynomial) !== 1
                || $argument === null
                || count($argument) !== 2
                || $argument[1][0] === '0'
            ) {
                continue;
            }
            $targetInterval = new ExactRationalInterval($targetPolynomial[0], $targetPolynomial[0]);
            $inRange = $this->principalPiHalfTargetIsInRange($targetInterval);
            if ($inRange === false) {
                return [];
            }
            if ($inRange !== true) {
                return null;
            }
            if ($targetPolynomial[0][0] === '0') {
                $zero = new ExactRationalInterval(['0', '1'], ['0', '1']);
                $exactRoot = $this->affineIntervalToVariable($zero, $zero, $argument[0], $argument[1]);

                return [new RationalRootInterval(
                    $exactRoot->lower[0],
                    $exactRoot->lower[1],
                    $exactRoot->upper[0],
                    $exactRoot->upper[1],
                    true,
                )];
            }

            try {
                $target = $targetPolynomial[0];
                $precision = min(1000, max(40, (2 * strlen($target[1])) + 20));
                $compareAt = function (string $numerator, string $denominator) use (&$precision, $target): ?int {
                    while (true) {
                        $angle = (new ExactRationalInterval(
                            [$numerator, $denominator],
                            [$numerator, $denominator],
                        ))->asin($precision);
                        if ($angle->compareUpperToRational($target[0], $target[1]) < 0) {
                            return -1;
                        }
                        if ($angle->compareLowerToRational($target[0], $target[1]) > 0) {
                            return 1;
                        }
                        if ($precision >= 1000) {
                            return null;
                        }
                        $precision = min(1000, max($precision + 20, $precision * 2));
                    }
                };

                $zero = ['0', '1'];
                $targetSign = (new ExactRationalInterval($target, $target))->compareLowerToRational('0', '1');
                $lower = $targetSign > 0 ? $zero : $this->rationalTuple('-1', '1');
                $upper = $targetSign > 0 ? $this->rationalTuple('1', '1') : $zero;
                if ($compareAt($lower[0], $lower[1]) !== -1 || $compareAt($upper[0], $upper[1]) !== 1) {
                    return null;
                }

                for ($iteration = 0; $iteration < 4096; ++$iteration) {
                    $rootX = $this->affineIntervalToVariable(
                        new ExactRationalInterval($lower, $lower),
                        new ExactRationalInterval($upper, $upper),
                        $argument[0],
                        $argument[1],
                    );
                    $rootWidth = (new ExactRationalInterval($rootX->upper, $rootX->upper))
                        ->subtract(new ExactRationalInterval($rootX->lower, $rootX->lower));
                    if ($rootWidth->compareUpperToRational($maximumWidth[0], $maximumWidth[1]) <= 0) {
                        return [new RationalRootInterval(
                            $rootX->lower[0],
                            $rootX->lower[1],
                            $rootX->upper[0],
                            $rootX->upper[1],
                            false,
                        )];
                    }
                    $midpoint = $this->rationalMidpoint($lower, $upper);
                    $side = $compareAt($midpoint[0], $midpoint[1]);
                    if ($side === null) {
                        return null;
                    }
                    if ($side < 0) {
                        $lower = $midpoint;
                    } else {
                        $upper = $midpoint;
                    }
                }
            } catch (\DomainException | \LengthException) {
                return null;
            }
            return null;
        }

        return null;
    }

