            if ($targetPolynomial[0][0] === '0') {
                $one = new ExactRationalInterval(['1', '1'], ['1', '1']);
                $exactRoot = $this->affineIntervalToVariable($one, $one, $argument[0], $argument[1]);

                return [new RationalRootInterval(
                    $exactRoot->lower[0],
                    $exactRoot->lower[1],
                    $exactRoot->upper[0],
