            }
        }

        return false;
    }

    /** @return int|null 1 for the positive branch, -1 for the negative branch, 0 out of range. */
    private function inverseSecantTargetBranch(ExactRationalInterval $target): ?int
    {
        $precision = 40;
        while (true) {
            $pi = self::certifiedPiEnclosure($precision);
            $halfPi = $pi->divide(new ExactRationalInterval(['2', '1'], ['2', '1']));
            if (
                $target->compareLowerToRational('0', '1') >= 0
                && $target->compareUpperToRational($halfPi->lower[0], $halfPi->lower[1]) < 0
            ) {
                return 1;
            }
            if (
                $target->compareLowerToRational($halfPi->upper[0], $halfPi->upper[1]) > 0
                && $target->compareUpperToRational($pi->lower[0], $pi->lower[1]) < 0
            ) {
                return -1;
            }
            if (
                $target->compareUpperToRational('0', '1') < 0
                || $target->compareLowerToRational($pi->upper[0], $pi->upper[1]) >= 0
            ) {
                return 0;
            }
            if ($precision >= 1000) {
                return null;
            }
            $precision = min(1000, max($precision + 20, $precision * 2));
        }
    }

    /** @return int|null 1 for the positive branch, -1 for the negative branch, 0 out of range. */
    private function inverseCosecantTargetBranch(ExactRationalInterval $target): ?int
    {
        $inRange = $this->principalPiHalfTargetIsInRange($target);
        if ($inRange !== true) {
            return $inRange === false ? 0 : null;
        }
        if ($target->compareLowerToRational('0', '1') === 0) {
            return 0;
        }

        return $target->compareLowerToRational('0', '1') > 0 ? 1 : -1;
    }

    /**
     * Isolate affine asec/acsc equations by checking certified endpoint enclosures.
     *
     * @param array<string, int|float> $parameters
     * @param array{string, string} $maximumWidth
     * @return list<RationalRootInterval>|null
     */
    private function isolateAffineReciprocalInverseTrigRoot(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        array $maximumWidth,
    ): ?array {
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            256,
            $evaluationOptions,
        );
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || !in_array($candidate->name, ['asec', 'acsc'], true)
                || !$evaluationOptions->functions->isBuiltIn($candidate->name)
                || count($candidate->arguments) !== 1
            ) {
                continue;
            }
            $targetPolynomial = $extractor->polynomial($target);
            $argument = $extractor->polynomial($candidate->arguments[0]);
            if (
                $targetPolynomial === null
                || count($targetPolynomial) !== 1
                || $argument === null
                || count($argument) !== 2
                || $argument[1][0] === '0'
            ) {
                continue;
            }
            $targetInterval = new ExactRationalInterval($targetPolynomial[0], $targetPolynomial[0]);
            $branch = $candidate->name === 'asec'
                ? $this->inverseSecantTargetBranch($targetInterval)
                : $this->inverseCosecantTargetBranch($targetInterval);
            if ($branch === 0) {
                return [];
            }
            if ($branch === null) {
                return null;
            }
            if ($candidate->name === 'asec' && $targetPolynomial[0][0] === '0') {
                $one = new ExactRationalInterval(['1', '1'], ['1', '1']);
                $root = $this->affineIntervalToVariable($one, $one, $argument[0], $argument[1]);

                return [new RationalRootInterval(
                    $root->lower[0],
                    $root->lower[1],
                    $root->upper[0],
                    $root->upper[1],
                    true,
                )];
            }

            try {
                $target = $targetPolynomial[0];
                $precision = min(1000, max(40, (2 * strlen($target[1])) + 20));
                $isSecant = $candidate->name === 'asec';
                $compareAt = function (string $numerator, string $denominator) use (
                    &$precision,
                    $target,
                    $isSecant,
                ): ?int {
                    while (true) {
                        $point = new ExactRationalInterval(
                            [$numerator, $denominator],
                            [$numerator, $denominator],
                        );
                        $angle = $isSecant ? $point->asec($precision) : $point->acsc($precision);
                        if ($angle->compareUpperToRational($target[0], $target[1]) < 0) {
                            return -1;
                        }
                        if ($angle->compareLowerToRational($target[0], $target[1]) > 0) {
                            return 1;
                        }
                        if ($precision >= 1000) {
                            return null;
                        }
                        $precision = min(1000, max($precision + 20, $precision * 2));
                    }
                };

                $negativeBranch = $branch < 0;
                $lower = $negativeBranch
                    ? $this->rationalTuple('-2', '1')
                    : $this->rationalTuple('1', '1');
                $upper = $negativeBranch
                    ? $this->rationalTuple('-1', '1')
                    : $this->rationalTuple('2', '1');
                $lowerSide = $compareAt($lower[0], $lower[1]);
                $upperSide = $compareAt($upper[0], $upper[1]);
                $increasing = $isSecant;
                $lowerIsBelow = $increasing ? -1 : 1;
                $upperIsAbove = -$lowerIsBelow;

                if ($negativeBranch) {
                    if ($upperSide !== $upperIsAbove) {
                        return null;
                    }
                    while ($lowerSide !== $lowerIsBelow) {
                        if ($lowerSide === null || strlen($lower[0]) > 8000) {
                            return null;
                        }
                        $lower = (new ExactRationalInterval($lower, $lower))
                            ->multiply(new ExactRationalInterval(['2', '1'], ['2', '1']))->lower;
                        $lowerSide = $compareAt($lower[0], $lower[1]);
                    }
                } else {
                    if ($lowerSide !== $lowerIsBelow) {
                        return null;
                    }
                    while ($upperSide !== $upperIsAbove) {
                        if ($upperSide === null || strlen($upper[0]) > 8000) {
                            return null;
                        }
                        $upper = (new ExactRationalInterval($upper, $upper))
                            ->multiply(new ExactRationalInterval(['2', '1'], ['2', '1']))->lower;
                        $upperSide = $compareAt($upper[0], $upper[1]);
                    }
                }

                for ($iteration = 0; $iteration < 4096; ++$iteration) {
                    $rootX = $this->affineIntervalToVariable(
                        new ExactRationalInterval($lower, $lower),
                        new ExactRationalInterval($upper, $upper),
                        $argument[0],
                        $argument[1],
                    );
                    $rootWidth = (new ExactRationalInterval($rootX->upper, $rootX->upper))
                        ->subtract(new ExactRationalInterval($rootX->lower, $rootX->lower));
                    if ($rootWidth->compareUpperToRational($maximumWidth[0], $maximumWidth[1]) <= 0) {
                        return [new RationalRootInterval(
                            $rootX->lower[0],
                            $rootX->lower[1],
                            $rootX->upper[0],
                            $rootX->upper[1],
                            false,
                        )];
                    }
                    $midpoint = $this->rationalMidpoint($lower, $upper);
                    $side = $compareAt($midpoint[0], $midpoint[1]);
                    if ($side === null) {
                        return null;
                    }
                    if ($increasing ? $side < 0 : $side > 0) {
                        $lower = $midpoint;
                    } else {
                        $upper = $midpoint;
                    }
                }
            } catch (\DomainException | \LengthException) {
                return null;
            }

            return null;
        }

        return null;
    }

    /** @return bool|null Whether the rational target is strictly inside (-pi/2, pi/2). */
    private function principalPiHalfTargetIsInRange(ExactRationalInterval $target): ?bool
    {
        $precision = 40;
        while (true) {
            $halfPi = self::certifiedPiEnclosure($precision)->divide(
