                    }
                } else {
                    $lower = $this->rationalTuple('-1', '1');
                    $upper = $zero;
                    while (true) {
                        $side = $compareAt($lower[0], $lower[1]);
                        if ($side === -1) {
                            break;
                        }
                        if ($side === null || strlen($lower[0]) > 8000) {
                            return null;
                        }
                        $lower = (new ExactRationalInterval($lower, $lower))
                            ->multiply(new ExactRationalInterval(['2', '1'], ['2', '1']))->lower;
                    }
                }

                for ($iteration = 0; $iteration < 4096; ++$iteration) {
                    $rootX = $this->affineIntervalToVariable(
                        new ExactRationalInterval($lower, $lower),
                        new ExactRationalInterval($upper, $upper),
                        $argument[0],
                        $argument[1],
                    );
                    $rootWidth = (new ExactRationalInterval($rootX->upper, $rootX->upper))
                        ->subtract(new ExactRationalInterval($rootX->lower, $rootX->lower));
                    if ($rootWidth->compareUpperToRational($maximumWidth[0], $maximumWidth[1]) <= 0) {
                        return [new RationalRootInterval(
                            $rootX->lower[0],
                            $rootX->lower[1],
                            $rootX->upper[0],
                            $rootX->upper[1],
                            false,
                        )];
                    }
                    $midpoint = $this->rationalMidpoint($lower, $upper);
                    $side = $compareAt($midpoint[0], $midpoint[1]);
                    if ($side === null) {
                        return null;
                    }
                    if ($side < 0) {
                        $lower = $midpoint;
                    } else {
                        $upper = $midpoint;
                    }
                }
            } catch (\DomainException | \LengthException) {
                return null;
            }

            return null;
        }

        return null;
    }

    /**
     * Isolate affine equations whose constant level is a rational affine expression in e.
     *
     * @param array<string, int|float> $parameters
     * @param array{string, string} $maximumWidth
     * @param array{string, string}|null $lowerBound
     * @param array{string, string}|null $upperBound
     * @return list<RationalRootInterval>|null
     */
    private function isolateAffineNamedConstantAllReal(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        string $constant,
        array $maximumWidth,
        ?array $lowerBound = null,
        ?array $upperBound = null,
    ): ?array {
        $data = $this->affineNamedConstantEquationData(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            $constant,
        );
        if ($data === null) {
            return null;
        }
        [$coefficient, $interceptValue, $slopeValue] = $data;
        $intercept = new ExactRationalInterval($interceptValue, $interceptValue);
        $slope = new ExactRationalInterval($slopeValue, $slopeValue);
        if ($coefficient[0] === '0') {
            $root = $intercept->negateInterval()->divide($slope);
            if (
                ($lowerBound !== null && $this->compareRationalFractions($root->lower, $lowerBound) <= 0)
                || ($upperBound !== null && $this->compareRationalFractions($root->upper, $upperBound) >= 0)
            ) {
                return [];
            }

            return [new RationalRootInterval(
                $root->lower[0],
                $root->lower[1],
                $root->upper[0],
                $root->upper[1],
                true,
            )];
        }

        $constantLevel = self::certifiedNamedConstantEnclosure($constant)->multiply(
            new ExactRationalInterval($coefficient, $coefficient),
        );
        $root = $constantLevel->subtract($intercept)->divide($slope);
        if (
            ($lowerBound !== null && $this->compareRationalFractions($root->lower, $lowerBound) <= 0)
            || ($upperBound !== null && $this->compareRationalFractions($root->upper, $upperBound) >= 0)
        ) {
            return null;
        }
        $rootWidth = new ExactRationalInterval($root->upper, $root->upper)
            ->subtract(new ExactRationalInterval($root->lower, $root->lower));
        $requestedWidth = new ExactRationalInterval($maximumWidth, $maximumWidth);
        if (
            $rootWidth->compareUpperToRational(
                $requestedWidth->upper[0],
                $requestedWidth->upper[1],
            ) > 0
        ) {
            return null;
        }

        return [new RationalRootInterval(
            $root->lower[0],
            $root->lower[1],
            $root->upper[0],
            $root->upper[1],
            false,
        )];
    }

    /** @return ExactRationalInterval Certified enclosure of a supported named constant. */
    private static function certifiedNamedConstantEnclosure(string $constant): ExactRationalInterval
    {
        if ($constant === 'e') {
            if (self::$eEnclosure === null) {
                self::$eEnclosure = (new ExactRationalInterval(['1', '1'], ['1', '1']))->exp();
            }

            return self::$eEnclosure;
        }
        if ($constant === 'phi') {
            if (self::$phiEnclosure === null) {
                $sqrtFive = (new ExactRationalInterval(['5', '1'], ['5', '1']))->sqrt();
                self::$phiEnclosure = $sqrtFive
                    ->add(new ExactRationalInterval(['1', '1'], ['1', '1']))
                    ->divide(new ExactRationalInterval(['2', '1'], ['2', '1']));
            }

            return self::$phiEnclosure;
        }

        throw new \InvalidArgumentException('No certified enclosure is available for the named constant.');
    }

    /**
     * @param array<string, int|float> $parameters
     * @param array{string, string} $lowerBound
     * @param array{string, string} $upperBound
     */
    private function countAffineNamedConstantInInterval(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        string $constant,
        array $lowerBound,
        array $upperBound,
    ): ?int {
        $data = $this->affineNamedConstantEquationData(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            $constant,
        );
        if ($data === null) {
            return null;
        }
        [$coefficient, $interceptValue, $slopeValue] = $data;
        $intercept = new ExactRationalInterval($interceptValue, $interceptValue);
        $slope = new ExactRationalInterval($slopeValue, $slopeValue);
        if ($coefficient[0] === '0') {
            $root = $intercept->negateInterval()->divide($slope)->lower;

            return $this->compareRationalFractions($root, $lowerBound) > 0
                && $this->compareRationalFractions($root, $upperBound) < 0
                ? 1
                : 0;
        }

        $root = self::certifiedNamedConstantEnclosure($constant)
            ->multiply(new ExactRationalInterval($coefficient, $coefficient))
            ->subtract($intercept)
            ->divide($slope);
        if (
            $this->compareRationalFractions($root->upper, $lowerBound) <= 0
            || $this->compareRationalFractions($root->lower, $upperBound) >= 0
        ) {
            return 0;
        }
        if (
            $this->compareRationalFractions($root->lower, $lowerBound) > 0
            && $this->compareRationalFractions($root->upper, $upperBound) < 0
        ) {
            return 1;
        }

        return null;
    }

    /**
     * Isolate affine rational equations whose constant level is a rational multiple of pi.
     *
     * @param array<string, int|float> $parameters
     * @param array{string, string} $maximumWidth
     * @param array{string, string}|null $lowerBound
     * @param array{string, string}|null $upperBound
     * @return list<RationalRootInterval>|null
     */
    private function isolateAffinePiMultipleAllReal(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        array $maximumWidth,
        ?array $lowerBound = null,
        ?array $upperBound = null,
    ): ?array {
        $data = $this->affineNamedConstantEquationData(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            'pi',
        );
        if ($data === null) {
            return null;
        }

        [$multiple, $interceptValue, $slopeValue] = $data;
        $intercept = new ExactRationalInterval($interceptValue, $interceptValue);
        $slope = new ExactRationalInterval($slopeValue, $slopeValue);
        if ($multiple[0] === '0') {
            $root = $intercept->negateInterval()->divide($slope);
            if (
                (
                    $lowerBound !== null
                    && $this->compareRationalFractions($root->lower, $lowerBound) <= 0
                )
                || (
                    $upperBound !== null
                    && $this->compareRationalFractions($root->upper, $upperBound) >= 0
                )
            ) {
                return [];
            }

            return [new RationalRootInterval(
                $root->lower[0],
                $root->lower[1],
                $root->upper[0],
                $root->upper[1],
                true,
            )];
        }

        $requestedWidth = new ExactRationalInterval($maximumWidth, $maximumWidth);
        for ($terms = 8; $terms <= 512; $terms *= 2) {
            $piLevel = self::certifiedPiEnclosure($terms)->multiply(
                new ExactRationalInterval($multiple, $multiple),
            );
            $root = $piLevel->subtract($intercept)->divide($slope);
            if (
                (
                    $lowerBound !== null
                    && $this->compareRationalFractions($root->lower, $lowerBound) <= 0
                )
                || (
                    $upperBound !== null
                    && $this->compareRationalFractions($root->upper, $upperBound) >= 0
                )
            ) {
                continue;
            }
            $rootWidth = new ExactRationalInterval($root->upper, $root->upper)
                ->subtract(new ExactRationalInterval($root->lower, $root->lower));
            if (
                $rootWidth->compareUpperToRational(
                    $requestedWidth->upper[0],
                    $requestedWidth->upper[1],
                ) <= 0
            ) {
                return [new RationalRootInterval(
                    $root->lower[0],
                    $root->lower[1],
                    $root->upper[0],
                    $root->upper[1],
                    false,
                )];
            }
        }

        return null;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return array{array{string, string}, array{string, string}, array{string, string}}|null
     */
    private function affineNamedConstantEquationData(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        string $constant,
    ): ?array {
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            256,
            $evaluationOptions,
        );
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $level]) {
            $constantAffine = match ($constant) {
                'pi' => RationalLiteral::piAffineAsStrings($level),
                'e' => RationalLiteral::eAffineAsStrings($level),
                'phi' => RationalLiteral::phiAffineAsStrings($level),
                default => null,
            };
            if ($constantAffine === null) {
                continue;
            }
            $affine = $extractor->polynomial($candidate);
            if ($affine !== null && \count($affine) === 2 && $affine[1][0] !== '0') {
                $intercept = (new ExactRationalInterval($affine[0], $affine[0]))
                    ->subtract(new ExactRationalInterval($constantAffine[1], $constantAffine[1]))
                    ->lower;

                return [$constantAffine[0], $intercept, $affine[1]];
            }
        }

        return null;
    }

