    /**
     * Isolate all real roots of affine cosh/sech equations using expanding exact bounds.
     *
     * @param array<string, int|float> $parameters
     * @param array{string, string} $maximumWidth
     * @return list<RationalRootInterval>|null
     */
    private function isolateAffineHyperbolicCosineAllReal(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        array $maximumWidth,
        int $maxDepth,
        int $expectedCount,
    ): ?array {
        if ($expectedCount === 0) {
            return [];
        }
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            256,
            $evaluationOptions,
        );
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || !\in_array($candidate->name, ['cosh', 'sech'], true)
                || !$evaluationOptions->functions->isBuiltIn($candidate->name)
                || \count($candidate->arguments) !== 1
            ) {
                continue;
            }
            $targetPolynomial = $extractor->polynomial($target);
            $argument = $extractor->polynomial($candidate->arguments[0]);
            if (
                $targetPolynomial === null
                || \count($targetPolynomial) !== 1
                || $argument === null
                || \count($argument) !== 2
                || $argument[1][0] === '0'
            ) {
                continue;
            }
            if ($expectedCount === 1) {
                $zero = new ExactRationalInterval(['0', '1'], ['0', '1']);
                $root = $this->affineIntervalToVariable($zero, $zero, $argument[0], $argument[1]);

                return [new RationalRootInterval(
                    $root->lower[0],
                    $root->lower[1],
                    $root->upper[0],
                    $root->upper[1],
                    true,
                )];
            }

            $solver = new HyperbolicEquationSolver();
            $bound = '1';
            for ($expansion = 0; $expansion < 4096; ++$expansion) {
                try {
                    $method = $candidate->name === 'cosh'
                        ? 'isolateAffineHyperbolicCosine'
                        : 'isolateAffineHyperbolicSecant';
                    $roots = $solver->{$method}(
                        $targetPolynomial[0],
                        $argument[1],
                        $argument[0],
                        ['-' . $bound, '1'],
                        [$bound, '1'],
                        $maximumWidth,
                        $maxDepth,
                    );
                } catch (\LengthException) {
                    return null;
                }
                if ($roots === null) {
                    return null;
                }
                if (\count($roots) === $expectedCount) {
                    return $roots;
                }
                $bound .= '0';
            }

            return null;
        }

        return null;
    }

    /**
