            if ($candidate->name === 'expm1') {
                $exponentialTarget = $exponentialTarget->add(
                    new ExactRationalInterval(['1', '1'], ['1', '1']),
                );
            }

            $solver = new ExponentialEquationSolver();
            $bound = '1';
            for ($expansion = 0; $expansion < 4096; ++$expansion) {
                try {
                    $roots = $solver->isolateQuadratic(
                        $exponentialTarget->lower,
                        $phase[2],
                        $phase[1],
                        $phase[0],
                        ['-' . $bound, '1'],
                        [$bound, '1'],
                        $maximumWidth,
                        $maxDepth,
                    );
                } catch (\LengthException) {
                    return null;
                }
                if ($roots === null) {
                    return null;
                }
                if (\count($roots) === $expectedCount) {
                    return $roots;
                }
                $bound .= '0';
            }

            return null;
        }

        return null;
    }

