        $cosineTangentPair = \in_array($phaseCall->name, ['acos', 'arccos', 'asec'], true)
            && \in_array($targetCall->name, ['atan', 'arctan'], true);
        if (!$sineCotangentPair && !$cosineTangentPair) {
            return null;
        }
        $p = $phaseCall->arguments[0];
        $q = $targetCall->arguments[0];
        if (!$this->containsVariable($p, $variable) && !$this->containsVariable($q, $variable)) {
