        $qSquared = new BinaryOperationNode(BinaryOperator::Power, $q, $two, $span);
        $onePlusQSquared = new BinaryOperationNode(BinaryOperator::Add, $one, $qSquared, $span);
        $product = new BinaryOperationNode(BinaryOperator::Multiply, $pSquared, $onePlusQSquared, $span);
        $extractor = new ExactRationalPolynomialExtractor($variable, $parameters, $maxPolynomialDegree);
        $equationForm = $extractor->rationalDifference($product, $one);
        $pForm = $extractor->rationalDifference($p, $zero);
        $qForm = $extractor->rationalDifference($q, $zero);
        if ($equationForm === null || $pForm === null || $qForm === null) {
