        $pSign = $this->multiplyIntegerPolynomialCoefficients($pForm[0], $pForm[1]);
        $qSign = $this->multiplyIntegerPolynomialCoefficients($qForm[0], $qForm[1]);
        $denominatorSquare = $this->multiplyIntegerPolynomialCoefficients($equationForm[1], $equationForm[1]);
        if ($pSign === null || $qSign === null || $denominatorSquare === null) {
            return null;
        }
        if ($this->isZeroCoefficientList($pSign)) {
            return [];
        }
        $arithmetic = new IntegerPolynomialExtractor('', [], 256);
        foreach ([&$pSign, &$denominatorSquare] as &$polynomial) {
            foreach ($polynomial as &$coefficient) {
