        $pSign = $this->multiplyIntegerPolynomialCoefficients($signForm[0], $signForm[1]);
        $denominatorSquare = $this->multiplyIntegerPolynomialCoefficients($equationForm[1], $equationForm[1]);
        if ($pSign === null || $denominatorSquare === null) {
