        $reciprocalCall = \in_array($left->name, $reciprocalNames, true)
            ? $left
            : (\in_array($right->name, $reciprocalNames, true) ? $right : null);
        if (
            $reciprocalCall === null
            || \count($directCall->arguments) !== 1
            || \count($reciprocalCall->arguments) !== 1
        ) {
