        $domainForm = $extractor->rationalDifference($one, $pSquared);
        if ($equationForm === null || $domainForm === null) {
            return null;
        }
        $domainSign = $this->multiplyIntegerPolynomialCoefficients($domainForm[0], $domainForm[1]);
        $denominatorSquare = $this->multiplyIntegerPolynomialCoefficients($equationForm[1], $equationForm[1]);
        if ($domainSign === null || $denominatorSquare === null) {
            return null;
        }
        $arithmetic = new IntegerPolynomialExtractor('', [], 256);
        foreach ($denominatorSquare as &$coefficient) {
            $coefficient = $arithmetic->negateIntegerValue($coefficient);
        }
        unset($coefficient);
        $constraints = [[$denominatorSquare, false]];
        $partitionPolynomials = [$equationForm[1]];
        if (!$this->isZeroCoefficientList($domainSign)) {
            $constraints[] = [$domainSign, true];
            $partitionPolynomials[] = $domainSign;
        }

        return $this->isolateSignConstrainedEquation(
            $equationForm[0],
            $constraints,
            $partitionPolynomials,
            $lower,
            $upper,
            $maxDepth,
            $maximumWidth,
        );
    }

    /**
     * @param list<string> $coefficients
     * @param list<array{list<string>, bool}> $constraints
     * @param list<list<string>> $partitionPolynomials
     * @param array{string, string}|null $lower
     * @param array{string, string}|null $upper
     * @param array{string, string} $maximumWidth
     * @return list<RationalRootInterval>|null
     */
    private function isolateSignConstrainedEquation(
        array $coefficients,
        array $constraints,
        array $partitionPolynomials,
        ?array $lower,
        ?array $upper,
        int $maxDepth,
        array $maximumWidth,
    ): ?array {
        if ($this->isZeroCoefficientList($coefficients)) {
            $partition = $this->squareFreeSignPartition($partitionPolynomials);
            if ($partition === null) {
                return null;
            }
            $counter = new ExactPolynomialRootCounter();
            $boundaries = $lower === null || $upper === null
                ? $counter->isolateAllRealRoots($partition, $maxDepth, $maximumWidth)
                : $counter->isolateOpenInterval(
                    $partition,
                    $lower[0],
                    $lower[1],
                    $upper[0],
                    $upper[1],
                    $maxDepth,
                    $maximumWidth,
                );
            if ($boundaries === null) {
                return null;
            }
            $samples = [];
            foreach ($boundaries as $boundary) {
                $samples[] = [$boundary[0], $boundary[1]];
                $samples[] = [$boundary[2], $boundary[3]];
            }
            if ($lower === null || $upper === null) {
                if ($boundaries === []) {
                    $samples[] = ['0', '1'];
                } else {
                    $first = [$boundaries[0][0], $boundaries[0][1]];
                    $samples[] = (new ExactRationalInterval($first, $first))
                        ->subtract(new ExactRationalInterval(['1', '1'], ['1', '1']))->lower;
                    for ($index = 1; $index < \count($boundaries); ++$index) {
                        $samples[] = $this->rationalMidpoint(
                            [$boundaries[$index - 1][2], $boundaries[$index - 1][3]],
                            [$boundaries[$index][0], $boundaries[$index][1]],
                        );
                    }
                    $last = $boundaries[\array_key_last($boundaries)];
                    $point = [$last[2], $last[3]];
                    $samples[] = (new ExactRationalInterval($point, $point))
                        ->add(new ExactRationalInterval(['1', '1'], ['1', '1']))->upper;
                }
            } else {
                $samples[] = $lower;
                $samples[] = $upper;
                $leftPoint = $lower;
                foreach ($boundaries as $boundary) {
                    $rightPoint = [$boundary[0], $boundary[1]];
                    if ($this->compareRationalFractions($leftPoint, $rightPoint) < 0) {
                        $samples[] = $this->rationalMidpoint($leftPoint, $rightPoint);
                    }
                    $leftPoint = [$boundary[2], $boundary[3]];
                }
                if ($this->compareRationalFractions($leftPoint, $upper) < 0) {
                    $samples[] = $this->rationalMidpoint($leftPoint, $upper);
                }
            }
            foreach ($samples as $sample) {
                $valid = $this->strictSignConstraintsHoldAt($constraints, $sample, $counter);
                if ($valid === null) {
                    return null;
                }
                if ($valid) {
                    throw new InfiniteSolutionSetException(
                        'The inverse hyperbolic equation has infinitely many roots in the requested domain.',
                    );
                }
            }
            if ($this->isZeroCoefficientList($partition)) {
                return null;
            }

            return $lower === null || $upper === null
                ? $this->isolatePolynomialRootsWithSignConstraintsOnRealLine(
                    $partition,
                    $constraints,
                    $maxDepth,
                    $maximumWidth,
                )
                : $this->isolatePolynomialRootsWithSignConstraints(
                    $partition,
                    $constraints,
                    $lower,
                    $upper,
                    $maxDepth,
                    $maximumWidth,
                );
        }

        return $lower === null || $upper === null
            ? $this->isolatePolynomialRootsWithSignConstraintsOnRealLine(
                $coefficients,
                $constraints,
                $maxDepth,
                $maximumWidth,
            )
            : $this->isolatePolynomialRootsWithSignConstraints(
                $coefficients,
                $constraints,
                $lower,
                $upper,
                $maxDepth,
                $maximumWidth,
            );
    }

    /**
     * Reduce atanh(P) = acoth(Q) to P*Q = 1 with the strict real-domain condition |P| < 1.
     *
     * @param array<string, int|float> $parameters
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @param array{string, string} $maximumWidth
     * @return list<RationalRootInterval>|null
     */
    private function isolateReciprocalAtanhAcothRootsInInterval(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        int $maxPolynomialDegree,
        ?array $lower,
        ?array $upper,
        int $maxDepth,
        array $maximumWidth,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if (!$left instanceof FunctionCallNode || !$right instanceof FunctionCallNode) {
            return null;
        }
        $atanhCall = \in_array($left->name, ['atanh', 'arctanh'], true) ? $left : $right;
        $acothCall = $left->name === 'acoth' ? $left : ($right->name === 'acoth' ? $right : null);
        if (
            $acothCall === null
            || !\in_array($atanhCall->name, ['atanh', 'arctanh'], true)
            || \count($atanhCall->arguments) !== 1
            || \count($acothCall->arguments) !== 1
        ) {
            return null;
        }
        $phase = $atanhCall->arguments[0];
        if (
            !$this->containsVariable($phase, $variable)
            && !$this->containsVariable($acothCall->arguments[0], $variable)
        ) {
            return null;
        }
        $extractor = new ExactRationalPolynomialExtractor($variable, $parameters, $maxPolynomialDegree);
        $product = new BinaryOperationNode(BinaryOperator::Multiply, $phase, $acothCall->arguments[0], $phase->span());
        $one = new NumberNode(1, '1', $product->span());
        $equationForm = $extractor->rationalDifference($product, $one);
        $minusForm = $extractor->rationalDifference($one, $phase);
        $plusPhase = new BinaryOperationNode(BinaryOperator::Add, $one, $phase, $phase->span());
        $plusForm = $extractor->rationalDifference($plusPhase, new NumberNode(0, '0', $phase->span()));
        if ($equationForm === null || $minusForm === null || $plusForm === null) {
            return null;
        }
        $minusSign = $this->multiplyIntegerPolynomialCoefficients($minusForm[0], $minusForm[1]);
        $plusSign = $this->multiplyIntegerPolynomialCoefficients($plusForm[0], $plusForm[1]);
        $denominatorSquare = $this->multiplyIntegerPolynomialCoefficients($equationForm[1], $equationForm[1]);
        if ($minusSign === null || $plusSign === null || $denominatorSquare === null) {
            return null;
        }
        $arithmetic = new IntegerPolynomialExtractor('', [], 256);
        foreach (['minusSign', 'plusSign', 'denominatorSquare'] as $constraintName) {
            foreach ($$constraintName as &$coefficient) {
                $coefficient = $arithmetic->negateIntegerValue($coefficient);
            }
            unset($coefficient);
        }
        $constraints = [[$minusSign, false], [$plusSign, false], [$denominatorSquare, false]];
        if ($this->isZeroCoefficientList($equationForm[0])) {
            foreach ($constraints as [$constraint]) {
                if ($this->isZeroCoefficientList($constraint)) {
                    return [];
                }
            }
            $partition = $this->squareFreeSignPartition([$minusSign, $plusSign, $equationForm[1]]);
            if ($partition === null) {
                return null;
            }
            $counter = new ExactPolynomialRootCounter();
            $boundaries = $lower === null || $upper === null
                ? $counter->isolateAllRealRoots($partition, $maxDepth, ['1', '1000000000000'])
                : $counter->isolateOpenInterval(
                    $partition,
                    $lower[0],
                    $lower[1],
                    $upper[0],
                    $upper[1],
                    $maxDepth,
                    ['1', '1000000000000'],
                );
            if ($boundaries === null) {
                return null;
            }
            $endpointSamples = [];
            foreach ($boundaries as $boundary) {
                $endpointSamples[] = [$boundary[0], $boundary[1]];
                $endpointSamples[] = [$boundary[2], $boundary[3]];
            }
            if ($lower !== null && $upper !== null) {
                $endpointSamples[] = $lower;
                $endpointSamples[] = $upper;
            }
            foreach ($endpointSamples as $sample) {
                $valid = $this->strictSignConstraintsHoldAt($constraints, $sample, $counter);
                if ($valid === null) {
                    return null;
                }
                if ($valid) {
                    throw new InfiniteSolutionSetException(
                        'The inverse hyperbolic equation has infinitely many roots in the requested domain.',
                    );
                }
            }
            if ($lower === null || $upper === null) {
                $samplePoints = [];
                if ($boundaries === []) {
                    $samplePoints[] = ['0', '1'];
                } else {
                    $firstLower = [$boundaries[0][0], $boundaries[0][1]];
                    $samplePoints[] = (new ExactRationalInterval($firstLower, $firstLower))
                        ->subtract(new ExactRationalInterval(['1', '1'], ['1', '1']))
                        ->lower;
                    for ($index = 1; $index < \count($boundaries); ++$index) {
                        $leftEndpoint = [$boundaries[$index - 1][2], $boundaries[$index - 1][3]];
                        $rightEndpoint = [$boundaries[$index][0], $boundaries[$index][1]];
                        $samplePoints[] = $this->rationalMidpoint($leftEndpoint, $rightEndpoint);
                    }
                    $lastUpper = $boundaries[\array_key_last($boundaries)];
                    $samplePoints[] = (new ExactRationalInterval(
                        [$lastUpper[2], $lastUpper[3]],
                        [$lastUpper[2], $lastUpper[3]],
                    ))->add(new ExactRationalInterval(['1', '1'], ['1', '1']))->upper;
                }
                foreach ($samplePoints as $sample) {
                    $valid = $this->strictSignConstraintsHoldAt($constraints, $sample, $counter);
                    if ($valid === null) {
                        return null;
                    }
                    if ($valid) {
                        throw new InfiniteSolutionSetException(
                            'The inverse hyperbolic equation has infinitely many real solutions.',
                        );
                    }
                }

                return [];
            }
            $leftPoint = $lower;
            foreach ($boundaries as $boundary) {
                $rightPoint = [$boundary[0], $boundary[1]];
                $sample = $this->rationalMidpoint($leftPoint, $rightPoint);
                $valid = $this->strictSignConstraintsHoldAt($constraints, $sample, $counter);
                if ($valid === null) {
                    return null;
                }
                if ($valid) {
                    throw new InfiniteSolutionSetException(
                        'The inverse hyperbolic equation has infinitely many roots in the interval.',
                    );
                }
                $leftPoint = [$boundary[2], $boundary[3]];
            }
            $sample = $this->rationalMidpoint($leftPoint, $upper);
            $valid = $this->strictSignConstraintsHoldAt($constraints, $sample, $counter);
            if ($valid === null) {
                return null;
            }
            if ($valid) {
                throw new InfiniteSolutionSetException(
                    'The inverse hyperbolic equation has infinitely many roots in the interval.',
                );
            }

            return [];
        }

        if ($lower === null || $upper === null) {
            return $this->isolatePolynomialRootsWithSignConstraintsOnRealLine(
                $equationForm[0],
                $constraints,
                $maxDepth,
                $maximumWidth,
            );
        }

        return $this->isolatePolynomialRootsWithSignConstraints(
            $equationForm[0],
            $constraints,
            $lower,
            $upper,
            $maxDepth,
            $maximumWidth,
        );
    }

    /**
     * @param list<string> $coefficients
     * @param list<array{list<string>, bool}> $constraints
     * @param array{string, string} $maximumWidth
     * @return list<RationalRootInterval>|null
     */
    private function isolatePolynomialRootsWithSignConstraintsOnRealLine(
        array $coefficients,
        array $constraints,
        int $maxDepth,
        array $maximumWidth,
    ): ?array {
        $counter = new ExactPolynomialRootCounter();
        $commonFactors = [];
        foreach ($constraints as [$constraint]) {
            $commonFactor = $counter->greatestCommonDivisor($coefficients, $constraint);
            if ($commonFactor === null) {
                return null;
            }
            $commonFactors[] = $commonFactor;
        }
        $width = $maximumWidth;
        $arithmetic = new IntegerPolynomialExtractor('', []);
        for ($attempt = 0; $attempt < 8; ++$attempt) {
            $rawRoots = $counter->isolateAllRealRoots($coefficients, $maxDepth, $width);
            if ($rawRoots === null) {
                return null;
            }
            $roots = [];
            $needsRefinement = false;
            foreach ($rawRoots as $root) {
                $lower = [$root[0], $root[1]];
                $upper = [$root[2], $root[3]];
                $exact = $lower === $upper;
                $interval = new ExactRationalInterval($lower, $upper);
                $valid = true;
                foreach ($constraints as $index => [$constraint, $acceptZero]) {
                    if ($exact) {
                        $sign = $counter->signAt($constraint, $lower);
                        if ($sign === null) {
                            return null;
                        }
                    } else {
                        $commonRoots = $counter->countOpenInterval(
                            $commonFactors[$index],
                            $lower[0],
                            $lower[1],
                            $upper[0],
                            $upper[1],
                        );
                        if ($commonRoots === null) {
                            return null;
                        }
                        if ($commonRoots > 0) {
                            $sign = 0;
                        } else {
                            $range = $this->evaluateIntegerPolynomialOnInterval($constraint, $interval);
                            if ($range === null) {
                                return null;
                            }
                            if ($acceptZero && $range->compareLowerToRational('0', '1') >= 0) {
                                $sign = 1;
                            } elseif (!$acceptZero && $range->compareUpperToRational('0', '1') < 0) {
                                $sign = -1;
                            } elseif (
                                ($acceptZero && $range->compareUpperToRational('0', '1') < 0)
                                || (!$acceptZero && $range->compareLowerToRational('0', '1') >= 0)
                            ) {
                                $valid = false;
                                break;
                            } else {
                                $needsRefinement = true;
                                break;
                            }
                        }
                    }
                    if (($acceptZero && $sign < 0) || (!$acceptZero && $sign >= 0)) {
                        $valid = false;
                        break;
                    }
                }
                if ($needsRefinement) {
                    break;
                }
                if ($valid) {
                    $roots[] = new RationalRootInterval(
                        $root[0],
                        $root[1],
                        $root[2],
                        $root[3],
                        $exact,
                    );
                }
            }
            if (!$needsRefinement) {
                return $roots;
            }
            $width = [$width[0], $arithmetic->multiplyIntegerValues($width[1], '1000000')];
        }

        return null;
    }

    /**
     * @param array{list<array{string, string}>, list<array{string, string}>} $form
     */
    private function evaluateRationalFormOnInterval(
        array $form,
        ExactRationalInterval $interval,
    ): ?ExactRationalInterval {
        $numerator = $this->evaluateRationalPolynomialOnInterval($form[0], $interval);
        $denominator = $this->evaluateRationalPolynomialOnInterval($form[1], $interval);
        if ($numerator === null || $denominator === null || $denominator->containsZero()) {
            return null;
        }

        return $numerator->divide($denominator);
    }

    /**
     * @param array<string, int|float> $parameters
     * @param array{string, string} $maximumWidth
     * @param array{array{string, string}, array{string, string}}|null $rationalBounds
     * @return list<RationalRootInterval>|false|null
     */
    private function sameMonotonePolynomialRootIntervals(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
        int $maxDepth,
        array $maximumWidth,
        ?array $rationalBounds = null,
    ): array|false|null {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if (
            $left instanceof FunctionCallNode
            && $right instanceof FunctionCallNode
            && $left->name === 'abs'
            && $right->name === 'abs'
            && \count($left->arguments) === 1
            && \count($right->arguments) === 1
        ) {
            $leftInner = $this->unwrapGrouping($left->arguments[0]);
            $rightInner = $this->unwrapGrouping($right->arguments[0]);
            if (
                $leftInner instanceof FunctionCallNode
                && $rightInner instanceof FunctionCallNode
                && $leftInner->name === $rightInner->name
                && \in_array($leftInner->name, ['gammainc', 'gammaincc', 'betainc', 'betaincc'], true)
            ) {
                return $this->sameMonotonePolynomialRootIntervals(
                    $leftInner,
                    $rightInner,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                    $maxPolynomialDegree,
                    $maxDepth,
                    $maximumWidth,
                    $rationalBounds,
                );
            }
        }
        $polynomialExtractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            $target = $this->unwrapGrouping($target);
            if (
                !$candidate instanceof FunctionCallNode
                || !\in_array($candidate->name, ['ln', 'log', 'log10', 'log2', 'log1p'], true)
                || !$evaluationOptions->functions->isBuiltIn($candidate->name)
                || $candidate->arguments === []
                || $target instanceof FunctionCallNode
            ) {
                continue;
            }
            $targetPolynomial = $polynomialExtractor->polynomial($target);
            if (
                $targetPolynomial === null
                || \count($targetPolynomial) !== 1
            ) {
                continue;
            }
            $targetValue = new ExactRationalInterval($targetPolynomial[0], $targetPolynomial[0]);
            $targetIsZero = $targetValue->compareLowerToRational('0', '1') === 0;
            if ($candidate->name === 'log' && \count($candidate->arguments) === 2) {
                $levelRoots = $this->variableBaseLogarithmLevelRootIntervals(
                    $candidate,
                    $targetPolynomial[0],
                    $variable,
                    $parameters,
                    $maxPolynomialDegree,
                    $maxDepth,
                    $maximumWidth,
                    $rationalBounds,
                );
                if ($levelRoots !== null) {
                    return $levelRoots;
                }

                continue;
            } elseif ($targetIsZero) {
                $identityArgument = new NumberNode(
                    $candidate->name === 'log1p' ? 0 : 1,
                    $candidate->name === 'log1p' ? '0' : '1',
                    $candidate->arguments[0]->span(),
                );
            } else {
                continue;
            }
            $identityArguments = $candidate->arguments;
            $identityArguments[0] = $identityArgument;
            $zeroTargetLog = new FunctionCallNode(
                $candidate->name,
                $identityArguments,
                $candidate->nameSpan,
                $candidate->span,
            );

            return $this->sameMonotonePolynomialRootIntervals(
                $candidate,
                $zeroTargetLog,
                $variable,
                $parameters,
                $evaluationOptions,
                $maxPolynomialDegree,
                $maxDepth,
                $maximumWidth,
                $rationalBounds,
            );
        }
        if (
            !$left instanceof FunctionCallNode
            || !$right instanceof FunctionCallNode
            || (
                $left->name !== $right->name
                && !(
                    (\in_array($left->name, ['ln', 'log', 'log10', 'log2', 'log1p'], true)
                        && \in_array($right->name, ['ln', 'log', 'log10', 'log2', 'log1p'], true))
                    || (\in_array($left->name, ['asinh', 'arcsinh'], true)
                        && \in_array($right->name, ['asinh', 'arcsinh'], true))
                    || (\in_array($left->name, ['acosh', 'arccosh'], true)
                        && \in_array($right->name, ['acosh', 'arccosh'], true))
                    || (\in_array($left->name, ['atanh', 'arctanh'], true)
                        && \in_array($right->name, ['atanh', 'arctanh'], true))
                    || (\in_array($left->name, ['atan', 'arctan'], true)
                        && \in_array($right->name, ['atan', 'arctan'], true))
                    || (\in_array($left->name, ['asin', 'arcsin'], true)
                        && \in_array($right->name, ['asin', 'arcsin'], true))
                    || (\in_array($left->name, ['acos', 'arccos'], true)
                        && \in_array($right->name, ['acos', 'arccos'], true))
                    || (\in_array($left->name, ['sqrt', 'cbrt', 'root'], true)
                        && \in_array($right->name, ['sqrt', 'cbrt', 'root'], true))
                    || (\in_array($left->name, ['gammaincinv', 'gammainccinv'], true)
                        && \in_array($right->name, ['gammaincinv', 'gammainccinv'], true))
                    || (\in_array($left->name, ['betaincinv', 'betainccinv'], true)
                        && \in_array($right->name, ['betaincinv', 'betainccinv'], true))
                )
            )
            || !\in_array(
                $left->name,
                [
                    'exp', 'expm1', 'sinh', 'tanh', 'erf', 'erfc', 'erfcx',
                    'ln', 'log', 'log10', 'log2', 'log1p', 'sqrt',
                    'acosh', 'arccosh', 'atanh', 'arctanh', 'acoth', 'acsch', 'asech', 'asec', 'acsc',
                    'asinh', 'arcsinh', 'atan', 'arctan',
                    'acot', 'asin', 'arcsin', 'acos', 'arccos',
                    'csch', 'coth',
                    'cbrt', 'root',
                    'erfinv', 'erfcinv',
                    'gammaincinv', 'gammainccinv', 'betaincinv', 'betainccinv',
                    'gammainc', 'gammaincc', 'betainc', 'betaincc',
                ],
                true,
            )
        ) {
            return null;
        }
        $inverseGammaQuantile = \in_array($left->name, ['gammaincinv', 'gammainccinv'], true);
        $inverseBetaQuantile = \in_array($left->name, ['betaincinv', 'betainccinv'], true);
        $regularizedGamma = \in_array($left->name, ['gammainc', 'gammaincc'], true);
        $regularizedBeta = \in_array($left->name, ['betainc', 'betaincc'], true);
        $leftExpectedArguments = match (true) {
            $left->name === 'log', $left->name === 'root', $inverseGammaQuantile, $regularizedGamma => 2,
            $inverseBetaQuantile, $regularizedBeta => 3,
            default => 1,
        };
        $rightExpectedArguments = match (true) {
            $right->name === 'log', $right->name === 'root',
            \in_array($right->name, ['gammaincinv', 'gammainccinv', 'gammainc', 'gammaincc'], true) => 2,
            \in_array($right->name, ['betaincinv', 'betainccinv', 'betainc', 'betaincc'], true) => 3,
            default => 1,
        };
        if (
            \count($left->arguments) !== $leftExpectedArguments
            || \count($right->arguments) !== $rightExpectedArguments
        ) {
            return null;
        }
        $variableLogarithmBase = false;
        $sameLogarithmBase = false;
        $differentFixedLogarithmBases = false;
        $leftBase = null;
        $rightBase = null;
        $fixedLogarithmDifference = null;
        $logarithmNames = ['ln', 'log', 'log10', 'log2', 'log1p'];
        $sameLogarithmFamily = \in_array($left->name, $logarithmNames, true)
            && \in_array($right->name, $logarithmNames, true);
        if ($sameLogarithmFamily) {
            $leftBase = $this->logarithmBaseIdentity($left);
            $rightBase = $this->logarithmBaseIdentity($right);
            if (\is_array($leftBase) && \is_array($rightBase)) {
                foreach ([$leftBase, $rightBase] as $base) {
                    $baseInterval = new ExactRationalInterval($base, $base);
                    if (
                        $baseInterval->compareLowerToRational('0', '1') <= 0
                        || $baseInterval->compareLowerToRational('1', '1') === 0
                    ) {
                        return [];
                    }
                }
                if ($leftBase === $rightBase) {
                    $sameLogarithmBase = true;
                } else {
                    $differentFixedLogarithmBases = true;
                }
            } elseif ($leftBase === 'e' && $rightBase === 'e') {
                // The natural logarithm has a valid, fixed base.
                $sameLogarithmBase = true;
            } elseif (($leftBase === 'e' && \is_array($rightBase)) || (\is_array($leftBase) && $rightBase === 'e')) {
                if (\is_array($leftBase)) {
                    $rationalBase = $leftBase;
                } elseif (\is_array($rightBase)) {
                    $rationalBase = $rightBase;
                } else {
                    return null;
                }
                $baseInterval = new ExactRationalInterval($rationalBase, $rationalBase);
                if (
                    $baseInterval->compareLowerToRational('0', '1') <= 0
                    || $baseInterval->compareLowerToRational('1', '1') === 0
                ) {
                    return [];
                }
                $differentFixedLogarithmBases = true;
            } elseif (
                $left->name === 'log'
                && $right->name === 'log'
                && $leftBase instanceof Node
                && $rightBase instanceof Node
            ) {
                $variableLogarithmBase = true;
            } else {
                return null;
            }
        }

        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        if ($variableLogarithmBase) {
            $baseDifference = $extractor->rationalDifference($left->arguments[1], $right->arguments[1]);
            $argumentDifference = $extractor->rationalDifference($left->arguments[0], $right->arguments[0]);
            if (
                $baseDifference !== null
                && $argumentDifference !== null
                && $this->isZeroCoefficientList($baseDifference[0])
                && $this->isZeroCoefficientList($argumentDifference[0])
                && $this->hasValidVariableLogarithmWitness(
                    $left,
                    $variable,
                    $parameters,
                    $maxPolynomialDegree,
                    $rationalBounds,
                )
            ) {
                throw new InfiniteSolutionSetException(
                    'The variable-base logarithmic equation has infinitely many real roots.',
                );
            }
        }
        $argumentIndex = 0;
        /** @var list<list<array{string, string}>> $inverseQuantileShapePolynomials */
        $inverseQuantileShapePolynomials = [];
        if ($inverseGammaQuantile || $inverseBetaQuantile || $regularizedGamma || $regularizedBeta) {
            $shapeCount = $inverseGammaQuantile || $regularizedGamma ? 1 : 2;
            $argumentIndex = $shapeCount;
            for ($shapeIndex = 0; $shapeIndex < $shapeCount; ++$shapeIndex) {
                if ($regularizedGamma || $regularizedBeta) {
                    $leftShapeForm = $extractor->rationalFunction($left->arguments[$shapeIndex]);
                    $rightShapeForm = $extractor->rationalFunction($right->arguments[$shapeIndex]);
                    $shapeDifference = $extractor->rationalDifference(
                        $left->arguments[$shapeIndex],
                        $right->arguments[$shapeIndex],
                    );
                    if (
                        $leftShapeForm === null
                        || $rightShapeForm === null
                        || $shapeDifference === null
                        || !$this->isZeroCoefficientList($shapeDifference[0])
                    ) {
                        return null;
                    }
                    $numeratorSign = $this->polynomialCertifiedGlobalSign($leftShapeForm[0]);
                    $denominatorSign = $this->polynomialCertifiedGlobalSign($leftShapeForm[1]);
                    if ($numeratorSign === null || $numeratorSign !== $denominatorSign) {
                        return null;
                    }

                    continue;
                }
                $leftShape = $extractor->polynomial($left->arguments[$shapeIndex]);
                $rightShape = $extractor->polynomial($right->arguments[$shapeIndex]);
                if (
                    $leftShape === null
                    || $rightShape === null
                    || $leftShape !== $rightShape
                ) {
                    return null;
                }
                if (\count($leftShape) === 1 && $this->compareRationalFractions($leftShape[0], ['0', '1']) <= 0) {
                    return [];
                }
                $inverseQuantileShapePolynomials[] = $leftShape;
            }
        }
        $globallyInjectiveFamilies = [
            ['ln'],
            ['log1p'],
            ['acosh', 'arccosh'],
            ['atanh', 'arctanh'],
            ['acoth'],
            ['asech'],
            ['acsch'],
            ['csch'],
            ['coth'],
            ['asin', 'arcsin'],
            ['acos', 'arccos'],
            ['exp'],
            ['expm1'],
            ['sinh'],
            ['tanh'],
            ['erf'],
            ['erfc'],
            ['erfcx'],
            ['gammainc'],
            ['gammaincc'],
            ['betainc'],
            ['betaincc'],
            ['asinh', 'arcsinh'],
            ['atan', 'arctan'],
        ];
        $sameGloballyInjectiveFamily = false;
        foreach ($globallyInjectiveFamilies as $family) {
            if (\in_array($left->name, $family, true) && \in_array($right->name, $family, true)) {
                $sameGloballyInjectiveFamily = true;
                break;
            }
        }
        $leftDomainArgument = null;
        if (
            $sameGloballyInjectiveFamily
            || $sameLogarithmBase
            || $differentFixedLogarithmBases
            || $variableLogarithmBase
        ) {
            $domainArgumentForms = null;
            $argumentDomain = null;
            $rightDomainArgument = null;
            $leftRationalArgument = $left->arguments[$argumentIndex];
            $rightRationalArgument = $right->arguments[$argumentIndex];
            if ($left->name === 'log1p') {
                $leftRationalArgument = new BinaryOperationNode(
                    BinaryOperator::Add,
                    $leftRationalArgument,
                    new NumberNode(1, '1', $leftRationalArgument->span()),
                    $leftRationalArgument->span(),
                );
            }
            if ($right->name === 'log1p') {
                $rightRationalArgument = new BinaryOperationNode(
                    BinaryOperator::Add,
                    $rightRationalArgument,
                    new NumberNode(1, '1', $rightRationalArgument->span()),
                    $rightRationalArgument->span(),
                );
            }
            if (\in_array($left->name, ['ln', 'log', 'log10', 'log2', 'log1p'], true)) {
                $leftDomainArgument = $this->logarithmArgumentDomainNode(
                    $leftRationalArgument,
                    $maxPolynomialDegree,
                );
                $rightDomainArgument = $this->logarithmArgumentDomainNode(
                    $rightRationalArgument,
                    $maxPolynomialDegree,
                );
                if ($leftDomainArgument === null || $rightDomainArgument === null) {
                    return null;
                }
                $leftArgumentForm = $extractor->rationalFunction($leftDomainArgument);
                $rightArgumentForm = $extractor->rationalFunction($rightDomainArgument);
                if ($leftArgumentForm === null || $rightArgumentForm === null) {
                    return null;
                }
                $domainArgumentForms = [];
                $domainArgumentForms[] = $leftArgumentForm;
                $domainArgumentForms[] = $rightArgumentForm;
