                            $canonicalInverseProbabilityPolynomial[0],
                            ['0', '1'],
                        ) === 0
                    ) {
                        throw new InfiniteSolutionSetException(
                            'The inverse gamma quantile equation has infinitely many real roots.',
                        );
                    }
                    if (
                        $this->compareRationalFractions(
                            $canonicalInverseProbabilityPolynomial[0],
                            ['1', '1'],
                        ) === 0
                    ) {
                        return [];
                    }
                }
                foreach ([['0', '1'], ['1', '1'], ['-1', '1'], ['1', '2']] as $point) {
                    $domainValue = $this->evaluateRationalPolynomialAt($domainPolynomial, $point);
                    if ($domainValue === null) {
                        return null;
                    }
                    if ($domainValue->compareLowerToRational('0', '1') > 0) {
                        throw new InfiniteSolutionSetException(
                            'The inverse quantile equation has infinitely many real roots.',
                        );
                    }
                }

                return null;
            }
            if (!$sameLogarithmFamily) {
                return null;
            }
            if ($variableLogarithmBase) {
                if ($logBasePolynomial === null || $logBaseMinusOnePolynomial === null) {
                    return null;
                }
                foreach ([['0', '1'], ['1', '1'], ['-1', '1'], ['1', '2'], ['-1', '2']] as $point) {
                    $validPoint = true;
                    foreach ($domainArgumentForms ?? [] as [$numerator, $denominator]) {
                        $numeratorValue = $this->evaluateRationalPolynomialAt($numerator, $point);
                        $denominatorValue = $this->evaluateRationalPolynomialAt($denominator, $point);
                        if (
                            $numeratorValue === null
                            || $denominatorValue === null
                            || $denominatorValue->compareLowerToRational('0', '1') === 0
                            || $numeratorValue->compareLowerToRational('0', '1') <= 0
                        ) {
                            $validPoint = false;
                            break;
                        }
                    }
                    $baseValue = $this->evaluateRationalPolynomialAt($logBasePolynomial, $point);
                    $baseMinusOneValue = $this->evaluateRationalPolynomialAt($logBaseMinusOnePolynomial, $point);
                    if (
                        $validPoint
                        && $baseValue !== null
                        && $baseValue->compareLowerToRational('0', '1') > 0
                        && $baseMinusOneValue !== null
                        && $baseMinusOneValue->compareLowerToRational('0', '1') !== 0
                    ) {
                        throw new InfiniteSolutionSetException(
                            'The variable-base logarithmic equation has infinitely many real roots.',
                        );
                    }
                }

                return null;
            }
            foreach ([['0', '1'], ['1', '1'], ['-1', '1']] as $point) {
                $domainValue = $this->evaluateRationalPolynomialAt($domainPolynomial, $point);
                if ($domainValue === null) {
                    return null;
                }
                if ($domainValue->compareLowerToRational('0', '1') > 0) {
                    throw new InfiniteSolutionSetException(
                        'The logarithmic equation has infinitely many real roots.',
                    );
                }
            }

            return \count($domainPolynomial) === 1 ? [] : null;
        }
        if ($variableLogarithmBase && ($logBasePolynomial === null || $logBaseMinusOnePolynomial === null)) {
            return false;
        }

        $counter = new ExactPolynomialRootCounter();
        $commonRootCount = $counter->countCommonRealRoots($difference, $argumentIntegerPolynomial);
        if ($commonRootCount === null) {
            return false;
        }
        $asechZeroBoundaryCount = 0;
        $asechOneBoundaryCount = 0;
        $asechArgumentPolynomial = null;
        if ($left->name === 'asech') {
            $asechArgumentPolynomial = $extractor->polynomial($left->arguments[0]);
            $zeroBoundaryPolynomial = $extractor->difference(
                $left->arguments[0],
                new NumberNode(0, '0', $left->arguments[0]->span()),
            );
            $oneBoundaryPolynomial = $extractor->difference(
                $left->arguments[0],
                new NumberNode(1, '1', $left->arguments[0]->span()),
            );
            if (
                $asechArgumentPolynomial === null
                || $zeroBoundaryPolynomial === null
                || $oneBoundaryPolynomial === null
            ) {
                return false;
            }
            $asechZeroBoundaryCount = $counter->countCommonRealRoots($difference, $zeroBoundaryPolynomial);
            $asechOneBoundaryCount = $counter->countCommonRealRoots($difference, $oneBoundaryPolynomial);
            if ($asechZeroBoundaryCount === null || $asechOneBoundaryCount === null) {
                return false;
            }
        }
        $currentWidth = $maximumWidth;
        for ($attempt = 0; $attempt < 12; ++$attempt) {
            $rawIntervals = $counter->isolateAllRealRoots($difference, $maxDepth, $currentWidth);
            if ($rawIntervals === null) {
                return false;
            }
            $validIntervals = [];
            $ambiguousIntervals = 0;
            $shapeAmbiguousIntervals = 0;
            $asechZeroBoundaries = 0;
            $asechOneBoundaries = 0;
            $asechUnclassifiedBoundaries = 0;
            foreach ($rawIntervals as [$lowerNumerator, $lowerDenominator, $upperNumerator, $upperDenominator]) {
                $range = $this->evaluateRationalPolynomialOnInterval(
                    $domainPolynomial,
                    new ExactRationalInterval(
                        [$lowerNumerator, $lowerDenominator],
                        [$upperNumerator, $upperDenominator],
                    ),
                );
                if ($range === null) {
                    return false;
                }
                if ($inverseQuantileShapePolynomials !== []) {
                    $rootInterval = new ExactRationalInterval(
                        [$lowerNumerator, $lowerDenominator],
                        [$upperNumerator, $upperDenominator],
                    );
                    $shapeIsInvalid = false;
                    $shapeIsAmbiguous = false;
                    foreach ($inverseQuantileShapePolynomials as $shapePolynomial) {
                        $shapeRange = $this->evaluateRationalPolynomialOnInterval(
                            $shapePolynomial,
                            $rootInterval,
                        );
                        if ($shapeRange === null) {
                            return false;
                        }
                        if ($shapeRange->compareUpperToRational('0', '1') <= 0) {
                            $shapeIsInvalid = true;
                            break;
                        }
                        if ($shapeRange->compareLowerToRational('0', '1') <= 0) {
                            $shapeIsAmbiguous = true;
                        }
                    }
                    if ($shapeIsInvalid) {
                        continue;
                    }
                    if ($shapeIsAmbiguous) {
                        ++$ambiguousIntervals;
                        ++$shapeAmbiguousIntervals;
                        continue;
                    }
                }
                if ($variableLogarithmBase) {
                    $interval = new ExactRationalInterval(
                        [$lowerNumerator, $lowerDenominator],
                        [$upperNumerator, $upperDenominator],
                    );
                    $baseRange = $this->evaluateRationalPolynomialOnInterval($logBasePolynomial, $interval);
                    $baseMinusOneRange = $this->evaluateRationalPolynomialOnInterval(
                        $logBaseMinusOnePolynomial,
                        $interval,
                    );
                    if ($baseRange === null || $baseMinusOneRange === null) {
                        return false;
                    }
                    if (
                        $this->compareRationalFractions($range->upper, ['0', '1']) <= 0
                        || $this->compareRationalFractions($baseRange->upper, ['0', '1']) <= 0
                        || (
                            $baseMinusOneRange->lower === ['0', '1']
                            && $baseMinusOneRange->upper === ['0', '1']
                        )
                    ) {
                        continue;
                    }
                    $positiveArgument = $this->compareRationalFractions($range->lower, ['0', '1']) > 0;
                    $positiveBase = $this->compareRationalFractions($baseRange->lower, ['0', '1']) > 0;
                    $baseNotOne = $this->compareRationalFractions($baseMinusOneRange->upper, ['0', '1']) < 0
                        || $this->compareRationalFractions($baseMinusOneRange->lower, ['0', '1']) > 0;
                    if ($positiveArgument && $positiveBase && $baseNotOne) {
                        $validIntervals[] = new RationalRootInterval(
                            $lowerNumerator,
                            $lowerDenominator,
                            $upperNumerator,
                            $upperDenominator,
                            $lowerNumerator === $upperNumerator && $lowerDenominator === $upperDenominator,
                        );
                    } else {
                        ++$ambiguousIntervals;
                    }

                    continue;
                }
                if ($range->lower[0] !== '0' && $range->lower[0][0] !== '-') {
                    $validIntervals[] = new RationalRootInterval(
                        $lowerNumerator,
                        $lowerDenominator,
                        $upperNumerator,
                        $upperDenominator,
                        $lowerNumerator === $upperNumerator && $lowerDenominator === $upperDenominator,
                    );
                } elseif ($range->upper[0] !== '0' && $range->upper[0][0] === '-') {
                    continue;
                } else {
                    ++$ambiguousIntervals;
                    if (
                        \in_array(
                            $left->name,
                            [
                                'sqrt', 'acosh', 'arccosh', 'asec', 'acsc', 'asin', 'arcsin', 'acos', 'arccos',
                                'betaincinv', 'betainccinv',
                            ],
                            true,
                        )
                        || (
                            $left->name === 'root'
                            && $leftRootDegree !== null
                            && $leftRootDegree > 0
                            && $leftRootDegree % 2 === 0
                        )
                    ) {
                        $validIntervals[] = new RationalRootInterval(
                            $lowerNumerator,
                            $lowerDenominator,
                            $upperNumerator,
                            $upperDenominator,
                            $lowerNumerator === $upperNumerator && $lowerDenominator === $upperDenominator,
                        );
                    } elseif (
                        $inverseGammaQuantile
                        && $canonicalInverseProbabilityPolynomial !== null
                    ) {
                        $probabilityRange = $this->evaluateRationalPolynomialOnInterval(
                            $canonicalInverseProbabilityPolynomial,
                            new ExactRationalInterval(
                                [$lowerNumerator, $lowerDenominator],
                                [$upperNumerator, $upperDenominator],
                            ),
                        );
                        if ($probabilityRange === null) {
                            return false;
                        }
                        if (
                            $probabilityRange->lower === ['0', '1']
                            && $probabilityRange->upper === ['0', '1']
                        ) {
                            $validIntervals[] = new RationalRootInterval(
                                $lowerNumerator,
                                $lowerDenominator,
                                $upperNumerator,
                                $upperDenominator,
                                $lowerNumerator === $upperNumerator && $lowerDenominator === $upperDenominator,
                            );
                        }
                    } elseif ($left->name === 'asech') {
                        $argumentRange = $this->evaluateRationalPolynomialOnInterval(
                            $asechArgumentPolynomial,
                            new ExactRationalInterval(
                                [$lowerNumerator, $lowerDenominator],
                                [$upperNumerator, $upperDenominator],
                            ),
                        );
                        if ($argumentRange === null) {
                            return false;
                        }
                        if ($this->compareRationalFractions($argumentRange->upper, ['1', '2']) <= 0) {
                            ++$asechZeroBoundaries;
                        } elseif ($this->compareRationalFractions($argumentRange->lower, ['1', '2']) >= 0) {
                            ++$asechOneBoundaries;
                            $validIntervals[] = new RationalRootInterval(
                                $lowerNumerator,
                                $lowerDenominator,
                                $upperNumerator,
                                $upperDenominator,
                                $lowerNumerator === $upperNumerator && $lowerDenominator === $upperDenominator,
                            );
                        } else {
                            ++$asechUnclassifiedBoundaries;
                        }
                    }
                }
            }
            if ($shapeAmbiguousIntervals > 0) {
                $widthInterval = new ExactRationalInterval($currentWidth, $currentWidth);
                $currentWidth = $widthInterval
                    ->divide(new ExactRationalInterval(['10', '1'], ['10', '1']))
                    ->lower;
                continue;
            }
            if ($variableLogarithmBase && $ambiguousIntervals === 0) {
                return $validIntervals;
            }
            if ($ambiguousIntervals === $commonRootCount) {
                if (
                    $left->name === 'asech'
                    && (
                        $asechZeroBoundaries !== $asechZeroBoundaryCount
                        || $asechOneBoundaries !== $asechOneBoundaryCount
                        || $asechUnclassifiedBoundaries !== 0
                    )
                ) {
                    $widthInterval = new ExactRationalInterval($currentWidth, $currentWidth);
                    $currentWidth = $widthInterval
                        ->divide(new ExactRationalInterval(['10', '1'], ['10', '1']))
                        ->lower;
                    continue;
                }

                return $validIntervals;
            }
            if ($ambiguousIntervals < $commonRootCount) {
                return false;
            }

            $widthInterval = new ExactRationalInterval($currentWidth, $currentWidth);
            $currentWidth = $widthInterval
                ->divide(new ExactRationalInterval(['10', '1'], ['10', '1']))
                ->lower;
        }

        return false;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return array{list<string>, list<string>}|false|null
     * @param AffineRationalPowerTransform|null $rationalPowerTransform
     * @param-out AffineRationalPowerTransform|null $rationalPowerTransform
     */
    private function directEquationPolynomial(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
        bool $allowHigherDegreeNonAffinePowerCounts = false,
        ?array &$rationalPowerTransform = null,
    ): array|false|null {
        $leftAbsolute = $this->unwrapGrouping($left);
        $rightAbsolute = $this->unwrapGrouping($right);
        $leftNormSquared = $this->nonnegativeNormSquared($leftAbsolute, $evaluationOptions);
        $rightNormSquared = $this->nonnegativeNormSquared($rightAbsolute, $evaluationOptions);
        if ($leftNormSquared !== null && $rightNormSquared !== null) {
            return (new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            ))->rationalDifference($leftNormSquared, $rightNormSquared);
        }
        $equivalentOddRadicalArguments = $this->equivalentOddRadicalArguments(
            $leftAbsolute,
            $rightAbsolute,
            $variable,
            $parameters,
            $evaluationOptions,
            $maxPolynomialDegree,
        );
        if ($equivalentOddRadicalArguments !== null) {
            return (new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            ))->rationalDifference(
                $equivalentOddRadicalArguments[0],
                $equivalentOddRadicalArguments[1],
            );
        }
        $rationalPowerEquation = $this->rationalPowerEquation(
            $leftAbsolute,
            $rightAbsolute,
            $variable,
            $parameters,
            $evaluationOptions,
            $maxPolynomialDegree,
        );
        if ($rationalPowerEquation !== null) {
            return $rationalPowerEquation;
        }
        $rationalPowerSum = $this->sameBaseRationalPowerZeroSum(
            $leftAbsolute,
            $rightAbsolute,
            $variable,
            $parameters,
            $evaluationOptions,
            $maxPolynomialDegree,
            $allowHigherDegreeNonAffinePowerCounts,
            $rationalPowerTransform,
        );
        if ($rationalPowerSum !== null) {
            return $rationalPowerSum;
        }
        $nestedRadical = $this->nestedRadicalArguments(
            $leftAbsolute,
            $rightAbsolute,
            $variable,
            $parameters,
            $evaluationOptions,
            $maxPolynomialDegree,
        );
        if ($nestedRadical === false) {
            return false;
        }
        if ($nestedRadical !== null) {
            return (new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            ))->rationalDifferenceFromFraction($nestedRadical[0], $nestedRadical[1]);
        }
        $exponentialTangentArguments = $this->exponentialTangentEqualityArguments(
            $leftAbsolute,
            $rightAbsolute,
            $variable,
            $parameters,
            $evaluationOptions,
            $maxPolynomialDegree,
        );
        if ($exponentialTangentArguments !== null) {
            $zero = new NumberNode(0, '0', $exponentialTangentArguments->span());

            return (new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            ))->rationalDifference($exponentialTangentArguments, $zero);
        }
        $exponentialTaylorArgument = $this->exponentialTaylorEqualityArgument(
            $leftAbsolute,
            $rightAbsolute,
            $variable,
            $parameters,
            $evaluationOptions,
            $maxPolynomialDegree,
        );
        if ($exponentialTaylorArgument !== null) {
            $zero = new NumberNode(0, '0', $exponentialTaylorArgument->span());

            return (new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            ))->rationalDifference($exponentialTaylorArgument, $zero);
        }
        $hyperbolicTaylorArgument = $this->hyperbolicTaylorEqualityArgument(
            $leftAbsolute,
            $rightAbsolute,
            $variable,
            $parameters,
            $evaluationOptions,
            $maxPolynomialDegree,
        );
        if ($hyperbolicTaylorArgument !== null) {
            $zero = new NumberNode(0, '0', $hyperbolicTaylorArgument->span());

            return (new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            ))->rationalDifference($hyperbolicTaylorArgument, $zero);
        }
        $trigonometricTaylorArgument = $this->trigonometricTaylorEqualityArgument(
            $leftAbsolute,
            $rightAbsolute,
            $variable,
            $parameters,
            $evaluationOptions,
            $maxPolynomialDegree,
        );
        if ($trigonometricTaylorArgument !== null) {
            $zero = new NumberNode(0, '0', $trigonometricTaylorArgument->span());

            return (new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            ))->rationalDifference($trigonometricTaylorArgument, $zero);
        }
        if (
            $this->isImpossibleRealFixedPointEquation(
                $leftAbsolute,
                $rightAbsolute,
                $variable,
                $parameters,
                $evaluationOptions,
                $maxPolynomialDegree,
            )
        ) {
            return false;
        }
        $zeroOnlyFixedPointArgument = $this->zeroOnlyFixedPointArgument(
            $leftAbsolute,
            $rightAbsolute,
            $variable,
            $parameters,
            $evaluationOptions,
            $maxPolynomialDegree,
        );
        if ($zeroOnlyFixedPointArgument !== null) {
            $zero = new NumberNode(0, '0', $zeroOnlyFixedPointArgument->span());

            return (new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            ))->rationalDifference($zeroOnlyFixedPointArgument, $zero);
        }
        $inverseComposition = $this->inverseCompositionArguments($leftAbsolute, $rightAbsolute);
        if ($inverseComposition === false) {
            return false;
        }
        if ($inverseComposition !== null) {
            return (new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            ))->rationalDifference($inverseComposition[0], $inverseComposition[1]);
        }
        $logarithmDifference = $this->logarithmDifferenceWithConstantArguments(
            $leftAbsolute,
            $rightAbsolute,
        );
        if ($logarithmDifference === false) {
            return false;
        }
        if ($logarithmDifference !== null) {
            return (new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            ))->rationalDifference($logarithmDifference[0], $logarithmDifference[1]);
        }
        $logEquality = $this->logEqualityWithConstantArgument(
            $leftAbsolute,
            $rightAbsolute,
        );
        if ($logEquality === false) {
            return false;
        }
        if ($logEquality !== null) {
            return (new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            ))->rationalDifference($logEquality[0], $logEquality[1]);
        }
        $oddFunctionEquality = $this->oddFunctionEqualityArguments($leftAbsolute, $rightAbsolute);
        if ($oddFunctionEquality !== null) {
            return (new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            ))->rationalSum($oddFunctionEquality[0], $oddFunctionEquality[1]);
        }
        $oddFunctionArguments = $this->oddFunctionSumArguments($leftAbsolute, $rightAbsolute);
        if ($oddFunctionArguments !== null) {
            return (new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            ))->rationalSum($oddFunctionArguments[0], $oddFunctionArguments[1]);
        }
        $complementaryArguments = $this->complementaryInverseTangentArguments(
            $leftAbsolute,
            $rightAbsolute,
        );
        if ($complementaryArguments !== null) {
            return (new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            ))->rationalDifference($complementaryArguments[0], $complementaryArguments[1]);
        }
        $complementaryErrorArguments = $this->complementaryErrorArguments(
            $leftAbsolute,
            $rightAbsolute,
        );
        if ($complementaryErrorArguments !== null) {
            return (new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            ))->rationalDifference(
                $complementaryErrorArguments[0],
                $complementaryErrorArguments[1],
            );
        }
        if (
            $leftAbsolute instanceof FunctionCallNode
            && $rightAbsolute instanceof FunctionCallNode
            && $leftAbsolute->name === 'sech'
            && $rightAbsolute->name === 'sech'
            && \count($leftAbsolute->arguments) === 1
            && \count($rightAbsolute->arguments) === 1
        ) {
            return (new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            ))->absoluteRationalDifference(
                $leftAbsolute->arguments[0],
                $rightAbsolute->arguments[0],
            );
        }
        if (
            $leftAbsolute instanceof FunctionCallNode
            && $rightAbsolute instanceof FunctionCallNode
            && $this->sameStrictlyMonotoneFunction(
                $leftAbsolute->name,
                $rightAbsolute->name,
            )
            && \count($leftAbsolute->arguments) === 1
            && \count($rightAbsolute->arguments) === 1
        ) {
            return (new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            ))->rationalDifference($leftAbsolute->arguments[0], $rightAbsolute->arguments[0]);
        }
        if (
            $leftAbsolute instanceof FunctionCallNode
            && $leftAbsolute->name === 'abs'
            && \count($leftAbsolute->arguments) === 1
            && $rightAbsolute instanceof FunctionCallNode
            && $rightAbsolute->name === 'abs'
            && \count($rightAbsolute->arguments) === 1
        ) {
            $extractor = new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            );
            $leftInner = $this->unwrapGrouping($leftAbsolute->arguments[0]);
            $rightInner = $this->unwrapGrouping($rightAbsolute->arguments[0]);
            $absoluteRootEquation = $this->absoluteRationalPowerEquation(
                $leftInner,
                $rightInner,
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            );
            if ($absoluteRootEquation !== null) {
                return $absoluteRootEquation;
            }
            if (
                $leftInner instanceof FunctionCallNode
                && $rightInner instanceof FunctionCallNode
                && \count($leftInner->arguments) === 1
                && \count($rightInner->arguments) === 1
                && $this->sameOddStrictlyMonotoneFunction($leftInner->name, $rightInner->name)
            ) {
                return $extractor->absoluteRationalDifference(
                    $leftInner->arguments[0],
                    $rightInner->arguments[0],
                );
            }
            if (
                $leftInner instanceof FunctionCallNode
                && $rightInner instanceof FunctionCallNode
                && \count($leftInner->arguments) === 1
                && \count($rightInner->arguments) === 1
                && $this->sameNonzeroOddAbsoluteInjectiveFunction(
                    $leftInner->name,
                    $rightInner->name,
                )
            ) {
                return $extractor->absoluteRationalDifference(
                    $leftInner->arguments[0],
                    $rightInner->arguments[0],
                    true,
                );
            }
            if (
                $leftInner instanceof FunctionCallNode
                && $rightInner instanceof FunctionCallNode
                && \count($leftInner->arguments) === 1
                && \count($rightInner->arguments) === 1
                && $this->samePositiveEvenFunction($leftInner->name, $rightInner->name)
            ) {
                return $extractor->absoluteRationalDifference(
                    $leftInner->arguments[0],
                    $rightInner->arguments[0],
                );
            }
            if (
                $leftInner instanceof FunctionCallNode
                && $rightInner instanceof FunctionCallNode
                && \count($leftInner->arguments) === 1
                && \count($rightInner->arguments) === 1
                && $this->samePositiveStrictlyMonotoneFunction($leftInner->name, $rightInner->name)
            ) {
                return $extractor->rationalDifference(
                    $leftInner->arguments[0],
                    $rightInner->arguments[0],
                );
            }

            return $extractor->absoluteRationalDifference(
                $leftAbsolute->arguments[0],
                $rightAbsolute->arguments[0],
            );
        }

        $absoluteCall = $leftAbsolute instanceof FunctionCallNode
            && $leftAbsolute->name === 'abs'
            && \count($leftAbsolute->arguments) === 1
                ? $leftAbsolute
                : ($rightAbsolute instanceof FunctionCallNode
                    && $rightAbsolute->name === 'abs'
                    && \count($rightAbsolute->arguments) === 1
                    ? $rightAbsolute
                    : null);
        if ($absoluteCall !== null) {
            $targetNode = $absoluteCall === $leftAbsolute ? $right : $left;
            $extractor = new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            );
            $target = $extractor->polynomial($targetNode);
            if ($target !== null && \count($target) === 1) {
                $targetSign = (new ExactRationalInterval($target[0], $target[0]))
                    ->compareLowerToRational('0', '1');
                if ($targetSign < 0) {
                    return false;
                }
                if ($targetSign === 0) {
                    $absolutePowerZeroEquation = $this->absoluteRationalPowerZeroLevelEquation(
                        $absoluteCall->arguments[0],
                        $targetNode,
                        $extractor,
                        $maxPolynomialDegree,
                        $evaluationOptions,
                    );
                    if ($absolutePowerZeroEquation !== null) {
                        return $absolutePowerZeroEquation;
                    }
                }

                return $extractor->absoluteRationalDifference(
                    $absoluteCall->arguments[0],
                    $targetNode,
                );
            }
        }

        foreach ([[$leftAbsolute, $right], [$rightAbsolute, $left]] as [$candidate, $targetNode]) {
            $extractor = new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            );
            $target = $extractor->polynomial($targetNode);
            if ($target === null || \count($target) !== 1) {
                continue;
            }
            if ($candidate instanceof FactorialNode && $target[0][0] === '0') {
                return false;
            }
            if (!$candidate instanceof FunctionCallNode) {
                continue;
            }
            $unitBoundFunction = \in_array($candidate->name, ['sin', 'cos', 'sinc', 'sincpi'], true)
                && \count($candidate->arguments) === 1;
            $boundaryRangeFunction = \in_array($candidate->name, ['exp', 'cosh', 'sech'], true)
                && \count($candidate->arguments) === 1;
            if ($target[0][0] !== '0' && !$unitBoundFunction && !$boundaryRangeFunction) {
                continue;
            }
            if ($unitBoundFunction) {
                $level = new ExactRationalInterval($target[0], $target[0]);
                if (
                    $level->compareLowerToRational('1', '1') > 0
                    || $level->compareUpperToRational('-1', '1') < 0
                ) {
                    if (
                        $this->constantTargetIsEvaluable($targetNode, $variable, $parameters, $evaluationOptions)
                        && $this->rationalPhaseIsEvaluable(
                            $candidate->arguments[0],
                            $extractor,
                            $variable,
                            $parameters,
                            $evaluationOptions,
                        )
                    ) {
                        return false;
                    }
                    continue;
                }
                if (
                    \in_array($candidate->name, ['sinc', 'sincpi'], true)
                    && $level->compareUpperToRational('-1', '1') === 0
                    && $this->constantTargetIsEvaluable($targetNode, $variable, $parameters, $evaluationOptions)
                ) {
                    $zero = new NumberNode(0, '0', $candidate->span());
                    $form = $extractor->rationalDifference($candidate->arguments[0], $zero);
                    $zeroPhase = new BinaryOperationNode(
                        BinaryOperator::Multiply,
                        $zero,
                        $candidate->arguments[0],
                        $candidate->span(),
                    );
                    if (
                        $form !== null && $this->validZeroRationalPhase(
                            $zeroPhase,
                            $form[1],
                            $evaluationOptions,
                            $variable,
                            $parameters,
                        )
                    ) {
                        return false;
                    }
                }
                if (
                    \in_array($candidate->name, ['sinc', 'sincpi'], true)
                    && $level->compareLowerToRational('1', '1') === 0
                ) {
                    return $extractor->rationalDifferenceFromFraction(
                        $candidate->arguments[0],
                        ['0', '1'],
                    );
                }
            }
            if ($boundaryRangeFunction) {
                $level = new ExactRationalInterval($target[0], $target[0]);
                $isUnitLevel = $level->compareLowerToRational('1', '1') === 0;
                if (
                    ($candidate->name === 'exp' && $level->compareUpperToRational('0', '1') <= 0)
                    || ($candidate->name === 'cosh' && $level->compareUpperToRational('1', '1') < 0)
                    || (
                        $candidate->name === 'sech'
                        && (
                            $level->compareUpperToRational('0', '1') <= 0
                            || $level->compareLowerToRational('1', '1') > 0
                        )
                    )
                ) {
                    if (
                        $this->constantTargetIsEvaluable($targetNode, $variable, $parameters, $evaluationOptions)
                        && $this->rationalPhaseIsEvaluable(
                            $candidate->arguments[0],
                            $extractor,
                            $variable,
                            $parameters,
                            $evaluationOptions,
                        )
                    ) {
                        return false;
                    }
                    continue;
                }
                if ($isUnitLevel) {
                    return $extractor->rationalDifferenceFromFraction(
                        $candidate->arguments[0],
                        ['0', '1'],
                    );
                }

                continue;
            }
            $zeroLevel = $this->exactZeroLevelFunction($candidate, $extractor, $evaluationOptions);
            if (\is_array($zeroLevel)) {
                return $extractor->rationalDifferenceFromFraction($zeroLevel[0], $zeroLevel[1]);
            }
            if ($zeroLevel === false) {
                if (
                    (!$this->constantTargetIsEvaluable($targetNode, $variable, $parameters, $evaluationOptions)
                        || !$this->rationalPhaseIsEvaluable(
                            $candidate->arguments[0],
                            $extractor,
                            $variable,
                            $parameters,
                            $evaluationOptions,
                        ))
                ) {
                    continue;
                }
                return false;
            }
        }

        return $this->directRationalPowerPolynomial(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            $maxPolynomialDegree,
        );
    }

    /**
     * Reduce real rational powers with odd denominators to an exact rational equation.
     * Raising both sides by the product of the denominators is reversible.
     *
     * @param array<string, int|float> $parameters
     * @return array{list<string>, list<string>}|false|null False means an identically undefined reciprocal power.
     */
    private function rationalPowerEquation(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
    ): array|false|null {
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        $leftPowers = $this->rationalPowerMonomial($left, $extractor, $maxPolynomialDegree);
        $rightPowers = $this->rationalPowerMonomial($right, $extractor, $maxPolynomialDegree);
        if ($leftPowers === null || $rightPowers === null) {
            return null;
        }
        $commonDenominator = 1;
        foreach ([...$leftPowers, ...$rightPowers] as [, , $denominator]) {
            $multiple = \intdiv($commonDenominator, $this->integerGcd($commonDenominator, $denominator));
            if ($multiple > \intdiv(\PHP_INT_MAX, $denominator)) {
                return null;
            }
            $commonDenominator = $multiple * $denominator;
        }
        $leftFactors = $this->integerPowerFactors($leftPowers, $commonDenominator, $maxPolynomialDegree);
        $rightFactors = $this->integerPowerFactors($rightPowers, $commonDenominator, $maxPolynomialDegree);
        if ($leftFactors === null || $rightFactors === null) {
            return null;
        }

        return $extractor->rationalMonomialDifference($leftFactors, $rightFactors);
    }

    /**
     * Resolve a zero-sum of two same-sign rational powers of one rational function.
     *
     * @param array<string, int|float> $parameters
     * @return array{list<string>, list<string>}|false|null
     * @param AffineRationalPowerTransform|null $rationalPowerTransform
     * @param-out AffineRationalPowerTransform|null $rationalPowerTransform
     */
    private function sameBaseRationalPowerZeroSum(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
        bool $allowHigherDegreeNonAffinePowerCounts,
        ?array &$rationalPowerTransform = null,
    ): array|false|null {
        foreach ([[$left, $right], [$right, $left]] as [$sumNode, $zeroNode]) {
            $sumNode = $this->unwrapGrouping($sumNode);
            $zeroNode = $this->unwrapGrouping($zeroNode);
            if (
                !$sumNode instanceof BinaryOperationNode
                || !\in_array($sumNode->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)
                || RationalLiteral::fromNodeAsStrings($zeroNode) !== ['0', '1']
            ) {
                continue;
            }
            $extractor = new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            );
            $multiTermPowerSum = $this->sameVariableRationalPowerPolynomialZeroSum(
                $sumNode,
                $maxPolynomialDegree,
                $extractor,
                $allowHigherDegreeNonAffinePowerCounts,
                $rationalPowerTransform,
            );
            if ($multiTermPowerSum !== null) {
                return $multiTermPowerSum;
            }
            $first = $this->rationalPowerTerm($sumNode->left, $extractor, $maxPolynomialDegree);
            $second = $this->rationalPowerTerm($sumNode->right, $extractor, $maxPolynomialDegree);
            if ($first === null) {
                $firstAtom = $this->rationalPowerAtom($sumNode->left, $extractor, $maxPolynomialDegree);
                $first = $firstAtom === null ? null : [...$firstAtom, 1, ['1', '1']];
            }
            if ($second === null) {
                $secondAtom = $this->rationalPowerAtom($sumNode->right, $extractor, $maxPolynomialDegree);
                $second = $secondAtom === null ? null : [...$secondAtom, 1, ['1', '1']];
            }
            if ($first === null || $second === null) {
                continue;
            }
            [$firstBase, $firstNumerator, $firstDenominator, $firstCoefficientSign, $firstCoefficient] = $first;
            [$secondBase, $secondNumerator, $secondDenominator, $secondCoefficientSign, $secondCoefficient] = $second;
            if ($sumNode->operator === BinaryOperator::Subtract) {
                $secondCoefficientSign = -$secondCoefficientSign;
            }
            $sameBase = $extractor->rationalDifference($firstBase, $secondBase);
            if (
                $sameBase === null
                || \array_filter(
                    $sameBase[0],
                    static fn (string $coefficient): bool => $coefficient !== '0',
                ) !== []
            ) {
                continue;
            }
            $signedFirstCoefficient = $firstCoefficient === null
                ? null
                : $extractor->multiplyExactFractions($firstCoefficient, [(string) $firstCoefficientSign, '1']);
            $signedSecondCoefficient = $secondCoefficient === null
                ? null
                : $extractor->multiplyExactFractions($secondCoefficient, [(string) $secondCoefficientSign, '1']);
            if ($signedFirstCoefficient === null || $signedSecondCoefficient === null) {
                continue;
            }
            $denominatorMultiple = \intdiv(
                $firstDenominator,
                $this->integerGcd($firstDenominator, $secondDenominator),
            );
            if ($denominatorMultiple > \intdiv(\PHP_INT_MAX, $secondDenominator)) {
                continue;
            }
            $commonDenominator = $denominatorMultiple * $secondDenominator;
            $firstIntegerPower = $firstNumerator * \intdiv($commonDenominator, $firstDenominator);
            $secondIntegerPower = $secondNumerator * \intdiv($commonDenominator, $secondDenominator);
            $powerDifference = \abs($firstIntegerPower - $secondIntegerPower);
            if ($powerDifference > $maxPolynomialDegree) {
                continue;
            }
            if ($powerDifference === 0) {
                $coefficientSum = $extractor->addExactFractions(
                    $signedFirstCoefficient,
                    $signedSecondCoefficient,
                );
                if ($coefficientSum === null) {
                    continue;
                }
                if ($coefficientSum[0] === '0') {
                    return $extractor->rationalMonomialDifference(
                        [[$firstBase, $firstIntegerPower]],
                        [[$secondBase, $secondIntegerPower]],
                    );
                }
                if ($firstIntegerPower < 0) {
                    return false;
                }

                return $extractor->rationalZeroWithDomains($firstBase, [$secondBase]);
            }
            $lowerCoefficient = $firstIntegerPower < $secondIntegerPower
                ? $signedFirstCoefficient
                : $signedSecondCoefficient;
            $higherCoefficient = $firstIntegerPower > $secondIntegerPower
                ? $signedFirstCoefficient
                : $signedSecondCoefficient;
            $coefficientRatio = $extractor->multiplyExactFractions(
                $lowerCoefficient,
                [$higherCoefficient[1], $higherCoefficient[0]],
            );
            if ($coefficientRatio === null || $coefficientRatio[0] === '0') {
                continue;
            }
            $coefficientRatio = $extractor->multiplyExactFractions($coefficientRatio, ['-1', '1']);
            if ($coefficientRatio === null) {
                continue;
            }
            $level = $extractor->powerExactFraction($coefficientRatio, $commonDenominator);
            if ($level === null) {
                continue;
            }
            if (($powerDifference % 2) === 0 && $level[0][0] === '-') {
                if (\min($firstIntegerPower, $secondIntegerPower) <= 0) {
                    return false;
                }

                return $extractor->rationalZeroWithDomains($firstBase, [$secondBase]);
            }
            if ($level[0] === '0') {
                continue;
            }

            return $extractor->rationalPowerLevelEquation(
                $firstBase,
                $powerDifference,
                $level,
                \min($firstIntegerPower, $secondIntegerPower) > 0,
                [$secondBase],
            );
        }

        return null;
    }

    private function nonnegativeNormSquared(Node $node, EvaluationOptions $evaluationOptions): ?Node
    {
        $node = $this->unwrapGrouping($node);
        if (
            $node instanceof FunctionCallNode
            && $node->name === 'abs'
            && \count($node->arguments) === 1
            && $evaluationOptions->functions->isBuiltIn('abs')
        ) {
            $node = $this->unwrapGrouping($node->arguments[0]);
        }
        if (!$node instanceof FunctionCallNode) {
            return null;
        }
        if ($node->name === 'hypot' && \count($node->arguments) === 2) {
            if (!$evaluationOptions->functions->isBuiltIn('hypot')) {
                return null;
            }
            $leftSquare = new BinaryOperationNode(
                BinaryOperator::Power,
                $node->arguments[0],
                new NumberNode(2, '2', $node->arguments[0]->span()),
                $node->arguments[0]->span(),
            );
            $rightSquare = new BinaryOperationNode(
                BinaryOperator::Power,
                $node->arguments[1],
                new NumberNode(2, '2', $node->arguments[1]->span()),
                $node->arguments[1]->span(),
            );

            return new BinaryOperationNode(
                BinaryOperator::Add,
                $leftSquare,
                $rightSquare,
                $node->span,
            );
        }
        if (
            $node->name !== 'sqrt'
            || \count($node->arguments) !== 1
            || !$evaluationOptions->functions->isBuiltIn('sqrt')
        ) {
            return null;
        }
        $sum = $this->unwrapGrouping($node->arguments[0]);
        if ($sum instanceof BinaryOperationNode && $sum->operator === BinaryOperator::Add) {
            return $this->isStructurallyNonnegative($sum->left)
                && $this->isStructurallyNonnegative($sum->right)
                    ? $sum
                    : null;
        }

        return $this->isStructurallyNonnegative($sum) ? $sum : null;
    }

    private function isStructurallyNonnegative(
        Node $node,
        ?ExactRationalPolynomialExtractor $extractor = null,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if (
            $node instanceof BinaryOperationNode
            && $node->operator === BinaryOperator::Power
        ) {
            $exponent = RationalLiteral::fromNodeAsStrings($node->right);
            if (
                $exponent !== null
                && $exponent[1] === '1'
                && ((int) \substr($exponent[0], -1)) % 2 === 0
            ) {
                return true;
            }
        }
        if (
            $node instanceof BinaryOperationNode
            && \in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Multiply], true)
        ) {
            if ($node->operator === BinaryOperator::Add) {
                if (
                    $this->isStructurallyNonnegative($node->left, $extractor)
                    && $this->isStructurallyNonnegative($node->right, $extractor)
                ) {
                    return true;
                }
            }
            if (
                $node->operator === BinaryOperator::Multiply
                && (($this->isStructurallyNonnegative($node->left, $extractor)
                        && $this->isStructurallyNonnegative($node->right, $extractor))
                    || ($this->isStructurallyNonpositive($node->left, $extractor)
                        && $this->isStructurallyNonpositive($node->right, $extractor)))
            ) {
                return true;
            }
        }
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Divide) {
            $denominator = RationalLiteral::fromNodeAsStrings($node->right);
            $denominatorIsPositive = $denominator !== null
                ? (new ExactRationalInterval($denominator, $denominator))->compareLowerToRational('0', '1') > 0
                : false;
            if (!$denominatorIsPositive && $extractor !== null) {
                $denominatorPolynomial = $extractor->polynomial($node->right);
                $lowerBound = $denominatorPolynomial === null
                    ? null
                    : $this->polynomialGlobalLowerBound($denominatorPolynomial);
                $denominatorIsPositive = $lowerBound !== null
                    && (new ExactRationalInterval($lowerBound, $lowerBound))->compareLowerToRational('0', '1') > 0;
                if (!$denominatorIsPositive && $denominatorPolynomial !== null) {
                    $denominatorIsPositive = $this->polynomialIsGloballyPositive($denominatorPolynomial);
                }
            }

            if ($denominatorIsPositive && $this->isStructurallyNonnegative($node->left, $extractor)) {
                return true;
            }
        }
        $constant = RationalLiteral::fromNodeAsStrings($node);
        if ($constant !== null) {
            return (new ExactRationalInterval($constant, $constant))->compareLowerToRational('0', '1') >= 0;
        }
        if ($extractor === null) {
            return false;
        }
        $polynomial = $extractor->polynomial($node);
        $lowerBound = $polynomial === null ? null : $this->polynomialGlobalLowerBound($polynomial);
        if (
            $lowerBound !== null
            && (new ExactRationalInterval($lowerBound, $lowerBound))->compareLowerToRational('0', '1') >= 0
        ) {
            return true;
        }

        return $polynomial !== null && $this->polynomialIsGloballyNonnegative($polynomial);
    }

    private function isStructurallyNonpositive(
        Node $node,
        ?ExactRationalPolynomialExtractor $extractor = null,
    ): bool {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode && $node->operator === UnaryOperator::Minus) {
            return $this->isStructurallyNonnegative($node->operand, $extractor);
        }
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Multiply) {
            return ($this->isStructurallyNonnegative($node->left, $extractor)
                    && $this->isStructurallyNonpositive($node->right, $extractor))
                || ($this->isStructurallyNonpositive($node->left, $extractor)
                    && $this->isStructurallyNonnegative($node->right, $extractor));
        }
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Divide) {
            $denominator = RationalLiteral::fromNodeAsStrings($node->right);
            $denominatorIsPositive = $denominator !== null
                ? (new ExactRationalInterval($denominator, $denominator))->compareLowerToRational('0', '1') > 0
                : false;
            if (!$denominatorIsPositive && $extractor !== null) {
                $denominatorPolynomial = $extractor->polynomial($node->right);
                $lowerBound = $denominatorPolynomial === null
                    ? null
                    : $this->polynomialGlobalLowerBound($denominatorPolynomial);
                $denominatorIsPositive = $lowerBound !== null
                    && (new ExactRationalInterval($lowerBound, $lowerBound))->compareLowerToRational('0', '1') > 0;
                if (!$denominatorIsPositive && $denominatorPolynomial !== null) {
                    $denominatorIsPositive = $this->polynomialIsGloballyPositive($denominatorPolynomial);
                }
            }

            return $denominatorIsPositive && $this->isStructurallyNonpositive($node->left, $extractor);
        }
        $constant = RationalLiteral::fromNodeAsStrings($node);
        if ($constant !== null) {
            return (new ExactRationalInterval($constant, $constant))->compareUpperToRational('0', '1') <= 0;
        }
        if ($extractor === null) {
            return false;
        }
        $polynomial = $extractor->polynomial($node);
        if ($polynomial === null) {
            return false;
        }
        $negativePolynomial = [];
        foreach ($polynomial as $coefficient) {
            $negativePolynomial[] = (new ExactRationalInterval($coefficient, $coefficient))
                ->multiply(new ExactRationalInterval(['-1', '1'], ['-1', '1']))
                ->lower;
        }
        $lowerBound = $this->polynomialGlobalLowerBound($negativePolynomial);
        if (
            $lowerBound !== null
            && (new ExactRationalInterval($lowerBound, $lowerBound))->compareLowerToRational('0', '1') >= 0
        ) {
            return true;
        }

        return $this->polynomialIsGloballyNonnegative($negativePolynomial);
    }

    /** @param list<array{string, string}> $polynomial */
    private function polynomialIsGloballyNonnegative(array $polynomial): bool
    {
        $integerPolynomial = $this->integerPolynomialFromRational($polynomial);
        if ($integerPolynomial === null || $integerPolynomial === []) {
            return false;
        }
        while (\count($integerPolynomial) > 1 && $integerPolynomial[\array_key_last($integerPolynomial)] === '0') {
            \array_pop($integerPolynomial);
        }
        if (\count($integerPolynomial) === 1) {
            return (new ExactRationalInterval([$integerPolynomial[0], '1'], [$integerPolynomial[0], '1']))
                ->compareLowerToRational('0', '1') >= 0;
        }
        $degree = \count($integerPolynomial) - 1;
        if (
            $degree % 2 !== 0
            || (new ExactRationalInterval(
                [$integerPolynomial[$degree], '1'],
                [$integerPolynomial[$degree], '1'],
            ))->compareLowerToRational('0', '1') <= 0
        ) {
            return false;
        }

        try {
            $counter = new ExactPolynomialRootCounter();
            $rootIntervals = $counter->isolateAllRealRoots(
                $integerPolynomial,
                maxDepth: 512,
            );
            if ($rootIntervals === null) {
                return false;
            }
            if ($rootIntervals === []) {
                return $counter->signAt($integerPolynomial, ['0', '1']) === 1;
            }

            $firstLower = [$rootIntervals[0][0], $rootIntervals[0][1]];
            $leftSample = (new ExactRationalInterval($firstLower, $firstLower))
                ->subtract(new ExactRationalInterval(['1', '1'], ['1', '1']))
                ->lower;
            if ($counter->signAt($integerPolynomial, $leftSample) !== 1) {
                return false;
            }
            for ($index = 0; $index + 1 < \count($rootIntervals); ++$index) {
                $left = [$rootIntervals[$index][2], $rootIntervals[$index][3]];
                $right = [$rootIntervals[$index + 1][0], $rootIntervals[$index + 1][1]];
                $gapOrder = $this->compareRationalFractions($left, $right);
                if ($gapOrder > 0) {
                    return false;
                }
                $sample = $gapOrder === 0
                    ? $left
                    : (new ExactRationalInterval($left, $left))
                        ->add(new ExactRationalInterval($right, $right))
                        ->divide(new ExactRationalInterval(['2', '1'], ['2', '1']))
                        ->lower;
                if ($counter->signAt($integerPolynomial, $sample) !== 1) {
                    return false;
                }
            }
            $lastUpper = [
                $rootIntervals[\array_key_last($rootIntervals)][2],
                $rootIntervals[\array_key_last($rootIntervals)][3],
            ];
            $rightSample = (new ExactRationalInterval($lastUpper, $lastUpper))
                ->add(new ExactRationalInterval(['1', '1'], ['1', '1']))
                ->upper;

            return $counter->signAt($integerPolynomial, $rightSample) === 1;
        } catch (\LengthException) {
            return false;
        }
    }

    /** @param list<array{string, string}> $polynomial */
    private function polynomialIsGloballyPositive(array $polynomial): bool
    {
        $integerPolynomial = $this->integerPolynomialFromRational($polynomial);
        if ($integerPolynomial === null) {
            return false;
        }
        $counter = new ExactPolynomialRootCounter();

        return $counter->countAllRealRoots($integerPolynomial) === 0
            && $counter->signAt($integerPolynomial, ['0', '1']) === 1;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return array{list<string>, list<string>}|false|null
     */
    private function absoluteRationalPowerEquation(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        int $maxPolynomialDegree,
        EvaluationOptions $evaluationOptions,
    ): array|false|null {
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        $leftRoot = $this->absoluteRationalPower(
            $left,
            $extractor,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        $rightRoot = $this->absoluteRationalPower(
            $right,
            $extractor,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        if ($leftRoot === null || $rightRoot === null) {
            $leftRoot = $this->absoluteRationalPower(
                $left,
                $extractor,
                $maxPolynomialDegree,
                $evaluationOptions,
                true,
            );
            $rightRoot = $this->absoluteRationalPower(
                $right,
                $extractor,
                $maxPolynomialDegree,
                $evaluationOptions,
                true,
            );
            if ($leftRoot === null || $rightRoot === null) {
                return null;
            }
            [$leftArgument, $leftExponent] = $leftRoot;
            [$rightArgument, $rightExponent] = $rightRoot;
            $leftIsZero = $this->isIdenticallyZeroRationalFunction($leftArgument, $extractor);
            $rightIsZero = $this->isIdenticallyZeroRationalFunction($rightArgument, $extractor);
            if (!$leftIsZero && !$rightIsZero) {
                return null;
            }
            if ($leftExponent <= 0 || $rightExponent <= 0) {
                return false;
            }

            return $extractor->absoluteRationalDifference(
                $leftIsZero ? $rightArgument : $leftArgument,
                $leftIsZero ? $leftArgument : $rightArgument,
            );
        }
        [$leftArgument, $leftExponent, $leftDenominator] = $leftRoot;
        [$rightArgument, $rightExponent, $rightDenominator] = $rightRoot;
        $commonDenominator = \intdiv(
            $leftDenominator,
            $this->integerGcd($leftDenominator, $rightDenominator),
        ) * $rightDenominator;
        $leftIntegerExponent = $leftExponent * \intdiv($commonDenominator, $leftDenominator);
        $rightIntegerExponent = $rightExponent * \intdiv($commonDenominator, $rightDenominator);
        if (
            $leftIntegerExponent === 0
            || $rightIntegerExponent === 0
            || \abs($leftIntegerExponent) > $maxPolynomialDegree
            || \abs($rightIntegerExponent) > $maxPolynomialDegree
        ) {
            return null;
        }
        if ($leftIntegerExponent === $rightIntegerExponent) {
            return $extractor->absoluteRationalDifference(
                $leftArgument,
                $rightArgument,
                $leftIntegerExponent < 0,
            );
        }
        $exponentGcd = $this->integerGcd(\abs($leftIntegerExponent), \abs($rightIntegerExponent));

        return $extractor->rationalPowerDifference(
            $leftArgument,
            2 * \intdiv($leftIntegerExponent, $exponentGcd),
            $rightArgument,
            2 * \intdiv($rightIntegerExponent, $exponentGcd),
        );
    }

    /**
     * @return array{Node, int, int}|null Base, signed numerator, positive denominator.
     */
    private function absoluteRationalPower(
        Node $node,
        ExactRationalPolynomialExtractor $extractor,
        int $maxPolynomialDegree,
        EvaluationOptions $evaluationOptions,
        bool $allowUnprovenEvenRadicand = false,
    ): ?array {
        $maximumPowerDegree = \max(63, $maxPolynomialDegree);
        $node = $this->unwrapGrouping($node);
        if ($node instanceof FunctionCallNode) {
            if ($node->name === 'cbrt' && \count($node->arguments) === 1) {
                return $evaluationOptions->functions->isBuiltIn('cbrt')
                    ? [$node->arguments[0], 1, 3]
                    : null;
            }
            if ($node->name === 'sqrt' && \count($node->arguments) === 1) {
                return $evaluationOptions->functions->isBuiltIn('sqrt')
                    && ($allowUnprovenEvenRadicand
                        || $this->isStructurallyNonnegative($node->arguments[0], $extractor))
                    ? [$node->arguments[0], 1, 2]
                    : null;
            }
            if ($node->name === 'root' && \count($node->arguments) === 2) {
                if (!$evaluationOptions->functions->isBuiltIn('root')) {
                    return null;
                }
                $degree = $this->exactRootFunctionDegree($node->arguments, $extractor);
                if ($degree === null || $degree === 0) {
                    return null;
                }
                if (
                    \abs($degree) % 2 === 0
                    && !$allowUnprovenEvenRadicand
                    && !$this->isStructurallyNonnegative($node->arguments[0], $extractor)
                ) {
                    return null;
                }

                return [$node->arguments[0], $degree < 0 ? -1 : 1, \abs($degree)];
            }

            return null;
        }
        if (!$node instanceof BinaryOperationNode || $node->operator !== BinaryOperator::Power) {
            return null;
        }
        $exponent = RationalLiteral::fromNodeAsStrings($node->right);
        if (
            $exponent === null
            || $exponent[0] === '0'
        ) {
            return null;
        }
        $numerator = \filter_var($exponent[0], FILTER_VALIDATE_INT);
        $denominator = \filter_var($exponent[1], FILTER_VALIDATE_INT);
        if (
            !\is_int($numerator)
            || !\is_int($denominator)
            || $numerator === \PHP_INT_MIN
            || \abs($numerator) > $maxPolynomialDegree
            || $denominator > $maxPolynomialDegree
            || (
                $denominator % 2 === 0
                && !$allowUnprovenEvenRadicand
                && !$this->isStructurallyNonnegative($node->left, $extractor)
            )
        ) {
            return null;
        }

        return [$node->left, $numerator, $denominator];
    }

    private function isIdenticallyZeroRationalFunction(
        Node $node,
        ExactRationalPolynomialExtractor $extractor,
    ): bool {
        $rationalFunction = $extractor->rationalFunction($node);
        if ($rationalFunction === null || $rationalFunction[0] === []) {
            return false;
        }
        foreach ($rationalFunction[0] as [$numerator]) {
            if ($numerator !== '0') {
                return false;
            }
        }

        return true;
    }

    /**
     * Reduce an absolute rational power at level zero to its base zero set.
     * The unproven even-root domain is safe here because every candidate sets
     * the radicand itself to zero.
     *
     * @return array{list<string>, list<string>}|false|null
     */
    private function absoluteRationalPowerZeroLevelEquation(
        Node $powerNode,
        Node $zeroTarget,
        ExactRationalPolynomialExtractor $extractor,
        int $maxPolynomialDegree,
        EvaluationOptions $evaluationOptions,
    ): array|false|null {
        $power = $this->absoluteRationalPower(
            $powerNode,
            $extractor,
            $maxPolynomialDegree,
            $evaluationOptions,
        ) ?? $this->absoluteRationalPower(
            $powerNode,
            $extractor,
            $maxPolynomialDegree,
            $evaluationOptions,
            true,
        );
        if ($power === null) {
            return null;
        }
        [$argument, $exponent] = $power;
        if ($exponent <= 0) {
            return false;
        }

        return $extractor->absoluteRationalDifference($argument, $zeroTarget);
    }

    /**
     * Reduce a difference of matching logarithms when both subtracted and
     * target arguments are exact positive rational constants.
     *
     * @return array{Node, Node}|false|null
     */
    private function logarithmDifferenceWithConstantArguments(Node $left, Node $right): array|false|null
    {
        foreach ([[$left, $right], [$right, $left]] as [$difference, $target]) {
            $difference = $this->unwrapGrouping($difference);
            $target = $this->unwrapGrouping($target);
            if (
                !$difference instanceof BinaryOperationNode
                || $difference->operator !== BinaryOperator::Subtract
                || !$target instanceof FunctionCallNode
                || !\in_array($target->name, ['ln', 'log10', 'log2'], true)
                || \count($target->arguments) !== 1
            ) {
                continue;
            }
            $targetValue = RationalLiteral::fromNodeAsStrings($target->arguments[0]);
            if ($targetValue === null) {
                continue;
            }
            if ($targetValue[0] === '0' || $targetValue[0][0] === '-') {
                return false;
            }
            $operandPairs = [
                [$difference->left, $difference->right],
                [$difference->right, $difference->left],
            ];
            foreach ($operandPairs as [$minuend, $subtrahend]) {
                $minuend = $this->unwrapGrouping($minuend);
                $subtrahend = $this->unwrapGrouping($subtrahend);
                if (
                    !$minuend instanceof FunctionCallNode
                    || !$subtrahend instanceof FunctionCallNode
                    || $minuend->name !== $target->name
                    || $subtrahend->name !== $target->name
                    || \count($minuend->arguments) !== 1
                    || \count($subtrahend->arguments) !== 1
                ) {
                    continue;
                }
                $subtrahendValue = RationalLiteral::fromNodeAsStrings($subtrahend->arguments[0]);
                if ($subtrahendValue === null) {
                    continue;
                }
                if ($subtrahendValue[0] === '0' || $subtrahendValue[0][0] === '-') {
                    return false;
                }

                return [
                    $minuend->arguments[0],
                    new BinaryOperationNode(
                        BinaryOperator::Multiply,
                        $subtrahend->arguments[0],
                        $target->arguments[0],
                        $target->span,
                    ),
                ];
            }
        }

        return null;
    }

    /**
     * Reduce equality of the same real logarithm when one argument is an exact
     * constant. A nonpositive constant makes that logarithm undefined.
     *
     * @return array{Node, Node}|false|null
     */
    private function logEqualityWithConstantArgument(Node $left, Node $right): array|false|null
    {
        foreach ([[$left, $right], [$right, $left]] as [$leftCall, $rightCall]) {
            $leftCall = $this->unwrapGrouping($leftCall);
            $rightCall = $this->unwrapGrouping($rightCall);
            if (
                !$leftCall instanceof FunctionCallNode
                || !$rightCall instanceof FunctionCallNode
                || !\in_array($leftCall->name, ['ln', 'log10', 'log2'], true)
                || $leftCall->name !== $rightCall->name
                || \count($leftCall->arguments) !== 1
                || \count($rightCall->arguments) !== 1
            ) {
                continue;
            }
            $leftConstant = RationalLiteral::fromNodeAsStrings($leftCall->arguments[0]);
            $rightConstant = RationalLiteral::fromNodeAsStrings($rightCall->arguments[0]);
            foreach ([$leftConstant, $rightConstant] as $constant) {
                if ($constant !== null && ($constant[0] === '0' || $constant[0][0] === '-')) {
                    return false;
                }
            }
            if ($leftConstant !== null) {
                return [$rightCall->arguments[0], $leftCall->arguments[0]];
            }
            if ($rightConstant !== null) {
                return [$leftCall->arguments[0], $rightCall->arguments[0]];
            }
        }

        return null;
    }

    /**
     * Reduce a sum of three or more exact rational powers of the variable to
     * a polynomial in a common odd root, which is bijective over the reals.
     *
     * @return array{list<string>, list<string>}|null
     * @param AffineRationalPowerTransform|null $rationalPowerTransform
     * @param-out AffineRationalPowerTransform|null $rationalPowerTransform
     */
    private function sameVariableRationalPowerPolynomialZeroSum(
        Node $sum,
        int $maxPolynomialDegree,
        ExactRationalPolynomialExtractor $extractor,
        bool $allowHigherDegreeNonAffinePowerCounts,
        ?array &$rationalPowerTransform = null,
    ): ?array {
        $terms = [];
        $this->collectAdditiveTerms($sum, 1, $terms);
        if (\count($terms) < 3) {
            return null;
        }

        $powers = [];
        $commonDenominator = 1;
        $commonBase = null;
        $commonBaseForm = null;
        $domainNodes = [];
        $domainDenominatorKeys = [];
        foreach ($terms as [$node, $termSign]) {
            $constant = RationalLiteral::fromNodeAsStrings($node);
            if ($constant !== null) {
                $powers[] = [0, 1, $constant, $termSign];
                continue;
            }
            $term = $this->rationalPowerTerm($node, $extractor, $maxPolynomialDegree);
            if ($term === null) {
                $atom = $this->rationalPowerAtom($node, $extractor, $maxPolynomialDegree);
                $term = $atom === null ? null : [...$atom, 1, ['1', '1']];
            }
            if ($term === null) {
                return null;
            }
            [$base, $numerator, $denominator, $coefficientSign, $coefficient] = $term;
            if ($coefficient === null) {
                return null;
            }
            $baseForm = $extractor->rationalPolynomialForm($base);
            if ($baseForm === null) {
                return null;
            }
            $baseNumerator = $extractor->integerCoefficients($baseForm[0]);
            $baseDenominator = $extractor->integerCoefficients($baseForm[1]);
            if (
                $baseNumerator === null
                || $baseDenominator === null
                || $this->isZeroCoefficientList($baseNumerator)
                || $this->isZeroCoefficientList($baseDenominator)
            ) {
                return null;
            }
            if ($commonBase === null) {
                $commonBase = $base;
                $commonBaseForm = $baseForm;
                $domainDenominatorKeys[$this->integerPolynomialProjectiveKey($baseDenominator)] = true;
            } else {
                $baseDifference = $extractor->rationalDifference($commonBase, $base);
                if (
                    $baseDifference === null
                    || \array_filter(
                        $baseDifference[0],
                        static fn (string $value): bool => $value !== '0',
                    ) !== []
                ) {
                    return null;
                }
                $domainKey = $this->integerPolynomialProjectiveKey($baseDenominator);
                if (!isset($domainDenominatorKeys[$domainKey])) {
                    $domainNodes[] = $base;
                    $domainDenominatorKeys[$domainKey] = true;
                }
            }
            $multiple = \intdiv($commonDenominator, $this->integerGcd($commonDenominator, $denominator));
            if ($multiple > \intdiv(\PHP_INT_MAX, $denominator)) {
                return null;
            }
            $commonDenominator = $multiple * $denominator;
            $powers[] = [
                $numerator,
                $denominator,
                $coefficient,
                $termSign * $coefficientSign,
            ];
        }

        $integerPowers = [];
        foreach ($powers as [$numerator, $denominator, $coefficient, $sign]) {
            $multiplier = \intdiv($commonDenominator, $denominator);
            if ($numerator !== 0 && \abs($numerator) > \intdiv(\PHP_INT_MAX, $multiplier)) {
                return null;
            }
            $integerPowers[] = [
                $numerator * $multiplier,
                $coefficient,
                $sign,
            ];
        }
        $minimumPower = \min(\array_column($integerPowers, 0));
        $maximumPower = \max(\array_column($integerPowers, 0));
        if ($minimumPower < 0 && $maximumPower > \PHP_INT_MAX + $minimumPower) {
            return null;
        }
        $degree = $maximumPower - $minimumPower;
        if ($degree + ($minimumPower > 0 ? 1 : 0) > $maxPolynomialDegree) {
            return null;
        }
        $polynomial = \array_fill(0, $degree + 1, ['0', '1']);
        foreach ($integerPowers as [$power, $coefficient, $sign]) {
            $index = $power - $minimumPower;
            if ($sign < 0) {
                $coefficient = $extractor->multiplyExactFractions($coefficient, ['-1', '1']);
                if ($coefficient === null) {
                    return null;
                }
            }
            $currentCoefficient = $polynomial[$index];
            if ($currentCoefficient === null) {
                return null;
            }
            $polynomial[$index] = $extractor->addExactFractions($currentCoefficient, $coefficient);
            if ($polynomial[$index] === null) {
                return null;
            }
        }
        $completePolynomial = [];
        foreach ($polynomial as $coefficient) {
            if ($coefficient === null) {
                return null;
            }
            $completePolynomial[] = $coefficient;
        }
        $numerator = $extractor->integerCoefficients($completePolynomial);
        if ($numerator === null || $commonBase === null) {
            return null;
        }
        if ($commonBaseForm === null || !isset($commonBaseForm[0][1], $commonBaseForm[1][0])) {
            return null;
        }
        while (\count($numerator) > 1 && $numerator[\array_key_last($numerator)] === '0') {
            \array_pop($numerator);
        }
        if ($this->isZeroCoefficientList($numerator)) {
            return [$numerator, ['1']];
        }

        $baseNumerator = $extractor->integerCoefficients($commonBaseForm[0]);
        $baseDenominator = $extractor->integerCoefficients($commonBaseForm[1]);
        if ($baseNumerator === null || $baseDenominator === null) {
            return null;
        }
        $isAffineBase = \count($baseNumerator) === 2
            && $baseNumerator[1] !== '0'
            && \count($baseDenominator) === 1
            && $baseDenominator[0] !== '0';
        if (!$isAffineBase) {
            return $this->nonAffineRationalPowerPolynomialLevels(
                $commonBase,
                $numerator,
                $commonDenominator,
                $minimumPower,
                $domainNodes,
                $extractor,
                $maxPolynomialDegree,
                $allowHigherDegreeNonAffinePowerCounts,
            );
        }

        $slope = $extractor->multiplyExactFractions(
            $commonBaseForm[0][1],
            [$commonBaseForm[1][0][1], $commonBaseForm[1][0][0]],
        );
        $intercept = $extractor->multiplyExactFractions(
            $commonBaseForm[0][0],
            [$commonBaseForm[1][0][1], $commonBaseForm[1][0][0]],
        );
        if ($slope === null || $slope[0] === '0' || $intercept === null) {
            return null;
        }
        $rationalPowerTransform = [
            'denominator' => $commonDenominator,
            'slope' => $slope,
            'intercept' => $intercept,
        ];
        if ($minimumPower > 0) {
            \array_unshift($numerator, '0');
        }

        return [$numerator, $minimumPower < 0 ? ['0', '1'] : ['1']];
    }

    /**
     * Convert rational real roots of the common-root polynomial into exact
     * rational-function level equations.
     *
     * @param list<string> $commonRootPolynomial
     * @param list<Node> $domainNodes
     * @return array{list<string>, list<string>}|null
     */
    private function nonAffineRationalPowerPolynomialLevels(
        Node $base,
        array $commonRootPolynomial,
        int $commonDenominator,
        int $minimumPower,
        array $domainNodes,
        ExactRationalPolynomialExtractor $extractor,
        int $maxPolynomialDegree,
        bool $allowHigherDegreeNonAffinePowerCounts,
    ): ?array {
        $counter = new ExactPolynomialRootCounter();
        $integerArithmetic = new IntegerPolynomialExtractor('', [], $maxPolynomialDegree);
        $derivative = [];
        for ($degree = 1, $count = \count($commonRootPolynomial); $degree < $count; ++$degree) {
            $derivative[] = $integerArithmetic->multiplyIntegerValues(
                $commonRootPolynomial[$degree],
                (string) $degree,
            );
        }
        $repeatedFactor = $counter->greatestCommonDivisor($commonRootPolynomial, $derivative);
        if ($repeatedFactor === null) {
            return null;
        }
        $squareFreePolynomial = $counter->dividePolynomialExactly($commonRootPolynomial, $repeatedFactor);
        if ($squareFreePolynomial === null || \count($squareFreePolynomial) < 2) {
            return null;
        }
        $rootIntervals = $counter->isolateAllRealRoots(
            $squareFreePolynomial,
            maximumWidth: ['1', '1000000'],
        );
        if ($rootIntervals === null) {
            return null;
        }
        $squareFreeDegree = \count($squareFreePolynomial) - 1;
        if ($squareFreeDegree === 3) {
            $levelPolynomial = $this->cubicOddPowerImagePolynomial(
                $squareFreePolynomial,
                $commonDenominator,
                $extractor,
            );
            if ($levelPolynomial !== null) {
                $certifiedLevelPolynomial = $this->certifyOddPowerImagePolynomial(
                    $levelPolynomial,
                    $squareFreePolynomial,
                    $squareFreeDegree,
                    \count($rootIntervals),
                    $commonDenominator,
                    $counter,
                    $extractor,
                );
                if ($certifiedLevelPolynomial !== null) {
                    return $extractor->rationalPolynomialInRationalFunction(
                        $base,
                        $certifiedLevelPolynomial,
                        $domainNodes,
                        $minimumPower > 0,
                        $minimumPower < 0,
                    );
                }
                $preimageConstrainedEquation = $this->composeOddPowerImageWithRealPreimageConstraint(
                    $base,
                    $levelPolynomial,
                    $squareFreePolynomial,
                    $domainNodes,
                    $minimumPower,
                    $extractor,
                );
                if ($preimageConstrainedEquation !== null) {
                    return $preimageConstrainedEquation;
                }
            }
        }
        if ($squareFreeDegree === 4) {
            $levelPolynomial = $this->quarticOddPowerImagePolynomial(
                $squareFreePolynomial,
                $commonDenominator,
                $extractor,
            );
            if ($levelPolynomial !== null) {
                $certifiedLevelPolynomial = $this->certifyOddPowerImagePolynomial(
                    $levelPolynomial,
                    $squareFreePolynomial,
                    $squareFreeDegree,
                    \count($rootIntervals),
                    $commonDenominator,
                    $counter,
                    $extractor,
                );
                if ($certifiedLevelPolynomial !== null) {
                    return $extractor->rationalPolynomialInRationalFunction(
                        $base,
                        $certifiedLevelPolynomial,
                        $domainNodes,
                        $minimumPower > 0,
                        $minimumPower < 0,
                    );
                }
                $preimageConstrainedEquation = $this->composeOddPowerImageWithRealPreimageConstraint(
                    $base,
                    $levelPolynomial,
                    $squareFreePolynomial,
                    $domainNodes,
                    $minimumPower,
                    $extractor,
                );
                if ($preimageConstrainedEquation !== null) {
                    return $preimageConstrainedEquation;
                }
            }
        }
        $commonRootDegree = $squareFreeDegree;
        $maximumCommonRootDegree = $allowHigherDegreeNonAffinePowerCounts
            ? $maxPolynomialDegree
            : \min(8, $maxPolynomialDegree);
        if (
            $commonRootDegree >= 5
            && $commonRootDegree <= $maximumCommonRootDegree
        ) {
            $levelPolynomial = $this->higherOddPowerImagePolynomial(
                $squareFreePolynomial,
                $commonDenominator,
                $extractor,
                $maxPolynomialDegree,
            );
            if ($levelPolynomial !== null) {
                $certifiedLevelPolynomial = $this->certifyOddPowerImagePolynomial(
                    $levelPolynomial,
                    $squareFreePolynomial,
                    $commonRootDegree,
                    \count($rootIntervals),
                    $commonDenominator,
                    $counter,
                    $extractor,
                );
                if ($certifiedLevelPolynomial !== null) {
                    return $extractor->rationalPolynomialInRationalFunction(
                        $base,
                        $certifiedLevelPolynomial,
                        $domainNodes,
                        $minimumPower > 0,
                        $minimumPower < 0,
                    );
                }
                $preimageConstrainedEquation = $this->composeOddPowerImageWithRealPreimageConstraint(
                    $base,
                    $levelPolynomial,
                    $squareFreePolynomial,
                    $domainNodes,
                    $minimumPower,
                    $extractor,
                );
                if ($preimageConstrainedEquation !== null) {
                    return $preimageConstrainedEquation;
                }
            }
        }
        $twoIrrationalQuadraticRoots = $squareFreeDegree === 2 && \count($rootIntervals) === 2;
        foreach ($rootIntervals as $rootInterval) {
            if ($rootInterval[0] === $rootInterval[2] && $rootInterval[1] === $rootInterval[3]) {
                $twoIrrationalQuadraticRoots = false;
                break;
            }
        }
        if ($twoIrrationalQuadraticRoots) {
            $levelPolynomial = $this->quadraticOddPowerImagePolynomial(
                $squareFreePolynomial,
                $commonDenominator,
                $extractor,
            );
            if ($levelPolynomial === null) {
                return null;
            }

            return $extractor->rationalPolynomialInRationalFunction(
                $base,
                $levelPolynomial,
                $domainNodes,
                $minimumPower > 0,
                $minimumPower < 0,
            );
        }

        $equationNumerator = ['1'];
        $equationDenominator = null;
        foreach ($rootIntervals as [$lowerNumerator, $lowerDenominator, $upperNumerator, $upperDenominator]) {
            if ($lowerNumerator !== $upperNumerator || $lowerDenominator !== $upperDenominator) {
                return null;
            }
            if ($lowerNumerator === '0' && $minimumPower !== 0) {
                continue;
            }
            $target = $extractor->powerExactFraction(
                [$lowerNumerator, $lowerDenominator],
                $commonDenominator,
            );
            if ($target === null) {
                return null;
            }
            $levelEquation = $extractor->rationalPowerLevelEquation(
                $base,
                1,
                $target,
                false,
                $domainNodes,
            );
            if ($levelEquation === null) {
                return null;
            }
            $equationNumerator = $this->multiplyIntegerCoefficientLists(
                $equationNumerator,
                $levelEquation[0],
                $maxPolynomialDegree,
            );
            if ($equationNumerator === null) {
                return null;
            }
            $equationDenominator ??= $levelEquation[1];
        }

        if ($minimumPower > 0) {
            $zeroLevelEquation = $extractor->rationalPowerLevelEquation(
                $base,
                1,
                ['0', '1'],
                false,
                $domainNodes,
            );
            if ($zeroLevelEquation === null) {
                return null;
            }
            $equationNumerator = $this->multiplyIntegerCoefficientLists(
                $equationNumerator,
                $zeroLevelEquation[0],
                $maxPolynomialDegree,
            );
            if ($equationNumerator === null) {
                return null;
            }
            $equationDenominator ??= $zeroLevelEquation[1];
        }

        return $equationDenominator === null
            ? [['1'], ['1']]
            : [$equationNumerator, $equationDenominator];
    }

    /**
     * Retain only real equation roots whose rational-base value is a real root
     * of the source polynomial, even when other image levels are irrational.
     *
     * @param list<array{string, string}> $imagePolynomial
     * @param list<string> $sourcePolynomial
     * @param list<Node> $domainNodes
     * @return array{list<string>, list<string>}|null
     */
    private function composeOddPowerImageWithRealPreimageConstraint(
        Node $base,
        array $imagePolynomial,
        array $sourcePolynomial,
        array $domainNodes,
        int $minimumPower,
        ExactRationalPolynomialExtractor $extractor,
    ): ?array {
        $imageEquation = $extractor->rationalPolynomialInRationalFunction(
            $base,
            $imagePolynomial,
            $domainNodes,
            $minimumPower > 0,
            $minimumPower < 0,
        );
        /** @var list<array{string, string}> $sourceCoefficients */
        $sourceCoefficients = \array_map(
            static fn (string $coefficient): array => [$coefficient, '1'],
            $sourcePolynomial,
        );
        $sourceEquation = $extractor->rationalPolynomialInRationalFunction(
            $base,
            $sourceCoefficients,
            $domainNodes,
            $minimumPower > 0,
            $minimumPower < 0,
        );
        if ($imageEquation === null || $sourceEquation === null) {
            return null;
        }
        $commonNumerator = (new ExactPolynomialRootCounter())->greatestCommonDivisor(
            $imageEquation[0],
            $sourceEquation[0],
        );
        if ($commonNumerator === null) {
            return null;
        }

        return [$commonNumerator, $imageEquation[1]];
    }

    /**
     * A real odd-power map is injective on distinct real roots. Matching real-root
     * counts therefore proves the image polynomial added no levels from
     * non-real source roots.
     *
     * @param list<array{string, string}> $imagePolynomial
     */
    private function oddPowerImagePreservesRealRootSet(
        array $imagePolynomial,
        int $sourceRealRootCount,
        ExactPolynomialRootCounter $counter,
        ExactRationalPolynomialExtractor $extractor,
    ): bool {
        if ($sourceRealRootCount < 1) {
            return false;
        }
        $integerImagePolynomial = $extractor->integerCoefficients($imagePolynomial);
        if ($integerImagePolynomial === null) {
            return false;
        }
        $imageRoots = $counter->isolateAllRealRoots(
            $integerImagePolynomial,
            maximumWidth: ['1', '1000000'],
        );

        return $imageRoots !== null && \count($imageRoots) === $sourceRealRootCount;
    }

    /**
     * Certify the image polynomial, filtering only rational levels without a real preimage.
     *
     * @param list<array{string, string}> $imagePolynomial
     * @param list<string> $sourcePolynomial
     * @return list<array{string, string}>|null
     */
    private function certifyOddPowerImagePolynomial(
        array $imagePolynomial,
        array $sourcePolynomial,
        int $sourceDegree,
        int $sourceRealRootCount,
        int $power,
        ExactPolynomialRootCounter $counter,
        ExactRationalPolynomialExtractor $extractor,
    ): ?array {
        if (
            $sourceRealRootCount === $sourceDegree
            || $this->oddPowerImagePreservesRealRootSet(
                $imagePolynomial,
                $sourceRealRootCount,
                $counter,
                $extractor,
            )
        ) {
            return $imagePolynomial;
        }

        $filtered = $this->removeRationalOddPowerLevelsWithoutRealPreimage(
            $imagePolynomial,
            $sourcePolynomial,
            $power,
            $counter,
            $extractor,
        );

        return $filtered !== null && $this->oddPowerImagePreservesRealRootSet(
            $filtered,
            $sourceRealRootCount,
            $counter,
            $extractor,
        )
            ? $filtered
            : null;
    }

    /**
     * Remove rational image roots that have no real common-root preimage.
     *
     * @param list<array{string, string}> $imagePolynomial
     * @param list<string> $sourcePolynomial
     * @return list<array{string, string}>|null
     */
    private function removeRationalOddPowerLevelsWithoutRealPreimage(
        array $imagePolynomial,
        array $sourcePolynomial,
        int $power,
        ExactPolynomialRootCounter $counter,
        ExactRationalPolynomialExtractor $extractor,
    ): ?array {
        if ($power < 1 || $power > 256 || ($power % 2) === 0) {
            return null;
        }
        $integerImage = $extractor->integerCoefficients($imagePolynomial);
        if ($integerImage === null) {
            return null;
        }
        $imageRoots = $counter->isolateAllRealRoots(
            $integerImage,
            maximumWidth: ['1', '1000000'],
        );
        if ($imageRoots === null) {
            return null;
        }
        $integerArithmetic = new IntegerPolynomialExtractor('', [], 256);

        foreach ($imageRoots as [$lowerNumerator, $lowerDenominator, $upperNumerator, $upperDenominator]) {
            if ($lowerNumerator !== $upperNumerator || $lowerDenominator !== $upperDenominator) {
                continue;
            }
            $preimagePolynomial = \array_fill(0, $power + 1, '0');
            $preimagePolynomial[0] = $integerArithmetic->negateIntegerValue($lowerNumerator);
            $preimagePolynomial[$power] = $lowerDenominator;
            $commonRealRoots = $counter->countCommonRealRoots(
                $sourcePolynomial,
                \array_values($preimagePolynomial),
            );
            if ($commonRealRoots === null) {
                return null;
            }
            if ($commonRealRoots > 0) {
                continue;
            }

            $factor = [
                $integerArithmetic->negateIntegerValue($lowerNumerator),
                $lowerDenominator,
            ];
            while ($counter->isRootAt($integerImage, [$lowerNumerator, $lowerDenominator]) === true) {
                $quotient = $counter->dividePolynomialExactly($integerImage, $factor);
                if ($quotient === null) {
                    return null;
                }
                $integerImage = $quotient;
            }
        }

        return \array_map(
            static fn (string $coefficient): array => [$coefficient, '1'],
            $integerImage,
        );
    }

    /**
     * Find the quadratic polynomial whose roots are the odd powers of the
     * roots of a real quadratic polynomial.
     *
     * @param list<string> $coefficients Ascending integer coefficients.
     * @return list<array{string, string}>|null
     */
    private function quadraticOddPowerImagePolynomial(
        array $coefficients,
        int $power,
        ExactRationalPolynomialExtractor $extractor,
    ): ?array {
        if (\count($coefficients) !== 3 || $power < 1) {
            return null;
        }
        [$constant, $linear, $quadratic] = $coefficients;
        if ($quadratic === '0') {
            return null;
        }
        $linearRatio = $extractor->multiplyExactFractions([$linear, $quadratic], ['1', '1']);
        $constantRatio = $extractor->multiplyExactFractions([$constant, $quadratic], ['1', '1']);
        if ($linearRatio === null || $constantRatio === null) {
            return null;
        }

        $linearPart = ['1', '1'];
        $constantPart = ['0', '1'];
        for ($exponent = 1; $exponent < $power; ++$exponent) {
            $linearProduct = $extractor->multiplyExactFractions($linearPart, $linearRatio);
            $constantProduct = $extractor->multiplyExactFractions($linearPart, $constantRatio);
            if ($linearProduct === null || $constantProduct === null) {
                return null;
            }
            $linearProduct = $extractor->multiplyExactFractions($linearProduct, ['-1', '1']);
            $constantProduct = $extractor->multiplyExactFractions($constantProduct, ['-1', '1']);
            if ($linearProduct === null || $constantProduct === null) {
                return null;
            }
            $nextLinearPart = $extractor->addExactFractions($constantPart, $linearProduct);
            if ($nextLinearPart === null) {
                return null;
            }
            $constantPart = $constantProduct;
            $linearPart = $nextLinearPart;
        }
        if ($linearPart[0] === '0') {
            return null;
        }

        $linearPartSquared = $extractor->powerExactFraction($linearPart, 2);
        $constantPartSquared = $extractor->powerExactFraction($constantPart, 2);
        $linearConstantProduct = $extractor->multiplyExactFractions($linearPart, $constantPart);
        if ($linearPartSquared === null || $constantPartSquared === null || $linearConstantProduct === null) {
            return null;
        }
        $quadraticConstant = $extractor->multiplyExactFractions([$quadratic, '1'], $constantPartSquared);
        $linearConstant = $extractor->multiplyExactFractions([$linear, '1'], $linearConstantProduct);
        $constantQuadratic = $extractor->multiplyExactFractions([$constant, '1'], $linearPartSquared);
        $quadraticLinear = $extractor->multiplyExactFractions([$quadratic, '1'], $constantPart);
        $quadraticLinear = $quadraticLinear === null
            ? null
            : $extractor->multiplyExactFractions($quadraticLinear, ['-2', '1']);
        $linearLinear = $extractor->multiplyExactFractions([$linear, '1'], $linearPart);
        if (
            $quadraticConstant === null
            || $linearConstant === null
            || $constantQuadratic === null
            || $quadraticLinear === null
            || $linearLinear === null
        ) {
            return null;
        }
        $negativeLinearConstant = $extractor->multiplyExactFractions($linearConstant, ['-1', '1']);
        if ($negativeLinearConstant === null) {
            return null;
        }
        $imageConstant = $extractor->addExactFractions($quadraticConstant, $constantQuadratic);
        $imageLinear = $extractor->addExactFractions($quadraticLinear, $linearLinear);
        if ($imageConstant === null || $imageLinear === null) {
            return null;
        }
        $imageConstant = $extractor->addExactFractions($imageConstant, $negativeLinearConstant);
        if ($imageConstant === null) {
            return null;
        }

        return [$imageConstant, $imageLinear, [$quadratic, '1']];
    }

    /**
     * @param list<string> $coefficients Ascending integer coefficients.
     * @return list<array{string, string}>|null
     */
    private function cubicOddPowerImagePolynomial(
        array $coefficients,
        int $power,
        ExactRationalPolynomialExtractor $extractor,
    ): ?array {
        if (\count($coefficients) !== 4 || $coefficients[3] === '0' || $power < 1) {
            return null;
        }
        [$constant, $linear, $quadratic, $cubic] = $coefficients;
        $negativeRatios = [];
        foreach ([$constant, $linear, $quadratic] as $coefficient) {
            $ratio = $extractor->multiplyExactFractions([$coefficient, $cubic], ['-1', '1']);
            if ($ratio === null) {
                return null;
            }
            $negativeRatios[] = $ratio;
        }
        [$constantRatio, $linearRatio, $quadraticRatio] = $negativeRatios;
        $zero = ['0', '1'];
        $one = ['1', '1'];
        $matrix = [
            [$zero, $zero, $constantRatio],
            [$one, $zero, $linearRatio],
            [$zero, $one, $quadraticRatio],
        ];
        $result = [
            [$one, $zero, $zero],
            [$zero, $one, $zero],
            [$zero, $zero, $one],
        ];
        $factor = $matrix;
        $remainingPower = $power;
        while ($remainingPower > 0) {
            if (($remainingPower % 2) === 1) {
                $result = $this->multiplyRationalMatrices3x3($result, $factor, $extractor);
                if ($result === null) {
                    return null;
                }
            }
            $remainingPower = \intdiv($remainingPower, 2);
            if ($remainingPower > 0) {
                $factor = $this->multiplyRationalMatrices3x3($factor, $factor, $extractor);
                if ($factor === null) {
                    return null;
                }
            }
        }

        $trace = $extractor->addExactFractions($result[0][0], $result[1][1]);
        $trace = $trace === null ? null : $extractor->addExactFractions($trace, $result[2][2]);
        if ($trace === null) {
            return null;
        }
        $secondCoefficient = ['0', '1'];
        foreach ([[0, 1], [0, 2], [1, 2]] as [$first, $second]) {
            $diagonal = $extractor->multiplyExactFractions($result[$first][$first], $result[$second][$second]);
            $offDiagonal = $extractor->multiplyExactFractions($result[$first][$second], $result[$second][$first]);
            if ($diagonal === null || $offDiagonal === null) {
                return null;
            }
            $negativeOffDiagonal = $extractor->multiplyExactFractions($offDiagonal, ['-1', '1']);
            if ($negativeOffDiagonal === null) {
                return null;
            }
            $minor = $extractor->addExactFractions($diagonal, $negativeOffDiagonal);
            $secondCoefficient = $minor === null
                ? null
                : $extractor->addExactFractions($secondCoefficient, $minor);
            if ($secondCoefficient === null) {
                return null;
            }
        }

        $determinant = ['0', '1'];
        foreach (
            [
                [[0, 0], [1, 1], [2, 2], 1],
                [[0, 1], [1, 2], [2, 0], 1],
                [[0, 2], [1, 0], [2, 1], 1],
                [[0, 2], [1, 1], [2, 0], -1],
                [[0, 1], [1, 0], [2, 2], -1],
                [[0, 0], [1, 2], [2, 1], -1],
            ] as [$firstPosition, $secondPosition, $thirdPosition, $sign]
        ) {
            $term = $extractor->multiplyExactFractions(
                $result[$firstPosition[0]][$firstPosition[1]],
                $result[$secondPosition[0]][$secondPosition[1]],
            );
            $term = $term === null
                ? null
                : $extractor->multiplyExactFractions(
                    $term,
                    $result[$thirdPosition[0]][$thirdPosition[1]],
                );
            if ($term === null) {
                return null;
            }
            if ($sign < 0) {
                $term = $extractor->multiplyExactFractions($term, ['-1', '1']);
                if ($term === null) {
                    return null;
                }
            }
            $determinant = $extractor->addExactFractions($determinant, $term);
            if ($determinant === null) {
                return null;
            }
        }
        $negativeDeterminant = $extractor->multiplyExactFractions($determinant, ['-1', '1']);
        $negativeTrace = $extractor->multiplyExactFractions($trace, ['-1', '1']);
        if ($negativeDeterminant === null || $negativeTrace === null) {
            return null;
        }

        return [$negativeDeterminant, $secondCoefficient, $negativeTrace, $one];
    }

    /**
     * Find the quartic polynomial whose roots are the odd powers of the roots
     * of a real quartic polynomial with four distinct real roots.
     *
     * @param list<string> $coefficients Ascending integer coefficients.
     * @return list<array{string, string}>|null
     */
    private function quarticOddPowerImagePolynomial(
        array $coefficients,
        int $power,
        ExactRationalPolynomialExtractor $extractor,
    ): ?array {
        if (\count($coefficients) !== 5 || $coefficients[4] === '0' || $power < 1) {
            return null;
        }
        $zero = ['0', '1'];
        $one = ['1', '1'];
        $ratios = [];
        foreach (\array_slice($coefficients, 0, 4) as $coefficient) {
            $ratio = $extractor->multiplyExactFractions([$coefficient, $coefficients[4]], ['-1', '1']);
            if ($ratio === null) {
                return null;
            }
            $ratios[] = $ratio;
        }
        [$constantRatio, $linearRatio, $quadraticRatio, $cubicRatio] = $ratios;
        $companion = [
            [$zero, $zero, $zero, $constantRatio],
            [$one, $zero, $zero, $linearRatio],
            [$zero, $one, $zero, $quadraticRatio],
            [$zero, $zero, $one, $cubicRatio],
        ];
        $identity = [
            [$one, $zero, $zero, $zero],
            [$zero, $one, $zero, $zero],
            [$zero, $zero, $one, $zero],
            [$zero, $zero, $zero, $one],
        ];
        $imageMatrix = $identity;
        $factor = $companion;
        $remainingPower = $power;
        while ($remainingPower > 0) {
            if (($remainingPower % 2) === 1) {
                $imageMatrix = $this->multiplyRationalMatrices4x4($imageMatrix, $factor, $extractor);
                if ($imageMatrix === null) {
                    return null;
                }
            }
            $remainingPower = \intdiv($remainingPower, 2);
            if ($remainingPower > 0) {
                $factor = $this->multiplyRationalMatrices4x4($factor, $factor, $extractor);
                if ($factor === null) {
                    return null;
                }
            }
        }

        /** @var list<array{string, string}> $powerSums */
        $powerSums = [];
        $matrixPower = $imageMatrix;
        for ($exponent = 1; $exponent <= 4; ++$exponent) {
            $trace = $zero;
            for ($diagonal = 0; $diagonal < 4; ++$diagonal) {
                $trace = $extractor->addExactFractions($trace, $matrixPower[$diagonal][$diagonal]);
                if ($trace === null) {
                    return null;
                }
            }
            $powerSums[] = $trace;
            if ($exponent < 4) {
                $matrixPower = $this->multiplyRationalMatrices4x4($matrixPower, $imageMatrix, $extractor);
                if ($matrixPower === null) {
                    return null;
                }
            }
        }

        $elementary = [0 => $one];
        for ($degree = 1; $degree <= 4; ++$degree) {
            $sum = $zero;
            for ($index = 1; $index <= $degree; ++$index) {
                $previousElementary = $elementary[$degree - $index] ?? null;
                $powerSum = $powerSums[$index - 1] ?? null;
                if ($previousElementary === null || $powerSum === null) {
                    return null;
                }
                $product = $extractor->multiplyExactFractions(
                    $previousElementary,
                    $powerSum,
                );
                if ($product === null) {
                    return null;
                }
                if (($index % 2) === 0) {
                    $product = $extractor->multiplyExactFractions($product, ['-1', '1']);
                    if ($product === null) {
                        return null;
                    }
                }
                $sum = $extractor->addExactFractions($sum, $product);
                if ($sum === null) {
                    return null;
                }
            }
            $coefficient = $extractor->multiplyExactFractions(
                $sum,
                ['1', (string) $degree],
            );
            if ($coefficient === null) {
                return null;
            }
            $elementary[$degree] = $coefficient;
        }

        $constantCoefficient = $elementary[4] ?? null;
        $cubicCoefficient = $elementary[3] ?? null;
        $quadraticCoefficient = $elementary[2] ?? null;
        $linearCoefficient = $elementary[1] ?? null;
        if (
            $constantCoefficient === null
            || $cubicCoefficient === null
            || $quadraticCoefficient === null
            || $linearCoefficient === null
        ) {
            return null;
        }
        $negativeCubic = $extractor->multiplyExactFractions($cubicCoefficient, ['-1', '1']);
        $negativeLinear = $extractor->multiplyExactFractions($linearCoefficient, ['-1', '1']);
        if ($negativeCubic === null || $negativeLinear === null) {
            return null;
        }

        return [$constantCoefficient, $negativeCubic, $quadraticCoefficient, $negativeLinear, $one];
    }

    /**
     * @param RationalMatrix4 $left
     * @param RationalMatrix4 $right
     * @return RationalMatrix4|null
     */
    private function multiplyRationalMatrices4x4(
        array $left,
        array $right,
        ExactRationalPolynomialExtractor $extractor,
    ): ?array {
        $zero = ['0', '1'];
        $product = [
            [$zero, $zero, $zero, $zero],
            [$zero, $zero, $zero, $zero],
            [$zero, $zero, $zero, $zero],
            [$zero, $zero, $zero, $zero],
        ];
        for ($row = 0; $row < 4; ++$row) {
            for ($column = 0; $column < 4; ++$column) {
                $value = $zero;
                for ($inner = 0; $inner < 4; ++$inner) {
                    $term = $extractor->multiplyExactFractions($left[$row][$inner], $right[$inner][$column]);
                    if ($term === null) {
                        return null;
                    }
                    $value = $extractor->addExactFractions($value, $term);
                    if ($value === null) {
                        return null;
                    }
                }
                $product[$row][$column] = $value;
            }
        }

        return $product;
    }

    /**
     * Build the exact odd-power image polynomial for a bounded-degree polynomial
     * whose roots have all been certified real and distinct.
     *
     * @param list<string> $coefficients Ascending integer coefficients.
     * @return list<array{string, string}>|null
     */
    private function higherOddPowerImagePolynomial(
        array $coefficients,
        int $power,
        ExactRationalPolynomialExtractor $extractor,
        int $maxPolynomialDegree,
    ): ?array {
        $degree = \count($coefficients) - 1;
        if ($degree < 5 || $degree > $maxPolynomialDegree || $coefficients[$degree] === '0' || $power < 1) {
            return null;
        }
        $zero = ['0', '1'];
        $one = ['1', '1'];
        $matrix = \array_fill(0, $degree, \array_fill(0, $degree, $zero));
        for ($row = 1; $row < $degree; ++$row) {
            $matrix[$row][$row - 1] = $one;
        }
        for ($row = 0; $row < $degree; ++$row) {
            $coefficient = $coefficients[$row] ?? null;
            if ($coefficient === null) {
                return null;
            }
            $lastColumnValue = $extractor->multiplyExactFractions(
                [$coefficient, $coefficients[$degree]],
                ['-1', '1'],
            );
            if ($lastColumnValue === null) {
                return null;
            }
            $matrix[$row][$degree - 1] = $lastColumnValue;
        }
        $identity = \array_fill(0, $degree, \array_fill(0, $degree, $zero));
        for ($diagonal = 0; $diagonal < $degree; ++$diagonal) {
            $identity[$diagonal][$diagonal] = $one;
        }
        $imageMatrix = $identity;
        $factor = $matrix;
        $remainingPower = $power;
        while ($remainingPower > 0) {
            if (($remainingPower % 2) === 1) {
                $imageMatrix = $this->multiplyRationalMatrices($imageMatrix, $factor, $extractor);
                if ($imageMatrix === null) {
                    return null;
                }
            }
            $remainingPower = \intdiv($remainingPower, 2);
            if ($remainingPower > 0) {
                $factor = $this->multiplyRationalMatrices($factor, $factor, $extractor);
                if ($factor === null) {
                    return null;
                }
            }
        }

        /** @var list<array{string, string}> $powerSums */
        $powerSums = [];
        $matrixPower = $imageMatrix;
        for ($exponent = 1; $exponent <= $degree; ++$exponent) {
            $trace = $zero;
            for ($diagonal = 0; $diagonal < $degree; ++$diagonal) {
                $diagonalValue = $matrixPower[$diagonal][$diagonal] ?? null;
                if ($diagonalValue === null) {
                    return null;
                }
                $trace = $extractor->addExactFractions($trace, $diagonalValue);
                if ($trace === null) {
                    return null;
                }
            }
            $powerSums[] = $trace;
            if ($exponent < $degree) {
                $matrixPower = $this->multiplyRationalMatrices($matrixPower, $imageMatrix, $extractor);
                if ($matrixPower === null) {
                    return null;
                }
            }
        }

        $elementary = [0 => $one];
        for ($order = 1; $order <= $degree; ++$order) {
            $sum = $zero;
            for ($index = 1; $index <= $order; ++$index) {
                $previousElementary = $elementary[$order - $index] ?? null;
                $powerSum = $powerSums[$index - 1] ?? null;
                if ($previousElementary === null || $powerSum === null) {
                    return null;
                }
                $product = $extractor->multiplyExactFractions($previousElementary, $powerSum);
                if ($product === null) {
                    return null;
                }
                if (($index % 2) === 0) {
                    $product = $extractor->multiplyExactFractions($product, ['-1', '1']);
                    if ($product === null) {
                        return null;
                    }
                }
                $sum = $extractor->addExactFractions($sum, $product);
                if ($sum === null) {
                    return null;
                }
            }
            $coefficient = $extractor->multiplyExactFractions($sum, ['1', (string) $order]);
            if ($coefficient === null) {
                return null;
            }
            $elementary[$order] = $coefficient;
        }

        $imageCoefficients = [];
        for ($degreeIndex = 0; $degreeIndex <= $degree; ++$degreeIndex) {
            $elementaryIndex = $degree - $degreeIndex;
            $coefficient = $elementary[$elementaryIndex] ?? null;
            if ($coefficient === null) {
                return null;
            }
            if (($elementaryIndex % 2) !== 0) {
                $coefficient = $extractor->multiplyExactFractions($coefficient, ['-1', '1']);
                if ($coefficient === null) {
                    return null;
                }
            }
            $imageCoefficients[] = $coefficient;
        }

        return $imageCoefficients;
    }

    /**
     * @param RationalMatrix $left
     * @param RationalMatrix $right
     * @return RationalMatrix|null
     */
    private function multiplyRationalMatrices(
        array $left,
        array $right,
        ExactRationalPolynomialExtractor $extractor,
    ): ?array {
        $size = \count($left);
        if ($size < 1 || \count($right) !== $size) {
            return null;
        }
        $zero = ['0', '1'];
        $product = \array_fill(0, $size, \array_fill(0, $size, $zero));
        for ($row = 0; $row < $size; ++$row) {
            for ($column = 0; $column < $size; ++$column) {
                $value = $zero;
                for ($inner = 0; $inner < $size; ++$inner) {
                    $leftValue = $left[$row][$inner] ?? null;
                    $rightValue = $right[$inner][$column] ?? null;
                    if ($leftValue === null || $rightValue === null) {
                        return null;
                    }
                    $term = $extractor->multiplyExactFractions($leftValue, $rightValue);
                    if ($term === null) {
                        return null;
                    }
                    $value = $extractor->addExactFractions($value, $term);
                    if ($value === null) {
                        return null;
                    }
                }
                $product[$row][$column] = $value;
            }
        }

        return $product;
    }

    /**
     * @param RationalMatrix3 $left
     * @param RationalMatrix3 $right
     * @return RationalMatrix3|null
     */
    private function multiplyRationalMatrices3x3(
        array $left,
        array $right,
        ExactRationalPolynomialExtractor $extractor,
    ): ?array {
        $zero = ['0', '1'];
        $product = [[$zero, $zero, $zero], [$zero, $zero, $zero], [$zero, $zero, $zero]];
        for ($row = 0; $row < 3; ++$row) {
            for ($column = 0; $column < 3; ++$column) {
                $value = $zero;
                for ($inner = 0; $inner < 3; ++$inner) {
                    $term = $extractor->multiplyExactFractions($left[$row][$inner], $right[$inner][$column]);
                    if ($term === null) {
                        return null;
                    }
                    $value = $extractor->addExactFractions($value, $term);
                    if ($value === null) {
                        return null;
                    }
                }
                $product[$row][$column] = $value;
            }
        }

        return $product;
    }

    /**
     * @param list<string> $left
     * @param list<string> $right
     * @return list<string>|null
     */
    private function multiplyIntegerCoefficientLists(array $left, array $right, int $maxDegree): ?array
    {
        $degree = \count($left) + \count($right) - 2;
        if ($degree > $maxDegree) {
            return null;
        }
        $arithmetic = new IntegerPolynomialExtractor('', [], $maxDegree);
        $product = \array_fill(0, $degree + 1, '0');
        foreach ($left as $leftDegree => $leftCoefficient) {
            foreach ($right as $rightDegree => $rightCoefficient) {
                $product[$leftDegree + $rightDegree] = $arithmetic->addIntegerValues(
                    $product[$leftDegree + $rightDegree],
                    $arithmetic->multiplyIntegerValues($leftCoefficient, $rightCoefficient),
                );
            }
        }
        while (\count($product) > 1 && $product[\array_key_last($product)] === '0') {
            \array_pop($product);
        }

        return \array_values($product);
    }

    /** @param list<string> $coefficients */
    private function integerPolynomialProjectiveKey(array $coefficients): string
    {
        $arithmetic = new IntegerPolynomialExtractor('', []);
        $content = '0';
        foreach ($coefficients as $coefficient) {
            $content = $arithmetic->greatestCommonDivisorValues($content, $coefficient);
        }
        $primitive = [];
        foreach ($coefficients as $coefficient) {
            $primitive[] = $arithmetic->divideIntegerValueExactly($coefficient, $content) ?? $coefficient;
        }
        if ($primitive === []) {
            return '';
        }
        $leading = $primitive[array_key_last($primitive)];
        if ($leading !== '0' && $leading[0] === '-') {
            foreach ($primitive as &$coefficient) {
                $coefficient = $arithmetic->negateIntegerValue($coefficient);
            }
            unset($coefficient);
        }

        return \implode(',', $primitive);
    }

    /** @param list<array{Node, int}> $terms */
    private function collectAdditiveTerms(Node $node, int $sign, array &$terms): void
    {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            $this->collectAdditiveTerms(
                $node->operand,
                $node->operator === UnaryOperator::Minus ? -$sign : $sign,
                $terms,
            );

            return;
        }
        if (
            $node instanceof BinaryOperationNode
            && \in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)
        ) {
            $this->collectAdditiveTerms($node->left, $sign, $terms);
            $this->collectAdditiveTerms(
                $node->right,
                $node->operator === BinaryOperator::Subtract ? -$sign : $sign,
                $terms,
            );

            return;
        }
        $terms[] = [$node, $sign];
    }

    /**
     * @return array{Node, int, int, int, array{string, string}|null}|null
     * Base, exponent numerator/denominator, coefficient sign and exact coefficient.
     */
    private function rationalPowerTerm(
        Node $node,
        ExactRationalPolynomialExtractor $extractor,
        int $maxPolynomialDegree,
    ): ?array {
        $factors = $this->rationalPowerMonomial($node, $extractor, $maxPolynomialDegree);
        if ($factors === null) {
            return null;
        }
        $basePower = null;
        $coefficientSign = 1;
        $exactCoefficient = ['1', '1'];
        /** @var list<array{array{string, string}, int, int}> $constantPowers */
        $constantPowers = [];
        foreach ($factors as [$base, $numerator, $denominator]) {
            $constant = RationalLiteral::fromNodeAsStrings($base);
            if ($constant === null) {
                if ($basePower !== null) {
                    return null;
                }
                $basePower = [$base, $numerator, $denominator];
                continue;
            }
            if ($constant[0] === '0') {
                return null;
            }
            if (($numerator % 2) !== 0 && $constant[0][0] === '-') {
                $coefficientSign = -$coefficientSign;
            }
            $constantPowers[] = [[\ltrim($constant[0], '-'), $constant[1]], $numerator, $denominator];
        }
        $commonDenominator = 1;
        foreach ($constantPowers as [, , $denominator]) {
            $multiple = \intdiv($commonDenominator, $this->integerGcd($commonDenominator, $denominator));
            if ($multiple > \intdiv(self::MAX_EXACT_ROOT_DEGREE, $denominator)) {
                $commonDenominator = null;
                break;
            }
            $commonDenominator = $multiple * $denominator;
        }
        foreach ($constantPowers as [$constant, $numerator, $denominator]) {
            if ($commonDenominator === null || $exactCoefficient === null) {
                break;
            }
            $integerPower = $numerator * \intdiv($commonDenominator, $denominator);
            $poweredConstant = $extractor->powerExactFraction($constant, $integerPower);
            $exactCoefficient = $poweredConstant === null
                ? null
                : $extractor->multiplyExactFractions($exactCoefficient, $poweredConstant);
        }
        if ($commonDenominator !== null && $exactCoefficient !== null) {
            $exactCoefficient = RationalLiteral::exactRationalPowerAsStrings(
                $exactCoefficient,
                1,
                $commonDenominator,
            );
        }

        return $basePower === null
            ? null
            : [
                $basePower[0],
                $basePower[1],
                $basePower[2],
                $coefficientSign,
                $exactCoefficient,
            ];
    }

    /** @return array{Node, int, int}|null Base and signed rational exponent. */
    private function rationalPowerAtom(
        Node $node,
        ExactRationalPolynomialExtractor $extractor,
        int $maxPolynomialDegree,
    ): ?array {
        $maximumPowerDegree = \max(63, $maxPolynomialDegree);
        $node = $this->unwrapGrouping($node);
        if ($node instanceof BinaryOperationNode && $node->operator === BinaryOperator::Power) {
            $exponent = $this->exactConstantRational($node->right, $extractor);
            if ($exponent === null) {
                return null;
            }
            $numerator = \filter_var($exponent[0], FILTER_VALIDATE_INT);
            $denominator = \filter_var($exponent[1], FILTER_VALIDATE_INT);
            if (
                !\is_int($numerator)
                || !\is_int($denominator)
                || $numerator === 0
                || \abs($numerator) > $maximumPowerDegree
                || $denominator < 1
                || $denominator > $maximumPowerDegree
                || ($denominator % 2) === 0
            ) {
                return null;
            }

            return [$node->left, $numerator, $denominator];
        }
        if ($node instanceof FunctionCallNode && \in_array($node->name, ['cbrt', 'root'], true)) {
            $degree = $node->name === 'cbrt'
                ? (\count($node->arguments) === 1 ? 3 : null)
                : $this->exactRootFunctionDegree($node->arguments, $extractor);
            if (
                $degree === null
                || $degree < -$maximumPowerDegree
                || $degree > $maximumPowerDegree
                || ($degree % 2) === 0
            ) {
                return null;
            }

            return [$node->arguments[0], $degree < 0 ? -1 : 1, \abs($degree)];
        }

        return $extractor->rationalPolynomialForm($node) === null
            ? null
            : [$node, 1, 1];
    }

    /**
     * @return list<array{Node, int, int}>|null Base, signed numerator, positive odd denominator.
     */
    private function rationalPowerMonomial(
        Node $node,
        ExactRationalPolynomialExtractor $extractor,
        int $maxPolynomialDegree,
    ): ?array {
        $maximumPowerDegree = \max(63, $maxPolynomialDegree);
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            $factors = $this->rationalPowerMonomial($node->operand, $extractor, $maxPolynomialDegree);
            if ($factors === null || $node->operator === UnaryOperator::Plus) {
                return $factors;
            }
            $negativeOne = new UnaryOperationNode(
                UnaryOperator::Minus,
                new NumberNode(1, '1', $node->span()),
                $node->span(),
            );
            $factors[] = [$negativeOne, 1, 1];

            return $factors;
        }
        if (
            $node instanceof BinaryOperationNode
            && \in_array($node->operator, [BinaryOperator::Multiply, BinaryOperator::Divide], true)
        ) {
            $leftFactors = $this->rationalPowerMonomial($node->left, $extractor, $maxPolynomialDegree);
            $rightFactors = $this->rationalPowerMonomial($node->right, $extractor, $maxPolynomialDegree);
            if ($leftFactors === null || $rightFactors === null) {
                return null;
            }
            $domainGuards = [];
            if ($node->operator === BinaryOperator::Divide) {
                foreach ($rightFactors as &$factor) {
                    if ($factor[1] < 0) {
                        $domainGuards[] = [$factor[0], 1, 1];
                        $domainGuards[] = [$factor[0], -1, 1];
                    }
                    $factor[1] = -$factor[1];
                }
                unset($factor);
            }

            return [...$leftFactors, ...$rightFactors, ...$domainGuards];
        }
        if (
            $node instanceof BinaryOperationNode
            && $node->operator === BinaryOperator::Power
        ) {
            $exponent = $this->exactConstantRational($node->right, $extractor);
            if ($exponent === null) {
                return null;
            }
            $numerator = \filter_var($exponent[0], FILTER_VALIDATE_INT);
            $denominator = \filter_var($exponent[1], FILTER_VALIDATE_INT);
            if (
                !\is_int($numerator)
                || !\is_int($denominator)
                || $numerator === 0
                || \abs($numerator) > $maximumPowerDegree
                || $denominator < 1
                || $denominator > $maximumPowerDegree
                || ($denominator % 2) === 0
            ) {
                return null;
            }
            $basePowers = $this->rationalPowerMonomial($node->left, $extractor, $maxPolynomialDegree);
            if ($basePowers === null) {
                return null;
            }
            $domainGuards = [];
            foreach ($basePowers as &$basePower) {
                if ($numerator < 0 && $basePower[1] < 0) {
                    $domainGuards[] = [$basePower[0], 1, 1];
                    $domainGuards[] = [$basePower[0], -1, 1];
                }
                $combinedNumerator = $basePower[1] * $numerator;
                $combinedDenominator = $basePower[2] * $denominator;
                $divisor = $this->integerGcd(\abs($combinedNumerator), $combinedDenominator);
                $combinedNumerator = \intdiv($combinedNumerator, $divisor);
                $combinedDenominator = \intdiv($combinedDenominator, $divisor);
                if (
                    \abs($combinedNumerator) > $maximumPowerDegree
                    || $combinedDenominator > $maximumPowerDegree
                ) {
                    return null;
                }
                $basePower[1] = $combinedNumerator;
                $basePower[2] = $combinedDenominator;
            }
            unset($basePower);

            return [...$basePowers, ...$domainGuards];
        }
        if ($node instanceof FunctionCallNode && \in_array($node->name, ['cbrt', 'root'], true)) {
            $degree = $node->name === 'cbrt'
                ? (\count($node->arguments) === 1 ? 3 : null)
                : $this->exactRootFunctionDegree($node->arguments, $extractor);
            if (
                $degree === null
                || $degree < -$maximumPowerDegree
                || $degree > $maximumPowerDegree
                || ($degree % 2) === 0
            ) {
                return null;
            }

            return [[$node->arguments[0], $degree < 0 ? -1 : 1, \abs($degree)]];
        }

        return $extractor->rationalPolynomialForm($node) === null
            ? null
            : [[$node, 1, 1]];
    }

    /**
     * @param list<array{Node, int, int}> $rationalPowers
     * @return list<array{Node, int}>|null
     */
    private function integerPowerFactors(
        array $rationalPowers,
        int $commonDenominator,
        int $maxPolynomialDegree,
    ): ?array {
        $factors = [];
        foreach ($rationalPowers as [$base, $numerator, $denominator]) {
            $multiplier = \intdiv($commonDenominator, $denominator);
            if ($numerator !== 0 && \abs($numerator) > \intdiv(\PHP_INT_MAX, $multiplier)) {
                return null;
            }
            $integerPower = $numerator * $multiplier;
            if (\abs($integerPower) > $maxPolynomialDegree) {
                return null;
            }
            $factors[] = [$base, $integerPower];
        }

        return $factors;
    }

    private function sameStrictlyMonotoneFunction(string $left, string $right): bool
    {
        $aliases = [
            'arctan' => 'atan',
            'arcsinh' => 'asinh',
        ];
        $left = $aliases[$left] ?? $left;
        $right = $aliases[$right] ?? $right;
        $supported = [
            'exp', 'expm1', 'sinh', 'tanh', 'asinh', 'atan',
            'erf', 'erfc', 'erfi', 'cbrt', 'acot',
        ];

        return $left === $right && \in_array($left, $supported, true);
    }

    /**
     * @param array<string, int|float> $parameters
     * @return array{Node, array{string, string}}|false|null
     */
    private function nestedRadicalArguments(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
    ): array|false|null {
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $chain = $this->nestedRadicalChain($candidate, $extractor, $maxPolynomialDegree);
            if ($chain === null || \count($chain[1]) < 2 || \count($chain[1]) > 8) {
                continue;
            }
            [$candidate, $degrees] = $chain;
            $targetPolynomial = $extractor->polynomial($target);
            if ($targetPolynomial === null || \count($targetPolynomial) !== 1) {
                continue;
            }
            $targetFraction = $targetPolynomial[0];
            $targetInterval = new ExactRationalInterval($targetFraction, $targetFraction);
            $hasNegativeDegree = false;
            $hasNegativeEvenDegree = false;
            $hasEvenDegree = false;
            foreach ($degrees as $degree) {
                $hasNegativeDegree = $hasNegativeDegree || $degree < 0;
                $hasNegativeEvenDegree = $hasNegativeEvenDegree || ($degree < 0 && $degree % 2 === 0);
                $hasEvenDegree = $hasEvenDegree || $degree % 2 === 0;
            }
            if (
                $hasEvenDegree
                && $targetInterval->compareLowerToRational('0', '1') < 0
            ) {
                return false;
            }
            if (
                ($hasNegativeDegree && $targetInterval->compareLowerToRational('0', '1') === 0)
                || ($hasNegativeEvenDegree && $targetInterval->compareLowerToRational('0', '1') === 0)
            ) {
                return false;
            }
            try {
                $targetPower = $targetInterval;
                foreach ($degrees as $degree) {
                    $previousPower = $targetPower;
                    $targetPower = new ExactRationalInterval(['1', '1'], ['1', '1']);
                    for ($power = 0; $power < \abs($degree); ++$power) {
                        $targetPower = $targetPower->multiply($previousPower);
                    }
                    if ($degree < 0) {
                        $targetPower = $targetPower->reciprocal();
                    }
                }
            } catch (\DomainException | \LengthException) {
                continue;
            }

            return [$candidate, $targetPower->lower];
        }

        return null;
    }

    /** @param array<string, int|float> $parameters
     *  @return array{Node, Node}|null
     */
    private function equivalentOddRadicalArguments(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
    ): ?array {
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        $leftChain = $this->nestedRadicalChain($left, $extractor, $maxPolynomialDegree);
        $rightChain = $this->nestedRadicalChain($right, $extractor, $maxPolynomialDegree);
        if ($leftChain === null || $rightChain === null) {
            return null;
        }
        [$leftArgument, $leftDegrees] = $leftChain;
        [$rightArgument, $rightDegrees] = $rightChain;
        if (
            $leftDegrees === []
            || $rightDegrees === []
            || \count($leftDegrees) > 8
            || \count($rightDegrees) > 8
        ) {
            return null;
        }
        $leftTotalDegree = 1;
        foreach ($leftDegrees as $degree) {
            if (
                $degree < 1
                || $degree % 2 === 0
                || $leftTotalDegree > \intdiv(\PHP_INT_MAX, $degree)
            ) {
                return null;
            }
            $leftTotalDegree *= $degree;
        }
        $rightTotalDegree = 1;
        foreach ($rightDegrees as $degree) {
            if (
                $degree < 1
                || $degree % 2 === 0
                || $rightTotalDegree > \intdiv(\PHP_INT_MAX, $degree)
            ) {
                return null;
            }
            $rightTotalDegree *= $degree;
        }

        return $leftTotalDegree === $rightTotalDegree
            ? [$leftArgument, $rightArgument]
            : null;
    }

    /** @return array{Node, list<int>}|null */
    private function nestedRadicalChain(
        Node $candidate,
        ExactRationalPolynomialExtractor $extractor,
        int $maxPolynomialDegree,
    ): ?array {
        $maximumRootDegree = \max(63, $maxPolynomialDegree);
        $candidate = $this->unwrapGrouping($candidate);
        $degrees = [];
        while (true) {
            if ($candidate instanceof FunctionCallNode) {
                $degree = match ($candidate->name) {
                    'sqrt' => \count($candidate->arguments) === 1 ? 2 : null,
                    'cbrt' => \count($candidate->arguments) === 1 ? 3 : null,
                    'root' => $this->exactNestedRootDegree(
                        $candidate->arguments,
                        $extractor,
                        $maximumRootDegree,
                    ),
                    default => null,
                };
                if ($degree === null) {
                    break;
                }
                $degrees[] = $degree;
                $candidate = $this->unwrapGrouping($candidate->arguments[0]);
                continue;
            }
            if (
                !$candidate instanceof BinaryOperationNode
                || $candidate->operator !== BinaryOperator::Power
            ) {
                break;
            }
            $exponent = RationalLiteral::fromNodeAsStrings($candidate->right);
            if (
                $exponent === null
                || $exponent[1] === '1'
                || !\in_array($exponent[0], ['1', '-1'], true)
            ) {
                break;
            }
            $degree = \filter_var($exponent[1], FILTER_VALIDATE_INT);
            if (!\is_int($degree) || $degree < 2 || $degree > $maximumRootDegree) {
                break;
            }
            $degrees[] = $exponent[0] === '-1' ? -$degree : $degree;
            $candidate = $this->unwrapGrouping($candidate->left);
        }

        return $degrees === [] ? null : [$candidate, $degrees];
    }

    /** @param list<Node> $arguments */
    private function exactNestedRootDegree(
        array $arguments,
        ExactRationalPolynomialExtractor $extractor,
        int $maximumRootDegree,
    ): ?int {
        $degree = $this->exactRootFunctionDegree($arguments, $extractor);

        return $degree !== null
            && $degree !== 0
            && $degree >= -$maximumRootDegree
            && $degree <= $maximumRootDegree
            ? $degree
            : null;
    }

    /**
     * Reduce exp(P) = 1 + P and ln(1 + P) = P to the exact zero set P = 0.
     *
     * @param array<string, int|float> $parameters
     */
    private function exponentialTangentEqualityArguments(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
    ): ?Node {
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            $target = $this->unwrapGrouping($target);
            if (
                !$candidate instanceof FunctionCallNode
                || \count($candidate->arguments) !== 1
                || !\in_array($candidate->name, ['exp', 'ln'], true)
                || !$evaluationOptions->functions->isBuiltIn($candidate->name)
            ) {
                continue;
            }
            $functionArgument = $this->unwrapGrouping($candidate->arguments[0]);
            if ($candidate->name === 'exp') {
                $otherArgument = $this->onePlusArgument($target);
                if ($otherArgument === null) {
                    continue;
                }
                $difference = $extractor->rationalDifference($functionArgument, $otherArgument);
                $negativeDifference = $extractor->rationalDifference(
                    $functionArgument,
                    new UnaryOperationNode(UnaryOperator::Minus, $otherArgument, $otherArgument->span()),
                );
                if (
                    ($difference !== null && $this->isZeroCoefficientList($difference[0]))
                    || ($negativeDifference !== null && $this->isZeroCoefficientList($negativeDifference[0]))
                ) {
                    return $functionArgument;
                }

                continue;
            }
            $logarithmArgument = $this->onePlusArgument($functionArgument);
            if ($logarithmArgument === null) {
                continue;
            }
            $difference = $extractor->rationalDifference($logarithmArgument, $target);
            $negativeDifference = $extractor->rationalDifference(
                $logarithmArgument,
                new UnaryOperationNode(UnaryOperator::Minus, $target, $target->span()),
            );
            if (
                ($difference !== null && $this->isZeroCoefficientList($difference[0]))
                || ($negativeDifference !== null && $this->isZeroCoefficientList($negativeDifference[0]))
            ) {
                return $logarithmArgument;
            }
        }

        return null;
    }

    private function onePlusArgument(Node $node): ?Node
    {
        $node = $this->unwrapGrouping($node);
        if (!$node instanceof BinaryOperationNode) {
            return null;
        }
        if (
            $node->operator === BinaryOperator::Subtract
            && RationalLiteral::fromNodeAsStrings($node->left) === ['1', '1']
        ) {
            return new UnaryOperationNode(UnaryOperator::Minus, $node->right, $node->left->span());
        }
        if ($node->operator !== BinaryOperator::Add) {
            return null;
        }
        if (RationalLiteral::fromNodeAsStrings($node->left) === ['1', '1']) {
            return $node->right;
        }
        if (RationalLiteral::fromNodeAsStrings($node->right) === ['1', '1']) {
            return $node->left;
        }

        return null;
    }

    /**
     * Reduce equality with a finite Taylor polynomial of exp to its argument's zeros.
     *
     * @param array<string, int|float> $parameters
     */
    private function exponentialTaylorEqualityArgument(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
    ): ?Node {
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            $target = $this->unwrapGrouping($target);
            if (
                !$candidate instanceof FunctionCallNode
                || \count($candidate->arguments) !== 1
                || !\in_array($candidate->name, ['exp', 'ln'], true)
                || !$evaluationOptions->functions->isBuiltIn($candidate->name)
            ) {
                continue;
            }
            $argument = $candidate->name === 'exp'
                ? $this->unwrapGrouping($candidate->arguments[0])
                : $target;
            $polynomial = $candidate->name === 'exp'
                ? $target
                : $this->unwrapGrouping($candidate->arguments[0]);
            for ($degree = 2; $degree <= 12; ++$degree) {
                $taylor = $this->exponentialTaylorPolynomial($argument, $degree);
                $difference = $extractor->rationalDifference($polynomial, $taylor);
                if ($difference !== null && $this->isZeroCoefficientList($difference[0])) {
                    return $argument;
                }
            }
        }

        return null;
    }

    private function exponentialTaylorPolynomial(Node $argument, int $degree): Node
    {
        $span = $argument->span();
        $sum = new NumberNode(1, '1', $span);
        $factorial = 1;
        for ($power = 1; $power <= $degree; ++$power) {
            $factorial *= $power;
            $powerNode = $power === 1
                ? $argument
                : new BinaryOperationNode(
                    BinaryOperator::Power,
                    $argument,
                    new NumberNode($power, (string) $power, $span),
                    $span,
                );
            $term = new BinaryOperationNode(
                BinaryOperator::Divide,
                $powerNode,
                new NumberNode($factorial, (string) $factorial, $span),
                $span,
            );
            $sum = new BinaryOperationNode(BinaryOperator::Add, $sum, $term, $span);
        }

        return $sum;
    }

    /**
     * Reduce sinh/cosh equality with their finite Taylor polynomials to P = 0.
     *
     * @param array<string, int|float> $parameters
     */
    private function hyperbolicTaylorEqualityArgument(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
    ): ?Node {
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || \count($candidate->arguments) !== 1
                || !\in_array($candidate->name, ['sinh', 'cosh'], true)
                || !$evaluationOptions->functions->isBuiltIn($candidate->name)
            ) {
                continue;
            }
            $argument = $this->unwrapGrouping($candidate->arguments[0]);
            for ($terms = 1; $terms <= 6; ++$terms) {
                $taylor = $this->hyperbolicTaylorPolynomial($argument, $candidate->name, $terms);
                $difference = $extractor->rationalDifference($target, $taylor);
                if ($difference !== null && $this->isZeroCoefficientList($difference[0])) {
                    return $argument;
                }
            }
        }

        return null;
    }

    private function hyperbolicTaylorPolynomial(Node $argument, string $function, int $terms): Node
    {
        $span = $argument->span();
        $isCosh = $function === 'cosh';
        $sum = new NumberNode($isCosh ? 1 : 0, $isCosh ? '1' : '0', $span);
        for ($index = 0; $index < $terms; ++$index) {
            $power = $isCosh ? 2 * ($index + 1) : 2 * $index + 1;
            $factorial = 1;
            for ($factor = 2; $factor <= $power; ++$factor) {
                $factorial *= $factor;
            }
            $powerNode = $power === 1
                ? $argument
                : new BinaryOperationNode(
                    BinaryOperator::Power,
                    $argument,
                    new NumberNode($power, (string) $power, $span),
                    $span,
                );
            $term = new BinaryOperationNode(
                BinaryOperator::Divide,
                $powerNode,
                new NumberNode($factorial, (string) $factorial, $span),
                $span,
            );
            $sum = new BinaryOperationNode(BinaryOperator::Add, $sum, $term, $span);
        }

        return $sum;
    }

    /**
     * Reduce the first globally one-sided sine and cosine Taylor remainders to P = 0.
     *
     * @param array<string, int|float> $parameters
     */
    private function trigonometricTaylorEqualityArgument(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
    ): ?Node {
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || \count($candidate->arguments) !== 1
                || !\in_array($candidate->name, ['sin', 'cos'], true)
                || !$evaluationOptions->functions->isBuiltIn($candidate->name)
            ) {
                continue;
            }
            $argument = $this->unwrapGrouping($candidate->arguments[0]);
            $span = $argument->span();
            $one = new NumberNode(1, '1', $span);
            if ($candidate->name === 'cos') {
                $square = new BinaryOperationNode(
                    BinaryOperator::Power,
                    $argument,
                    new NumberNode(2, '2', $span),
                    $span,
                );
                $taylor = new BinaryOperationNode(
                    BinaryOperator::Subtract,
                    $one,
                    new BinaryOperationNode(
                        BinaryOperator::Divide,
                        $square,
                        new NumberNode(2, '2', $span),
                        $span,
                    ),
                    $span,
                );
            } else {
                $cube = new BinaryOperationNode(
                    BinaryOperator::Power,
                    $argument,
                    new NumberNode(3, '3', $span),
                    $span,
                );
                $taylor = new BinaryOperationNode(
                    BinaryOperator::Subtract,
                    $argument,
                    new BinaryOperationNode(
                        BinaryOperator::Divide,
                        $cube,
                        new NumberNode(6, '6', $span),
                        $span,
                    ),
                    $span,
                );
            }
            $difference = $extractor->rationalDifference($target, $taylor);
            if ($difference !== null && $this->isZeroCoefficientList($difference[0])) {
                return $argument;
            }
        }

        return null;
    }

    /**
     * Reduce strict zero-only fixed-point equations f(P) = P to P = 0.
     *
     * @param array<string, int|float> $parameters
     */
    private function zeroOnlyFixedPointArgument(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
    ): ?Node {
        $fixedPointFunctions = [
            'sin', 'sinh', 'tanh', 'atan', 'arctan', 'asinh', 'arcsinh', 'atanh', 'arctanh',
        ];
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            $target = $this->unwrapGrouping($target);
            if (
                !$candidate instanceof FunctionCallNode
                || \count($candidate->arguments) !== 1
                || !\in_array($candidate->name, $fixedPointFunctions, true)
                || !$evaluationOptions->functions->isBuiltIn($candidate->name)
            ) {
                continue;
            }
            $argument = $this->unwrapGrouping($candidate->arguments[0]);
            $difference = $extractor->rationalDifference($argument, $target);
            if ($difference !== null && $this->isZeroCoefficientList($difference[0])) {
                return $argument;
            }
        }

        return null;
    }

    /**
     * Detect elementary real fixed-point equations with no solutions.
     *
     * @param array<string, int|float> $parameters
     */
    private function isImpossibleRealFixedPointEquation(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
    ): bool {
        $impossibleFunctions = ['exp', 'ln', 'cosh'];
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            $target = $this->unwrapGrouping($target);
            if (
                !$candidate instanceof FunctionCallNode
                || \count($candidate->arguments) !== 1
                || !\in_array($candidate->name, $impossibleFunctions, true)
                || !$evaluationOptions->functions->isBuiltIn($candidate->name)
            ) {
                continue;
            }
            $difference = $extractor->rationalDifference($candidate->arguments[0], $target);
            if ($difference !== null && $this->isZeroCoefficientList($difference[0])) {
                return true;
            }
        }

        return false;
    }

    /** @return array{Node, Node}|false|null */
    private function inverseCompositionArguments(Node $left, Node $right): array|false|null
    {
        $inversePairs = [
            'erfinv' => 'erf',
            'erfcinv' => 'erfc',
            'asinh' => 'sinh',
            'arcsinh' => 'sinh',
            'atanh' => 'tanh',
            'arctanh' => 'tanh',
            'acoth' => 'coth',
            'acsch' => 'csch',
        ];
        $forwardInversePairs = [
            'erf' => 'erfinv',
            'erfc' => 'erfcinv',
            'sinh' => 'asinh',
            'tan' => 'atan',
            'cot' => 'acot',
        ];
        $allRealInversePairs = ['asinh', 'arcsinh', 'atanh', 'arctanh'];
        $nonzeroRangeInversePairs = ['acoth', 'acsch'];
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            $target = $this->unwrapGrouping($target);
            $inverseRegularizedArguments = $this->inverseRegularizedCompositionArguments($candidate, $target);
            if ($inverseRegularizedArguments !== null) {
                return $inverseRegularizedArguments;
            }
            $regularizedInverseArguments = $this->regularizedInverseCompositionArguments($candidate, $target);
            if ($regularizedInverseArguments !== null) {
                return $regularizedInverseArguments;
            }
            $absoluteHyperbolicArguments = $this->absoluteHyperbolicInverseArguments($candidate, $target);
            if ($absoluteHyperbolicArguments !== null) {
                return $absoluteHyperbolicArguments;
            }
            $targetFraction = RationalLiteral::fromNodeAsStrings($target);
            if ($targetFraction !== null) {
                $targetIsPositive = $targetFraction[0] !== '0' && $targetFraction[0][0] !== '-';
                if (
                    $candidate instanceof FunctionCallNode
                    && $candidate->name === 'exp'
                    && \count($candidate->arguments) === 1
                ) {
                    $inner = $this->unwrapGrouping($candidate->arguments[0]);
                    if (
                        $inner instanceof FunctionCallNode
                        && $inner->name === 'ln'
                        && \count($inner->arguments) === 1
                    ) {
                        return $targetIsPositive
                            ? [$inner->arguments[0], $target]
                            : false;
                    }
                }
                if (
                    $candidate instanceof BinaryOperationNode
                    && $candidate->operator === BinaryOperator::Power
                ) {
                    $exponent = $this->unwrapGrouping($candidate->right);
                    if (
                        $this->isEulerConstant($candidate->left)
                        && $exponent instanceof FunctionCallNode
                        && $exponent->name === 'ln'
                        && \count($exponent->arguments) === 1
                    ) {
                        return $targetIsPositive
                            ? [$exponent->arguments[0], $target]
                            : false;
                    }
                    if (
                        $exponent instanceof FunctionCallNode
                        && (
                            (\count($exponent->arguments) === 1
                                && \in_array($exponent->name, ['log2', 'log10'], true)
                                && $this->isMatchingLogarithmBase($exponent->name, $candidate->left))
                            || (\count($exponent->arguments) === 2
                                && $exponent->name === 'log'
                                && $this->sameValidRationalLogarithmBase(
                                    $candidate->left,
                                    $exponent->arguments[1],
                                ))
                        )
                    ) {
                        return $targetIsPositive
                            ? [$exponent->arguments[0], $target]
                            : false;
                    }
                }
            }
            if (!$candidate instanceof FunctionCallNode || \count($candidate->arguments) !== 1) {
                if (
                    $candidate instanceof FunctionCallNode
                    && $candidate->name === 'log'
                    && \count($candidate->arguments) === 2
                ) {
                    $power = $this->unwrapGrouping($candidate->arguments[0]);
                    if (
                        $power instanceof BinaryOperationNode
                        && $power->operator === BinaryOperator::Power
                        && $this->sameValidRationalLogarithmBase(
                            $power->left,
                            $candidate->arguments[1],
                        )
                    ) {
                        return [$power->right, $target];
                    }
                }

                continue;
            }
            $inner = $this->unwrapGrouping($candidate->arguments[0]);
            if (
                $candidate->name === 'ln'
                && $inner instanceof FunctionCallNode
                && $inner->name === 'exp'
                && \count($inner->arguments) === 1
            ) {
                return [$inner->arguments[0], $target];
            }
            if (
                $candidate->name === 'ln'
                && $inner instanceof BinaryOperationNode
                && $inner->operator === BinaryOperator::Power
                && $this->isEulerConstant($inner->left)
            ) {
                return [$inner->right, $target];
            }
            if (
                $candidate->name === 'log1p'
                && $inner instanceof FunctionCallNode
                && $inner->name === 'expm1'
                && \count($inner->arguments) === 1
            ) {
                return [$inner->arguments[0], $target];
            }
            if (
                $candidate->name === 'expm1'
                && $inner instanceof FunctionCallNode
                && $inner->name === 'log1p'
                && \count($inner->arguments) === 1
            ) {
                $targetFraction = RationalLiteral::fromNodeAsStrings($target);
                if ($targetFraction === null) {
                    continue;
                }
                if (
                    (new ExactRationalInterval($targetFraction, $targetFraction))
                        ->compareLowerToRational('-1', '1') <= 0
                ) {
                    return false;
                }

                return [$inner->arguments[0], $target];
            }
            if (
                ($forwardInversePairs[$candidate->name] ?? null) !== null
                && $inner instanceof FunctionCallNode
                && $inner->name === $forwardInversePairs[$candidate->name]
                && \count($inner->arguments) === 1
            ) {
                if (\in_array($candidate->name, ['sinh', 'tan', 'cot'], true)) {
                    return [$inner->arguments[0], $target];
                }
                if (\in_array($candidate->name, ['erfinv', 'erfcinv'], true)) {
                    return [$inner->arguments[0], $target];
                }
                $targetFraction = RationalLiteral::fromNodeAsStrings($target);
                if ($targetFraction === null) {
                    continue;
                }
                $targetInterval = new ExactRationalInterval($targetFraction, $targetFraction);
                $withinRange = $candidate->name === 'erf'
                    ? $targetInterval->compareLowerToRational('-1', '1') > 0
                        && $targetInterval->compareUpperToRational('1', '1') < 0
                    : $targetInterval->compareLowerToRational('0', '1') > 0
                        && $targetInterval->compareUpperToRational('2', '1') < 0;
                if (!$withinRange) {
                    return false;
                }

                return [$inner->arguments[0], $target];
            }
            if (
                \in_array($candidate->name, ['log2', 'log10'], true)
                && $inner instanceof BinaryOperationNode
                && $inner->operator === BinaryOperator::Power
                && $this->isMatchingLogarithmBase($candidate->name, $inner->left)
            ) {
                return [$inner->right, $target];
            }
            if (
                !$inner instanceof FunctionCallNode
                || \count($inner->arguments) !== 1
                || ($inversePairs[$candidate->name] ?? null) !== $inner->name
            ) {
                continue;
            }
            $targetFraction = RationalLiteral::fromNodeAsStrings($target);
            if (\in_array($candidate->name, ['erfinv', 'erfcinv'], true)) {
                return [$inner->arguments[0], $target];
            }
            if (\in_array($candidate->name, $allRealInversePairs, true)) {
                return [$inner->arguments[0], $target];
            }
            if (\in_array($candidate->name, $nonzeroRangeInversePairs, true)) {
                if ($targetFraction === null) {
                    continue;
                }
                if ($targetFraction[0] === '0') {
                    return false;
                }

                return [$inner->arguments[0], $target];
            }
            if ($targetFraction === null) {
                continue;
            }
            $targetInterval = new ExactRationalInterval($targetFraction, $targetFraction);
            if (
                $targetInterval->compareLowerToRational('-4', '1') < 0
                || $targetInterval->compareUpperToRational('4', '1') > 0
            ) {
                continue;
            }

            return [$inner->arguments[0], $target];
        }

        return null;
    }

    /** @return array{Node, Node}|false|null */
    private function inverseRegularizedCompositionArguments(Node $candidate, Node $target): array|false|null
    {
        if (!$candidate instanceof FunctionCallNode) {
            return null;
        }
        $composition = match ($candidate->name) {
            'gammaincinv' => ['gammainc', 2],
            'gammainccinv' => ['gammaincc', 2],
            'betaincinv' => ['betainc', 3],
            'betainccinv' => ['betaincc', 3],
            default => null,
        };
        if ($composition === null || \count($candidate->arguments) !== $composition[1]) {
            return null;
        }
        $regularized = $this->unwrapGrouping($candidate->arguments[$composition[1] - 1]);
        if (
            !$regularized instanceof FunctionCallNode
            || $regularized->name !== $composition[0]
            || \count($regularized->arguments) !== $composition[1]
        ) {
            return null;
        }
        for ($index = 0; $index < $composition[1] - 1; ++$index) {
            $outerShape = RationalLiteral::fromNodeAsStrings($candidate->arguments[$index]);
            $innerShape = RationalLiteral::fromNodeAsStrings($regularized->arguments[$index]);
            if (
                $outerShape === null
                || $outerShape !== $innerShape
                || $outerShape[0] === '0'
                || $outerShape[0][0] === '-'
            ) {
                return null;
            }
        }
        $targetFraction = RationalLiteral::fromNodeAsStrings($target);
        if ($targetFraction === null) {
            return null;
        }
        $targetInterval = new ExactRationalInterval($targetFraction, $targetFraction);
        if ($composition[1] === 2) {
            if ($targetInterval->compareLowerToRational('0', '1') <= 0) {
                return false;
            }
        } elseif (
            $targetInterval->compareLowerToRational('0', '1') <= 0
            || $targetInterval->compareUpperToRational('1', '1') >= 0
        ) {
            return false;
        }

        return [$regularized->arguments[$composition[1] - 1], $target];
    }

    /** @return array{Node, Node}|false|null */
    private function regularizedInverseCompositionArguments(Node $candidate, Node $target): array|false|null
    {
        if (!$candidate instanceof FunctionCallNode) {
            return null;
        }
        $composition = match ($candidate->name) {
            'gammainc' => ['gammaincinv', 2],
            'gammaincc' => ['gammainccinv', 2],
            'betainc' => ['betaincinv', 3],
            'betaincc' => ['betainccinv', 3],
            default => null,
        };
        if ($composition === null || \count($candidate->arguments) !== $composition[1]) {
            return null;
        }
        $inverse = $this->unwrapGrouping($candidate->arguments[$composition[1] - 1]);
        if (
            !$inverse instanceof FunctionCallNode
            || $inverse->name !== $composition[0]
            || \count($inverse->arguments) !== $composition[1]
        ) {
            return null;
        }
        for ($index = 0; $index < $composition[1] - 1; ++$index) {
            $outerShape = RationalLiteral::fromNodeAsStrings($candidate->arguments[$index]);
            $innerShape = RationalLiteral::fromNodeAsStrings($inverse->arguments[$index]);
            if (
                $outerShape === null
                || $outerShape !== $innerShape
                || $outerShape[0] === '0'
                || $outerShape[0][0] === '-'
            ) {
                return null;
            }
        }
        $targetFraction = RationalLiteral::fromNodeAsStrings($target);
        if ($targetFraction === null) {
            return null;
        }
        $targetInterval = new ExactRationalInterval($targetFraction, $targetFraction);
        if (
            $targetInterval->compareLowerToRational('0', '1') <= 0
            || $targetInterval->compareUpperToRational('1', '1') >= 0
        ) {
            return false;
        }

        return [$inverse->arguments[$composition[1] - 1], $target];
    }

    /** @return array{Node, Node}|false|null */
    private function absoluteHyperbolicInverseArguments(Node $candidate, Node $target): array|false|null
    {
        if (!$candidate instanceof FunctionCallNode || \count($candidate->arguments) !== 1) {
            return null;
        }
        $forwardFunctions = match ($candidate->name) {
            'acosh', 'arccosh' => ['cosh'],
            'asech' => ['sech'],
            default => [],
        };
        $inner = $this->unwrapGrouping($candidate->arguments[0]);
        if (
            $forwardFunctions === []
            || !$inner instanceof FunctionCallNode
            || !\in_array($inner->name, $forwardFunctions, true)
            || \count($inner->arguments) !== 1
        ) {
            return null;
        }
        $targetFraction = RationalLiteral::fromNodeAsStrings($target);
        if ($targetFraction === null) {
            return null;
        }
        if ($targetFraction[0][0] === '-') {
            return false;
        }

        $argument = $inner->arguments[0];
        $two = new NumberNode(2, '2', $argument->span());
        $argumentSquared = new BinaryOperationNode(
            BinaryOperator::Power,
            $argument,
            $two,
            $candidate->span(),
        );
        $targetTwo = new NumberNode(2, '2', $target->span());
        $targetSquared = new BinaryOperationNode(
            BinaryOperator::Power,
            $target,
            $targetTwo,
            $candidate->span(),
        );

        return [$argumentSquared, $targetSquared];
    }

    private function isMatchingLogarithmBase(string $logarithm, Node $base): bool
    {
        $base = $this->unwrapGrouping($base);

        return match ($logarithm) {
            'log2' => RationalLiteral::fromNodeAsStrings($base) === ['2', '1'],
            'log10' => RationalLiteral::fromNodeAsStrings($base) === ['10', '1'],
            default => false,
        };
    }

    private function sameValidRationalLogarithmBase(Node $first, Node $second): bool
    {
        $firstFraction = RationalLiteral::fromNodeAsStrings($first);
        $secondFraction = RationalLiteral::fromNodeAsStrings($second);
        if ($firstFraction === null || $secondFraction === null) {
            return false;
        }
        $firstInterval = new ExactRationalInterval($firstFraction, $firstFraction);
        $secondInterval = new ExactRationalInterval($secondFraction, $secondFraction);

        return $firstInterval->compareLowerToRational('0', '1') > 0
            && $firstInterval->compareLowerToRational('1', '1') !== 0
            && $firstInterval->compareLowerEndpoint($secondInterval) === 0;
    }

    private function isEulerConstant(Node $node): bool
    {
        $node = $this->unwrapGrouping($node);

        return $node instanceof ConstantNode && $node->name === 'e';
    }

    /** @return array{Node, Node}|null */
    private function complementaryInverseTangentArguments(Node $left, Node $right): ?array
    {
        foreach ([[$left, $right], [$right, $left]] as [$sumNode, $levelNode]) {
            $sumNode = $this->unwrapGrouping($sumNode);
            $levelNode = $this->unwrapGrouping($levelNode);
            if (
                !$sumNode instanceof BinaryOperationNode
                || $sumNode->operator !== BinaryOperator::Add
                || !$this->isPiHalf($levelNode)
            ) {
                continue;
            }
            $first = $this->unwrapGrouping($sumNode->left);
            $second = $this->unwrapGrouping($sumNode->right);
            foreach ([[$first, $second], [$second, $first]] as [$tangent, $cotangent]) {
                if (
                    !$tangent instanceof FunctionCallNode
                    || !\in_array($tangent->name, ['atan', 'arctan'], true)
                    || \count($tangent->arguments) !== 1
                    || !$cotangent instanceof FunctionCallNode
                    || $cotangent->name !== 'acot'
                    || \count($cotangent->arguments) !== 1
                ) {
                    continue;
                }

                return [$tangent->arguments[0], $cotangent->arguments[0]];
            }
        }

        return null;
    }

    private function isPiHalf(Node $node): bool
    {
        $node = $this->unwrapGrouping($node);
        if (
            !$node instanceof BinaryOperationNode
            || $node->operator !== BinaryOperator::Divide
        ) {
            return false;
        }
        $constant = $this->unwrapGrouping($node->left);
        $denominator = RationalLiteral::fromNodeAsStrings($node->right);

        return $constant instanceof ConstantNode
            && $constant->name === 'pi'
            && $denominator === ['2', '1'];
    }

    /** @return array{Node, Node}|null */
    private function complementaryErrorArguments(Node $left, Node $right): ?array
    {
        foreach ([[$left, $right], [$right, $left]] as [$sumNode, $levelNode]) {
            $sumNode = $this->unwrapGrouping($sumNode);
            $levelNode = $this->unwrapGrouping($levelNode);
            if (
                !$sumNode instanceof BinaryOperationNode
                || $sumNode->operator !== BinaryOperator::Add
                || RationalLiteral::fromNodeAsStrings($levelNode) !== ['1', '1']
            ) {
                continue;
            }
            $first = $this->unwrapGrouping($sumNode->left);
            $second = $this->unwrapGrouping($sumNode->right);
            foreach ([[$first, $second], [$second, $first]] as [$error, $complementaryError]) {
                if (
                    !$error instanceof FunctionCallNode
                    || $error->name !== 'erf'
                    || \count($error->arguments) !== 1
                    || !$complementaryError instanceof FunctionCallNode
                    || $complementaryError->name !== 'erfc'
                    || \count($complementaryError->arguments) !== 1
                ) {
                    continue;
                }

                return [$error->arguments[0], $complementaryError->arguments[0]];
            }
        }

        return null;
    }

    /** @return array{Node, Node}|null */
    private function oddFunctionSumArguments(Node $left, Node $right): ?array
    {
        foreach ([[$left, $right], [$right, $left]] as [$sumNode, $levelNode]) {
            $sumNode = $this->unwrapGrouping($sumNode);
            $levelNode = $this->unwrapGrouping($levelNode);
            if (
                !$sumNode instanceof BinaryOperationNode
                || $sumNode->operator !== BinaryOperator::Add
                || RationalLiteral::fromNodeAsStrings($levelNode) !== ['0', '1']
            ) {
                continue;
            }
            $first = $this->unwrapGrouping($sumNode->left);
            $second = $this->unwrapGrouping($sumNode->right);
            if (
                !$first instanceof FunctionCallNode
                || !$second instanceof FunctionCallNode
                || \count($first->arguments) !== 1
                || \count($second->arguments) !== 1
                || !$this->sameOddStrictlyMonotoneFunction($first->name, $second->name)
            ) {
                continue;
            }

            return [$first->arguments[0], $second->arguments[0]];
        }

        return null;
    }

    /** @return array{Node, Node}|null */
    private function oddFunctionEqualityArguments(Node $left, Node $right): ?array
    {
        foreach ([[$left, $right], [$right, $left]] as [$functionNode, $negativeNode]) {
            $functionNode = $this->unwrapGrouping($functionNode);
            $negativeNode = $this->unwrapGrouping($negativeNode);
            if (
                !$functionNode instanceof FunctionCallNode
                || \count($functionNode->arguments) !== 1
                || !$negativeNode instanceof UnaryOperationNode
                || $negativeNode->operator !== UnaryOperator::Minus
            ) {
                continue;
            }
            $negativeFunction = $this->unwrapGrouping($negativeNode->operand);
            if (
                !$negativeFunction instanceof FunctionCallNode
                || \count($negativeFunction->arguments) !== 1
                || !$this->sameOddStrictlyMonotoneFunction($functionNode->name, $negativeFunction->name)
            ) {
                continue;
            }

            return [$functionNode->arguments[0], $negativeFunction->arguments[0]];
        }

        return null;
    }

    private function sameOddStrictlyMonotoneFunction(string $left, string $right): bool
    {
        $aliases = [
            'arctan' => 'atan',
            'arcsinh' => 'asinh',
        ];
        $left = $aliases[$left] ?? $left;
        $right = $aliases[$right] ?? $right;

        return $left === $right
            && \in_array(
                $left,
                ['expm1', 'sinh', 'tanh', 'asinh', 'atan', 'erf', 'erfi', 'cbrt'],
                true,
            );
    }

    private function samePositiveStrictlyMonotoneFunction(string $left, string $right): bool
    {
        return $left === $right && \in_array($left, ['exp', 'erfc', 'erfcx'], true);
    }

    private function sameNonzeroOddAbsoluteInjectiveFunction(string $left, string $right): bool
    {
        return $left === $right && \in_array($left, ['acsch', 'csch', 'coth'], true);
    }

    private function samePositiveEvenFunction(string $left, string $right): bool
    {
        return $left === $right && \in_array($left, ['cosh', 'sech'], true);
    }

    /**
     * Enumerate all-real zeta levels for polynomials with an exact global minimum.
     *
     * @param array<string, int|float> $parameters
     * @return list<array{list<string>, list<string>}>|null Null means unsupported.
     */
    private function polynomialZetaAllRealLevels(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        int $maxPolynomialDegree,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || $candidate->name !== 'zeta'
                || \count($candidate->arguments) !== 1
            ) {
                continue;
            }
            $extractor = new ExactRationalPolynomialExtractor($variable, $parameters, $maxPolynomialDegree);
            $targetPolynomial = $extractor->polynomial($target);
            if ($targetPolynomial === null || \count($targetPolynomial) !== 1 || $targetPolynomial[0][0] !== '0') {
                return null;
            }
            $argument = $candidate->arguments[0];
            $polynomial = $extractor->polynomial($argument);
            if ($polynomial === null) {
                return null;
            }
            while (\count($polynomial) > 1 && $polynomial[\array_key_last($polynomial)][0] === '0') {
                \array_pop($polynomial);
            }
            $degree = \count($polynomial) - 1;
            if ($degree < 2) {
                return null;
            }
            $leading = new ExactRationalInterval(
                $polynomial[$degree],
                $polynomial[$degree],
            );
            if ($degree % 2 === 1 || $leading->compareLowerToRational('0', '1') < 0) {
                throw new InfiniteSolutionSetException('The zeta equation has infinitely many real roots.');
            }
            $minimum = $this->polynomialGlobalLowerBound($polynomial);
            if ($minimum === null) {
                return null;
            }
            if ((new ExactRationalInterval($minimum, $minimum))->compareLowerToRational('-2', '1') > 0) {
                return [];
            }
            $lastIndex = $this->positiveHalfIndex($minimum, false);
            if ($lastIndex === null) {
                return null;
            }

            $levels = [];
            for ($index = 1; $index <= $lastIndex; ++$index) {
                $levelForm = $extractor->rationalDifferenceFromFraction(
                    $argument,
                    [(string) (-2 * $index), '1'],
                );
                if ($levelForm === null || $levelForm[1] !== ['1']) {
                    return null;
                }
                if (\count($levelForm[0]) > 1) {
                    $levels[] = $levelForm;
                }
            }

            return $levels;
        }

        return null;
    }

    /**
     * Enumerate zeta levels for bounded rational functions with no genuine real poles.
     *
     * @param array<string, int|float> $parameters
     * @return list<array{list<string>, list<string>}>|null
     */
    private function rationalZetaAllRealLevels(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        int $maxPolynomialDegree,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || $candidate->name !== 'zeta'
                || \count($candidate->arguments) !== 1
            ) {
                continue;
            }
            $extractor = new ExactRationalPolynomialExtractor($variable, $parameters, $maxPolynomialDegree);
            $targetPolynomial = $extractor->polynomial($target);
            if ($targetPolynomial === null || \count($targetPolynomial) !== 1 || $targetPolynomial[0][0] !== '0') {
                return null;
            }
            if ($extractor->polynomial($candidate->arguments[0]) !== null) {
                return null;
            }
            $form = $extractor->rationalPolynomialForm($candidate->arguments[0]);
            if ($form === null) {
                return null;
            }
            [$numerator, $denominator] = $form;
            while (\count($numerator) > 1 && $numerator[\array_key_last($numerator)][0] === '0') {
                \array_pop($numerator);
            }
            while (\count($denominator) > 1 && $denominator[\array_key_last($denominator)][0] === '0') {
                \array_pop($denominator);
            }
            $rangeForm = $this->cancelCommonRationalPolynomialFactors($extractor, $numerator, $denominator);
            if ($rangeForm !== null) {
                [$numerator, $denominator] = $rangeForm;
            }
            $integerDenominator = $extractor->integerCoefficients($denominator);
            $integerNumerator = $extractor->integerCoefficients($numerator);
            if ($integerDenominator === null || $integerNumerator === null) {
                return null;
            }
            $counter = new ExactPolynomialRootCounter();
            $squarePoleLevels = $this->rationalZetaSquarePoleLevels(
                $extractor,
                $candidate->arguments[0],
                $numerator,
                $denominator,
            );
            if ($squarePoleLevels !== null) {
                return $squarePoleLevels;
            }
            if ($counter->countAllRealRoots($integerDenominator) !== 0) {
                return null;
            }
            $numeratorDegree = \count($numerator) - 1;
            $denominatorDegree = \count($denominator) - 1;
            $positiveInfiniteUpperBound = false;
            if ($numeratorDegree > $denominatorDegree) {
                $degreeDifference = $numeratorDegree - $denominatorDegree;
                $leadingRatio = (new ExactRationalInterval(
                    $numerator[$numeratorDegree],
                    $numerator[$numeratorDegree],
                ))->divide(new ExactRationalInterval(
                    $denominator[$denominatorDegree],
                    $denominator[$denominatorDegree],
                ))->lower;
                $leadingSign = $this->compareRationalFractions($leadingRatio, ['0', '1']);
                if (($degreeDifference % 2) === 1 || $leadingSign < 0) {
                    throw new InfiniteSolutionSetException(
                        'The rational zeta argument is unbounded below and has infinitely many roots.',
                    );
                }
                $positiveInfiniteUpperBound = true;
            }

            $numeratorDerivative = $this->differentiateRationalPolynomial($numerator);
            $denominatorDerivative = $this->differentiateRationalPolynomial($denominator);
            $leftCriticalPart = $this->multiplyRationalPolynomials($numeratorDerivative, $denominator);
            $rightCriticalPart = $this->multiplyRationalPolynomials($numerator, $denominatorDerivative);
            if ($leftCriticalPart === null || $rightCriticalPart === null) {
                return null;
            }
            $criticalNumerator = $this->subtractRationalPolynomials(
                $leftCriticalPart,
                $rightCriticalPart,
            );
            $integerCritical = $extractor->integerCoefficients($criticalNumerator);
            if ($integerCritical === null) {
                return null;
            }
            while (\count($integerCritical) > 1 && $integerCritical[\array_key_last($integerCritical)] === '0') {
                \array_pop($integerCritical);
            }
            if (\count($integerCritical) === 1 && $integerCritical[0] === '0') {
                return null;
            }
            $criticalRoots = \count($integerCritical) === 1
                ? []
                : $counter->isolateAllRealRoots(
                    $integerCritical,
                    maxDepth: 256,
                    maximumWidth: ['1', '1000000000000'],
                );
            if ($criticalRoots === null) {
                return null;
            }

            $rangeCandidates = [];
            if ($positiveInfiniteUpperBound) {
                if ($criticalRoots === []) {
                    return null;
                }
            } elseif ($numeratorDegree < $denominatorDegree) {
                $rangeCandidates[] = new ExactRationalInterval(['0', '1'], ['0', '1']);
            } else {
                $rangeCandidates[] = (new ExactRationalInterval(
                    $numerator[$numeratorDegree],
                    $numerator[$numeratorDegree],
                ))->divide(new ExactRationalInterval(
                    $denominator[$denominatorDegree],
                    $denominator[$denominatorDegree],
                ));
            }
            foreach ($criticalRoots as $criticalRoot) {
                [
                    $rootLowerNumerator,
                    $rootLowerDenominator,
                    $rootUpperNumerator,
                    $rootUpperDenominator,
                ] = $criticalRoot;
                try {
                    $criticalRange = $this->exactRationalFunctionRangeOnInterval(
                        $numerator,
                        $denominator,
                        [$rootLowerNumerator, $rootLowerDenominator],
                        [$rootUpperNumerator, $rootUpperDenominator],
                    );
                } catch (\LengthException) {
                    return null;
                }
                if ($criticalRange === null) {
                    return null;
                }
                $rangeCandidates[] = $criticalRange;
            }
            $minimum = $rangeCandidates[0]->lower;
            $maximum = $rangeCandidates[0]->upper;
            foreach ($rangeCandidates as $range) {
                if ($this->compareRationalFractions($range->lower, $minimum) < 0) {
                    $minimum = $range->lower;
                }
                if ($this->compareRationalFractions($range->upper, $maximum) > 0) {
                    $maximum = $range->upper;
                }
            }
            $firstIndex = $this->positiveHalfIndex($maximum, true);
            $lastIndex = $this->positiveHalfIndex($minimum, false);
            if ((!$positiveInfiniteUpperBound && $firstIndex === null) || $lastIndex === null) {
                return null;
            }
            $firstIndex = $positiveInfiniteUpperBound ? 1 : \max(1, $firstIndex);
            if ($lastIndex < $firstIndex) {
                return [];
            }
            if ($lastIndex - $firstIndex + 1 > self::MAX_SPECIAL_ZERO_LEVELS) {
                return null;
            }

            $levels = [];
            for ($index = $firstIndex; $index <= $lastIndex; ++$index) {
                $level = $extractor->rationalDifferenceFromFraction(
                    $candidate->arguments[0],
                    [(string) (-2 * $index), '1'],
                );
                if ($level === null) {
                    return null;
                }
                $levels[] = $level;
            }

            return $levels;
        }

        return null;
    }

    /** @param list<array{string, string}> $polynomial
     *  @return list<array{string, string}>
     */
    private function differentiateRationalPolynomial(array $polynomial): array
    {
        $derivative = [];
        for ($degree = 1, $count = \count($polynomial); $degree < $count; ++$degree) {
            $derivative[] = (new ExactRationalInterval($polynomial[$degree], $polynomial[$degree]))
                ->multiply(new ExactRationalInterval([(string) $degree, '1'], [(string) $degree, '1']))->lower;
        }

        return $derivative === [] ? [['0', '1']] : $derivative;
    }

    /**
     * Enumerate trivial zeta zeros for a linear-over-linear rational argument on a pole-free interval.
     *
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @return list<array{string, string}>|null
     */
    private function exactRationalZetaTrivialZeroRoots(
        ExactRationalPolynomialExtractor $extractor,
        Node $argument,
        array $lower,
        array $upper,
    ): ?array {
        $form = $extractor->rationalPolynomialForm($argument);
        if ($form === null) {
            return null;
        }
        [$numerator, $denominator] = $form;
        while (\count($numerator) > 1 && $numerator[\array_key_last($numerator)][0] === '0') {
            \array_pop($numerator);
        }
        while (\count($denominator) > 1 && $denominator[\array_key_last($denominator)][0] === '0') {
            \array_pop($denominator);
        }
        if (\count($numerator) > 2 || \count($denominator) > 2) {
            return null;
        }

        $lowerValue = $this->evaluateLinearRationalAt($numerator, $denominator, $lower);
        $upperValue = $this->evaluateLinearRationalAt($numerator, $denominator, $upper);
        $positiveInfiniteUpperBound = false;
        if ($lowerValue === null || $upperValue === null) {
            if (\count($denominator) !== 2) {
                return null;
            }
            $pole = (new ExactRationalInterval($denominator[0], $denominator[0]))
                ->negateInterval()
                ->divide(new ExactRationalInterval($denominator[1], $denominator[1]))->lower;
            $numeratorAtPole = $this->evaluateLinearAt($numerator, $pole);
            $residueSign = $this->compareRationalFractions($numeratorAtPole, ['0', '1'])
                * $this->compareRationalFractions($denominator[1], ['0', '1']);
            if (
                $lowerValue === null
                && $this->compareRationalFractions($pole, $lower) === 0
                && $residueSign > 0
            ) {
                $positiveInfiniteUpperBound = true;
                $lowerValue = $upperValue;
            } elseif (
                $upperValue === null
                && $this->compareRationalFractions($pole, $upper) === 0
                && $residueSign < 0
            ) {
                $positiveInfiniteUpperBound = true;
                $upperValue = $lowerValue;
            } else {
                return null;
            }
        }
        if ($lowerValue === null || $upperValue === null) {
            return null;
        }
        $minimum = $this->compareRationalFractions($lowerValue, $upperValue) <= 0
            ? $lowerValue
            : $upperValue;
        $maximum = $this->compareRationalFractions($lowerValue, $upperValue) <= 0
            ? $upperValue
            : $lowerValue;
        $firstIndex = $positiveInfiniteUpperBound ? 1 : $this->positiveHalfIndex($maximum, true);
        $lastIndex = $this->positiveHalfIndex($minimum, false);
        if ($firstIndex === null || $lastIndex === null) {
            return null;
        }
        $firstIndex = \max(1, $firstIndex);
        if ($lastIndex < $firstIndex) {
            return [];
        }
        if ($lastIndex - $firstIndex + 1 > self::MAX_SPECIAL_ZERO_LEVELS) {
            return null;
        }

        $roots = [];
        for ($index = $firstIndex; $index <= $lastIndex; ++$index) {
            $level = $extractor->rationalDifferenceFromFraction($argument, [(string) (-2 * $index), '1']);
            if ($level === null || \count($level[0]) !== 2) {
                return null;
            }
            $constant = $level[0][0];
            $slope = $level[0][1];
            if ($slope === '0') {
                return null;
            }
            $root = (new ExactRationalInterval([$constant, '1'], [$constant, '1']))
                ->negateInterval()
                ->divide(new ExactRationalInterval([$slope, '1'], [$slope, '1']))->lower;
            if (
                $this->compareRationalFractions($root, $lower) < 0
                || $this->compareRationalFractions($root, $upper) > 0
            ) {
                continue;
            }
            if ($this->evaluateLinearAt($denominator, $root) === ['0', '1']) {
                continue;
            }
            $roots[] = $root;
        }
        \usort($roots, fn (array $left, array $right): int => $this->compareRationalFractions($left, $right));

        return $roots;
    }

    /**
     * @param list<array{string, string}> $numerator
     * @param list<array{string, string}> $denominator
     * @param array{string, string} $point
     * @return array{string, string}|null
     */
    private function evaluateLinearRationalAt(array $numerator, array $denominator, array $point): ?array
    {
        $denominatorValue = $this->evaluateLinearAt($denominator, $point);
        if ($denominatorValue === ['0', '1']) {
            return null;
        }
        $numeratorValue = $this->evaluateLinearAt($numerator, $point);

        return (new ExactRationalInterval($numeratorValue, $numeratorValue))
            ->divide(new ExactRationalInterval($denominatorValue, $denominatorValue))->lower;
    }

    /**
     * @param list<array{string, string}> $polynomial
     * @param array{string, string} $point
     * @return array{string, string}
     */
    private function evaluateLinearAt(array $polynomial, array $point): array
    {
        return (new ExactRationalInterval($polynomial[0] ?? ['0', '1'], $polynomial[0] ?? ['0', '1']))
            ->add(
                (new ExactRationalInterval($polynomial[1] ?? ['0', '1'], $polynomial[1] ?? ['0', '1']))
                    ->multiply(new ExactRationalInterval($point, $point)),
            )->lower;
    }

    /**
     * Count zeta roots directly for a*x^n + b*x^(n-1) + c, where n is even.
     * The derivative has one minimum, so every crossed level contributes two roots.
     *
     * @param array<string, int|float> $parameters
     */
    private function countSimpleEvenPolynomialZetaRoots(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        int $maxPolynomialDegree,
    ): ?int {
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || $candidate->name !== 'zeta'
                || \count($candidate->arguments) !== 1
            ) {
                continue;
            }
            $extractor = new ExactRationalPolynomialExtractor($variable, $parameters, $maxPolynomialDegree);
            $targetPolynomial = $extractor->polynomial($target);
            if ($targetPolynomial === null || \count($targetPolynomial) !== 1 || $targetPolynomial[0][0] !== '0') {
                return null;
            }
            $polynomial = $extractor->polynomial($candidate->arguments[0]);
            if ($polynomial === null) {
                return null;
            }
            while (\count($polynomial) > 1 && $polynomial[\array_key_last($polynomial)][0] === '0') {
                \array_pop($polynomial);
            }
            $degree = \count($polynomial) - 1;
            if ($degree < 4 || $degree % 2 !== 0) {
                return null;
            }
            $leading = new ExactRationalInterval($polynomial[$degree], $polynomial[$degree]);
            if ($leading->compareLowerToRational('0', '1') <= 0) {
                return null;
            }
            for ($power = 1; $power < $degree - 1; ++$power) {
                if ($polynomial[$power][0] !== '0') {
                    return null;
                }
            }

            try {
                $linearCoefficient = new ExactRationalInterval(
                    $polynomial[$degree - 1],
                    $polynomial[$degree - 1],
                );
                $criticalPoint = $linearCoefficient
                    ->multiply(
                        new ExactRationalInterval(
                            [(string) ($degree - 1), '1'],
                            [(string) ($degree - 1), '1'],
                        ),
                    )
                    ->negateInterval()
                    ->divide(
                        $leading->multiply(
                            new ExactRationalInterval([(string) $degree, '1'], [(string) $degree, '1']),
                        ),
                    );
                $criticalPower = new ExactRationalInterval(['1', '1'], ['1', '1']);
                $factor = $criticalPoint;
                $exponent = $degree - 1;
                while ($exponent > 0) {
                    if ($exponent % 2 === 1) {
                        $criticalPower = $criticalPower->multiply($factor);
                    }
                    $exponent = intdiv($exponent, 2);
                    if ($exponent > 0) {
                        $factor = $factor->multiply($factor);
                    }
                }
                $minimum = new ExactRationalInterval($polynomial[0], $polynomial[0])->add(
                    $linearCoefficient
                        ->divide(new ExactRationalInterval([(string) $degree, '1'], [(string) $degree, '1']))
                        ->multiply($criticalPower),
                );
            } catch (\LengthException) {
                return null;
            }
            $lastLevel = $this->positiveHalfIndex($minimum->lower, false);
            if ($lastLevel === null) {
                return null;
            }
            $count = 0;
            for ($level = 1; $level <= $lastLevel; ++$level) {
                $comparison = $minimum->compareLowerToRational((string) (-2 * $level), '1');
                $count += $comparison < 0 ? 2 : ($comparison === 0 ? 1 : 0);
            }

            return $count;
        }

        return null;
    }

    /**
     * Enumerate all-real zeta levels for q + a/(x-p)^2.
     *
     * @param list<array{string, string}> $numerator
     * @param list<array{string, string}> $denominator
     * @return list<array{list<string>, list<string>}>|null
     */
    private function rationalZetaSquarePoleLevels(
        ExactRationalPolynomialExtractor $extractor,
        Node $argument,
        array $numerator,
        array $denominator,
    ): ?array {
        if (\count($denominator) !== 3 || \count($numerator) > 3) {
            return null;
        }
        $quadratic = $denominator[2];
        if ($this->compareRationalFractions($quadratic, ['0', '1']) === 0) {
            return null;
        }
        $discriminant = (new ExactRationalInterval($denominator[1], $denominator[1]))
            ->multiply(new ExactRationalInterval($denominator[1], $denominator[1]))
            ->subtract(
                (new ExactRationalInterval(['4', '1'], ['4', '1']))
                    ->multiply(new ExactRationalInterval($denominator[0], $denominator[0]))
                    ->multiply(new ExactRationalInterval($quadratic, $quadratic)),
            )->lower;
        if ($this->compareRationalFractions($discriminant, ['0', '1']) !== 0) {
            return null;
        }

        $constantLevel = (new ExactRationalInterval($numerator[2] ?? ['0', '1'], $numerator[2] ?? ['0', '1']))
            ->divide(new ExactRationalInterval($quadratic, $quadratic))->lower;
        $linearRemainder = (new ExactRationalInterval($numerator[1] ?? ['0', '1'], $numerator[1] ?? ['0', '1']))
            ->subtract(
                (new ExactRationalInterval($constantLevel, $constantLevel))
                    ->multiply(new ExactRationalInterval($denominator[1], $denominator[1])),
            )->lower;
        if ($this->compareRationalFractions($linearRemainder, ['0', '1']) !== 0) {
            return null;
        }
        $remainder = (new ExactRationalInterval($numerator[0] ?? ['0', '1'], $numerator[0] ?? ['0', '1']))
            ->subtract(
                (new ExactRationalInterval($constantLevel, $constantLevel))
                    ->multiply(new ExactRationalInterval($denominator[0], $denominator[0])),
            )->lower;
        $poleCoefficient = (new ExactRationalInterval($remainder, $remainder))
            ->divide(new ExactRationalInterval($quadratic, $quadratic))->lower;
        $poleCoefficientSign = $this->compareRationalFractions($poleCoefficient, ['0', '1']);
        if ($poleCoefficientSign === 0) {
            return null;
        }
        if ($poleCoefficientSign < 0) {
            throw new InfiniteSolutionSetException(
                'The rational zeta argument diverges to negative infinity at its double pole.',
            );
        }
        if ($this->compareRationalFractions($constantLevel, ['0', '1']) >= 0) {
            return [];
        }

        $lastIndex = $this->positiveHalfIndex($constantLevel, false);
        if ($lastIndex === null) {
            return null;
        }
        while ($lastIndex > 0) {
            $level = [(string) (-2 * $lastIndex), '1'];
            if ($this->compareRationalFractions($level, $constantLevel) > 0) {
                break;
            }
            --$lastIndex;
        }
        if ($lastIndex > self::MAX_SPECIAL_ZERO_LEVELS) {
            return null;
        }

        $levels = [];
        for ($index = 1; $index <= $lastIndex; ++$index) {
            $level = $extractor->rationalDifferenceFromFraction($argument, [(string) (-2 * $index), '1']);
            if ($level === null) {
                return null;
            }
            $levels[] = $level;
        }

        return $levels;
    }

    /**
     * Count levels for an even-degree polynomial with exactly one global minimum.
     *
     * @param array<string, int|float> $parameters
     */
    private function countUnimodalEvenPolynomialZetaRoots(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        int $maxPolynomialDegree,
    ): ?int {
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || $candidate->name !== 'zeta'
                || \count($candidate->arguments) !== 1
            ) {
                continue;
            }
            $extractor = new ExactRationalPolynomialExtractor($variable, $parameters, $maxPolynomialDegree);
            $targetPolynomial = $extractor->polynomial($target);
            if ($targetPolynomial === null || \count($targetPolynomial) !== 1 || $targetPolynomial[0][0] !== '0') {
                return null;
            }
            $polynomial = $extractor->polynomial($candidate->arguments[0]);
            if ($polynomial === null) {
                return null;
            }
            while (\count($polynomial) > 1 && $polynomial[\array_key_last($polynomial)][0] === '0') {
                \array_pop($polynomial);
            }
            $degree = \count($polynomial) - 1;
            if ($degree < 4 || $degree % 2 !== 0) {
                return null;
            }
            $leading = new ExactRationalInterval($polynomial[$degree], $polynomial[$degree]);
            if ($leading->compareLowerToRational('0', '1') <= 0) {
                return null;
            }

            try {
                $derivative = [];
                for ($power = 1; $power <= $degree; ++$power) {
                    $derivative[] = (new ExactRationalInterval($polynomial[$power], $polynomial[$power]))
                        ->multiply(new ExactRationalInterval([(string) $power, '1'], [(string) $power, '1']))
                        ->lower;
                }
                $integerDerivative = $this->integerPolynomialFromRational($derivative);
                if ($integerDerivative === null || \count($integerDerivative) < 2) {
                    return null;
                }
                $criticalIntervals = (new ExactPolynomialRootCounter())->isolateAllRealRoots(
                    $integerDerivative,
                    maxDepth: 256,
                    maximumWidth: ['1', '1000000000000'],
                );
                if ($criticalIntervals === null || $criticalIntervals === []) {
                    return null;
                }
                $gapSigns = [];
                $arithmetic = new IntegerPolynomialExtractor('', []);
                for ($index = 0; $index + 1 < \count($criticalIntervals); ++$index) {
                    $upper = [$criticalIntervals[$index][2], $criticalIntervals[$index][3]];
                    $lower = [$criticalIntervals[$index + 1][0], $criticalIntervals[$index + 1][1]];
                    $upperInterval = new ExactRationalInterval($upper, $upper);
                    if ($upperInterval->compareLowerToRational($lower[0], $lower[1]) >= 0) {
                        return null;
                    }
                    $midpoint = [
                        $arithmetic->addIntegerValues(
                            $arithmetic->multiplyIntegerValues($upper[0], $lower[1]),
                            $arithmetic->multiplyIntegerValues($lower[0], $upper[1]),
                        ),
                        $arithmetic->multiplyIntegerValues(
                            '2',
                            $arithmetic->multiplyIntegerValues($upper[1], $lower[1]),
                        ),
                    ];
                    $gapSign = (new ExactPolynomialRootCounter())->signAt($integerDerivative, $midpoint);
                    if ($gapSign === null || $gapSign === 0) {
                        return null;
                    }
                    $gapSigns[] = $gapSign;
                }

                $minimumIndex = null;
                foreach ($criticalIntervals as $index => $_interval) {
                    $signBefore = $index === 0 ? -1 : $gapSigns[$index - 1];
                    $signAfter = $index === \count($criticalIntervals) - 1 ? 1 : $gapSigns[$index];
                    if ($signBefore > $signAfter) {
                        return null;
                    }
                    if ($signBefore < 0 && $signAfter > 0) {
                        if ($minimumIndex !== null) {
                            return null;
                        }
                        $minimumIndex = $index;
                    }
                }
                if ($minimumIndex === null) {
                    return null;
                }

                $minimumRange = new ExactRationalInterval(
                    [$criticalIntervals[$minimumIndex][0], $criticalIntervals[$minimumIndex][1]],
                    [$criticalIntervals[$minimumIndex][2], $criticalIntervals[$minimumIndex][3]],
                );
                $valueRange = new ExactRationalInterval(['0', '1'], ['0', '1']);
                for ($power = $degree; $power >= 0; --$power) {
                    $valueRange = $valueRange
                        ->multiply($minimumRange)
                        ->add(new ExactRationalInterval($polynomial[$power], $polynomial[$power]));
                }
                $lastLevel = $this->positiveHalfIndex($valueRange->lower, false);
                if ($lastLevel === null) {
                    return null;
                }
                $count = 0;
                for ($level = 1; $level <= $lastLevel; ++$level) {
                    $threshold = (string) (-2 * $level);
                    if ($valueRange->compareUpperToRational($threshold, '1') < 0) {
                        $count += 2;
                        continue;
                    }
                    if ($valueRange->compareLowerToRational($threshold, '1') > 0) {
                        break;
                    }
                    if (
                        $valueRange->compareLowerToRational($threshold, '1') === 0
                        && $valueRange->compareUpperToRational($threshold, '1') === 0
                    ) {
                        ++$count;
                        break;
                    }

                    return null;
                }

                return $count;
            } catch (\LengthException) {
                return null;
            }
        }

        return null;
    }

    /** @param list<array{string, string}> $polynomial */
    private function evenPolynomialHasNonnegativeTerms(array $polynomial): bool
    {
        foreach ($polynomial as $degree => $coefficient) {
            if ($degree % 2 === 1 && $coefficient[0] !== '0') {
                return false;
            }
            if (
                $degree > 0
                && (new ExactRationalInterval($coefficient, $coefficient))->compareLowerToRational('0', '1') < 0
            ) {
                return false;
            }
        }

        return true;
    }

    /** @param list<array{string, string}> $polynomial
     *  @return array{string, string}|null
     */
    private function polynomialGlobalLowerBound(array $polynomial): ?array
    {
        if ($polynomial === []) {
            return null;
        }
        while (\count($polynomial) > 1 && $polynomial[\array_key_last($polynomial)][0] === '0') {
            \array_pop($polynomial);
        }
        $degree = \array_key_last($polynomial);
        if ($degree === null) {
            return null;
        }
        $constantCoefficient = $polynomial[0];
        $constant = new ExactRationalInterval($constantCoefficient, $constantCoefficient);
        if ($degree === 0) {
            return $constant->lower;
        }
        if ($degree === 1) {
            return null;
        }
        if ($degree === 2) {
            $linear = new ExactRationalInterval($polynomial[1], $polynomial[1]);
            $quadratic = new ExactRationalInterval($polynomial[2], $polynomial[2]);
            if ($quadratic->compareLowerToRational('0', '1') <= 0) {
                return null;
            }
            $fourLeading = $quadratic->multiply(new ExactRationalInterval(['4', '1'], ['4', '1']));

            return $constant->subtract($linear->multiply($linear)->divide($fourLeading))->lower;
        }
        if ($degree % 2 === 1) {
            return null;
        }
        $leading = new ExactRationalInterval($polynomial[$degree], $polynomial[$degree]);
        if ($leading->compareLowerToRational('0', '1') <= 0) {
            return null;
        }
        if ($this->evenPolynomialHasNonnegativeTerms($polynomial)) {
            return $constant->lower;
        }
        if ($degree >= 4) {
            $squareLowerBound = $this->polynomialSquareLowerBound($polynomial);
            if ($squareLowerBound !== null) {
                return $squareLowerBound;
            }

            return $this->evenDegreePolynomialGlobalLowerBound($polynomial);
        }

        return null;
    }

    /** @param list<array{string, string}> $polynomial */
    private function polynomialCertifiedGlobalSign(array $polynomial): ?int
    {
        $lowerBound = $this->polynomialGlobalLowerBound($polynomial);
        if ($lowerBound !== null && $this->compareRationalFractions($lowerBound, ['0', '1']) > 0) {
            return 1;
        }

        $negativePolynomial = [];
        foreach ($polynomial as $coefficient) {
            $negativePolynomial[] = (new ExactRationalInterval($coefficient, $coefficient))->negateInterval()->lower;
        }
        $negativeLowerBound = $this->polynomialGlobalLowerBound($negativePolynomial);

        return $negativeLowerBound !== null
            && $this->compareRationalFractions($negativeLowerBound, ['0', '1']) > 0
                ? -1
                : null;
    }

    /** @param list<array{string, string}> $polynomial
     *  @return array{string, string}|null
     */
    private function evenDegreePolynomialGlobalLowerBound(array $polynomial): ?array
    {
        try {
            $derivative = [];
            for ($power = 1; $power < \count($polynomial); ++$power) {
                $coefficient = new ExactRationalInterval(
                    $polynomial[$power],
                    $polynomial[$power],
                );
                $derivative[] = $coefficient
                    ->multiply(new ExactRationalInterval([(string) $power, '1'], [(string) $power, '1']))
                    ->lower;
            }
            $integerDerivative = $this->integerPolynomialFromRational($derivative);
            if ($integerDerivative === null || \count($integerDerivative) < 2) {
                return null;
            }
            $criticalIntervals = (new ExactPolynomialRootCounter())->isolateAllRealRoots(
                $integerDerivative,
                maxDepth: 256,
                maximumWidth: ['1', '1000000'],
            );
            if ($criticalIntervals === null) {
                return null;
            }

            $minimum = new ExactRationalInterval($polynomial[0], $polynomial[0]);
            foreach ($criticalIntervals as [$lowerNumerator, $lowerDenominator, $upperNumerator, $upperDenominator]) {
                $criticalRange = new ExactRationalInterval(
                    [$lowerNumerator, $lowerDenominator],
                    [$upperNumerator, $upperDenominator],
                );
                $valueRange = new ExactRationalInterval(['0', '1'], ['0', '1']);
                for ($power = \count($polynomial) - 1; $power >= 0; --$power) {
                    $valueRange = $valueRange
                        ->multiply($criticalRange)
                        ->add(new ExactRationalInterval($polynomial[$power], $polynomial[$power]));
                }
                if ($valueRange->compareLowerEndpoint($minimum) < 0) {
                    $minimum = new ExactRationalInterval($valueRange->lower, $valueRange->lower);
                }
            }

            return $minimum->lower;
        } catch (\LengthException) {
            return null;
        }
    }

    /** @param list<array{string, string}> $coefficients
     *  @return list<string>|null
     */
    private function integerPolynomialFromRational(array $coefficients): ?array
    {
        if ($coefficients === []) {
            return null;
        }
        $arithmetic = new IntegerPolynomialExtractor('', []);
        $commonDenominator = '1';
        foreach ($coefficients as [, $denominator]) {
            $gcd = $arithmetic->greatestCommonDivisorValues($commonDenominator, $denominator);
            $factor = $arithmetic->divideIntegerValueExactly($denominator, $gcd);
            if ($factor === null) {
                return null;
            }
            $commonDenominator = $arithmetic->multiplyIntegerValues($commonDenominator, $factor);
        }

        $integers = [];
        $content = '0';
        foreach ($coefficients as [$numerator, $denominator]) {
            $factor = $arithmetic->divideIntegerValueExactly($commonDenominator, $denominator);
            if ($factor === null) {
                return null;
            }
            $integer = $arithmetic->multiplyIntegerValues($numerator, $factor);
            $integers[] = $integer;
            $content = $arithmetic->greatestCommonDivisorValues($content, $integer);
        }
        if ($content !== '0' && $content !== '1') {
            foreach ($integers as $index => $integer) {
                $integers[$index] = $arithmetic->divideIntegerValueExactly($integer, $content) ?? $integer;
            }
        }

        return $integers;
    }

    /** @param list<array{string, string}> $polynomial
     *  @return array{string, string}|null
     */
    private function polynomialSquareLowerBound(array $polynomial): ?array
    {
        $degree = \count($polynomial) - 1;
        $squareDegree = intdiv($degree, 2);
        $leading = new ExactRationalInterval($polynomial[$degree], $polynomial[$degree]);
        if ($leading->compareLowerToRational('0', '1') <= 0) {
            return null;
        }

        try {
            $two = new ExactRationalInterval(['2', '1'], ['2', '1']);
            $normalized = [];
            for ($power = 0; $power <= $degree; ++$power) {
                $normalized[] = (new ExactRationalInterval($polynomial[$power], $polynomial[$power]))
                    ->divide($leading);
            }
            $squareRoot = \array_fill(0, $squareDegree + 1, new ExactRationalInterval(['0', '1'], ['0', '1']));
            $squareRoot[$squareDegree] = new ExactRationalInterval(['1', '1'], ['1', '1']);
            for ($power = $squareDegree - 1; $power >= 0; --$power) {
                $degreeToMatch = $squareDegree + $power;
                $knownTerms = new ExactRationalInterval(['0', '1'], ['0', '1']);
                for ($leftPower = $power + 1; $leftPower <= $squareDegree; ++$leftPower) {
                    $rightPower = $degreeToMatch - $leftPower;
                    if ($rightPower > $power && $rightPower <= $squareDegree) {
                        $knownTerms = $knownTerms->add(
                            $squareRoot[$leftPower]->multiply($squareRoot[$rightPower]),
                        );
                    }
                }
                $squareRoot[$power] = $normalized[$degreeToMatch]
                    ->subtract($knownTerms)
                    ->divide($two);
            }

            $residual = [];
            for ($power = 0; $power <= $degree; ++$power) {
                if ($power === 0) {
                    $residual[] = (new ExactRationalInterval($polynomial[0], $polynomial[0]))
                        ->subtract($leading->multiply($squareRoot[0])->multiply($squareRoot[0]))
                        ->lower;
                    continue;
                }
                $squareCoefficient = new ExactRationalInterval(['0', '1'], ['0', '1']);
                $firstPower = \max(0, $power - $squareDegree);
                $lastPower = \min($squareDegree, $power);
                for ($leftPower = $firstPower; $leftPower <= $lastPower; ++$leftPower) {
                    $squareCoefficient = $squareCoefficient->add(
                        $squareRoot[$leftPower]->multiply($squareRoot[$power - $leftPower]),
                    );
                }
                $residualCoefficient = $normalized[$power]->subtract($squareCoefficient);
                $residual[] = $leading->multiply($residualCoefficient)->lower;
            }

            return $this->polynomialGlobalLowerBound($residual);
        } catch (\LengthException) {
            return null;
        }
    }

    /**
     * Reduce nonlinear polynomial zeta arguments to exact trivial-zero levels.
     *
     * @param array<string, int|float> $parameters
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @return list<array{list<string>, list<string>}>|null Null means unsupported.
     */
    private function polynomialZetaZeroLevels(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        int $maxPolynomialDegree,
        array $lower,
        array $upper,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || $candidate->name !== 'zeta'
                || \count($candidate->arguments) !== 1
            ) {
                continue;
            }
            $extractor = new ExactRationalPolynomialExtractor($variable, $parameters, $maxPolynomialDegree);
            $targetPolynomial = $extractor->polynomial($target);
            if ($targetPolynomial === null || \count($targetPolynomial) !== 1 || $targetPolynomial[0][0] !== '0') {
                return null;
            }
            $argument = $candidate->arguments[0];
            $polynomial = $extractor->polynomial($argument);
            $rationalForm = $extractor->rationalPolynomialForm($argument);
            if ($polynomial !== null) {
                while (\count($polynomial) > 1 && $polynomial[\array_key_last($polynomial)][0] === '0') {
                    \array_pop($polynomial);
                }
                if (\count($polynomial) < 3) {
                    return null;
                }
                $argumentRange = $this->exactPolynomialRangeOnInterval($polynomial, $lower, $upper);
            } elseif ($rationalForm !== null) {
                [$numerator, $denominator] = $rationalForm;
                while (\count($numerator) > 1 && $numerator[\array_key_last($numerator)][0] === '0') {
                    \array_pop($numerator);
                }
                while (\count($denominator) > 1 && $denominator[\array_key_last($denominator)][0] === '0') {
                    \array_pop($denominator);
                }
                try {
                    $reducedRangeForm = $this->cancelCommonRationalPolynomialFactors(
                        $extractor,
                        $numerator,
                        $denominator,
                    );
                    if ($reducedRangeForm !== null) {
                        [$numerator, $denominator] = $reducedRangeForm;
                    }
                    $argumentRange = $this->exactRationalFunctionRangeOnInterval(
                        $numerator,
                        $denominator,
                        $lower,
                        $upper,
                    );
                    if ($argumentRange === null) {
                        return null;
                    }
                } catch (\LengthException) {
                    return null;
                }
            } else {
                return null;
            }
            $minimum = $argumentRange->lower;
            $maximum = $argumentRange->upper;
            $firstIndex = $this->positiveHalfIndex($maximum, true);
            $lastIndex = $this->positiveHalfIndex($minimum, false);
            if ($firstIndex === null || $lastIndex === null) {
                return null;
            }
            $firstIndex = \max(1, $firstIndex);
            if ($lastIndex < $firstIndex) {
                return [];
            }
            if ($lastIndex - $firstIndex + 1 > self::MAX_SPECIAL_ZERO_LEVELS) {
                return null;
            }

            $levels = [];
            for ($index = $firstIndex; $index <= $lastIndex; ++$index) {
                $levelForm = $extractor->rationalDifferenceFromFraction(
                    $argument,
                    [(string) (-2 * $index), '1'],
                );
                if ($levelForm === null) {
                    return null;
                }
                if (\count($levelForm[0]) > 1) {
                    $levels[] = $levelForm;
                }
            }

            return $levels;
        }

        return null;
    }

    /**
     * @param list<array{string, string}> $polynomial
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     */
    private function exactPolynomialRangeOnInterval(
        array $polynomial,
        array $lower,
        array $upper,
    ): ExactRationalInterval {
        $range = new ExactRationalInterval(['0', '1'], ['0', '1']);
        $variableRange = new ExactRationalInterval($lower, $upper);
        for ($degree = \count($polynomial) - 1; $degree >= 0; --$degree) {
            $range = $range
                ->multiply($variableRange)
                ->add(new ExactRationalInterval($polynomial[$degree], $polynomial[$degree]));
        }
        if ($variableRange->containsZero() && \count($polynomial) <= 33) {
            $powerBasis = $this->evaluatePowerBasisOnInterval($polynomial, $variableRange);
            $intersection = $range->intersect($powerBasis);
            if ($intersection !== null) {
                return $intersection;
            }
        }

        return $range;
    }

    /**
     * @param list<array{string, string}> $numerator
     * @param list<array{string, string}> $denominator
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     */
    private function exactRationalFunctionRangeOnInterval(
        array $numerator,
        array $denominator,
        array $lower,
        array $upper,
        int $depth = 0,
    ): ?ExactRationalInterval {
        $denominatorRange = $this->exactPolynomialRangeOnInterval($denominator, $lower, $upper);
        if (!$denominatorRange->containsZero()) {
            return $this->exactPolynomialRangeOnInterval($numerator, $lower, $upper)
                ->divide($denominatorRange);
        }
        if ($depth >= self::MAX_RATIONAL_RANGE_SUBDIVISION_DEPTH) {
            return null;
        }

        $midpoint = (new ExactRationalInterval($lower, $lower))
            ->add(new ExactRationalInterval($upper, $upper))
            ->divide(new ExactRationalInterval(['2', '1'], ['2', '1']))->lower;
        if (
            $this->compareRationalFractions($midpoint, $lower) <= 0
            || $this->compareRationalFractions($midpoint, $upper) >= 0
        ) {
            return null;
        }
        $leftRange = $this->exactRationalFunctionRangeOnInterval(
            $numerator,
            $denominator,
            $lower,
            $midpoint,
            $depth + 1,
        );
        $rightRange = $this->exactRationalFunctionRangeOnInterval(
            $numerator,
            $denominator,
            $midpoint,
            $upper,
            $depth + 1,
        );
        if ($leftRange === null || $rightRange === null) {
            return null;
        }

        $rangeLower = $this->compareRationalFractions($leftRange->lower, $rightRange->lower) <= 0
            ? $leftRange->lower
            : $rightRange->lower;
        $rangeUpper = $this->compareRationalFractions($leftRange->upper, $rightRange->upper) >= 0
            ? $leftRange->upper
            : $rightRange->upper;

        return new ExactRationalInterval($rangeLower, $rangeUpper);
    }

    /**
     * Cancel common polynomial factors for range estimation only; level equations retain original holes.
     *
     * @param list<array{string, string}> $numerator
     * @param list<array{string, string}> $denominator
     * @return array{list<array{string, string}>, list<array{string, string}>}|null
     */
    private function cancelCommonRationalPolynomialFactors(
        ExactRationalPolynomialExtractor $extractor,
        array $numerator,
        array $denominator,
    ): ?array {
        $integerNumerator = $extractor->integerCoefficients($numerator);
        $integerDenominator = $extractor->integerCoefficients($denominator);
        if ($integerNumerator === null || $integerDenominator === null) {
            return null;
        }
        $counter = new ExactPolynomialRootCounter();
        $commonFactor = $counter->greatestCommonDivisor($integerNumerator, $integerDenominator);
        if ($commonFactor === null || \count($commonFactor) < 2) {
            return null;
        }
        $reducedNumerator = $counter->dividePolynomialExactly($integerNumerator, $commonFactor);
        $reducedDenominator = $counter->dividePolynomialExactly($integerDenominator, $commonFactor);
        if ($reducedNumerator === null || $reducedDenominator === null) {
            return null;
        }

        $scaleNumerator = $this->rationalPolynomialIntegerScale($numerator, $integerNumerator);
        $scaleDenominator = $this->rationalPolynomialIntegerScale($denominator, $integerDenominator);
        if ($scaleNumerator === null || $scaleDenominator === null) {
            return null;
        }
        $scale = (new ExactRationalInterval($scaleNumerator, $scaleNumerator))
            ->divide(new ExactRationalInterval($scaleDenominator, $scaleDenominator))->lower;
        $scaledNumerator = [];
        foreach ($reducedNumerator as $coefficient) {
            $scaledNumerator[] = (new ExactRationalInterval([$coefficient, '1'], [$coefficient, '1']))
                ->multiply(new ExactRationalInterval($scale, $scale))->lower;
        }

        $scaledDenominator = \array_map(
            fn (string $coefficient): array => [$coefficient, '1'],
            $reducedDenominator,
        );

        return [$scaledNumerator, $scaledDenominator];
    }

    /**
     * @param list<array{string, string}> $polynomial
     * @param list<string> $integerCoefficients
     * @return array{string, string}|null
     */
    private function rationalPolynomialIntegerScale(array $polynomial, array $integerCoefficients): ?array
    {
        foreach ($integerCoefficients as $degree => $coefficient) {
            if ($coefficient !== '0') {
                return (new ExactRationalInterval(
                    $polynomial[$degree],
                    $polynomial[$degree],
                ))->divide(new ExactRationalInterval([$coefficient, '1'], [$coefficient, '1']))->lower;
            }
        }

        return null;
    }

    /**
     * Isolate exact trivial zeta zeros for affine and pole-free linear-rational arguments.
     *
     * @param array<string, int|float> $parameters
     * @param array{string, string}|null $lower
     * @param array{string, string}|null $upper
     * @return list<array{string, string}>|null Null means unsupported.
     */
    private function exactZetaTrivialZeroRoots(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        int $maxPolynomialDegree,
        ?array $lower,
        ?array $upper,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || $candidate->name !== 'zeta'
                || \count($candidate->arguments) !== 1
            ) {
                continue;
            }
            $extractor = new ExactRationalPolynomialExtractor($variable, $parameters, $maxPolynomialDegree);
            $targetPolynomial = $extractor->polynomial($target);
            if ($targetPolynomial === null || \count($targetPolynomial) !== 1 || $targetPolynomial[0][0] !== '0') {
                return null;
            }
            $argument = $candidate->arguments[0];
            $rationalForm = $extractor->rationalPolynomialForm($argument);
            if ($rationalForm !== null) {
                [$numerator, $denominator] = $rationalForm;
                while (\count($numerator) > 1 && $numerator[\array_key_last($numerator)][0] === '0') {
                    \array_pop($numerator);
                }
                while (\count($denominator) > 1 && $denominator[\array_key_last($denominator)][0] === '0') {
                    \array_pop($denominator);
                }
                $constantValue = $this->constantRationalFunctionValue($numerator, $denominator);
                if ($constantValue !== null) {
                    if ($this->isNegativeEvenInteger($constantValue)) {
                        throw new InfiniteSolutionSetException(
                            'The constant rational zeta argument is a trivial zero away from its denominator holes.',
                        );
                    }

                    return [];
                }
                if ($this->hasNegativeDivergingRealPole($extractor, $numerator, $denominator, $lower, $upper)) {
                    throw new InfiniteSolutionSetException(
                        'A genuine negative-diverging real pole gives infinitely many trivial-zero preimages.',
                    );
                }
                if (\count($numerator) <= 2 && \count($denominator) === 2) {
                    $pole = (new ExactRationalInterval($denominator[0], $denominator[0]))
                        ->negateInterval()
                        ->divide(new ExactRationalInterval($denominator[1], $denominator[1]))->lower;
                    $numeratorAtPole = (new ExactRationalInterval($numerator[0], $numerator[0]))->add(
                        (new ExactRationalInterval($numerator[1] ?? ['0', '1'], $numerator[1] ?? ['0', '1']))
                            ->multiply(new ExactRationalInterval($pole, $pole)),
                    )->lower;
                    $hasGenuinePole = $this->compareRationalFractions($numeratorAtPole, ['0', '1']) !== 0;
                    $intervalContainsNegativeDivergence = $lower === null || $upper === null;
                    if ($lower !== null && $upper !== null) {
                        $poleComparedToLower = $this->compareRationalFractions($pole, $lower);
                        $poleComparedToUpper = $this->compareRationalFractions($pole, $upper);
                        $residueSign = $this->compareRationalFractions($numeratorAtPole, ['0', '1'])
                            * $this->compareRationalFractions($denominator[1], ['0', '1']);
                        $intervalContainsNegativeDivergence = (
                            $poleComparedToLower > 0 && $poleComparedToUpper < 0
                        ) || ($poleComparedToLower === 0 && $residueSign < 0)
                            || ($poleComparedToUpper === 0 && $residueSign > 0);
                    }
                    if ($hasGenuinePole && $intervalContainsNegativeDivergence) {
                        throw new InfiniteSolutionSetException(
                            'The rational zeta argument has infinitely many trivial-zero preimages near a pole.',
                        );
                    }
                }
            }
            $polynomial = $extractor->polynomial($argument);
            if ($polynomial === null) {
                return $lower === null || $upper === null
                    ? null
                    : $this->exactRationalZetaTrivialZeroRoots(
                        $extractor,
                        $argument,
                        $lower,
                        $upper,
                    );
            }
            while (\count($polynomial) > 1 && $polynomial[\array_key_last($polynomial)][0] === '0') {
                \array_pop($polynomial);
            }
            if (\count($polynomial) > 2) {
                return null;
            }
            if (\count($polynomial) === 1) {
                $constant = $polynomial[0];
                if ($constant[1] === '1' && \str_starts_with($constant[0], '-')) {
                    $digits = \substr($constant[0], 1);
                    $lastDigit = \substr($digits, -1);
                    if ($digits !== '' && $lastDigit !== '' && ((int) $lastDigit % 2) === 0) {
                        throw new InfiniteSolutionSetException('The constant zeta argument is a trivial zero.');
                    }
                }

                return [];
            }
            if ($lower === null || $upper === null) {
                throw new InfiniteSolutionSetException('The zeta equation has infinitely many real roots.');
            }

            $intercept = new ExactRationalInterval($polynomial[0], $polynomial[0]);
            $slope = new ExactRationalInterval($polynomial[1], $polynomial[1]);
            $lowerValue = $slope->multiply(new ExactRationalInterval($lower, $lower))->add($intercept)->lower;
            $upperValue = $slope->multiply(new ExactRationalInterval($upper, $upper))->add($intercept)->lower;
            $minimum = $this->compareRationalFractions($lowerValue, $upperValue) <= 0
                ? $lowerValue
                : $upperValue;
            $maximum = $this->compareRationalFractions($lowerValue, $upperValue) <= 0
                ? $upperValue
                : $lowerValue;
            $firstIndex = $this->positiveHalfIndex($maximum, true);
            $lastIndex = $this->positiveHalfIndex($minimum, false);
            if ($firstIndex === null || $lastIndex === null) {
                return null;
            }
            $firstIndex = \max(1, $firstIndex);
            if ($lastIndex < $firstIndex) {
                return [];
            }
            if ($lastIndex - $firstIndex + 1 > self::MAX_SPECIAL_ZERO_LEVELS) {
                return null;
            }

            $roots = [];
            for ($index = $firstIndex; $index <= $lastIndex; ++$index) {
                $levelForm = $extractor->rationalDifferenceFromFraction(
                    $argument,
                    [(string) (-2 * $index), '1'],
                );
                if ($levelForm === null || $levelForm[1] !== ['1'] || \count($levelForm[0]) !== 2) {
                    return null;
                }
                $rootNumerator = $levelForm[0][0] === '0'
                    ? '0'
                    : (\str_starts_with($levelForm[0][0], '-')
                        ? \substr($levelForm[0][0], 1)
                        : '-' . $levelForm[0][0]);
                $root = (new ExactRationalInterval(
                    [$rootNumerator, $levelForm[0][1]],
                    [$rootNumerator, $levelForm[0][1]],
                ))->lower;
                $roots[] = $root;
            }
            \usort($roots, fn (array $a, array $b): int => $this->compareRationalFractions($a, $b));

            return $roots;
        }

        return null;
    }

    /**
     * @param list<array{string, string}> $numerator
     * @param list<array{string, string}> $denominator
     * @param array{string, string}|null $domainLower
     * @param array{string, string}|null $domainUpper
     */
    private function hasNegativeDivergingRealPole(
        ExactRationalPolynomialExtractor $extractor,
        array $numerator,
        array $denominator,
        ?array $domainLower,
        ?array $domainUpper,
    ): bool {
        $integerNumerator = $extractor->integerCoefficients($numerator);
        $integerDenominator = $extractor->integerCoefficients($denominator);
        if ($integerNumerator === null || $integerDenominator === null || \count($integerDenominator) < 2) {
            return false;
        }
        $counter = new ExactPolynomialRootCounter();
        $denominatorRoots = $counter->isolateAllRealRoots(
            $integerDenominator,
            maxDepth: 256,
            maximumWidth: ['1', '1000000000000'],
        );
        $commonFactor = $counter->greatestCommonDivisor($integerNumerator, $integerDenominator);
        if ($denominatorRoots === null || $commonFactor === null) {
            return false;
        }

        foreach ($denominatorRoots as [$lowerNumerator, $lowerDenominator, $upperNumerator, $upperDenominator]) {
            if (\count($commonFactor) > 1) {
                if ($lowerNumerator === $upperNumerator && $lowerDenominator === $upperDenominator) {
                    $isCommonRoot = $counter->isRootAt($commonFactor, [$lowerNumerator, $lowerDenominator]);
                    if ($isCommonRoot === null) {
                        return false;
                    }
                    $commonRootCount = $isCommonRoot ? 1 : 0;
                } else {
                    $commonRootCount = $counter->countOpenInterval(
                        $commonFactor,
                        $lowerNumerator,
                        $lowerDenominator,
                        $upperNumerator,
                        $upperDenominator,
                    );
                }
                if ($commonRootCount === null) {
                    return false;
                }
                if ($commonRootCount > 0) {
                    continue;
                }
            }

            $derivative = $denominator;
            $poleOrder = 0;
            $denominatorLeadingDerivativeSign = 0;
            for ($order = 1, $degree = \count($denominator) - 1; $order <= $degree; ++$order) {
                $nextDerivative = [];
                for ($power = 1, $count = \count($derivative); $power < $count; ++$power) {
                    $nextDerivative[] = (new ExactRationalInterval(
                        $derivative[$power],
                        $derivative[$power],
                    ))->multiply(new ExactRationalInterval([(string) $power, '1'], [(string) $power, '1']))->lower;
                }
                $derivative = $nextDerivative;
                $integerDerivative = $extractor->integerCoefficients($derivative);
                if ($integerDerivative === null) {
                    break;
                }
                $derivativeCommonFactor = $counter->greatestCommonDivisor(
                    $integerDenominator,
                    $integerDerivative,
                );
                if ($derivativeCommonFactor === null) {
                    break;
                }
                $derivativeHasPoleRoot = false;
                if (\count($derivativeCommonFactor) > 1) {
                    if ($lowerNumerator === $upperNumerator && $lowerDenominator === $upperDenominator) {
                        $derivativeHasPoleRoot = $counter->isRootAt(
                            $derivativeCommonFactor,
                            [$lowerNumerator, $lowerDenominator],
                        );
                        if ($derivativeHasPoleRoot === null) {
                            break;
                        }
                    } else {
                        $derivativeRootCount = $counter->countOpenInterval(
                            $derivativeCommonFactor,
                            $lowerNumerator,
                            $lowerDenominator,
                            $upperNumerator,
                            $upperDenominator,
                        );
                        if ($derivativeRootCount === null) {
                            break;
                        }
                        $derivativeHasPoleRoot = $derivativeRootCount > 0;
                    }
                }
                if ($derivativeHasPoleRoot) {
                    continue;
                }
                $poleOrder = $order;
                if ($lowerNumerator === $upperNumerator && $lowerDenominator === $upperDenominator) {
                    $denominatorLeadingDerivativeSign = $counter->signAt(
                        $integerDerivative,
                        [$lowerNumerator, $lowerDenominator],
                    ) ?? 0;
                } else {
                    $derivativeRange = $this->exactPolynomialRangeOnInterval(
                        \array_map(fn (string $coefficient): array => [$coefficient, '1'], $integerDerivative),
                        [$lowerNumerator, $lowerDenominator],
                        [$upperNumerator, $upperDenominator],
                    );
                    if (!$derivativeRange->containsZero()) {
                        $denominatorLeadingDerivativeSign = $this->compareRationalFractions(
                            $derivativeRange->lower,
                            ['0', '1'],
                        );
                    }
                }
                break;
            }
            if ($poleOrder === 0 || $denominatorLeadingDerivativeSign === 0) {
                continue;
            }

            if ($lowerNumerator === $upperNumerator && $lowerDenominator === $upperDenominator) {
                $numeratorSign = $counter->signAt($integerNumerator, [$lowerNumerator, $lowerDenominator]) ?? 0;
            } else {
                $numeratorRange = $this->exactPolynomialRangeOnInterval(
                    \array_map(fn (string $coefficient): array => [$coefficient, '1'], $integerNumerator),
                    [$lowerNumerator, $lowerDenominator],
                    [$upperNumerator, $upperDenominator],
                );
                $numeratorSign = $numeratorRange->containsZero()
                    ? 0
                    : $this->compareRationalFractions($numeratorRange->lower, ['0', '1']);
            }
            if ($numeratorSign === 0) {
                continue;
            }
            $principalCoefficientSign = $numeratorSign * $denominatorLeadingDerivativeSign;
            if (
                $this->poleHasNegativeDivergenceInDomain(
                    [$lowerNumerator, $lowerDenominator],
                    [$upperNumerator, $upperDenominator],
                    $poleOrder,
                    $principalCoefficientSign,
                    $domainLower,
                    $domainUpper,
                )
            ) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param array{string, string} $poleLower
     * @param array{string, string} $poleUpper
     * @param array{string, string}|null $domainLower
     * @param array{string, string}|null $domainUpper
     */
    private function poleHasNegativeDivergenceInDomain(
        array $poleLower,
        array $poleUpper,
        int $order,
        int $principalCoefficientSign,
        ?array $domainLower,
        ?array $domainUpper,
    ): bool {
        if ($domainLower === null || $domainUpper === null) {
            return ($order % 2) === 1 || $principalCoefficientSign < 0;
        }
        if (
            $this->compareRationalFractions($poleLower, $domainLower) > 0
            && $this->compareRationalFractions($poleUpper, $domainUpper) < 0
        ) {
            return ($order % 2) === 1 || $principalCoefficientSign < 0;
        }
        if (
            $this->compareRationalFractions($poleLower, $poleUpper) === 0
            && $this->compareRationalFractions($poleLower, $domainLower) === 0
        ) {
            return $principalCoefficientSign < 0;
        }
        if (
            $this->compareRationalFractions($poleLower, $poleUpper) === 0
            && $this->compareRationalFractions($poleUpper, $domainUpper) === 0
        ) {
            return (($order % 2) === 0 ? $principalCoefficientSign : -$principalCoefficientSign) < 0;
        }

        return false;
    }

    /**
     * @param list<array{string, string}> $numerator
     * @param list<array{string, string}> $denominator
     * @return array{string, string}|null
     */
    private function constantRationalFunctionValue(array $numerator, array $denominator): ?array
    {
        $constant = null;
        foreach ($denominator as $degree => $coefficient) {
            if ($this->compareRationalFractions($coefficient, ['0', '1']) === 0) {
                continue;
            }
            $numeratorCoefficient = $numerator[$degree] ?? ['0', '1'];
            $constant = (new ExactRationalInterval($numeratorCoefficient, $numeratorCoefficient))
                ->divide(new ExactRationalInterval($coefficient, $coefficient))->lower;
            break;
        }
        if ($constant === null) {
            return null;
        }

        $degreeCount = \max(\count($numerator), \count($denominator));
        for ($degree = 0; $degree < $degreeCount; ++$degree) {
            $numeratorCoefficient = new ExactRationalInterval(
                $numerator[$degree] ?? ['0', '1'],
                $numerator[$degree] ?? ['0', '1'],
            );
            $denominatorCoefficient = new ExactRationalInterval(
                $denominator[$degree] ?? ['0', '1'],
                $denominator[$degree] ?? ['0', '1'],
            );
            $difference = $numeratorCoefficient->subtract(
                (new ExactRationalInterval($constant, $constant))->multiply($denominatorCoefficient),
            )->lower;
            if ($this->compareRationalFractions($difference, ['0', '1']) !== 0) {
                return null;
            }
        }

        return $constant;
    }

    /** @param array{string, string} $value */
    private function isNegativeEvenInteger(array $value): bool
    {
        if ($value[1] !== '1' || !\str_starts_with($value[0], '-')) {
            return false;
        }
        $digits = \substr($value[0], 1);
        $lastDigit = \substr($digits, -1);

        return $digits !== '' && $lastDigit !== '' && ((int) $lastDigit % 2) === 0;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return list<array{list<string>, list<string>}>|null Null means unsupported; an empty list means no roots.
     */
    private function polynomialBetaZeroLevels(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        int $maxPolynomialDegree,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || $candidate->name !== 'beta'
                || \count($candidate->arguments) !== 2
            ) {
                continue;
            }
            $extractor = new ExactRationalPolynomialExtractor($variable, $parameters, $maxPolynomialDegree);
            $targetPolynomial = $extractor->polynomial($target);
            if ($targetPolynomial === null || \count($targetPolynomial) !== 1 || $targetPolynomial[0][0] !== '0') {
                continue;
            }
            foreach ([0, 1] as $variableIndex) {
                $variableArgument = $candidate->arguments[$variableIndex];
                $fixedPolynomial = $extractor->polynomial($candidate->arguments[1 - $variableIndex]);
                $variableForm = $extractor->rationalPolynomialForm($variableArgument);
                if ($fixedPolynomial === null || $variableForm === null) {
                    return null;
                }
                if (
                    !$this->containsVariable($variableArgument, $variable)
                    || \count($fixedPolynomial) !== 1
                    || (\count($variableForm[0]) < 2 && \count($variableForm[1]) < 2)
                ) {
                    continue;
                }
                $fixed = $fixedPolynomial[0];
                $fixedInterval = new ExactRationalInterval($fixed, $fixed);
                if (
                    $fixedInterval->compareLowerToRational('-171', '1') < 0
                    || $fixedInterval->compareUpperToRational('171', '1') > 0
                    || $this->isNonpositiveInteger($fixed)
                ) {
                    return [];
                }
                $levels = [];
                for ($integerLevel = 0; $integerLevel <= 342; ++$integerLevel) {
                    $targetValue = (new ExactRationalInterval(
                        [(string) -$integerLevel, '1'],
                        [(string) -$integerLevel, '1'],
                    ))->subtract($fixedInterval)->lower;
                    $targetInterval = new ExactRationalInterval($targetValue, $targetValue);
                    if (
                        $targetInterval->compareLowerToRational('-171', '1') < 0
                        || $targetInterval->compareUpperToRational('171', '1') > 0
                        || $this->isNonpositiveInteger($targetValue)
                    ) {
                        continue;
                    }
                    $levelForm = $extractor->rationalDifferenceFromFraction($variableArgument, $targetValue);
                    if ($levelForm === null) {
                        return null;
                    }
                    if (\count($levelForm[0]) > 1) {
                        $levels[] = $levelForm;
                    }
                }

                return $levels;
            }
        }

        return null;
    }

    /**
     * Classify beta(trig(P(x)), c) and beta(c, trig(P(x))) over the real line.
     *
     * @param array<string, int|float> $parameters
     * @return bool|null True means infinitely many roots, false means none, null means unsupported.
     */
    private function periodicBetaZeroHasInfiniteRoots(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
    ): ?bool {
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || $candidate->name !== 'beta'
                || \count($candidate->arguments) !== 2
                || !$evaluationOptions->functions->isBuiltIn('beta')
            ) {
                continue;
            }
            $extractor = new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            );
            $targetPolynomial = $extractor->polynomial($target);
            if ($targetPolynomial === null || \count($targetPolynomial) !== 1 || $targetPolynomial[0][0] !== '0') {
                continue;
            }

            $firstPeriodic = $this->unwrapGrouping($candidate->arguments[0]);
            $secondPeriodic = $this->unwrapGrouping($candidate->arguments[1]);
            if (
                $firstPeriodic instanceof FunctionCallNode
                && $secondPeriodic instanceof FunctionCallNode
                && \in_array(
                    [$firstPeriodic->name, $secondPeriodic->name],
                    [['sin', 'cos'], ['cos', 'sin']],
                    true,
                )
                && $evaluationOptions->functions->isBuiltIn($firstPeriodic->name)
                && $evaluationOptions->functions->isBuiltIn($secondPeriodic->name)
                && \count($firstPeriodic->arguments) === 1
                && \count($secondPeriodic->arguments) === 1
                && $this->containsVariable($firstPeriodic->arguments[0], $variable)
                && $this->containsVariable($secondPeriodic->arguments[0], $variable)
            ) {
                $phase = $extractor->polynomial($firstPeriodic->arguments[0]);
                $secondPhase = $extractor->polynomial($secondPeriodic->arguments[0]);
                if ($phase === null || $phase !== $secondPhase || \count($phase) < 2) {
                    return null;
                }
                // The zero-sum phase has sin(P) and cos(P) at non-pole half-levels.
                return true;
            }

            $firstPeriodic = $this->unwrapGrouping($candidate->arguments[0]);
            $secondPeriodic = $this->unwrapGrouping($candidate->arguments[1]);
            if (
                $firstPeriodic instanceof FunctionCallNode
                && $secondPeriodic instanceof FunctionCallNode
                && $firstPeriodic->name === $secondPeriodic->name
                && \in_array($firstPeriodic->name, ['sin', 'cos', 'tan', 'cot', 'sec', 'csc'], true)
                && $evaluationOptions->functions->isBuiltIn($firstPeriodic->name)
                && \count($firstPeriodic->arguments) === 1
                && \count($secondPeriodic->arguments) === 1
                && $this->containsVariable($firstPeriodic->arguments[0], $variable)
                && $this->containsVariable($secondPeriodic->arguments[0], $variable)
            ) {
                $firstPhase = $extractor->polynomial($firstPeriodic->arguments[0]);
                $secondPhase = $extractor->polynomial($secondPeriodic->arguments[0]);
                if (
                    $firstPhase !== null
                    && $firstPhase === $secondPhase
                    && \count($firstPhase) > 1
                ) {
                    $sharedLevel = \in_array($firstPeriodic->name, ['sec', 'csc'], true)
                        ? ['-3', '2']
                        : ['-1', '2'];
                    if (
                        $this->periodicLevelIsInRange(
                            $firstPeriodic->name,
                            new ExactRationalInterval($sharedLevel, $sharedLevel),
                        )
                        && !$this->isNonpositiveInteger($sharedLevel)
                    ) {
                        return true;
                    }
                }
            }
            if (
                $firstPeriodic instanceof FunctionCallNode
                && $secondPeriodic instanceof FunctionCallNode
                && \count($firstPeriodic->arguments) === 1
                && \count($secondPeriodic->arguments) === 1
                && $evaluationOptions->functions->isBuiltIn($firstPeriodic->name)
                && $evaluationOptions->functions->isBuiltIn($secondPeriodic->name)
                && \in_array(
                    [$firstPeriodic->name, $secondPeriodic->name],
                    [['sin', 'cos'], ['cos', 'sin'], ['tan', 'cot'], ['cot', 'tan'], ['sec', 'csc'], ['csc', 'sec']],
                    true,
                )
                && $this->containsVariable($firstPeriodic->arguments[0], $variable)
                && $this->containsVariable($secondPeriodic->arguments[0], $variable)
            ) {
                $firstPhase = $extractor->polynomial($firstPeriodic->arguments[0]);
                $secondPhase = $extractor->polynomial($secondPeriodic->arguments[0]);
                if (
                    $firstPhase !== null
                    && $firstPhase === $secondPhase
                    && \count($firstPhase) > 1
                ) {
                    // Each pair reaches a beta zero level away from its gamma poles.
                    return true;
                }
            }

            foreach ([0, 1] as $periodicIndex) {
                $periodic = $this->unwrapGrouping($candidate->arguments[$periodicIndex]);
                $constant = $extractor->polynomial($candidate->arguments[1 - $periodicIndex]);
                if (
                    !$periodic instanceof FunctionCallNode
                    || !\in_array($periodic->name, ['sin', 'cos', 'tan', 'cot', 'sec', 'csc'], true)
                    || !$evaluationOptions->functions->isBuiltIn($periodic->name)
                    || \count($periodic->arguments) !== 1
                    || $constant === null
                    || \count($constant) !== 1
                    || !$this->containsVariable($periodic->arguments[0], $variable)
                ) {
                    continue;
                }
                $phase = $extractor->polynomial($periodic->arguments[0]);
                if ($phase === null || \count($phase) < 2) {
                    continue;
                }

                $constantValue = $constant[0];
                $constantInterval = new ExactRationalInterval($constantValue, $constantValue);
                if (
                    $constantInterval->compareLowerToRational('-171', '1') < 0
                    || $constantInterval->compareUpperToRational('171', '1') > 0
                    || $this->isNonpositiveInteger($constantValue)
                ) {
                    return false;
                }

                for ($integerLevel = 0; $integerLevel <= 342; ++$integerLevel) {
                    $argumentLevel = (new ExactRationalInterval(
                        [(string) -$integerLevel, '1'],
                        [(string) -$integerLevel, '1'],
                    ))->subtract($constantInterval)->lower;
                    $level = new ExactRationalInterval($argumentLevel, $argumentLevel);
                    if (
                        !$this->periodicLevelIsInRange($periodic->name, $level)
                        || $this->isNonpositiveInteger($argumentLevel)
                    ) {
                        continue;
                    }

                    return true;
                }

                return false;
            }
        }

        return null;
    }

    /**
     * Isolate beta zero levels with periodic trig functions of rational-polynomial phases.
     *
     * @param array<string, int|float> $parameters
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @param array{string, string} $maximumWidth
     * @return list<RationalRootInterval>|null
     */
    private function isolatePeriodicBetaZeroLevelsInInterval(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        array $lower,
        array $upper,
        array $maximumWidth,
        int $maxDepth,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || $candidate->name !== 'beta'
                || \count($candidate->arguments) !== 2
                || !$evaluationOptions->functions->isBuiltIn('beta')
            ) {
                continue;
            }
            $extractor = new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                256,
                $evaluationOptions,
            );
            $targetPolynomial = $extractor->polynomial($target);
            if ($targetPolynomial === null || \count($targetPolynomial) !== 1 || $targetPolynomial[0][0] !== '0') {
                continue;
            }

            foreach ([0, 1] as $periodicIndex) {
                $periodic = $this->unwrapGrouping($candidate->arguments[$periodicIndex]);
                $constantPolynomial = $extractor->polynomial($candidate->arguments[1 - $periodicIndex]);
                if (
                    !$periodic instanceof FunctionCallNode
                    || !\in_array($periodic->name, ['sin', 'cos', 'tan', 'cot', 'sec', 'csc'], true)
                    || !$evaluationOptions->functions->isBuiltIn($periodic->name)
                    || \count($periodic->arguments) !== 1
                    || !$this->containsVariable($periodic->arguments[0], $variable)
                    || $constantPolynomial === null
                    || \count($constantPolynomial) !== 1
                ) {
                    continue;
                }

                $constant = $constantPolynomial[0];
                $constantRange = new ExactRationalInterval($constant, $constant);
                if (
                    $constantRange->compareLowerToRational('-171', '1') < 0
                    || $constantRange->compareUpperToRational('171', '1') > 0
                ) {
                    return null;
                }
                if ($this->isNonpositiveInteger($constant)) {
                    return [];
                }

                $phase = $extractor->polynomial($periodic->arguments[0]);
                if ($phase === null || \count($phase) < 2 || $phase[\array_key_last($phase)][0] === '0') {
                    return null;
                }
                $phaseRange = $this->evaluateRationalPolynomialOnInterval(
                    $phase,
                    new ExactRationalInterval($lower, $upper),
                );
                if ($phaseRange === null) {
                    return null;
                }
                $maximumMagnitude = \in_array($periodic->name, ['sin', 'cos'], true)
                    ? ['1', '1']
                    : $this->periodicTrigMagnitudeBound($periodic->name, $phaseRange);
                $constantValue = (new IntegerPolynomialExtractor('', []))->ratio($constant[0], $constant[1]);
                $magnitudeValue = $maximumMagnitude === null
                    ? null
                    : (new IntegerPolynomialExtractor('', []))->ratio(
                        $maximumMagnitude[0],
                        $maximumMagnitude[1],
                    );
                $firstLevel = 0;
                $lastLevel = 342;
                if (
                    \is_float($constantValue)
                    && \is_float($magnitudeValue)
                    && \is_finite($constantValue)
                    && \is_finite($magnitudeValue)
                ) {
                    // The two-level margin keeps float-derived bounds conservative; exact checks follow.
                    $firstLevel = \max(0, (int) \floor(-$constantValue - $magnitudeValue) - 2);
                    $lastLevel = \min(342, (int) \ceil(-$constantValue + $magnitudeValue) + 2);
                }
                $roots = [];
                for ($integerLevel = $firstLevel; $integerLevel <= $lastLevel; ++$integerLevel) {
                    $level = (new ExactRationalInterval(
                        [(string) -$integerLevel, '1'],
                        [(string) -$integerLevel, '1'],
                    ))->subtract($constantRange);
                    if (
                        $level->compareLowerToRational('-171', '1') < 0
                        || $level->compareUpperToRational('171', '1') > 0
                        || $this->isNonpositiveInteger($level->lower)
                    ) {
                        continue;
                    }
                    if (
                        (\in_array($periodic->name, ['sin', 'cos'], true)
                            && ($level->compareLowerToRational('-1', '1') < 0
                                || $level->compareUpperToRational('1', '1') > 0))
                        || (\in_array($periodic->name, ['sec', 'csc'], true)
                            && $level->compareLowerToRational('-1', '1') > 0
                            && $level->compareUpperToRational('1', '1') < 0)
                    ) {
                        continue;
                    }

                    $levelNode = $this->rationalFractionNode($level->lower, $periodic->span());
                    if ($levelNode === null) {
                        return null;
                    }
                    $levelRoots = \count($phase) === 2
                        ? $this->isolateAffinePeriodicRootsInInterval(
                            $periodic,
                            $levelNode,
                            $variable,
                            $parameters,
                            $evaluationOptions,
                            $lower,
                            $upper,
                            $maximumWidth,
                        )
                        : $this->isolatePolynomialTrigonometricRootsInInterval(
                            $periodic,
                            $levelNode,
                            $variable,
                            $parameters,
                            $evaluationOptions,
                            $lower,
                            $upper,
                            $maximumWidth,
                            $maxDepth,
                        );
                    if ($levelRoots === null) {
                        return null;
                    }
                    $roots = [...$roots, ...$levelRoots];
                }

                \usort(
                    $roots,
                    fn (RationalRootInterval $first, RationalRootInterval $second): int =>
                        $this->compareRationalFractions(
                            [$first->lowerNumerator, $first->lowerDenominator],
                            [$second->lowerNumerator, $second->lowerDenominator],
                        ),
                );

                return $roots;
            }

            $firstPeriodic = $this->unwrapGrouping($candidate->arguments[0]);
            $secondPeriodic = $this->unwrapGrouping($candidate->arguments[1]);
            if (
                $firstPeriodic instanceof FunctionCallNode
                && $secondPeriodic instanceof FunctionCallNode
                && \in_array(
                    [$firstPeriodic->name, $secondPeriodic->name],
                    [['sin', 'cos'], ['cos', 'sin']],
                    true,
                )
                && $evaluationOptions->functions->isBuiltIn($firstPeriodic->name)
                && $evaluationOptions->functions->isBuiltIn($secondPeriodic->name)
                && \count($firstPeriodic->arguments) === 1
                && \count($secondPeriodic->arguments) === 1
                && $this->containsVariable($firstPeriodic->arguments[0], $variable)
                && $this->containsVariable($secondPeriodic->arguments[0], $variable)
            ) {
                $phase = $extractor->polynomial($firstPeriodic->arguments[0]);
                $secondPhase = $extractor->polynomial($secondPeriodic->arguments[0]);
                if ($phase === null || $phase !== $secondPhase || \count($phase) < 2) {
                    return null;
                }
                $tangent = new FunctionCallNode(
                    'tan',
                    [$firstPeriodic->arguments[0]],
                    $firstPeriodic->nameSpan,
                    $firstPeriodic->span,
                );
                $minusOne = $this->rationalFractionNode(['-1', '1'], $firstPeriodic->span);
                if ($minusOne === null) {
                    return null;
                }

                return \count($phase) === 2
                    ? $this->isolateAffinePeriodicRootsInInterval(
                        $tangent,
                        $minusOne,
                        $variable,
                        $parameters,
                        $evaluationOptions,
                        $lower,
                        $upper,
                        $maximumWidth,
                    )
                    : $this->isolatePolynomialTrigonometricRootsInInterval(
                        $tangent,
                        $minusOne,
                        $variable,
                        $parameters,
                        $evaluationOptions,
                        $lower,
                        $upper,
                        $maximumWidth,
                        $maxDepth,
                    );
            }

            $firstPeriodic = $this->unwrapGrouping($candidate->arguments[0]);
            $secondPeriodic = $this->unwrapGrouping($candidate->arguments[1]);
            if (
                $firstPeriodic instanceof FunctionCallNode
                && $secondPeriodic instanceof FunctionCallNode
                && \in_array(
                    [$firstPeriodic->name, $secondPeriodic->name],
                    [['tan', 'cot'], ['cot', 'tan']],
                    true,
                )
                && $evaluationOptions->functions->isBuiltIn($firstPeriodic->name)
                && $evaluationOptions->functions->isBuiltIn($secondPeriodic->name)
                && \count($firstPeriodic->arguments) === 1
                && \count($secondPeriodic->arguments) === 1
                && $this->containsVariable($firstPeriodic->arguments[0], $variable)
                && $this->containsVariable($secondPeriodic->arguments[0], $variable)
            ) {
                $phase = $extractor->polynomial($firstPeriodic->arguments[0]);
                $secondPhase = $extractor->polynomial($secondPeriodic->arguments[0]);
                if ($phase === null || $phase !== $secondPhase || \count($phase) < 2) {
                    return null;
                }
                $phaseRange = $this->evaluateRationalPolynomialOnInterval(
                    $phase,
                    new ExactRationalInterval($lower, $upper),
                );
                if ($phaseRange === null) {
                    return null;
                }
                $doublePhaseRange = $phaseRange->multiply(
                    new ExactRationalInterval(['2', '1'], ['2', '1']),
                );
                $sineRange = $this->certifiedSineRangeOnInterval($doublePhaseRange);
                $doublePhase = new BinaryOperationNode(
                    BinaryOperator::Multiply,
                    new NumberNode(2, '2', $firstPeriodic->arguments[0]->span()),
                    $firstPeriodic->arguments[0],
                    $firstPeriodic->span,
                );
                $sine = new FunctionCallNode(
                    'sin',
                    [$doublePhase],
                    $firstPeriodic->nameSpan,
                    $firstPeriodic->span,
                );
                $roots = [];
                $firstIntegerLevel = 3;
                $lastIntegerLevel = 171;
                $extractorForRatios = new IntegerPolynomialExtractor('', []);
                $lowerSine = $extractorForRatios->ratio(
                    $sineRange->lower[0],
                    $sineRange->lower[1],
                );
                $upperSine = $extractorForRatios->ratio(
                    $sineRange->upper[0],
                    $sineRange->upper[1],
                );
                if (\is_float($lowerSine) && \is_float($upperSine) && $lowerSine >= 0.0) {
                    return [];
                }
                if (\is_float($lowerSine) && \is_float($upperSine) && $upperSine < 0.0) {
                    $lowerCandidate = 2.0 / -$lowerSine;
                    $upperCandidate = 2.0 / -$upperSine;
                    if (\is_finite($lowerCandidate) && \is_finite($upperCandidate)) {
                        $firstIntegerLevel = \max(3, (int) \floor($lowerCandidate) - 1);
                        $lastIntegerLevel = \min(171, (int) \ceil($upperCandidate) + 1);
                    }
                }
                for ($integerLevel = $firstIntegerLevel; $integerLevel <= $lastIntegerLevel; ++$integerLevel) {
                    $sineLevel = ['-2', (string) $integerLevel];
                    if (
                        $sineRange->compareLowerToRational($sineLevel[0], $sineLevel[1]) > 0
                        || $sineRange->compareUpperToRational($sineLevel[0], $sineLevel[1]) < 0
                    ) {
                        continue;
                    }
                    $levelNode = $this->rationalFractionNode($sineLevel, $firstPeriodic->span());
                    if ($levelNode === null) {
                        return null;
                    }
                    $levelRoots = \count($phase) === 2
                        ? $this->isolateAffinePeriodicRootsInInterval(
                            $sine,
                            $levelNode,
                            $variable,
                            $parameters,
                            $evaluationOptions,
                            $lower,
                            $upper,
                            $maximumWidth,
                        )
                        : $this->isolatePolynomialTrigonometricRootsInInterval(
                            $sine,
                            $levelNode,
                            $variable,
                            $parameters,
                            $evaluationOptions,
                            $lower,
                            $upper,
                            $maximumWidth,
                            $maxDepth,
                        );
                    if ($levelRoots === null) {
                        return null;
                    }
                    $roots = \array_merge($roots, $levelRoots);
                }
                usort(
                    $roots,
                    fn (RationalRootInterval $a, RationalRootInterval $b): int =>
                        $this->compareRationalFractions(
                            [$a->lowerNumerator, $a->lowerDenominator],
                            [$b->lowerNumerator, $b->lowerDenominator],
                        ),
                );
                for ($rootIndex = 1; $rootIndex < \count($roots); ++$rootIndex) {
                    if (
                        $this->compareRationalFractions(
                            [$roots[$rootIndex - 1]->upperNumerator, $roots[$rootIndex - 1]->upperDenominator],
                            [$roots[$rootIndex]->lowerNumerator, $roots[$rootIndex]->lowerDenominator],
                        ) >= 0
                    ) {
                        return null;
                    }
                }

                return $roots;
            }

            $firstPeriodic = $this->unwrapGrouping($candidate->arguments[0]);
            $secondPeriodic = $this->unwrapGrouping($candidate->arguments[1]);
            if (
                $firstPeriodic instanceof FunctionCallNode
                && $secondPeriodic instanceof FunctionCallNode
                && $firstPeriodic->name === $secondPeriodic->name
                && \in_array($firstPeriodic->name, ['sin', 'cos', 'tan', 'cot', 'sec', 'csc'], true)
                && $evaluationOptions->functions->isBuiltIn($firstPeriodic->name)
                && \count($firstPeriodic->arguments) === 1
                && \count($secondPeriodic->arguments) === 1
                && $this->containsVariable($firstPeriodic->arguments[0], $variable)
                && $this->containsVariable($secondPeriodic->arguments[0], $variable)
            ) {
                $phase = $extractor->polynomial($firstPeriodic->arguments[0]);
                $secondPhase = $extractor->polynomial($secondPeriodic->arguments[0]);
                if ($phase === null || $phase !== $secondPhase || \count($phase) < 2) {
                    return null;
                }
                $phaseRange = null;
                if (\in_array($firstPeriodic->name, ['tan', 'cot', 'sec', 'csc'], true)) {
                    $phaseRange = $this->evaluateRationalPolynomialOnInterval(
                        $phase,
                        new ExactRationalInterval($lower, $upper),
                    );
                    if ($phaseRange === null) {
                        return null;
                    }
                }
                $periodicTrigBound = $phaseRange === null
                    ? null
                    : $this->periodicTrigMagnitudeBound($firstPeriodic->name, $phaseRange);
                $roots = [];
                $lastIntegerLevel = \in_array($firstPeriodic->name, ['sin', 'cos'], true) ? 2 : 342;
                for ($integerLevel = 0; $integerLevel <= $lastIntegerLevel; ++$integerLevel) {
                    $sharedLevel = [(string) (-$integerLevel), '2'];
                    $level = new ExactRationalInterval($sharedLevel, $sharedLevel);
                    if (
                        !$this->periodicLevelIsInRange($firstPeriodic->name, $level)
                        || $this->isNonpositiveInteger($sharedLevel)
                        || ($periodicTrigBound !== null
                            && $this->compareRationalFractions(
                                [\ltrim($sharedLevel[0], '-'), $sharedLevel[1]],
                                $periodicTrigBound,
                            ) > 0)
                    ) {
                        continue;
                    }
                    $levelNode = $this->rationalFractionNode($sharedLevel, $firstPeriodic->span());
                    if ($levelNode === null) {
                        return null;
                    }
                    $levelRoots = \count($phase) === 2
                        ? $this->isolateAffinePeriodicRootsInInterval(
                            $firstPeriodic,
                            $levelNode,
                            $variable,
                            $parameters,
                            $evaluationOptions,
                            $lower,
                            $upper,
                            $maximumWidth,
                        )
                        : $this->isolatePolynomialTrigonometricRootsInInterval(
                            $firstPeriodic,
                            $levelNode,
                            $variable,
                            $parameters,
                            $evaluationOptions,
                            $lower,
                            $upper,
                            $maximumWidth,
                            $maxDepth,
                        );
                    if ($levelRoots === null) {
                        return null;
                    }
                    $roots = \array_merge($roots, $levelRoots);
                }

                usort(
                    $roots,
                    fn (RationalRootInterval $a, RationalRootInterval $b): int =>
                        $this->compareRationalFractions(
                            [$a->lowerNumerator, $a->lowerDenominator],
                            [$b->lowerNumerator, $b->lowerDenominator],
                        ),
                );
                for ($rootIndex = 1; $rootIndex < \count($roots); ++$rootIndex) {
                    if (
                        $this->compareRationalFractions(
                            [$roots[$rootIndex - 1]->upperNumerator, $roots[$rootIndex - 1]->upperDenominator],
                            [$roots[$rootIndex]->lowerNumerator, $roots[$rootIndex]->lowerDenominator],
                        ) >= 0
                    ) {
                        return null;
                    }
                }

                return $roots;
            }

            foreach ([0, 1] as $periodicIndex) {
                $periodic = $this->unwrapGrouping($candidate->arguments[$periodicIndex]);
                $constant = $extractor->polynomial($candidate->arguments[1 - $periodicIndex]);
                if (
                    !$periodic instanceof FunctionCallNode
                    || !\in_array($periodic->name, ['sin', 'cos', 'tan', 'cot', 'sec', 'csc'], true)
                    || !$evaluationOptions->functions->isBuiltIn($periodic->name)
                    || \count($periodic->arguments) !== 1
                    || $constant === null
                    || \count($constant) !== 1
                    || !$this->containsVariable($periodic->arguments[0], $variable)
                ) {
                    continue;
                }
                $phase = $extractor->polynomial($periodic->arguments[0]);
                if ($phase === null || \count($phase) < 2) {
                    return null;
                }
                $periodicTrigBound = null;
                if (\in_array($periodic->name, ['tan', 'cot', 'sec', 'csc'], true)) {
                    $phaseRange = $this->evaluateRationalPolynomialOnInterval(
                        $phase,
                        new ExactRationalInterval($lower, $upper),
                    );
                    if ($phaseRange === null) {
                        return null;
                    }
                    $periodicTrigBound = $this->periodicTrigMagnitudeBound(
                        $periodic->name,
                        $phaseRange,
                    );
                }

                $constantValue = $constant[0];
                $constantInterval = new ExactRationalInterval($constantValue, $constantValue);
                if (
                    $constantInterval->compareLowerToRational('-171', '1') < 0
                    || $constantInterval->compareUpperToRational('171', '1') > 0
                    || $this->isNonpositiveInteger($constantValue)
                ) {
                    return [];
                }

                $roots = [];
                for ($integerLevel = 0; $integerLevel <= 342; ++$integerLevel) {
                    $argumentLevel = (new ExactRationalInterval(
                        [(string) -$integerLevel, '1'],
                        [(string) -$integerLevel, '1'],
                    ))->subtract($constantInterval)->lower;
                    $level = new ExactRationalInterval($argumentLevel, $argumentLevel);
                    if (
                        !$this->periodicLevelIsInRange($periodic->name, $level)
                        || $this->isNonpositiveInteger($argumentLevel)
                    ) {
                        continue;
                    }
                    if (
                        $periodicTrigBound !== null
                        && $this->compareRationalFractions(
                            [\ltrim($argumentLevel[0], '-'), $argumentLevel[1]],
                            $periodicTrigBound,
                        ) > 0
                    ) {
                        continue;
                    }
                    $levelNode = $this->rationalFractionNode($argumentLevel, $periodic->span());
                    if ($levelNode === null) {
                        return null;
                    }
                    $levelRoots = \count($phase) === 2
                        ? $this->isolateAffinePeriodicRootsInInterval(
                            $periodic,
                            $levelNode,
                            $variable,
                            $parameters,
                            $evaluationOptions,
                            $lower,
                            $upper,
                            $maximumWidth,
                        )
                        : $this->isolatePolynomialTrigonometricRootsInInterval(
                            $periodic,
                            $levelNode,
                            $variable,
                            $parameters,
                            $evaluationOptions,
                            $lower,
                            $upper,
                            $maximumWidth,
                            $maxDepth,
                        );
                    if ($levelRoots === null) {
                        return null;
                    }
                    $roots = \array_merge($roots, $levelRoots);
                }

                usort(
                    $roots,
                    fn (RationalRootInterval $a, RationalRootInterval $b): int =>
                        $this->compareRationalFractions(
                            [$a->lowerNumerator, $a->lowerDenominator],
                            [$b->lowerNumerator, $b->lowerDenominator],
                        ),
                );
                for ($index = 1; $index < \count($roots); ++$index) {
                    if (
                        $this->compareRationalFractions(
                            [$roots[$index - 1]->upperNumerator, $roots[$index - 1]->upperDenominator],
                            [$roots[$index]->lowerNumerator, $roots[$index]->lowerDenominator],
                        ) >= 0
                    ) {
                        return null;
                    }
                }

                return $roots;
            }
        }

        return null;
    }

    private function periodicLevelIsInRange(string $function, ExactRationalInterval $level): bool
    {
        if (\in_array($function, ['tan', 'cot'], true)) {
            return true;
        }
        if (\in_array($function, ['sec', 'csc'], true)) {
            return $level->compareUpperToRational('-1', '1') <= 0
                || $level->compareLowerToRational('1', '1') >= 0;
        }

        return $level->compareLowerToRational('-1', '1') >= 0
            && $level->compareUpperToRational('1', '1') <= 0;
    }

    private function certifiedSineRangeOnInterval(ExactRationalInterval $phaseRange): ExactRationalInterval
    {
        $fullRange = new ExactRationalInterval(['-1', '1'], ['1', '1']);
        $width = (new ExactRationalInterval($phaseRange->upper, $phaseRange->upper))
            ->subtract(new ExactRationalInterval($phaseRange->lower, $phaseRange->lower));
        if (
            $width->compareLowerToRational('6', '1') >= 0
            || $phaseRange->compareLowerToRational('-5', '1') < 0
            || $phaseRange->compareUpperToRational('5', '1') > 0
        ) {
            return $fullRange;
        }

        $lowerEndpointSine = $this->certifiedSineEnclosure($phaseRange->lower);
        $upperEndpointSine = $this->certifiedSineEnclosure($phaseRange->upper);
        $rangeLower = $this->compareRationalFractions(
            $lowerEndpointSine->lower,
            $upperEndpointSine->lower,
        ) <= 0 ? $lowerEndpointSine->lower : $upperEndpointSine->lower;
        $rangeUpper = $this->compareRationalFractions(
            $lowerEndpointSine->upper,
            $upperEndpointSine->upper,
        ) >= 0 ? $lowerEndpointSine->upper : $upperEndpointSine->upper;
        $pi = self::certifiedPiEnclosure();
        for ($periodIndex = -2; $periodIndex <= 2; ++$periodIndex) {
            $maximumPhase = $pi->multiply(new ExactRationalInterval(
                [(string) (4 * $periodIndex + 1), '2'],
                [(string) (4 * $periodIndex + 1), '2'],
            ));
            if (
                $phaseRange->compareLowerToRational($maximumPhase->upper[0], $maximumPhase->upper[1]) <= 0
                && $phaseRange->compareUpperToRational($maximumPhase->lower[0], $maximumPhase->lower[1]) >= 0
            ) {
                $rangeUpper = ['1', '1'];
            }

            $minimumPhase = $pi->multiply(new ExactRationalInterval(
                [(string) (4 * $periodIndex - 1), '2'],
                [(string) (4 * $periodIndex - 1), '2'],
            ));
            if (
                $phaseRange->compareLowerToRational($minimumPhase->upper[0], $minimumPhase->upper[1]) <= 0
                && $phaseRange->compareUpperToRational($minimumPhase->lower[0], $minimumPhase->lower[1]) >= 0
            ) {
                $rangeLower = ['-1', '1'];
            }
        }

        return new ExactRationalInterval($rangeLower, $rangeUpper);
    }

    /** @return array{string, string}|null Maximum periodic-trig magnitude, or null when unbounded/uncertain. */
    private function periodicTrigMagnitudeBound(
        string $function,
        ExactRationalInterval $phaseRange,
    ): ?array {
        $phaseWidth = (new ExactRationalInterval($phaseRange->upper, $phaseRange->upper))
            ->subtract(new ExactRationalInterval($phaseRange->lower, $phaseRange->lower))
            ->lower;
        if ($this->compareRationalFractions($phaseWidth, ['3', '1']) >= 0) {
            return null;
        }

        $midpoint = (new ExactRationalInterval($phaseRange->lower, $phaseRange->lower))
            ->add(new ExactRationalInterval($phaseRange->upper, $phaseRange->upper))
            ->divide(new ExactRationalInterval(['2', '1'], ['2', '1']))
            ->lower;
        $approximateMidpoint = (new IntegerPolynomialExtractor('', []))->ratio($midpoint[0], $midpoint[1]);
        if (!\is_float($approximateMidpoint) || \abs($approximateMidpoint) > 1000000.0) {
            return null;
        }

        $center = (int) \floor($approximateMidpoint / \M_PI);
        $pi = self::certifiedPiEnclosure();
        $nearestDistance = null;
        for ($multiple = $center - 3; $multiple <= $center + 3; ++$multiple) {
            $poleMultiple = \in_array($function, ['sec', 'tan'], true)
                ? [(string) (2 * $multiple + 1), '2']
                : [(string) $multiple, '1'];
            $pole = $pi->multiply(new ExactRationalInterval($poleMultiple, $poleMultiple));
            if (
                $phaseRange->compareLowerToRational($pole->upper[0], $pole->upper[1]) <= 0
                && $phaseRange->compareUpperToRational($pole->lower[0], $pole->lower[1]) >= 0
            ) {
                return null;
            }
            if ($phaseRange->compareUpperToRational($pole->lower[0], $pole->lower[1]) < 0) {
                $distance = (new ExactRationalInterval($pole->lower, $pole->lower))
                    ->subtract(new ExactRationalInterval($phaseRange->upper, $phaseRange->upper))
                    ->lower;
            } else {
                $distance = (new ExactRationalInterval($phaseRange->lower, $phaseRange->lower))
                    ->subtract(new ExactRationalInterval($pole->upper, $pole->upper))
                    ->lower;
            }
            if (
                $nearestDistance === null
                || $this->compareRationalFractions($distance, $nearestDistance) < 0
            ) {
                $nearestDistance = $distance;
            }
        }
        if ($nearestDistance === null || $nearestDistance[0] === '0') {
            return null;
        }

        if (\in_array($function, ['tan', 'cot'], true)) {
            return (new ExactRationalInterval(['1', '1'], ['1', '1']))
                ->divide(new ExactRationalInterval($nearestDistance, $nearestDistance))
                ->upper;
        }

        $distance = new ExactRationalInterval($nearestDistance, $nearestDistance);
        if ($distance->compareUpperToRational('1', '1') <= 0) {
            $minimumTrigMagnitude = $distance->multiply(
                new ExactRationalInterval(['5', '6'], ['5', '6']),
            );
        } else {
            $two = new ExactRationalInterval(['2', '1'], ['2', '1']);
            $minimumTrigMagnitude = $distance
                ->multiply($two)
                ->divide(new ExactRationalInterval($pi->upper, $pi->upper));
        }

        return $minimumTrigMagnitude->lower[0] === '0'
            ? null
            : (new ExactRationalInterval(['1', '1'], ['1', '1']))
                ->divide($minimumTrigMagnitude)
                ->upper;
    }

    /** @param array{string, string} $fraction */
    private function rationalFractionNode(array $fraction, SourceSpan $span): ?Node
    {
        $numerator = (float) $fraction[0];
        $denominator = (float) $fraction[1];
        if (!\is_finite($numerator) || !\is_finite($denominator) || $denominator === 0.0) {
            return null;
        }
        $negative = \str_starts_with($fraction[0], '-');
        $numeratorDigits = $negative ? \substr($fraction[0], 1) : $fraction[0];
        $numeratorNode = new NumberNode(
            \abs($numerator),
            $numeratorDigits,
            $span,
        );
        $signedNumerator = $negative
            ? new UnaryOperationNode(UnaryOperator::Minus, $numeratorNode, $span)
            : $numeratorNode;
        $denominatorNode = new NumberNode($denominator, $fraction[1], $span);

        return new BinaryOperationNode(
            BinaryOperator::Divide,
            $signedNumerator,
            $denominatorNode,
            $span,
        );
    }

    /**
     * Isolate affine positive-integer-shape regularized gamma equations.
     *
     * @param array<string, int|float> $parameters
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @param array{string, string} $maximumWidth
     * @return list<RationalRootInterval>|int|null
     */
    private function isolateRegularizedGammaIntegerShapeInInterval(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
        array $lower,
        array $upper,
        array $maximumWidth,
        int $maxDepth,
        bool $countOnly = false,
    ): array|int|null {
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || !\in_array($candidate->name, ['gammainc', 'gammaincc'], true)
                || !$evaluationOptions->functions->isBuiltIn($candidate->name)
                || \count($candidate->arguments) !== 2
                || !$this->containsVariable($candidate->arguments[1], $variable)
            ) {
                continue;
            }
            $shape = $extractor->polynomial($candidate->arguments[0]);
            $argument = $extractor->polynomial($candidate->arguments[1]);
            $probability = $extractor->polynomial($target);
            if (
                $shape !== null
                && \count($shape) === 1
                && $this->compareRationalFractions($shape[0], ['1', '2']) === 0
                && $argument === null
                && $probability !== null
                && \count($probability) === 1
            ) {
                $rationalArgument = $extractor->rationalFunction($candidate->arguments[1]);
                if ($rationalArgument !== null) {
                    return $this->isolateRegularizedGammaHalfShapeRationalRoots(
                        $candidate->name,
                        $rationalArgument,
                        $probability[0],
                        $lower,
                        $upper,
                        $maximumWidth,
                        $maxDepth,
                        $countOnly,
                    );
                }
            }
            if (
                $shape !== null
                && \count($shape) === 1
                && $this->compareRationalFractions($shape[0], ['1', '2']) === 0
                && $argument !== null
                && $probability !== null
                && \count($probability) === 1
            ) {
                return $this->isolateRegularizedGammaHalfShapeAffineRoots(
                    $candidate->name,
                    $argument,
                    $probability[0],
                    $lower,
                    $upper,
                    $maximumWidth,
                    $maxDepth,
                    $countOnly,
                );
            }
            if (
                $shape === null
                || \count($shape) !== 1
                || $shape[0][1] !== '1'
                || \preg_match('/\A[1-9][0-9]*\z/D', $shape[0][0]) !== 1
                || \strlen($shape[0][0]) > 3
                || $argument === null
                || \count($argument) < 2
                || $probability === null
                || \count($probability) !== 1
            ) {
                return null;
            }
            $shapeValue = (int) $shape[0][0];
            if ($shapeValue > $maxPolynomialDegree) {
                return null;
            }

            $probabilityInterval = new ExactRationalInterval($probability[0], $probability[0]);
            if (
                $probabilityInterval->compareLowerToRational('0', '1') < 0
                || $probabilityInterval->compareUpperToRational('1', '1') > 0
            ) {
                return $countOnly ? 0 : [];
            }
            $one = new ExactRationalInterval(['1', '1'], ['1', '1']);
            $zero = new ExactRationalInterval(['0', '1'], ['0', '1']);
            $exponentialTarget = $candidate->name === 'gammainc'
                ? $one->subtract($probabilityInterval)->lower
                : $probability[0];

            if ($this->compareRationalFractions($exponentialTarget, ['0', '1']) === 0) {
                return $countOnly ? 0 : [];
            }
            if ($this->compareRationalFractions($exponentialTarget, ['1', '1']) === 0) {
                $integerArgument = $this->integerPolynomialFromRational($argument);
                if ($integerArgument === null) {
                    return null;
                }
                $counter = new ExactPolynomialRootCounter();
                if ($countOnly) {
                    return $counter->countOpenInterval(
                        $integerArgument,
                        $lower[0],
                        $lower[1],
                        $upper[0],
                        $upper[1],
                    );
                }
                $exactRoots = $counter->isolateOpenInterval(
                    $integerArgument,
                    $lower[0],
                    $lower[1],
                    $upper[0],
                    $upper[1],
                    $maxDepth,
                    $maximumWidth,
                );

                return $this->rationalRootIntervalsFromExactPolynomial($exactRoots);
            }

            $argumentDegree = \count($argument) - 1;
            if ($shapeValue === 1 && $argumentDegree > 1) {
                return $this->isolateRegularizedGammaShapeOnePolynomialArgument(
                    $candidate,
                    $target,
                    $argumentDegree,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                    $lower,
                    $upper,
                    $maximumWidth,
                    $maxDepth,
                    $countOnly,
                );
            }
            if ($argumentDegree !== 1) {
                return $this->isolateIntegerShapeRegularizedGammaPolynomialRoots(
                    $shapeValue,
                    $exponentialTarget,
                    $argument,
                    $variable,
                    $parameters,
                    $lower,
                    $upper,
                    $maximumWidth,
                    $maxDepth,
                    $countOnly,
                );
            }

            $argumentSlope = new ExactRationalInterval($argument[1], $argument[1]);
            $argumentIntercept = new ExactRationalInterval($argument[0], $argument[0]);
            $zeroArgumentRoot = $zero
                ->subtract($argumentIntercept)
                ->divide($argumentSlope)
                ->lower;
            if ($countOnly) {
                return $this->countIntegerShapeRegularizedGammaRoots(
                    $shapeValue,
                    $exponentialTarget,
                    $argument[1],
                    $argument[0],
                    $lower,
                    $upper,
                );
            }

            if ($shapeValue > 1) {
                return $this->isolateIntegerShapeRegularizedGammaRoot(
                    $shapeValue,
                    $exponentialTarget,
                    $argument[1],
                    $argument[0],
                    $lower,
                    $upper,
                    $maximumWidth,
                    $maxDepth,
                );
            }

            $domainLower = $lower;
            $domainUpper = $upper;
            if ($this->compareRationalFractions($argument[1], ['0', '1']) > 0) {
                if ($this->compareRationalFractions($zeroArgumentRoot, $upper) >= 0) {
                    return [];
                }
                if ($this->compareRationalFractions($zeroArgumentRoot, $lower) > 0) {
                    $domainLower = $zeroArgumentRoot;
                }
            } else {
                if ($this->compareRationalFractions($zeroArgumentRoot, $lower) <= 0) {
                    return [];
                }
                if ($this->compareRationalFractions($zeroArgumentRoot, $upper) < 0) {
                    $domainUpper = $zeroArgumentRoot;
                }
            }

            $negativeOne = new ExactRationalInterval(['-1', '1'], ['-1', '1']);
            $roots = (new ExponentialEquationSolver())->isolateAffine(
                $exponentialTarget,
                $argumentSlope->multiply($negativeOne)->lower,
                $argumentIntercept->multiply($negativeOne)->lower,
                $domainLower,
                $domainUpper,
                $maximumWidth,
                $maxDepth,
            );
            if ($roots === null) {
                return null;
            }

            return $roots;
        }

        return null;
    }

    /**
     * Reduce P(1/2,x) and Q(1/2,x) to erf(sqrt(x)) and erfc(sqrt(x)).
     *
     * @param list<array{string, string}> $argument
     * @param array{string, string} $probability
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @param array{string, string} $maximumWidth
     * @return list<RationalRootInterval>|int|null
     */
    private function isolateRegularizedGammaHalfShapeAffineRoots(
        string $function,
        array $argument,
        array $probability,
        array $lower,
        array $upper,
        array $maximumWidth,
        int $maxDepth,
        bool $countOnly,
    ): array|int|null {
        if (\count($argument) === 3) {
            return $this->isolateRegularizedGammaHalfShapeQuadraticRoots(
                $function,
                $argument,
                $probability,
                $lower,
                $upper,
                $maximumWidth,
                $maxDepth,
                $countOnly,
            );
        }
        if (\count($argument) > 3) {
            return $this->isolateRegularizedGammaHalfShapePolynomialRoots(
                $function,
                $argument,
                $probability,
                $lower,
                $upper,
                $maximumWidth,
                $maxDepth,
                $countOnly,
            );
        }
        if (\count($argument) !== 2) {
            return null;
        }

        $probabilityInterval = new ExactRationalInterval($probability, $probability);
        if (
            $probabilityInterval->compareLowerToRational('0', '1') < 0
            || $probabilityInterval->compareUpperToRational('1', '1') > 0
        ) {
            return $countOnly ? 0 : [];
        }

        $inverseFunction = $function === 'gammainc' ? 'erf' : 'erfc';
        $boundaryProbability = $function === 'gammainc' ? ['0', '1'] : ['1', '1'];
        $noFiniteRootProbability = $function === 'gammainc' ? ['1', '1'] : ['0', '1'];
        if ($this->compareRationalFractions($probability, $noFiniteRootProbability) === 0) {
            return $countOnly ? 0 : [];
        }
        $zeroLevel = $this->compareRationalFractions($probability, $boundaryProbability) === 0;
        $inverseLevel = $zeroLevel
            ? null
            : $this->certifiedInverseErrorFunctionLevel($inverseFunction, $probability);
        if ($inverseLevel === null) {
            if (!$zeroLevel) {
                return null;
            }
            $integerArgument = $this->integerPolynomialFromRational($argument);
            if ($integerArgument === null) {
                return null;
            }
            $argumentRoots = (new ExactPolynomialRootCounter())->isolateOpenInterval(
                $integerArgument,
                $lower[0],
                $lower[1],
                $upper[0],
                $upper[1],
                $maxDepth,
                $maximumWidth,
            );
            if ($argumentRoots === null) {
                return null;
            }

            return $countOnly
                ? \count($argumentRoots)
                : $this->rationalRootIntervalsFromExactPolynomial($argumentRoots);
        }

        if ($inverseLevel->compareUpperToRational('0', '1') < 0) {
            return $countOnly ? 0 : [];
        }
        $level = $inverseLevel->multiply($inverseLevel);
        $slope = new ExactRationalInterval($argument[1], $argument[1]);
        $intercept = new ExactRationalInterval($argument[0], $argument[0]);
        if ($slope->lower === ['0', '1']) {
            return null;
        }
        $zeroArgument = (new ExactRationalInterval(['0', '1'], ['0', '1']))
            ->subtract($intercept)
            ->divide($slope)
            ->lower;
        $domainLower = $lower;
        $domainUpper = $upper;
        if ($slope->compareLowerToRational('0', '1') > 0) {
            if ($this->compareRationalFractions($zeroArgument, $domainLower) > 0) {
                $domainLower = $zeroArgument;
            }
        } elseif ($this->compareRationalFractions($zeroArgument, $domainUpper) < 0) {
            $domainUpper = $zeroArgument;
        }
        if ($this->compareRationalFractions($domainLower, $domainUpper) >= 0) {
            return $countOnly ? 0 : [];
        }

        $derivativeSign = $slope->compareLowerToRational('0', '1');
        $roots = $this->isolateMonotonePolynomialLevelSegment(
            $argument,
            $level,
            $derivativeSign,
            $domainLower,
            $domainUpper,
            $maximumWidth,
            $maxDepth,
        );

        return $roots === null ? null : ($countOnly ? \count($roots) : $roots);
    }

    /**
     * @param list<array{string, string}> $argument
     * @param array{string, string} $probability
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @param array{string, string} $maximumWidth
     * @return list<RationalRootInterval>|int|null
     */
    private function isolateRegularizedGammaHalfShapeQuadraticRoots(
        string $function,
        array $argument,
        array $probability,
        array $lower,
        array $upper,
        array $maximumWidth,
        int $maxDepth,
        bool $countOnly,
    ): array|int|null {
        $target = new ExactRationalInterval($probability, $probability);
        if (
            $target->compareLowerToRational('0', '1') < 0
            || $target->compareUpperToRational('1', '1') > 0
        ) {
            return $countOnly ? 0 : [];
        }
        $boundaryProbability = $function === 'gammainc' ? ['0', '1'] : ['1', '1'];
        $noFiniteRootProbability = $function === 'gammainc' ? ['1', '1'] : ['0', '1'];
        if ($this->compareRationalFractions($probability, $noFiniteRootProbability) === 0) {
            return $countOnly ? 0 : [];
        }
        if (
            $this->compareRationalFractions($probability, $boundaryProbability) === 0
        ) {
            $integerArgument = $this->integerPolynomialFromRational($argument);
            if ($integerArgument === null) {
                return null;
            }
            $exactRoots = (new ExactPolynomialRootCounter())->isolateOpenInterval(
                $integerArgument,
                $lower[0],
                $lower[1],
                $upper[0],
                $upper[1],
                $maxDepth,
                $maximumWidth,
            );
            if ($exactRoots === null) {
                return null;
            }

            return $countOnly
                ? \count($exactRoots)
                : $this->rationalRootIntervalsFromExactPolynomial($exactRoots);
        }

        $inverseLevel = $this->certifiedInverseErrorFunctionLevel(
            $function === 'gammainc' ? 'erf' : 'erfc',
            $probability,
        );
        if ($inverseLevel === null) {
            return null;
        }
        if ($inverseLevel->compareUpperToRational('0', '1') < 0) {
            return $countOnly ? 0 : [];
        }
        $level = $inverseLevel->multiply($inverseLevel);
        $a = new ExactRationalInterval($argument[2], $argument[2]);
        $b = new ExactRationalInterval($argument[1], $argument[1]);
        $c = new ExactRationalInterval($argument[0], $argument[0]);
        if ($a->lower === ['0', '1']) {
            return null;
        }
        $four = new ExactRationalInterval(['4', '1'], ['4', '1']);
        $twoA = $a->multiply(new ExactRationalInterval(['2', '1'], ['2', '1']));
        $discriminant = $b->multiply($b)->subtract($four->multiply($a)->multiply($c->subtract($level)));
        if ($discriminant->compareUpperToRational('0', '1') < 0) {
            return $countOnly ? 0 : [];
        }
        if ($discriminant->compareLowerToRational('0', '1') <= 0) {
            return null;
        }
        $squareRoot = $discriminant->sqrt(40);
        $negativeB = $b->negateInterval();
        $rootCandidates = [
            $negativeB->subtract($squareRoot)->divide($twoA),
            $negativeB->add($squareRoot)->divide($twoA),
        ];
        usort($rootCandidates, fn (ExactRationalInterval $leftRoot, ExactRationalInterval $rightRoot): int =>
            $leftRoot->compareLowerEndpoint($rightRoot));

        $roots = [];
        foreach ($rootCandidates as $candidate) {
            if (
                $candidate->compareUpperToRational($lower[0], $lower[1]) <= 0
                || $candidate->compareLowerToRational($upper[0], $upper[1]) >= 0
            ) {
                continue;
            }
            if (
                $candidate->compareLowerToRational($lower[0], $lower[1]) <= 0
                || $candidate->compareUpperToRational($upper[0], $upper[1]) >= 0
                || $candidate->subtract(new ExactRationalInterval($candidate->lower, $candidate->lower))
                    ->compareUpperToRational($maximumWidth[0], $maximumWidth[1]) > 0
            ) {
                return null;
            }
            $roots[] = new RationalRootInterval(
                $candidate->lower[0],
                $candidate->lower[1],
                $candidate->upper[0],
                $candidate->upper[1],
            );
        }

        return $countOnly ? \count($roots) : $roots;
    }

    /**
     * @param array{list<array{string, string}>, list<array{string, string}>} $argument
     * @param array{string, string} $probability
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @param array{string, string} $maximumWidth
     * @return list<RationalRootInterval>|int|null
     */
    private function isolateRegularizedGammaHalfShapeRationalRoots(
        string $function,
        array $argument,
        array $probability,
        array $lower,
        array $upper,
        array $maximumWidth,
        int $maxDepth,
        bool $countOnly,
    ): array|int|null {
        [$numerator, $denominator] = $argument;
        if (\count($numerator) > 3 || \count($denominator) > 3) {
            return null;
        }
        $denominatorIsZero = true;
        foreach ($denominator as [$coefficientNumerator]) {
            if ($coefficientNumerator !== '0') {
                $denominatorIsZero = false;
                break;
            }
        }
        if ($denominatorIsZero) {
            return null;
        }

        $target = new ExactRationalInterval($probability, $probability);
        if (
            $target->compareLowerToRational('0', '1') < 0
            || $target->compareUpperToRational('1', '1') > 0
        ) {
            return $countOnly ? 0 : [];
        }
        $boundaryProbability = $function === 'gammainc' ? ['0', '1'] : ['1', '1'];
        $noFiniteRootProbability = $function === 'gammainc' ? ['1', '1'] : ['0', '1'];
        if ($this->compareRationalFractions($probability, $noFiniteRootProbability) === 0) {
            return $countOnly ? 0 : [];
        }

        if ($this->compareRationalFractions($probability, $boundaryProbability) === 0) {
            $integerNumerator = $this->integerPolynomialFromRational($numerator);
            $integerDenominator = $this->integerPolynomialFromRational($denominator);
            if ($integerNumerator === null || $integerDenominator === null) {
                return null;
            }
            if ($this->isZeroCoefficientList($integerNumerator)) {
                throw new InfiniteSolutionSetException(
                    'The regularized gamma equation has infinitely many roots where its argument is zero.',
                );
            }
            $counter = new ExactPolynomialRootCounter();
            $rawRoots = $counter->isolateOpenInterval(
                $integerNumerator,
                $lower[0],
                $lower[1],
                $upper[0],
                $upper[1],
                $maxDepth,
                $maximumWidth,
            );
            if ($rawRoots === null) {
                return null;
            }
            $validRoots = $this->excludeCommonDenominatorRoots(
                $counter,
                $integerNumerator,
                $integerDenominator,
                $rawRoots,
            );
            if ($validRoots === null) {
                return null;
            }

            return $countOnly
                ? \count($validRoots)
                : $this->rationalRootIntervalsFromExactPolynomial($validRoots);
        }

        $inverseLevel = $this->certifiedInverseErrorFunctionLevel(
            $function === 'gammainc' ? 'erf' : 'erfc',
            $probability,
        );
        if ($inverseLevel === null) {
            return null;
        }
        if ($inverseLevel->compareUpperToRational('0', '1') < 0) {
            return $countOnly ? 0 : [];
        }
        $level = $inverseLevel->multiply($inverseLevel);
        if (\count($numerator) > 2 || \count($denominator) > 2) {
            return $this->isolateQuadraticRationalGammaHalfShapeRoots(
                $numerator,
                $denominator,
                $level,
                $lower,
                $upper,
                $maximumWidth,
                $countOnly,
            );
        }
        $numeratorIntercept = new ExactRationalInterval($numerator[0], $numerator[0]);
        $numeratorSlope = new ExactRationalInterval($numerator[1] ?? ['0', '1'], $numerator[1] ?? ['0', '1']);
        $denominatorIntercept = new ExactRationalInterval($denominator[0], $denominator[0]);
        $denominatorSlope = new ExactRationalInterval($denominator[1] ?? ['0', '1'], $denominator[1] ?? ['0', '1']);
        $rootDenominator = $numeratorSlope->subtract($level->multiply($denominatorSlope));
        if ($rootDenominator->containsZero()) {
            return null;
        }
        $root = $level->multiply($denominatorIntercept)
            ->subtract($numeratorIntercept)
            ->divide($rootDenominator);
        if (
            $root->compareUpperToRational($lower[0], $lower[1]) <= 0
            || $root->compareLowerToRational($upper[0], $upper[1]) >= 0
        ) {
            return $countOnly ? 0 : [];
        }
        if (
            $root->compareLowerToRational($lower[0], $lower[1]) <= 0
            || $root->compareUpperToRational($upper[0], $upper[1]) >= 0
            || $root->subtract(new ExactRationalInterval($root->lower, $root->lower))
                ->compareUpperToRational($maximumWidth[0], $maximumWidth[1]) > 0
        ) {
            return null;
        }
        $denominatorAtRoot = $denominatorIntercept->add($denominatorSlope->multiply($root));
        if ($denominatorAtRoot->containsZero()) {
            return null;
        }
        if ($countOnly) {
            return 1;
        }

        return [new RationalRootInterval(
            $root->lower[0],
            $root->lower[1],
            $root->upper[0],
            $root->upper[1],
        )];
    }

    /**
     * @param list<array{string, string}> $numerator
     * @param list<array{string, string}> $denominator
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @param array{string, string} $maximumWidth
     * @return list<RationalRootInterval>|int|null
     */
    private function isolateQuadraticRationalGammaHalfShapeRoots(
        array $numerator,
        array $denominator,
        ExactRationalInterval $level,
        array $lower,
        array $upper,
        array $maximumWidth,
        bool $countOnly,
    ): array|int|null {
        $quadratic = $this->rationalPolynomialCoefficientInterval($numerator, 2)
            ->subtract($level->multiply($this->rationalPolynomialCoefficientInterval($denominator, 2)));
        $linear = $this->rationalPolynomialCoefficientInterval($numerator, 1)
            ->subtract($level->multiply($this->rationalPolynomialCoefficientInterval($denominator, 1)));
        $constant = $this->rationalPolynomialCoefficientInterval($numerator, 0)
            ->subtract($level->multiply($this->rationalPolynomialCoefficientInterval($denominator, 0)));
        if ($quadratic->containsZero()) {
            return null;
        }
        $four = new ExactRationalInterval(['4', '1'], ['4', '1']);
        $twoQuadratic = $quadratic->multiply(new ExactRationalInterval(['2', '1'], ['2', '1']));
        $discriminant = $linear->multiply($linear)->subtract($four->multiply($quadratic)->multiply($constant));
        if ($discriminant->compareUpperToRational('0', '1') < 0) {
            return $countOnly ? 0 : [];
        }
        if ($discriminant->compareLowerToRational('0', '1') <= 0) {
            return null;
        }

        $squareRoot = $discriminant->sqrt(40);
        $negativeLinear = $linear->negateInterval();
        $rootCandidates = [
            $negativeLinear->subtract($squareRoot)->divide($twoQuadratic),
            $negativeLinear->add($squareRoot)->divide($twoQuadratic),
        ];
        usort($rootCandidates, fn (ExactRationalInterval $leftRoot, ExactRationalInterval $rightRoot): int =>
            $leftRoot->compareLowerEndpoint($rightRoot));

        $roots = [];
        foreach ($rootCandidates as $candidate) {
            if (
                $candidate->compareUpperToRational($lower[0], $lower[1]) <= 0
                || $candidate->compareLowerToRational($upper[0], $upper[1]) >= 0
            ) {
                continue;
            }
            if (
                $candidate->compareLowerToRational($lower[0], $lower[1]) <= 0
                || $candidate->compareUpperToRational($upper[0], $upper[1]) >= 0
                || $candidate->subtract(new ExactRationalInterval($candidate->lower, $candidate->lower))
                    ->compareUpperToRational($maximumWidth[0], $maximumWidth[1]) > 0
            ) {
                return null;
            }
            $rootSquared = $candidate->multiply($candidate);
            $denominatorAtRoot = $this->rationalPolynomialCoefficientInterval($denominator, 0)
                ->add($this->rationalPolynomialCoefficientInterval($denominator, 1)->multiply($candidate))
                ->add($this->rationalPolynomialCoefficientInterval($denominator, 2)->multiply($rootSquared));
            if ($denominatorAtRoot->containsZero()) {
                return null;
            }
            $roots[] = new RationalRootInterval(
                $candidate->lower[0],
                $candidate->lower[1],
                $candidate->upper[0],
                $candidate->upper[1],
            );
        }
        if (
            \count($roots) === 2
            && $this->compareRationalFractions(
                [$roots[0]->upperNumerator, $roots[0]->upperDenominator],
                [$roots[1]->lowerNumerator, $roots[1]->lowerDenominator],
            ) >= 0
        ) {
            return null;
        }

        return $countOnly ? \count($roots) : $roots;
    }

    /** @param list<array{string, string}> $polynomial */
    private function rationalPolynomialCoefficientInterval(
        array $polynomial,
        int $degree,
    ): ExactRationalInterval {
        $coefficient = $polynomial[$degree] ?? ['0', '1'];

        return new ExactRationalInterval($coefficient, $coefficient);
    }

    /**
     * @param list<array{string, string}> $argument
     * @param array{string, string} $probability
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @param array{string, string} $maximumWidth
     * @return list<RationalRootInterval>|int|null
     */
    private function isolateRegularizedGammaHalfShapePolynomialRoots(
        string $function,
        array $argument,
        array $probability,
        array $lower,
        array $upper,
        array $maximumWidth,
        int $maxDepth,
        bool $countOnly,
    ): array|int|null {
        $target = new ExactRationalInterval($probability, $probability);
        if (
            $target->compareLowerToRational('0', '1') < 0
            || $target->compareUpperToRational('1', '1') > 0
        ) {
            return $countOnly ? 0 : [];
        }
        $boundaryProbability = $function === 'gammainc' ? ['0', '1'] : ['1', '1'];
        $noFiniteRootProbability = $function === 'gammainc' ? ['1', '1'] : ['0', '1'];
        if ($this->compareRationalFractions($probability, $noFiniteRootProbability) === 0) {
            return $countOnly ? 0 : [];
        }
        $integerArgument = $this->integerPolynomialFromRational($argument);
        if ($integerArgument === null) {
            return null;
        }
        if ($this->compareRationalFractions($probability, $boundaryProbability) === 0) {
            $exactRoots = (new ExactPolynomialRootCounter())->isolateOpenInterval(
                $integerArgument,
                $lower[0],
                $lower[1],
                $upper[0],
                $upper[1],
                $maxDepth,
                $maximumWidth,
            );
            if ($exactRoots === null) {
                return null;
            }

            return $countOnly
                ? \count($exactRoots)
                : $this->rationalRootIntervalsFromExactPolynomial($exactRoots);
        }

        $inverseLevel = $this->certifiedInverseErrorFunctionLevel(
            $function === 'gammainc' ? 'erf' : 'erfc',
            $probability,
        );
        if ($inverseLevel === null) {
            return null;
        }
        if ($inverseLevel->compareUpperToRational('0', '1') < 0) {
            return $countOnly ? 0 : [];
        }
        $level = $inverseLevel->multiply($inverseLevel);

        $arithmetic = new IntegerPolynomialExtractor('', []);
        $derivative = [];
        for ($degree = 1; $degree < \count($integerArgument); ++$degree) {
            $derivative[] = $arithmetic->multiplyIntegerValues(
                $integerArgument[$degree],
                (string) $degree,
            );
        }
        while (\count($derivative) > 1 && $derivative[\array_key_last($derivative)] === '0') {
            \array_pop($derivative);
        }
        if (\count($derivative) <= 1) {
            return null;
        }
        $derivativePolynomial = \array_map(
            static fn (string $coefficient): array => [$coefficient, '1'],
            $derivative,
        );
        $criticalPoints = (new ExactPolynomialRootCounter())->isolateOpenInterval(
            $derivative,
            $lower[0],
            $lower[1],
            $upper[0],
            $upper[1],
            min($maxDepth, 512),
            ['1', '1000000000000'],
        );
        if ($criticalPoints === null) {
            return null;
        }

        $roots = [];
        $rootCount = 0;
        $segmentLower = $lower;
        $segments = [];
        foreach (
            $criticalPoints as [
                $criticalLowerNumerator,
                $criticalLowerDenominator,
                $criticalUpperNumerator,
                $criticalUpperDenominator,
            ]
        ) {
            $criticalLower = [$criticalLowerNumerator, $criticalLowerDenominator];
            $criticalUpper = [$criticalUpperNumerator, $criticalUpperDenominator];
            $criticalRange = $this->evaluateRationalPolynomialOnInterval(
                $argument,
                new ExactRationalInterval($criticalLower, $criticalUpper),
            );
            if ($criticalRange === null || $this->polynomialLevelSign($criticalRange, $level) === null) {
                return null;
            }
            $segments[] = [$segmentLower, $criticalLower];
            $segmentLower = $criticalUpper;
        }
        $segments[] = [$segmentLower, $upper];

        foreach ($segments as [$segmentStart, $segmentEnd]) {
            if ($this->compareRationalFractions($segmentStart, $segmentEnd) >= 0) {
                continue;
            }
            $midpoint = (new ExactRationalInterval($segmentStart, $segmentStart))
                ->add(new ExactRationalInterval($segmentEnd, $segmentEnd))
                ->multiply(new ExactRationalInterval(['1', '2'], ['1', '2']))
                ->lower;
            $derivativeValue = $this->evaluateRationalPolynomialAt($derivativePolynomial, $midpoint);
            if ($derivativeValue === null) {
                return null;
            }
            $derivativeSign = $derivativeValue->compareLowerToRational('0', '1') > 0
                ? 1
                : ($derivativeValue->compareUpperToRational('0', '1') < 0 ? -1 : 0);
            if ($derivativeSign === 0) {
                return null;
            }
            if ($countOnly) {
                $startValue = $this->evaluateRationalPolynomialAt($argument, $segmentStart);
                $endValue = $this->evaluateRationalPolynomialAt($argument, $segmentEnd);
                if ($startValue === null || $endValue === null) {
                    return null;
                }
                $startSign = $this->compareIntervals($startValue, $level);
                $endSign = $this->compareIntervals($endValue, $level);
                if ($startSign === null || $endSign === null) {
                    return null;
                }
                $crosses = $derivativeSign > 0
                    ? $startSign < 0 && $endSign > 0
                    : $startSign > 0 && $endSign < 0;
                if ($crosses) {
                    ++$rootCount;
                }
                continue;
            }

            $segmentRoots = $this->isolateMonotonePolynomialLevelSegment(
                $argument,
                $level,
                $derivativeSign,
                $segmentStart,
                $segmentEnd,
                $maximumWidth,
                $maxDepth,
            );
            if ($segmentRoots === null) {
                return null;
            }
            array_push($roots, ...$segmentRoots);
        }

        if ($countOnly) {
            return $rootCount;
        }
        usort($roots, fn (RationalRootInterval $leftRoot, RationalRootInterval $rightRoot): int =>
            $this->compareRationalFractions(
                [$leftRoot->lowerNumerator, $leftRoot->lowerDenominator],
                [$rightRoot->lowerNumerator, $rightRoot->lowerDenominator],
            ));

        return $roots;
    }

    /**
     * Reduce shape-one gamma with a polynomial argument to exp(-u)=q.
     *
     * @param array<string, int|float> $parameters
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @param array{string, string} $maximumWidth
     * @return list<RationalRootInterval>|int|null
     */
    private function isolateRegularizedGammaShapeOnePolynomialArgument(
        FunctionCallNode $candidate,
        Node $target,
        int $argumentDegree,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        array $lower,
        array $upper,
        array $maximumWidth,
        int $maxDepth,
        bool $countOnly,
    ): array|int|null {
        $span = $candidate->span();
        $one = new NumberNode(1, '1', $span);
        $exponentialTarget = $candidate->name === 'gammainc'
            ? new BinaryOperationNode(BinaryOperator::Subtract, $one, $target, $span)
            : $target;
        $negativeArgument = new UnaryOperationNode(
            UnaryOperator::Minus,
            $candidate->arguments[1],
            $span,
        );
        $exponential = new FunctionCallNode('exp', [$negativeArgument], $candidate->nameSpan, $span);

        if ($countOnly) {
            if ($argumentDegree === 2) {
                return $this->countQuadraticExponentialRootsInInterval(
                    $exponential,
                    $exponentialTarget,
                    $variable,
                    $parameters,
                    $evaluationOptions,
                    $lower,
                    $upper,
                );
            }
            $roots = $this->isolateMonotonePolynomialExponentialRootsInInterval(
                $exponential,
                $exponentialTarget,
                $variable,
                $parameters,
                $evaluationOptions,
                $lower,
                $upper,
                ['1', '1000000'],
                256,
            );

            return $roots === null ? null : \count($roots);
        }

        if ($argumentDegree === 2) {
            return $this->isolateQuadraticExponentialRootsInInterval(
                $exponential,
                $exponentialTarget,
                $variable,
                $parameters,
                $evaluationOptions,
                $lower,
                $upper,
                $maximumWidth,
                $maxDepth,
            );
        }

        return $this->isolateMonotonePolynomialExponentialRootsInInterval(
            $exponential,
            $exponentialTarget,
            $variable,
            $parameters,
            $evaluationOptions,
            $lower,
            $upper,
            $maximumWidth,
            $maxDepth,
        );
    }

    /**
     * Isolate gamma levels composed with a polynomial by partitioning its monotone branches.
     *
     * @param array{string, string} $target
     * @param list<array{string, string}> $argument
     * @param array<string, int|float> $parameters
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @param array{string, string} $maximumWidth
     * @return list<RationalRootInterval>|int|null
     */
    private function isolateIntegerShapeRegularizedGammaPolynomialRoots(
        int $shape,
        array $target,
        array $argument,
        string $variable,
        array $parameters,
        array $lower,
        array $upper,
        array $maximumWidth,
        int $maxDepth,
        bool $countOnly,
    ): array|int|null {
        $derivative = $this->integerPolynomialFromRational(
            $this->differentiateRationalPolynomial($argument),
        );
        if ($derivative === null || \count($derivative) < 2) {
            return null;
        }
        $counter = new ExactPolynomialRootCounter();
        $criticalCount = $counter->countOpenInterval(
            $derivative,
            $lower[0],
            $lower[1],
            $upper[0],
            $upper[1],
        );
        if ($criticalCount === null) {
            return null;
        }
        $criticalWidth = $this->compareRationalFractions($maximumWidth, ['1', '1000000000000000000']) < 0
            ? $maximumWidth
            : ['1', '1000000000000000000'];
        $criticalRoots = $criticalCount === 0
            ? []
            : $counter->isolateOpenInterval(
                $derivative,
                $lower[0],
                $lower[1],
                $upper[0],
                $upper[1],
                $maxDepth,
                $criticalWidth,
            );
        if ($criticalRoots === null) {
            return null;
        }

        $roots = [];
        $cursor = $lower;
        $cursorSign = $this->compareRegularizedGammaPolynomialAt(
            $argument,
            $cursor,
            $shape,
            $target,
        );
        if ($cursorSign === null) {
            return null;
        }
        foreach (
            $criticalRoots as [
                $criticalLowerNumerator,
                $criticalLowerDenominator,
                $criticalUpperNumerator,
                $criticalUpperDenominator,
            ]
        ) {
            $criticalLower = [$criticalLowerNumerator, $criticalLowerDenominator];
            $criticalUpper = [$criticalUpperNumerator, $criticalUpperDenominator];
            $criticalRange = $this->evaluateRationalPolynomialOnInterval(
                $argument,
                new ExactRationalInterval($criticalLower, $criticalUpper),
            );
            if ($criticalRange === null) {
                return null;
            }
            $criticalSide = $this->compareRegularizedGammaPolynomialRangeToLevel(
                $criticalRange,
                $shape,
                $target,
            );
            if ($criticalSide === null) {
                return null;
            }

            if ($this->compareRationalFractions($cursor, $criticalLower) < 0) {
                $segmentRoots = $this->isolateRegularizedGammaPolynomialSegment(
                    $argument,
                    $shape,
                    $target,
                    $cursor,
                    $criticalLower,
                    $cursorSign,
                    $criticalSide,
                    $maximumWidth,
                    $maxDepth,
                );
                if ($segmentRoots === null) {
                    return null;
                }
                $roots = [...$roots, ...$segmentRoots];
            }
            $cursor = $criticalUpper;
            $cursorSign = $criticalSide;
        }

        if ($this->compareRationalFractions($cursor, $upper) < 0) {
            $upperSign = $this->compareRegularizedGammaPolynomialAt($argument, $upper, $shape, $target);
            if ($upperSign === null) {
                return null;
            }
            $segmentRoots = $this->isolateRegularizedGammaPolynomialSegment(
                $argument,
                $shape,
                $target,
                $cursor,
                $upper,
                $cursorSign,
                $upperSign,
                $maximumWidth,
                $maxDepth,
            );
            if ($segmentRoots === null) {
                return null;
            }
            $roots = [...$roots, ...$segmentRoots];
        }

        return $countOnly ? \count($roots) : $roots;
    }

    /**
     * Compare the gamma composite at a rational input with the requested level.
     * Negative polynomial arguments are treated as below the positive quantile.
     *
     * @param list<array{string, string}> $argument
     * @param array{string, string} $point
     * @param array{string, string} $target
     */
    private function compareRegularizedGammaPolynomialAt(
        array $argument,
        array $point,
        int $shape,
        array $target,
    ): ?int {
        $value = $this->evaluateRationalPolynomialAt($argument, $point);
        if ($value === null) {
            return null;
        }
        if ($value->compareUpperToRational('0', '1') < 0) {
            return -1;
        }
        $argumentValue = $value->lower;
        if ($this->compareRationalFractions($argumentValue, ['0', '1']) < 0) {
            return -1;
        }
        $tailComparison = $this->compareIntegerShapeGammaTail($argumentValue, $shape, $target);

        return $tailComparison === null ? null : -$tailComparison;
    }

    /**
     * Compare a polynomial range at a critical point with the inverse gamma level.
     *
     * @param array{string, string} $target
     */
    private function compareRegularizedGammaPolynomialRangeToLevel(
        ExactRationalInterval $range,
        int $shape,
        array $target,
    ): ?int {
        if ($range->compareUpperToRational('0', '1') < 0) {
            return -1;
        }
        $atUpper = $this->compareIntegerShapeGammaTail($range->upper, $shape, $target);
        if ($atUpper === null) {
            return null;
        }
        if ($atUpper > 0) {
            return -1;
        }
        if ($range->compareLowerToRational('0', '1') >= 0) {
            $atLower = $this->compareIntegerShapeGammaTail($range->lower, $shape, $target);
            if ($atLower === null) {
                return null;
            }
            if ($atLower < 0) {
                return 1;
            }
        }

        return null;
    }

    /**
     * Isolate at most one gamma-composite root on a polynomial monotonic segment.
     *
     * @param list<array{string, string}> $argument
     * @param array{string, string} $target
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @param array{string, string} $maximumWidth
     * @return list<RationalRootInterval>|null
     */
    private function isolateRegularizedGammaPolynomialSegment(
        array $argument,
        int $shape,
        array $target,
        array $lower,
        array $upper,
        int $lowerSign,
        int $upperSign,
        array $maximumWidth,
        int $maxDepth,
    ): ?array {
        if ($lowerSign === $upperSign) {
            return [];
        }
        if ($lowerSign === 0 || $upperSign === 0) {
            return null;
        }
        $low = $lower;
        $high = $upper;
        for ($iteration = 0; $iteration < $maxDepth; ++$iteration) {
            $width = (new ExactRationalInterval($high, $high))
                ->subtract(new ExactRationalInterval($low, $low));
            if ($width->compareUpperToRational($maximumWidth[0], $maximumWidth[1]) <= 0) {
                return [new RationalRootInterval($low[0], $low[1], $high[0], $high[1])];
            }
            $midpoint = (new ExactRationalInterval($low, $low))
                ->add(new ExactRationalInterval($high, $high))
                ->divide(new ExactRationalInterval(['2', '1'], ['2', '1']))
                ->lower;
            $midpointSign = $this->compareRegularizedGammaPolynomialAt($argument, $midpoint, $shape, $target);
            if ($midpointSign === null || $midpointSign === 0) {
                return null;
            }
            if ($midpointSign === $lowerSign) {
                $low = $midpoint;
                $lowerSign = $midpointSign;
            } else {
                $high = $midpoint;
                $upperSign = $midpointSign;
            }
        }

        return null;
    }

    /**
     * Count a monotone integer-shape gamma level from certified endpoint signs.
     *
     * @param array{string, string} $target
     * @param array{string, string} $slope
     * @param array{string, string} $intercept
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     */
    private function countIntegerShapeRegularizedGammaRoots(
        int $shape,
        array $target,
        array $slope,
        array $intercept,
        array $lower,
        array $upper,
    ): ?int {
        $slopeInterval = new ExactRationalInterval($slope, $slope);
        $interceptInterval = new ExactRationalInterval($intercept, $intercept);
        $zero = new ExactRationalInterval(['0', '1'], ['0', '1']);
        $zeroArgumentRoot = $zero->subtract($interceptInterval)->divide($slopeInterval)->lower;
        $domainLower = $lower;
        $domainUpper = $upper;
        if ($this->compareRationalFractions($slope, ['0', '1']) > 0) {
            if ($this->compareRationalFractions($zeroArgumentRoot, $upper) >= 0) {
                return 0;
            }
            if ($this->compareRationalFractions($zeroArgumentRoot, $lower) > 0) {
                $domainLower = $zeroArgumentRoot;
            }
        } else {
            if ($this->compareRationalFractions($zeroArgumentRoot, $lower) <= 0) {
                return 0;
            }
            if ($this->compareRationalFractions($zeroArgumentRoot, $upper) < 0) {
                $domainUpper = $zeroArgumentRoot;
            }
        }

        $domainStart = (new ExactRationalInterval($domainLower, $domainLower))
            ->multiply($slopeInterval)
            ->add($interceptInterval)
            ->lower;
        $domainEnd = (new ExactRationalInterval($domainUpper, $domainUpper))
            ->multiply($slopeInterval)
            ->add($interceptInterval)
            ->lower;
        $argumentLower = $this->compareRationalFractions($domainStart, $domainEnd) <= 0
            ? $domainStart
            : $domainEnd;
        $argumentUpper = $this->compareRationalFractions($domainStart, $domainEnd) <= 0
            ? $domainEnd
            : $domainStart;
        $lowerComparison = $this->compareIntegerShapeGammaTail($argumentLower, $shape, $target);
        $upperComparison = $this->compareIntegerShapeGammaTail($argumentUpper, $shape, $target);
        if ($lowerComparison === null || $upperComparison === null) {
            return null;
        }
        if ($lowerComparison === 0 || $upperComparison === 0) {
            return null;
        }

        return $lowerComparison > 0 && $upperComparison < 0 ? 1 : 0;
    }

    /**
     * Isolate a nontrivial integer-shape gamma level using its finite tail series.
     *
     * @param array{string, string} $target
     * @param array{string, string} $slope
     * @param array{string, string} $intercept
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @param array{string, string} $maximumWidth
     * @return list<RationalRootInterval>|null
     */
    private function isolateIntegerShapeRegularizedGammaRoot(
        int $shape,
        array $target,
        array $slope,
        array $intercept,
        array $lower,
        array $upper,
        array $maximumWidth,
        int $maxDepth,
    ): ?array {
        $slopeInterval = new ExactRationalInterval($slope, $slope);
        $interceptInterval = new ExactRationalInterval($intercept, $intercept);
        $zero = new ExactRationalInterval(['0', '1'], ['0', '1']);
        $zeroArgumentRoot = $zero->subtract($interceptInterval)->divide($slopeInterval)->lower;
        $domainLower = $lower;
        $domainUpper = $upper;
        if ($this->compareRationalFractions($slope, ['0', '1']) > 0) {
            if ($this->compareRationalFractions($zeroArgumentRoot, $upper) >= 0) {
                return [];
            }
            if ($this->compareRationalFractions($zeroArgumentRoot, $lower) > 0) {
                $domainLower = $zeroArgumentRoot;
            }
        } else {
            if ($this->compareRationalFractions($zeroArgumentRoot, $lower) <= 0) {
                return [];
            }
            if ($this->compareRationalFractions($zeroArgumentRoot, $upper) < 0) {
                $domainUpper = $zeroArgumentRoot;
            }
        }

        $domainStart = (new ExactRationalInterval($domainLower, $domainLower))
            ->multiply($slopeInterval)
            ->add($interceptInterval)
            ->lower;
        $domainEnd = (new ExactRationalInterval($domainUpper, $domainUpper))
            ->multiply($slopeInterval)
            ->add($interceptInterval)
            ->lower;
        $argumentLower = $this->compareRationalFractions($domainStart, $domainEnd) <= 0
            ? $domainStart
            : $domainEnd;
        $argumentUpper = $this->compareRationalFractions($domainStart, $domainEnd) <= 0
            ? $domainEnd
            : $domainStart;
        $lowerComparison = $this->compareIntegerShapeGammaTail($argumentLower, $shape, $target);
        $upperComparison = $this->compareIntegerShapeGammaTail($argumentUpper, $shape, $target);
        if ($lowerComparison === null || $upperComparison === null) {
            return null;
        }
        if ($lowerComparison < 0 || $upperComparison > 0) {
            return [];
        }
        if ($lowerComparison === 0 || $upperComparison === 0) {
            return null;
        }

        $maximumVariableWidth = new ExactRationalInterval(['0', '1'], $maximumWidth);
        for ($iteration = 0; $iteration < $maxDepth; ++$iteration) {
            $lowerX = (new ExactRationalInterval($argumentLower, $argumentLower))
                ->subtract($interceptInterval)
                ->divide($slopeInterval);
            $upperX = (new ExactRationalInterval($argumentUpper, $argumentUpper))
                ->subtract($interceptInterval)
                ->divide($slopeInterval);
            $variableLower = $this->compareRationalFractions($lowerX->lower, $upperX->lower) <= 0
                ? $lowerX->lower
                : $upperX->lower;
            $variableUpper = $this->compareRationalFractions($lowerX->upper, $upperX->upper) >= 0
                ? $lowerX->upper
                : $upperX->upper;
            $variableWidth = (new ExactRationalInterval($variableUpper, $variableUpper))
                ->subtract(new ExactRationalInterval($variableLower, $variableLower));
            if (
                $variableWidth->compareUpperToRational(
                    $maximumVariableWidth->upper[0],
                    $maximumVariableWidth->upper[1],
                ) <= 0
            ) {
                return [new RationalRootInterval(
                    $variableLower[0],
                    $variableLower[1],
                    $variableUpper[0],
                    $variableUpper[1],
                    false,
                )];
            }

            $midpoint = (new ExactRationalInterval($argumentLower, $argumentLower))
                ->add(new ExactRationalInterval($argumentUpper, $argumentUpper))
                ->divide(new ExactRationalInterval(['2', '1'], ['2', '1']))
                ->lower;
            $midpointComparison = $this->compareIntegerShapeGammaTail($midpoint, $shape, $target);
            if ($midpointComparison === null || $midpointComparison === 0) {
                return null;
            }
            if ($midpointComparison > 0) {
                $argumentLower = $midpoint;
            } else {
                $argumentUpper = $midpoint;
            }
        }

        return null;
    }

    /**
     * Compare the regularized upper incomplete gamma tail with a rational target.
     *
     * @param array{string, string} $argument
     * @param array{string, string} $target
     */
    private function compareIntegerShapeGammaTail(array $argument, int $shape, array $target): ?int
    {
        try {
            $point = new ExactRationalInterval($argument, $argument);
            $term = new ExactRationalInterval(['1', '1'], ['1', '1']);
            $sum = $term;
            for ($index = 1; $index < $shape; ++$index) {
                $term = $term
                    ->multiply($point)
                    ->divide(new ExactRationalInterval([(string) $index, '1'], [(string) $index, '1']));
                $sum = $sum->add($term);
            }
            $negativePoint = $point->multiply(new ExactRationalInterval(['-1', '1'], ['-1', '1']));
            $tail = $negativePoint->exp()->multiply($sum);
        } catch (\DomainException | \LengthException) {
            return null;
        }

        if ($tail->compareLowerToRational($target[0], $target[1]) > 0) {
            return 1;
        }
        if ($tail->compareUpperToRational($target[0], $target[1]) < 0) {
            return -1;
        }

        return null;
    }

    /**
     * Extract a polynomial equation for regularized beta with positive integer shapes.
     * The argument range must be certified to stay in the function's real domain.
     *
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @param array<string, int|float> $parameters
     * @return list<string>|null
     */
    private function regularizedBetaPolynomialInInterval(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        int $maxPolynomialDegree,
        array $lower,
        array $upper,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || !\in_array($candidate->name, ['betainc', 'betaincc'], true)
                || \count($candidate->arguments) !== 3
                || !$this->containsVariable($candidate->arguments[2], $variable)
            ) {
                continue;
            }
            $extractor = new ExactRationalPolynomialExtractor($variable, $parameters, $maxPolynomialDegree);
            $shapeParameters = [];
            foreach ([$candidate->arguments[0], $candidate->arguments[1]] as $shapeNode) {
                $shape = $extractor->polynomial($shapeNode);
                if (
                    $shape === null
                    || \count($shape) !== 1
                    || $shape[0][1] !== '1'
                    || \preg_match('/\A[1-9][0-9]*\z/D', $shape[0][0]) !== 1
                    || \strlen($shape[0][0]) > 3
                ) {
                    return null;
                }
                $shapeParameters[] = (int) $shape[0][0];
            }
            [$alpha, $beta] = $shapeParameters;
            if ($alpha + $beta - 1 > $maxPolynomialDegree) {
                return null;
            }
            $argumentForm = $extractor->rationalPolynomialForm($candidate->arguments[2]);
            if ($argumentForm === null) {
                return null;
            }
            $rangeBudget = 512;
            $domainRange = $this->regularizedBetaArgumentRange(
                $argumentForm,
                $lower,
                $upper,
                $rangeBudget,
            );
            if (
                $domainRange === null
                || $domainRange->compareLowerToRational('0', '1') < 0
                || $domainRange->compareUpperToRational('1', '1') > 0
            ) {
                return null;
            }

            $span = $candidate->span();
            $one = new NumberNode(1, '1', $span);
            $oneMinusArgument = new BinaryOperationNode(
                BinaryOperator::Subtract,
                $one,
                $candidate->arguments[2],
                $span,
            );
            $sum = null;
            $binomial = '1';
            $integerArithmetic = new IntegerPolynomialExtractor('', [], $maxPolynomialDegree);
            for ($power = 0; $power < $beta; ++$power) {
                if ($power > 0) {
                    $numerator = $integerArithmetic->multiplyIntegerValues(
                        $binomial,
                        (string) ($alpha + $power - 1),
                    );
                    $binomial = $integerArithmetic->divideIntegerValueExactly($numerator, (string) $power);
                    if ($binomial === null) {
                        return null;
                    }
                }
                $coefficient = new NumberNode((float) $binomial, $binomial, $span);
                $term = new BinaryOperationNode(
                    BinaryOperator::Multiply,
                    $coefficient,
                    $candidate->arguments[2],
                    $span,
                );
                $term = new BinaryOperationNode(
                    BinaryOperator::Multiply,
                    $term,
                    new BinaryOperationNode(
                        BinaryOperator::Power,
                        $candidate->arguments[2],
                        new NumberNode($alpha - 1, (string) ($alpha - 1), $span),
                        $span,
                    ),
                    $span,
                );
                if ($power > 0) {
                    $term = new BinaryOperationNode(
                        BinaryOperator::Multiply,
                        $term,
                        new BinaryOperationNode(
                            BinaryOperator::Power,
                            $oneMinusArgument,
                            new NumberNode($power, (string) $power, $span),
                            $span,
                        ),
                        $span,
                    );
                }
                $sum = $sum === null
                    ? $term
                    : new BinaryOperationNode(BinaryOperator::Add, $sum, $term, $span);
            }
            if ($sum === null) {
                return null;
            }
            if ($candidate->name === 'betaincc') {
                $sum = new BinaryOperationNode(BinaryOperator::Subtract, $one, $sum, $span);
            }
            $difference = $extractor->difference($sum, $target);

            return $difference;
        }

        return null;
    }

    /**
     * Certify that a rational beta argument stays in [0,1], subdividing to reduce interval overestimation.
     *
     * @param array{list<array{string, string}>, list<array{string, string}>} $form
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     */
    private function regularizedBetaArgumentRange(
        array $form,
        array $lower,
        array $upper,
        int &$remainingSubdivisions,
        int $depth = 0,
    ): ?ExactRationalInterval {
        if ($remainingSubdivisions <= 0) {
            return null;
        }
        --$remainingSubdivisions;
        $range = $this->exactRationalFunctionRange($form, new ExactRationalInterval($lower, $upper));
        if ($range !== null) {
            if (
                $range->compareLowerToRational('0', '1') >= 0
                && $range->compareUpperToRational('1', '1') <= 0
            ) {
                return $range;
            }
            if (
                $range->compareUpperToRational('0', '1') < 0
                || $range->compareLowerToRational('1', '1') > 0
            ) {
                return null;
            }
        }
        if ($depth >= 16) {
            return null;
        }

        $midpoint = (new ExactRationalInterval($lower, $lower))
            ->add(new ExactRationalInterval($upper, $upper))
            ->divide(new ExactRationalInterval(['2', '1'], ['2', '1']))
            ->lower;
        if (
            $this->compareRationalFractions($midpoint, $lower) <= 0
            || $this->compareRationalFractions($midpoint, $upper) >= 0
        ) {
            return null;
        }
        $leftRange = $this->regularizedBetaArgumentRange(
            $form,
            $lower,
            $midpoint,
            $remainingSubdivisions,
            $depth + 1,
        );
        if ($leftRange === null) {
            return null;
        }
        $rightRange = $this->regularizedBetaArgumentRange(
            $form,
            $midpoint,
            $upper,
            $remainingSubdivisions,
            $depth + 1,
        );
        if ($rightRange === null) {
            return null;
        }

        $rangeLower = $this->compareRationalFractions($leftRange->lower, $rightRange->lower) <= 0
            ? $leftRange->lower
            : $rightRange->lower;
        $rangeUpper = $this->compareRationalFractions($leftRange->upper, $rightRange->upper) >= 0
            ? $leftRange->upper
            : $rightRange->upper;

        return new ExactRationalInterval($rangeLower, $rangeUpper);
    }

    /** Prove whether a rational-function sum reaches any supported beta zero level. */
    private function hasDefinedBetaZeroSumLevel(
        ExactRationalPolynomialExtractor $extractor,
        Node $sum,
    ): ?bool {
        $counter = new ExactPolynomialRootCounter();
        $sumForm = $extractor->rationalPolynomialForm($sum);
        if ($sumForm === null) {
            return null;
        }
        $numerator = $extractor->integerCoefficients($sumForm[0]);
        $denominator = $extractor->integerCoefficients($sumForm[1]);
        if ($numerator === null || $denominator === null) {
            return null;
        }
        $numeratorRootCount = $counter->countAllRealRoots($numerator);
        $denominatorRootCount = $counter->countAllRealRoots($denominator);
        if ($numeratorRootCount === null || $denominatorRootCount === null) {
            return null;
        }
        if (
            $numeratorRootCount === 0
            && $denominatorRootCount === 0
            && (($numerator[0][0] === '-') === ($denominator[0][0] === '-'))
        ) {
            return false;
        }

        for ($integerLevel = 0; $integerLevel <= 342; ++$integerLevel) {
            $level = $extractor->rationalDifferenceFromFraction(
                $sum,
                [(string) -$integerLevel, '1'],
            );
            if ($level === null) {
                return null;
            }
            $rootCount = $counter->countAllRealRoots($level[0]);
            $holeCount = $counter->countCommonRealRoots($level[0], $level[1]);
            if ($rootCount === null || $holeCount === null) {
                return null;
            }
            if ($rootCount > $holeCount) {
                return true;
            }
        }

        return false;
    }

    /**
     * Isolate beta zero levels when both varying arguments are polynomials.
     *
     * @param array<string, int|float> $parameters
     * @param array{string, string}|null $lower
     * @param array{string, string}|null $upper
     * @param array{string, string} $width
     * @return list<RationalRootInterval>|null
     */
    private function isolateRationalBetaVariableLevels(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        int $maxPolynomialDegree,
        ?array $lower,
        ?array $upper,
        int $maxDepth,
        array $width,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || $candidate->name !== 'beta'
                || \count($candidate->arguments) !== 2
                || !$this->containsVariable($candidate->arguments[0], $variable)
                || !$this->containsVariable($candidate->arguments[1], $variable)
            ) {
                continue;
            }
            $extractor = new ExactRationalPolynomialExtractor($variable, $parameters, $maxPolynomialDegree);
            $targetPolynomial = $extractor->polynomial($target);
            $firstArgument = $extractor->rationalPolynomialForm($candidate->arguments[0]);
            $secondArgument = $extractor->rationalPolynomialForm($candidate->arguments[1]);
            if (
                $targetPolynomial === null
                || \count($targetPolynomial) !== 1
                || $targetPolynomial[0][0] !== '0'
                || $firstArgument === null
                || $secondArgument === null
            ) {
                return null;
            }
            $sum = new BinaryOperationNode(
                BinaryOperator::Add,
                $candidate->arguments[0],
                $candidate->arguments[1],
                $candidate->span(),
            );
            $counter = new ExactPolynomialRootCounter();
            $intervals = [];
            for ($integerLevel = 0; $integerLevel <= 342; ++$integerLevel) {
                $level = $extractor->rationalDifferenceFromFraction(
                    $sum,
                    [(string) -$integerLevel, '1'],
                );
                if ($level === null) {
                    return null;
                }
                if ($this->isZeroCoefficientList($level[0])) {
                    return null;
                }
                if (\count($level[0]) === 1) {
                    continue;
                }
                $roots = $lower === null || $upper === null
                    ? $counter->isolateAllRealRoots($level[0], $maxDepth, $width)
                    : $counter->isolateOpenInterval(
                        $level[0],
                        $lower[0],
                        $lower[1],
                        $upper[0],
                        $upper[1],
                        $maxDepth,
                        $width,
                    );
                if ($roots === null) {
                    return null;
                }
                $roots = $this->excludeCommonDenominatorRoots($counter, $level[0], $level[1], $roots);
                if ($roots === null) {
                    return null;
                }
                foreach ($roots as $root) {
                    $isDefined = true;
                    $refinementCount = 0;
                    $argumentRanges = [];
                    while (true) {
                        $rootInterval = new ExactRationalInterval(
                            [$root[0], $root[1]],
                            [$root[2], $root[3]],
                        );
                        $isExact = $root[0] === $root[2] && $root[1] === $root[3];
                        $argumentRanges = [];
                        $needsRefinement = false;
                        foreach ([$firstArgument, $secondArgument] as $argument) {
                            $denominatorRange = $this->exactRationalPolynomialRange($argument[1], $rootInterval);
                            if ($denominatorRange->containsZero()) {
                                if ($isExact) {
                                    $isDefined = false;
                                    break;
                                }
                                $denominator = $extractor->integerCoefficients($argument[1]);
                                if ($denominator === null) {
                                    return null;
                                }
                                $commonFactor = $counter->greatestCommonDivisor($level[0], $denominator);
                                if ($commonFactor === null) {
                                    return null;
                                }
                                $commonRoots = \count($commonFactor) < 2
                                    ? 0
                                    : $counter->countOpenInterval(
                                        $commonFactor,
                                        $root[0],
                                        $root[1],
                                        $root[2],
                                        $root[3],
                                    );
                                if ($commonRoots === null) {
                                    return null;
                                }
                                if ($commonRoots > 0) {
                                    $isDefined = false;
                                    break;
                                }
                                $needsRefinement = true;
                                break;
                            }
                            $argumentRange = $this->exactRationalFunctionRange($argument, $rootInterval);
                            if ($argumentRange === null) {
                                return null;
                            }
                            if (
                                $argumentRange->compareUpperToRational('-171', '1') < 0
                                || $argumentRange->compareLowerToRational('171', '1') > 0
                            ) {
                                $isDefined = false;
                                break;
                            }
                            if (
                                $argumentRange->compareLowerToRational('-171', '1') < 0
                                || $argumentRange->compareUpperToRational('171', '1') > 0
                            ) {
                                $needsRefinement = true;
                                break;
                            }
                            $argumentRanges[] = $argumentRange;
                        }
                        if (!$isDefined || !$needsRefinement) {
                            break;
                        }
                        if ($isExact || $refinementCount >= 32) {
                            return null;
                        }
                        $rootWidth = (new ExactRationalInterval(
                            [$root[2], $root[3]],
                            [$root[2], $root[3]],
                        ))->subtract(new ExactRationalInterval(
                            [$root[0], $root[1]],
                            [$root[0], $root[1]],
                        ));
                        $halfWidth = $rootWidth->divide(new ExactRationalInterval(['2', '1'], ['2', '1']))->lower;
                        $refinedRoots = $counter->isolateOpenInterval(
                            $level[0],
                            $root[0],
                            $root[1],
                            $root[2],
                            $root[3],
                            \max($maxDepth, 256),
                            $halfWidth,
                        );
                        if ($refinedRoots === null || \count($refinedRoots) !== 1) {
                            return null;
                        }
                        $root = $refinedRoots[0];
                        ++$refinementCount;
                    }
                    if ($isDefined) {
                        if (\count($argumentRanges) !== 2) {
                            return null;
                        }
                        foreach (
                            [
                                [$firstArgument, $candidate->arguments[0]],
                                [$secondArgument, $candidate->arguments[1]],
                            ] as $index => [$argument, $argumentNode]
                        ) {
                            if ($isExact) {
                                if ($this->isNonpositiveInteger($argumentRanges[$index]->lower)) {
                                    $isDefined = false;
                                    break;
                                }
                                continue;
                            }
                            for ($poleLevel = 0; $poleLevel <= 171; ++$poleLevel) {
                                $poleValue = [(string) -$poleLevel, '1'];
                                if (!$argumentRanges[$index]->containsRational($poleValue[0], $poleValue[1])) {
                                    continue;
                                }
                                $poleEquation = $extractor->rationalDifferenceFromFraction($argumentNode, $poleValue);
                                if ($poleEquation === null) {
                                    return null;
                                }
                                $commonFactor = $counter->greatestCommonDivisor($level[0], $poleEquation[0]);
                                if ($commonFactor === null) {
                                    return null;
                                }
                                if (\count($commonFactor) < 2) {
                                    continue;
                                }
                                $commonRoots = $counter->countOpenInterval(
                                    $commonFactor,
                                    $root[0],
                                    $root[1],
                                    $root[2],
                                    $root[3],
                                );
                                if ($commonRoots === null) {
                                    return null;
                                }
                                if ($commonRoots > 0) {
                                    $isDefined = false;
                                    break 2;
                                }
                            }
                        }
                    }
                    if ($isDefined) {
                        $intervals[] = new RationalRootInterval(
                            $root[0],
                            $root[1],
                            $root[2],
                            $root[3],
                            $isExact,
                        );
                    }
                }
            }
            \usort($intervals, fn (RationalRootInterval $a, RationalRootInterval $b): int =>
                $this->compareRationalFractions(
                    [$a->lowerNumerator, $a->lowerDenominator],
                    [$b->lowerNumerator, $b->lowerDenominator],
                ));

            return $intervals;
        }

        return null;
    }

    /**
     * @param array{list<array{string, string}>, list<array{string, string}>} $form
     */
    private function exactRationalFunctionRange(array $form, ExactRationalInterval $argument): ?ExactRationalInterval
    {
        $numerator = $this->exactRationalPolynomialRange($form[0], $argument);
        $denominator = $this->exactRationalPolynomialRange($form[1], $argument);
        if ($denominator->containsZero()) {
            return null;
        }

        return $numerator->divide($denominator);
    }

    /** @param list<array{string, string}> $polynomial */
    private function exactRationalPolynomialRange(
        array $polynomial,
        ExactRationalInterval $argument,
    ): ExactRationalInterval {
        $value = new ExactRationalInterval(['0', '1'], ['0', '1']);
        for ($degree = \count($polynomial) - 1; $degree >= 0; --$degree) {
            $value = $value->multiply($argument)->add(
                new ExactRationalInterval($polynomial[$degree], $polynomial[$degree]),
            );
        }
        if ($argument->containsZero() && \count($polynomial) <= 33) {
            $powerBasis = $this->evaluatePowerBasisOnInterval($polynomial, $argument);
            $intersection = $value->intersect($powerBasis);
            if ($intersection !== null) {
                return $intersection;
            }
        }

        return $value;
    }

    /** @param list<array{list<string>, list<string>}> $polynomials */
    private function countBetaLevelPolynomials(array $polynomials): ?int
    {
        $counter = new ExactPolynomialRootCounter();
        $count = 0;
        foreach ($polynomials as $polynomial) {
            $levelCount = $counter->countAllRealRoots($polynomial[0]);
            $holeCount = $counter->countCommonRealRoots($polynomial[0], $polynomial[1]);
            if ($levelCount === null || $holeCount === null) {
                return null;
            }
            $count += $levelCount - $holeCount;
        }

        return $count;
    }

    /**
     * @param list<array{list<string>, list<string>}> $polynomials
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     */
    private function countBetaLevelPolynomialsInInterval(array $polynomials, array $lower, array $upper): ?int
    {
        $counter = new ExactPolynomialRootCounter();
        $count = 0;
        foreach ($polynomials as $polynomial) {
            $levelCount = $counter->countOpenInterval(
                $polynomial[0],
                $lower[0],
                $lower[1],
                $upper[0],
                $upper[1],
            );
            $commonFactor = $counter->greatestCommonDivisor($polynomial[0], $polynomial[1]);
            if ($levelCount === null || $commonFactor === null) {
                return null;
            }
            $holeCount = \count($commonFactor) < 2
                ? 0
                : $counter->countOpenInterval(
                    $commonFactor,
                    $lower[0],
                    $lower[1],
                    $upper[0],
                    $upper[1],
                );
            if ($holeCount === null) {
                return null;
            }
            $count += $levelCount - $holeCount;
        }

        return $count;
    }

    /**
     * @param list<array{list<string>, list<string>}> $polynomials
     * @param array{string, string} $width
     * @return list<RationalRootInterval>|null
     */
    private function isolateBetaLevelPolynomials(array $polynomials, int $maxDepth, array $width): ?array
    {
        $counter = new ExactPolynomialRootCounter();
        $intervals = [];
        foreach ($polynomials as $polynomial) {
            $roots = $counter->isolateAllRealRoots($polynomial[0], $maxDepth, $width);
            if ($roots === null) {
                return null;
            }
            $roots = $this->excludeCommonDenominatorRoots($counter, $polynomial[0], $polynomial[1], $roots);
            if ($roots === null) {
                return null;
            }
            foreach ($roots as [$lowerNumerator, $lowerDenominator, $upperNumerator, $upperDenominator]) {
                $intervals[] = new RationalRootInterval(
                    $lowerNumerator,
                    $lowerDenominator,
                    $upperNumerator,
                    $upperDenominator,
                    $lowerNumerator === $upperNumerator && $lowerDenominator === $upperDenominator,
                );
            }
        }
        \usort($intervals, fn (RationalRootInterval $a, RationalRootInterval $b): int =>
            $this->compareRationalFractions(
                [$a->lowerNumerator, $a->lowerDenominator],
                [$b->lowerNumerator, $b->lowerDenominator],
            ));

        return $intervals;
    }

    /**
     * @param list<array{list<string>, list<string>}> $polynomials
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @param array{string, string} $width
     * @return list<RationalRootInterval>|null
     */
    private function isolateBetaLevelPolynomialsInInterval(
        array $polynomials,
        array $lower,
        array $upper,
        int $maxDepth,
        array $width,
    ): ?array {
        $counter = new ExactPolynomialRootCounter();
        $intervals = [];
        foreach ($polynomials as $polynomial) {
            $roots = $counter->isolateOpenInterval(
                $polynomial[0],
                $lower[0],
                $lower[1],
                $upper[0],
                $upper[1],
                $maxDepth,
                $width,
            );
            if ($roots === null) {
                return null;
            }
            $roots = $this->excludeCommonDenominatorRoots($counter, $polynomial[0], $polynomial[1], $roots);
            if ($roots === null) {
                return null;
            }
            foreach ($roots as [$lowerNumerator, $lowerDenominator, $upperNumerator, $upperDenominator]) {
                $intervals[] = new RationalRootInterval(
                    $lowerNumerator,
                    $lowerDenominator,
                    $upperNumerator,
                    $upperDenominator,
                    $lowerNumerator === $upperNumerator && $lowerDenominator === $upperDenominator,
                );
            }
        }
        \usort($intervals, fn (RationalRootInterval $a, RationalRootInterval $b): int =>
            $this->compareRationalFractions(
                [$a->lowerNumerator, $a->lowerDenominator],
                [$b->lowerNumerator, $b->lowerDenominator],
            ));

        return $intervals;
    }

    /**
     * @param array<string, int|float> $parameters
     * @param array{string, string}|null $witnessLower
     * @param array{string, string}|null $witnessUpper
     * @return list<array{string, string}>|null Null means this beta shape is unsupported.
     */
    private function exactBetaZeroRoots(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        int $maxPolynomialDegree,
        ?array $witnessLower = null,
        ?array $witnessUpper = null,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || $candidate->name !== 'beta'
                || \count($candidate->arguments) !== 2
            ) {
                continue;
            }
            $extractor = new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
            );
            $targetPolynomial = $extractor->polynomial($target);
            if ($targetPolynomial === null || \count($targetPolynomial) !== 1 || $targetPolynomial[0][0] !== '0') {
                continue;
            }
            $argumentForms = [];
            foreach ($candidate->arguments as $argument) {
                $form = $extractor->rationalPolynomialForm($argument);
                if ($form === null) {
                    $argumentForms = [];
                    break;
                }
                $argumentForms[] = $form;
            }
            if (\count($argumentForms) === 2) {
                $sumNode = new BinaryOperationNode(
                    BinaryOperator::Add,
                    $candidate->arguments[0],
                    $candidate->arguments[1],
                    $candidate->span(),
                );
                $sumForm = $extractor->rationalPolynomialForm($sumNode);
                $sum = $sumForm === null
                    ? null
                    : $this->constantRationalFunctionValue($sumForm[0], $sumForm[1]);
                if ($sum !== null) {
                    if (!$this->isNonpositiveInteger($sum)) {
                        return [];
                    }
                    $minimumSupportedSum = $this->compareRationalFractions($sum, ['-342', '1']);
                    if ($minimumSupportedSum < 0 || $minimumSupportedSum === 0) {
                        return [];
                    }
                    if (
                        $this->hasSupportedBetaRationalWitness(
                            $argumentForms,
                            $witnessLower,
                            $witnessUpper,
                            $sum,
                        )
                    ) {
                        throw new InfiniteSolutionSetException(
                            'The beta equation has infinitely many roots: its rational-function arguments sum to '
                            . 'a nonpositive integer.',
                        );
                    }
                } elseif ($this->hasDefinedBetaZeroSumLevel($extractor, $sumNode) === false) {
                    return [];
                }
            }
            $forms = [];
            foreach ($candidate->arguments as $argument) {
                $polynomial = $extractor->polynomial($argument);
                if ($polynomial === null) {
                    return null;
                }
                while (\count($polynomial) > 1 && $polynomial[\array_key_last($polynomial)][0] === '0') {
                    \array_pop($polynomial);
                }
                if (\count($polynomial) > 2) {
                    return null;
                }
                $intercept = $polynomial[0] ?? ['0', '1'];
                $slope = $polynomial[1] ?? ['0', '1'];
                if (
                    !$this->isSupportedBetaCoefficient($intercept)
                    || ($slope[0] !== '0' && !$this->isSupportedBetaCoefficient($slope))
                ) {
                    return null;
                }
                $interceptInterval = new ExactRationalInterval($intercept, $intercept);
                if (
                    $interceptInterval->compareLowerToRational('-171', '1') < 0
                    || $interceptInterval->compareUpperToRational('171', '1') > 0
                ) {
                    return null;
                }
                $forms[] = [$slope, $intercept];
            }

            [$firstSlope, $firstIntercept] = $forms[0];
            [$secondSlope, $secondIntercept] = $forms[1];
            $slope = (new ExactRationalInterval($firstSlope, $firstSlope))
                ->add(new ExactRationalInterval($secondSlope, $secondSlope));
            $intercept = (new ExactRationalInterval($firstIntercept, $firstIntercept))
                ->add(new ExactRationalInterval($secondIntercept, $secondIntercept));
            $firstSlopeInterval = new ExactRationalInterval($firstSlope, $firstSlope);
            $firstInterceptInterval = new ExactRationalInterval($firstIntercept, $firstIntercept);
            $secondSlopeInterval = new ExactRationalInterval($secondSlope, $secondSlope);
            $secondInterceptInterval = new ExactRationalInterval($secondIntercept, $secondIntercept);

            if ($slope->containsZero()) {
                if (
                    ($firstSlope[0] !== '0' || $secondSlope[0] !== '0')
                    && $this->hasSupportedBetaRationalWitness(
                        $argumentForms,
                        $witnessLower,
                        $witnessUpper,
                        $intercept->lower,
                    )
                ) {
                    if ($this->isNonpositiveInteger($intercept->lower)) {
                        throw new InfiniteSolutionSetException(
                            'The beta equation has infinitely many roots: its arguments sum to a nonpositive integer.',
                        );
                    }

                    return [];
                }

                return null;
            }
            if (!$this->isSupportedBetaCoefficient($slope->lower)) {
                return null;
            }

            $roots = [];
            for ($integerLevel = 0; $integerLevel <= 342; ++$integerLevel) {
                $level = new ExactRationalInterval(
                    [(string) -$integerLevel, '1'],
                    [(string) -$integerLevel, '1'],
                );
                $root = $level
                    ->subtract($intercept)
                    ->divide($slope)
                    ->lower;
                $rootInterval = new ExactRationalInterval($root, $root);
                $firstArgument = $firstSlopeInterval->multiply($rootInterval)->add($firstInterceptInterval);
                $secondArgument = $secondSlopeInterval->multiply($rootInterval)->add($secondInterceptInterval);
                if (
                    $firstArgument->compareLowerToRational('-171', '1') < 0
                    || $firstArgument->compareUpperToRational('171', '1') > 0
                    || $secondArgument->compareLowerToRational('-171', '1') < 0
                    || $secondArgument->compareUpperToRational('171', '1') > 0
                    || $this->isNonpositiveInteger($firstArgument->lower)
                    || $this->isNonpositiveInteger($secondArgument->lower)
                ) {
                    continue;
                }
                $roots[] = $root;
            }
            \usort(
                $roots,
                fn (array $leftRoot, array $rightRoot): int => $this->compareRationalFractions(
                    $leftRoot,
                    $rightRoot,
                ),
            );

            return $roots;
        }

        return null;
    }

    /**
     * @param list<array{list<array{string, string}>, list<array{string, string}>}> $forms
     * @param array{string, string}|null $lower
     * @param array{string, string}|null $upper
     * @param array{string, string}|null $argumentSum
     */
    private function hasSupportedBetaRationalWitness(
        array $forms,
        ?array $lower = null,
        ?array $upper = null,
        ?array $argumentSum = null,
    ): bool {
        $points = [['0', '1']];
        for ($denominator = 1; $denominator <= 4; ++$denominator) {
            for ($numerator = -16; $numerator <= 16; ++$numerator) {
                $points[] = [(string) $numerator, (string) $denominator];
            }
        }
        foreach ($forms as [$polynomial, $denominatorPolynomial]) {
            while (\count($polynomial) > 1 && $polynomial[\array_key_last($polynomial)][0] === '0') {
                \array_pop($polynomial);
            }
            while (
                \count($denominatorPolynomial) > 1
                && $denominatorPolynomial[\array_key_last($denominatorPolynomial)][0] === '0'
            ) {
                \array_pop($denominatorPolynomial);
            }
            if (\count($polynomial) > 2 || \count($denominatorPolynomial) > 2) {
                continue;
            }
            $targets = [['1', '2'], ['-1', '2']];
            if ($argumentSum !== null) {
                $halfSum = (new ExactRationalInterval($argumentSum, $argumentSum))
                    ->divide(new ExactRationalInterval(['2', '1'], ['2', '1']));
                $half = new ExactRationalInterval(['1', '2'], ['1', '2']);
                $targets[] = $halfSum->lower;
                $targets[] = $halfSum->subtract($half)->lower;
                $targets[] = $halfSum->add($half)->lower;
            }
            foreach ($targets as $target) {
                $targetInterval = new ExactRationalInterval($target, $target);
                $constant = (new ExactRationalInterval($polynomial[0], $polynomial[0]))
                    ->subtract($targetInterval->multiply(
                        new ExactRationalInterval($denominatorPolynomial[0], $denominatorPolynomial[0]),
                    ));
                $slope = (new ExactRationalInterval($polynomial[1] ?? ['0', '1'], $polynomial[1] ?? ['0', '1']))
                    ->subtract($targetInterval->multiply(
                        new ExactRationalInterval(
                            $denominatorPolynomial[1] ?? ['0', '1'],
                            $denominatorPolynomial[1] ?? ['0', '1'],
                        ),
                    ));
                if ($slope->containsZero()) {
                    continue;
                }
                $point = $constant->negateInterval()->divide($slope);
                $points[] = $point->lower;
            }
        }

        foreach ($points as $point) {
            if (
                ($lower !== null && $this->compareRationalFractions($point, $lower) <= 0)
                || ($upper !== null && $this->compareRationalFractions($point, $upper) >= 0)
            ) {
                continue;
            }
            $values = [];
            foreach ($forms as [$polynomial, $denominatorPolynomial]) {
                $numeratorValue = $this->evaluateExactRationalPolynomial($polynomial, $point);
                $denominatorValue = $this->evaluateExactRationalPolynomial($denominatorPolynomial, $point);
                if ($this->compareRationalFractions($denominatorValue, ['0', '1']) === 0) {
                    continue 2;
                }
                $value = (new ExactRationalInterval($numeratorValue, $numeratorValue))
                    ->divide(new ExactRationalInterval($denominatorValue, $denominatorValue))->lower;
                $interval = new ExactRationalInterval($value, $value);
                if (
                    $interval->compareLowerToRational('-171', '1') < 0
                    || $interval->compareUpperToRational('171', '1') > 0
                    || $this->isNonpositiveInteger($value)
                ) {
                    continue 2;
                }
                $values[] = $value;
            }
            if (\count($values) === 2) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param list<array{string, string}> $polynomial
     * @param array{string, string} $point
     * @return array{string, string}
     */
    private function evaluateExactRationalPolynomial(array $polynomial, array $point): array
    {
        $pointInterval = new ExactRationalInterval($point, $point);
        $value = new ExactRationalInterval(['0', '1'], ['0', '1']);
        for ($degree = \count($polynomial) - 1; $degree >= 0; --$degree) {
            $value = $value->multiply($pointInterval)->add(
                new ExactRationalInterval($polynomial[$degree], $polynomial[$degree]),
            );
        }

        return $value->lower;
    }

    /** @param array{string, string} $value */
    private function isNonpositiveInteger(array $value): bool
    {
        return $value[1] === '1'
            && (new ExactRationalInterval($value, $value))->compareLowerToRational('0', '1') <= 0;
    }

    /** @param array{string, string} $value */
    private function isSupportedBetaCoefficient(array $value): bool
    {
        if (
            \preg_match('/\\A-?(?:0|[1-9][0-9]*)\\z/D', $value[0]) !== 1
            || \preg_match('/\\A(?:[1-9][0-9]*)\\z/D', $value[1]) !== 1
            || \strlen(\ltrim($value[0], '-')) > 256
            || \strlen($value[1]) > 256
        ) {
            return false;
        }

        return true;
    }

    /** @param list<array{string, string}> $roots
     *  @return list<RationalRootInterval>
     */
    private function exactRootIntervals(array $roots): array
    {
        return \array_map(
            fn (array $root): RationalRootInterval => new RationalRootInterval(
                $root[0],
                $root[1],
                $root[0],
                $root[1],
                true,
            ),
            $roots,
        );
    }

    /**
     * @param list<array{string, string}> $roots
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     */
    private function countRationalRootsInOpenInterval(array $roots, array $lower, array $upper): int
    {
        $count = 0;
        foreach ($roots as $root) {
            if (
                $this->compareRationalFractions($root, $lower) > 0
                && $this->compareRationalFractions($root, $upper) < 0
            ) {
                ++$count;
            }
        }

        return $count;
    }

    /**
     * @return array{Node, array{string, string}}|false|null
     * False means a recognized function level has no real solution.
     */
    private function exactZeroLevelFunction(
        FunctionCallNode $call,
        ExactRationalPolynomialExtractor $extractor,
        EvaluationOptions $evaluationOptions,
    ): array|false|null {
        $argumentCount = \count($call->arguments);
        $zeroLevel = ['0', '1'];
        $unitLevel = ['1', '1'];

        if ($call->name === 'root') {
            $argument = $this->zeroLevelRootFunctionArgument($call, $extractor);

            return $argument instanceof Node ? [$argument, $zeroLevel] : $argument;
        }
        if (
            \in_array(
                $call->name,
                [
                    'exp', 'cosh', 'sech', 'sec', 'csc', 'erfc', 'erfcx', 'gamma', 'gammaincc',
                    'doublefactorial',
                    'csch', 'coth', 'acsch', 'acoth', 'acsc', 'acot',
                ],
                true,
            )
            && (
                $argumentCount === 1
                || ($call->name === 'gammaincc' && $argumentCount === 2)
            )
        ) {
            return false;
        }
        if ($call->name === 'gammainc' && $argumentCount === 2) {
            return $this->exactPositiveShapeParameters([$call->arguments[0]], $extractor)
                ? [$call->arguments[1], $zeroLevel]
                : null;
        }
        if ($call->name === 'gammaincinv' && $argumentCount === 2) {
            return $this->exactPositiveShapeParameters([$call->arguments[0]], $extractor)
                ? [$call->arguments[1], $zeroLevel]
                : null;
        }
        if ($call->name === 'gammainccinv' && $argumentCount === 2) {
            return $this->exactPositiveShapeParameters([$call->arguments[0]], $extractor)
                ? [$call->arguments[1], $unitLevel]
                : null;
        }
        if ($call->name === 'betainc' && $argumentCount === 3) {
            return $this->exactPositiveShapeParameters(
                [$call->arguments[0], $call->arguments[1]],
                $extractor,
            ) ? [$call->arguments[2], $zeroLevel] : null;
        }
        if ($call->name === 'betaincc' && $argumentCount === 3) {
            return $this->exactPositiveShapeParameters(
                [$call->arguments[0], $call->arguments[1]],
                $extractor,
            ) ? [$call->arguments[2], $unitLevel] : null;
        }
        if ($call->name === 'betaincinv' && $argumentCount === 3) {
            return $this->exactPositiveShapeParameters(
                [$call->arguments[0], $call->arguments[1]],
                $extractor,
            ) ? [$call->arguments[2], $zeroLevel] : null;
        }
        if ($call->name === 'betainccinv' && $argumentCount === 3) {
            return $this->exactPositiveShapeParameters(
                [$call->arguments[0], $call->arguments[1]],
                $extractor,
            ) ? [$call->arguments[2], $unitLevel] : null;
        }

        if ($call->name === 'log' && $argumentCount === 2) {
            $base = $this->exactConstantRational($call->arguments[1], $extractor);
            if ($base === null) {
                return null;
            }
            $baseInterval = new ExactRationalInterval($base, $base);
            if (
                $baseInterval->compareLowerToRational('0', '1') <= 0
                || $baseInterval->compareLowerToRational('1', '1') === 0
            ) {
                return null;
            }

            return [$call->arguments[0], $unitLevel];
        }

        if ($call->name === 'erfcinv' && $argumentCount === 1) {
            return [$call->arguments[0], ['2', '1']];
        }
        if ($call->name === 'erfinv' && $argumentCount === 1) {
            return [$call->arguments[0], $zeroLevel];
        }
        if (
            (($call->name === 'polygamma' && $argumentCount === 2)
                || (\in_array($call->name, ['trigamma', 'tetragamma'], true) && $argumentCount === 1))
            && $evaluationOptions->functions->isBuiltIn($call->name)
        ) {
            $order = match ($call->name) {
                'trigamma' => 1,
                'tetragamma' => 2,
                default => null,
            };
            $argumentIndex = 0;
            if ($call->name === 'polygamma') {
                $orderFraction = $this->exactConstantRational($call->arguments[0], $extractor);
                $order = $orderFraction !== null && $orderFraction[1] === '1'
                    ? \filter_var($orderFraction[0], FILTER_VALIDATE_INT)
                    : null;
                $argumentIndex = 1;
            }
            if (
                \is_int($order)
                && $order > 0
                && $order <= SpecialFunctions::MAX_POLYGAMMA_ORDER
            ) {
                $argument = $extractor->rationalFunction($call->arguments[$argumentIndex]);
                $numeratorSign = $argument === null
                    ? null
                    : $this->polynomialCertifiedGlobalSign($argument[0]);
                $denominatorSign = $argument === null
                    ? null
                    : $this->polynomialCertifiedGlobalSign($argument[1]);
                if ($numeratorSign !== null && $numeratorSign === $denominatorSign) {
                    return false;
                }
            }
        }
        if ($call->name === 'besseli' && $argumentCount === 2) {
            $order = $this->exactConstantRational($call->arguments[0], $extractor);
            if ($order === null || $order[1] !== '1') {
                return null;
            }
            $integerOrder = \filter_var($order[0], FILTER_VALIDATE_INT);
            if (!\is_int($integerOrder) || \abs($integerOrder) > SpecialFunctions::MAX_BESSEL_ORDER) {
                return null;
            }
            if ($integerOrder === 0) {
                return false;
            }

            return [$call->arguments[1], $zeroLevel];
        }
        if ($call->name === 'ln' || $call->name === 'log10' || $call->name === 'log2') {
            return $argumentCount === 1 ? [$call->arguments[0], $unitLevel] : null;
        }
        if (
            \in_array(
                $call->name,
                [
                    'sign', 'sqrt', 'cbrt', 'log1p', 'expm1', 'sinh', 'tanh', 'asinh', 'arcsinh',
                    'atan', 'arctan', 'asin', 'arcsin', 'atanh', 'arctanh', 'erf', 'erfi', 'dawson',
                ],
                true,
            )
            && $argumentCount === 1
        ) {
            return [$call->arguments[0], $zeroLevel];
        }
        if (
            \in_array($call->name, ['acos', 'arccos', 'acosh', 'arccosh', 'asec', 'asech'], true)
            && $argumentCount === 1
        ) {
            return [$call->arguments[0], $unitLevel];
        }
        if ($call->name === 'lambertw' && \in_array($argumentCount, [1, 2], true)) {
            if ($argumentCount === 1) {
                return [$call->arguments[0], $zeroLevel];
            }
            $branch = $this->exactConstantRational($call->arguments[1], $extractor);
            if ($branch === null) {
                return null;
            }
            $branchInterval = new ExactRationalInterval($branch, $branch);
            if ($branchInterval->compareLowerToRational('0', '1') === 0) {
                return [$call->arguments[0], $zeroLevel];
            }
            if ($branchInterval->compareLowerToRational('-1', '1') === 0) {
                return false;
            }
        }

        return null;
    }

    /**
     * Reduce ceil(Q(x)^(2k)) = 0 and floor(-Q(x)^(2k)) = 0 to Q(x) = 0.
     *
     * @param array<string, int|float> $parameters
     * @return list<string>|null Null means this form is unsupported.
     */
    private function roundingEvenPowerZeroPolynomial(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || !\in_array($candidate->name, ['floor', 'ceil'], true)
                || !$evaluationOptions->functions->isBuiltIn($candidate->name)
                || \count($candidate->arguments) !== 1
            ) {
                continue;
            }
            $extractor = new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            );
            $targetPolynomial = $extractor->polynomial($target);
            if ($targetPolynomial === null || \count($targetPolynomial) !== 1 || $targetPolynomial[0][0] !== '0') {
                continue;
            }

            $argument = $this->unwrapGrouping($candidate->arguments[0]);
            if ($candidate->name === 'floor' && $argument instanceof UnaryOperationNode) {
                if ($argument->operator !== UnaryOperator::Minus) {
                    continue;
                }
                $argument = $this->unwrapGrouping($argument->operand);
            } elseif ($candidate->name !== 'ceil') {
                continue;
            }
            if (!$argument instanceof BinaryOperationNode || $argument->operator !== BinaryOperator::Power) {
                continue;
            }
            $exponent = RationalLiteral::fromNode($argument->right);
            if (
                $exponent === null
                || $exponent[1] !== 1
                || $exponent[0] < 2
                || $exponent[0] % 2 !== 0
            ) {
                continue;
            }
            $base = $extractor->polynomial($argument->left);
            $coefficients = $base === null ? null : $extractor->integerCoefficients($base);
            if ($coefficients === null) {
                return null;
            }
            if ($this->isZeroCoefficientList($coefficients)) {
                throw new InfiniteSolutionSetException(
                    'The equation has infinitely many real solutions.',
                );
            }

            return $coefficients;
        }

        return null;
    }

    /**
     * Resolve the polynomial whose zero level forms a bounded rounding root set.
     *
     * @param array<string, int|float> $parameters
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @return list<string>|null Null means this shape is unsupported; an empty list means no roots.
     */
    private function roundingZeroPolynomialInInterval(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
        array $lower,
        array $upper,
    ): ?array {
        $squarePolynomial = $this->roundingEvenPowerZeroPolynomial(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            $maxPolynomialDegree,
        );
        if ($squarePolynomial !== null) {
            return $squarePolynomial;
        }

        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || !\in_array($candidate->name, ['floor', 'ceil', 'round', 'trunc'], true)
                || !$evaluationOptions->functions->isBuiltIn($candidate->name)
                || \count($candidate->arguments) !== 1
            ) {
                continue;
            }
            $extractor = new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            );
            $targetPolynomial = $extractor->polynomial($target);
            $polynomial = $extractor->polynomial($candidate->arguments[0]);
            if (
                $targetPolynomial === null
                || \count($targetPolynomial) !== 1
                || $targetPolynomial[0][0] !== '0'
                || $polynomial === null
            ) {
                continue;
            }
            while (\count($polynomial) > 1 && $polynomial[\array_key_last($polynomial)][0] === '0') {
                \array_pop($polynomial);
            }
            if (\count($polynomial) !== 3) {
                continue;
            }

            $lowerValue = $this->evaluateRationalPolynomialAt($polynomial, $lower);
            $upperValue = $this->evaluateRationalPolynomialAt($polynomial, $upper);
            if ($lowerValue === null || $upperValue === null) {
                return null;
            }
            $values = [$lowerValue, $upperValue];
            $quadratic = new ExactRationalInterval($polynomial[2], $polynomial[2]);
            $linear = new ExactRationalInterval($polynomial[1], $polynomial[1]);
            $vertex = $linear->negateInterval()->divide(
                $quadratic->multiply(new ExactRationalInterval(['2', '1'], ['2', '1'])),
            );
            if (
                $this->compareRationalFractions($vertex->lower, $lower) >= 0
                && $this->compareRationalFractions($vertex->lower, $upper) <= 0
            ) {
                $vertexValue = $this->evaluateRationalPolynomialAt($polynomial, $vertex->lower);
                if ($vertexValue === null) {
                    return null;
                }
                $values[] = $vertexValue;
            }
            $minimum = $values[0]->lower;
            $maximum = $values[0]->upper;
            foreach ($values as $value) {
                if ($this->compareRationalFractions($value->lower, $minimum) < 0) {
                    $minimum = $value->lower;
                }
                if ($this->compareRationalFractions($value->upper, $maximum) > 0) {
                    $maximum = $value->upper;
                }
            }
            [$upperBin, $lowerBin] = match ($candidate->name) {
                'floor' => [['1', '1'], ['0', '1']],
                'ceil' => [['0', '1'], ['-1', '1']],
                'round' => [['1', '2'], ['-1', '2']],
                'trunc' => [['1', '1'], ['-1', '1']],
            };
            if (
                (new ExactRationalInterval($maximum, $maximum))
                    ->compareLowerToRational($lowerBin[0], $lowerBin[1]) > 0
                && (new ExactRationalInterval($minimum, $minimum))
                    ->compareUpperToRational($upperBin[0], $upperBin[1]) < 0
            ) {
                throw new InfiniteSolutionSetException(
                    'The equation has infinitely many real solutions in the requested interval.',
                );
            }
            if (!\in_array($candidate->name, ['floor', 'ceil'], true)) {
                return [];
            }

            return $extractor->integerCoefficients($polynomial);
        }

        return null;
    }

    /**
     * Resolve quadratic rounding equations from the exact range of the parabola.
     *
     * @param array<string, int|float> $parameters
     * @return list<RationalRootInterval>|null Null means this shape is unsupported.
     */
    private function quadraticRoundingZeroRoots(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof FunctionCallNode
                || !\in_array($candidate->name, ['floor', 'ceil', 'round', 'trunc'], true)
                || !$evaluationOptions->functions->isBuiltIn($candidate->name)
                || \count($candidate->arguments) !== 1
            ) {
                continue;
            }
            $extractor = new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            );
            $targetPolynomial = $extractor->polynomial($target);
            $argumentPolynomial = $extractor->polynomial($candidate->arguments[0]);
            if (
                $targetPolynomial === null
                || \count($targetPolynomial) !== 1
                || $targetPolynomial[0][0] !== '0'
                || $argumentPolynomial === null
            ) {
                continue;
            }
            while (
                \count($argumentPolynomial) > 1
                && $argumentPolynomial[\array_key_last($argumentPolynomial)][0] === '0'
            ) {
                \array_pop($argumentPolynomial);
            }
            if (\count($argumentPolynomial) !== 3) {
                continue;
            }

            $constant = new ExactRationalInterval($argumentPolynomial[0], $argumentPolynomial[0]);
            $linear = new ExactRationalInterval($argumentPolynomial[1], $argumentPolynomial[1]);
            $quadratic = new ExactRationalInterval($argumentPolynomial[2], $argumentPolynomial[2]);
            $vertexValue = $constant->subtract(
                $linear->multiply($linear)->divide(
                    $quadratic->multiply(new ExactRationalInterval(['4', '1'], ['4', '1'])),
                ),
            );
            [$upperBound, $lowerBound] = match ($candidate->name) {
                'floor' => [['1', '1'], ['0', '1']],
                'ceil' => [['0', '1'], ['-1', '1']],
                'round' => [['1', '2'], ['-1', '2']],
                'trunc' => [['1', '1'], ['-1', '1']],
            };
            if (!\str_starts_with($argumentPolynomial[2][0], '-')) {
                if ($vertexValue->compareLowerToRational($upperBound[0], $upperBound[1]) < 0) {
                    throw new InfiniteSolutionSetException(
                        'The equation has infinitely many real solutions over the real line.',
                    );
                }
                if (
                    $candidate->name !== 'ceil'
                    || $vertexValue->compareLowerToRational('0', '1') !== 0
                ) {
                    return [];
                }
            } else {
                if ($vertexValue->compareUpperToRational($lowerBound[0], $lowerBound[1]) > 0) {
                    throw new InfiniteSolutionSetException(
                        'The equation has infinitely many real solutions over the real line.',
                    );
                }
                if (
                    $candidate->name !== 'floor'
                    || $vertexValue->compareUpperToRational('0', '1') !== 0
                ) {
                    return [];
                }
            }

            $vertex = $linear->negateInterval()->divide(
                $quadratic->multiply(new ExactRationalInterval(['2', '1'], ['2', '1'])),
            );

            return $this->exactRootIntervals([$vertex->lower]);
        }

        return null;
    }

    /**
     * @param array<string, int|float> $parameters
     */
    private function throwIfInfinitePolynomialZeroSet(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
    ): void {
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            $periodicFunction = $candidate instanceof FunctionCallNode
                && \in_array($candidate->name, ['sin', 'cos', 'tan', 'cot', 'sec', 'csc', 'sinc', 'sincpi'], true);
            $roundingFunction = $candidate instanceof FunctionCallNode
                && \in_array($candidate->name, ['floor', 'ceil', 'round', 'trunc'], true);
            if (
                !$candidate instanceof FunctionCallNode
                || (!$periodicFunction && !$roundingFunction)
                || \count($candidate->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($candidate->name)
            ) {
                continue;
            }
            if (!$this->constantTargetIsEvaluable($target, $variable, $parameters, $evaluationOptions)) {
                continue;
            }
            $extractor = new ExactRationalPolynomialExtractor(
                $variable,
                $parameters,
                $maxPolynomialDegree,
                $evaluationOptions,
            );
            $targetPolynomial = $extractor->polynomial($target);
            if ($targetPolynomial === null || \count($targetPolynomial) !== 1) {
                continue;
            }
            $targetLevel = $targetPolynomial[0];
            if ($roundingFunction && $targetLevel[0] !== '0') {
                continue;
            }
            $targetInterval = new ExactRationalInterval($targetLevel, $targetLevel);
            $periodicLevelHasInfiniteRoots = match ($candidate->name) {
                'sin', 'cos' => $targetInterval->compareLowerToRational('-1', '1') >= 0
                    && $targetInterval->compareUpperToRational('1', '1') <= 0,
                'sec', 'csc' => $targetInterval->compareUpperToRational('-1', '1') <= 0
                    || $targetInterval->compareLowerToRational('1', '1') >= 0,
                'tan', 'cot' => true,
                'sinc', 'sincpi' => $targetLevel[0] === '0',
                default => false,
            };
            if ($periodicFunction && !$periodicLevelHasInfiniteRoots) {
                continue;
            }
            $argumentPolynomial = $extractor->polynomial($candidate->arguments[0]);
            if (
                $argumentPolynomial === null
                || !$this->polynomialPhaseIsEvaluable(
                    $candidate->arguments[0],
                    $variable,
                    $parameters,
                    $evaluationOptions,
                )
            ) {
                continue;
            }
            while (
                \count($argumentPolynomial) > 1
                && $argumentPolynomial[\array_key_last($argumentPolynomial)][0] === '0'
            ) {
                \array_pop($argumentPolynomial);
            }
            $argumentDegree = \count($argumentPolynomial) - 1;
            if (
                ($periodicFunction && $argumentDegree > 0)
                || ($roundingFunction && $argumentDegree > 0 && $argumentDegree % 2 === 1)
            ) {
                throw new InfiniteSolutionSetException(
                    'The equation has infinitely many real solutions over the real line.',
                );
            }
        }
    }

    /** @param list<Node> $parameters */
    private function exactPositiveShapeParameters(
        array $parameters,
        ExactRationalPolynomialExtractor $extractor,
    ): bool {
        foreach ($parameters as $parameter) {
            $value = $this->exactConstantRational($parameter, $extractor);
            if ($value === null || (new ExactRationalInterval($value, $value))->compareLowerToRational('0', '1') <= 0) {
                return false;
            }
        }

        return true;
    }

    /** @return Node|false|null False means a negative root degree, which cannot produce zero. */
    private function zeroLevelRootFunctionArgument(
        FunctionCallNode $call,
        ExactRationalPolynomialExtractor $extractor,
    ): Node|false|null {
        if (\count($call->arguments) !== 2) {
            return null;
        }
        $degree = $this->exactRootFunctionDegree($call->arguments, $extractor);
        if ($degree === null) {
            return null;
        }
        if ($degree < 0) {
            return false;
        }

        return $call->arguments[0];
    }

    /** @return array{string, string}|null */
    private function exactConstantRational(
        Node $node,
        ExactRationalPolynomialExtractor $extractor,
    ): ?array {
        $polynomial = $extractor->polynomial($node);

        return $polynomial !== null && \count($polynomial) === 1 ? $polynomial[0] : null;
    }

    /**
     * Isolate equations of the form x = sqrt(a) +/- sqrt(b) over exact rationals.
     *
     * @param array<string, int|float> $parameters
     * @param array{array{string, string}, array{string, string}}|null $bounds
     * @param array{string, string} $maximumWidth
     * @return list<RationalRootInterval>|null
     */
    private function constantSquareRootSumRoots(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxDepth,
        array $maximumWidth,
        ?array $bounds,
    ): ?array {
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            256,
            $evaluationOptions,
        );
        $multiRoots = $this->constantSquareRootMultisumRoots(
            $left,
            $right,
            $variable,
            $parameters,
            $evaluationOptions,
            $maxDepth,
            $maximumWidth,
            $bounds,
            $extractor,
        );
        if ($multiRoots !== null && $multiRoots !== []) {
            return $multiRoots;
        }
        foreach ([[$left, $right], [$right, $left]] as [$variableNode, $sumNode]) {
            $affineVariable = $this->constantAffineVariable($variableNode, $variable, $extractor);
            $sumNode = $this->unwrapGrouping($sumNode);
            if (
                $affineVariable === null
                || !$sumNode instanceof BinaryOperationNode
                || !\in_array($sumNode->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)
            ) {
                continue;
            }
            $radicands = [];
            $signedTerms = [
                [$sumNode->left, 1],
                [$sumNode->right, $sumNode->operator === BinaryOperator::Add ? 1 : -1],
            ];
            foreach ($signedTerms as [$term, $sign]) {
                $term = $this->unwrapGrouping($term);
                $termSign = 1;
                if ($term instanceof UnaryOperationNode && $term->operator === UnaryOperator::Minus) {
                    $termSign = -1;
                    $term = $this->unwrapGrouping($term->operand);
                }
                $radicalTerm = $this->constantRationalSquareRootTerm($term, $extractor, $evaluationOptions);
                if ($radicalTerm === null) {
                    continue 2;
                }
                [$radicand, $coefficientSign] = $radicalTerm;
                if ($radicand[0][0] === '-') {
                    return [];
                }
                $radicands[] = [$radicand, $sign * $termSign * $coefficientSign];
            }
            [$first, $firstSign] = $radicands[0];
            [$second, $secondSign] = $radicands[1];
            $sum = $extractor->addExactFractions($first, $second);
            $negativeSecond = $second;
            $negativeSecond[0] = $negativeSecond[0] === '0' ? '0' : '-' . $negativeSecond[0];
            $difference = $extractor->addExactFractions($first, $negativeSecond);
            if ($sum === null || $difference === null) {
                return null;
            }
            $constant = $extractor->multiplyExactFractions($difference, $difference);
            $quadratic = $extractor->multiplyExactFractions($sum, ['-2', '1']);
            if ($constant === null || $quadratic === null) {
                return null;
            }
            $rootPolynomial = [
                $constant,
                ['0', '1'],
                $quadratic,
                ['0', '1'],
                ['1', '1'],
            ];
            $rationalPolynomial = $this->composeRationalPolynomialWithAffineTransform(
                $rootPolynomial,
                $affineVariable['slope'],
                $affineVariable['intercept'],
                $extractor,
            );
            if ($rationalPolynomial === null) {
                return null;
            }
            $polynomial = $extractor->integerCoefficients($rationalPolynomial);
            if ($polynomial === null) {
                return null;
            }
            $counter = new ExactPolynomialRootCounter();
            $rawRoots = $counter->isolateAllRealRoots($polynomial, $maxDepth, $maximumWidth);
            if ($rawRoots === null) {
                return null;
            }
            $roots = [];
            $sameSign = $firstSign === $secondSign;
            $expectedSign = $sameSign
                ? $firstSign
                : ($this->compareRationalFractions($difference, ['0', '1']) * $firstSign);
            foreach ($rawRoots as $root) {
                $rootInterval = new ExactRationalInterval([$root[0], $root[1]], [$root[2], $root[3]]);
                $value = $affineVariable['slope'] > 0
                    ? $rootInterval->add(new ExactRationalInterval(
                        $affineVariable['intercept'],
                        $affineVariable['intercept'],
                    ))
                    : $rootInterval->negateInterval()->add(new ExactRationalInterval(
                        $affineVariable['intercept'],
                        $affineVariable['intercept'],
                    ));
                $radicalValue = $value;
                $radicalSign = $radicalValue->compareLowerToRational('0', '1') > 0
                    ? 1
                    : ($radicalValue->compareUpperToRational('0', '1') < 0 ? -1 : 0);
                if ($sameSign && $expectedSign === $radicalSign) {
                    $squared = $radicalValue->multiply($radicalValue);
                    if ($squared->compareLowerToRational($sum[0], $sum[1]) <= 0) {
                        continue;
                    }
                } elseif (!$sameSign && $expectedSign !== 0 && $expectedSign === $radicalSign) {
                    $squared = $radicalValue->multiply($radicalValue);
                    if ($squared->compareUpperToRational($sum[0], $sum[1]) >= 0) {
                        continue;
                    }
                } else {
                    continue;
                }
                $roots[] = new RationalRootInterval(
                    $root[0],
                    $root[1],
                    $root[2],
                    $root[3],
                    $root[0] === $root[2] && $root[1] === $root[3],
                );
            }

            return $roots;
        }

        return $multiRoots;
    }

    /**
     * @param array<string, int|float> $parameters
     * @param array{string, string} $maximumWidth
     * @param array{array{string, string}, array{string, string}}|null $bounds
     * @return list<RationalRootInterval>|null
     */
    private function constantSquareRootMultisumRoots(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxDepth,
        array $maximumWidth,
        ?array $bounds,
        ExactRationalPolynomialExtractor $extractor,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$variableNode, $sumNode]) {
            $affineVariable = $this->constantAffineVariable($variableNode, $variable, $extractor);
            if ($affineVariable === null) {
                continue;
            }
            $constantOffset = ['0', '1'];
            $flattenedRadicals = $this->constantRationalSquareRootSumTerms(
                $sumNode,
                1,
                ['1', '1'],
                $constantOffset,
                $extractor,
                $evaluationOptions,
            );
            if ($flattenedRadicals === null) {
                continue;
            }
            if ($flattenedRadicals === false) {
                return [];
            }
            if ($constantOffset === null) {
                return null;
            }
            if (
                \count($flattenedRadicals) < 2
                && $constantOffset === ['0', '1']
            ) {
                continue;
            }
            $negativeOffset = (new ExactRationalInterval($constantOffset, $constantOffset))
                    ->negateInterval()->lower;
            $adjustedIntercept = $extractor->addExactFractions(
                $affineVariable['intercept'],
                $negativeOffset,
            );
            if ($adjustedIntercept === null) {
                return null;
            }
            $affineVariable['intercept'] = $adjustedIntercept;
            $radicals = [];
            foreach ($flattenedRadicals as [$scaledRadicand, $sign]) {
                if ($scaledRadicand[0][0] === '-') {
                    return [];
                }
                $rootValue = (new ExactRationalInterval($scaledRadicand, $scaledRadicand))->sqrt();
                if ($rootValue->lower === $rootValue->upper) {
                    $signedRoot = $sign > 0 ? $rootValue : $rootValue->negateInterval();
                    $offset = new ExactRationalInterval(
                        $affineVariable['intercept'],
                        $affineVariable['intercept'],
                    )->subtract($signedRoot);
                    $affineVariable['intercept'] = $offset->lower;
                    continue;
                }
                $radicals[] = [$scaledRadicand, $sign];
            }

            $radicals = $this->combineEquivalentConstantSquareRootTerms($radicals, $extractor);
            if ($radicals === null) {
                return null;
            }
            if ($radicals === []) {
                $root = $affineVariable['slope'] > 0
                    ? (new ExactRationalInterval($affineVariable['intercept'], $affineVariable['intercept']))
                        ->negateInterval()
                    : new ExactRationalInterval(
                        $affineVariable['intercept'],
                        $affineVariable['intercept'],
                    );
                return [new RationalRootInterval(
                    $root->lower[0],
                    $root->lower[1],
                    $root->upper[0],
                    $root->upper[1],
                    $root->lower === $root->upper,
                )];
            }
            $precision = \max(
                24,
                \strlen($maximumWidth[1])
                    - \strlen(\ltrim($maximumWidth[0], '-'))
                    + \strlen((string) \count($radicals))
                    + 1,
            );
            $precisionLimit = 4000;
            foreach ($radicals as [$radicand]) {
                $radicandDigits = \max(
                    \strlen(\ltrim($radicand[0], '-')),
                    \strlen($radicand[1]),
                );
                $precisionLimit = \min($precisionLimit, \intdiv(8191 - $radicandDigits, 2));
            }
            $targetValue = new ExactRationalInterval(['0', '1'], ['0', '1']);
            if ($precision > $precisionLimit) {
                if ($precisionLimit < 1) {
                    return null;
                }
                $fallbackPrecision = \min(24, $precisionLimit);
                foreach ($radicals as [$radicand, $sign]) {
                    $radicalInterval = (new ExactRationalInterval($radicand, $radicand))
                        ->sqrt($fallbackPrecision);
                    $targetValue = $sign > 0
                        ? $targetValue->add($radicalInterval)
                        : $targetValue->subtract($radicalInterval);
                }
            }
            for ($attempt = 0; $attempt < 16 && $precision <= $precisionLimit; ++$attempt) {
                $targetValue = new ExactRationalInterval(['0', '1'], ['0', '1']);
                foreach ($radicals as [$radicand, $sign]) {
                    $radicalInterval = (new ExactRationalInterval($radicand, $radicand))->sqrt($precision);
                    $targetValue = $sign > 0
                        ? $targetValue->add($radicalInterval)
                        : $targetValue->subtract($radicalInterval);
                }
                $rootValue = $targetValue->subtract(new ExactRationalInterval(
                    $affineVariable['intercept'],
                    $affineVariable['intercept'],
                ));
                if ($affineVariable['slope'] < 0) {
                    $rootValue = $rootValue->negateInterval();
                }
                $rootWidth = (new ExactRationalInterval($rootValue->upper, $rootValue->upper))
                    ->subtract(new ExactRationalInterval($rootValue->lower, $rootValue->lower))->lower;
                $insideBounds = $bounds === null
                    || $this->compareRationalFractions($rootValue->upper, $bounds[0]) <= 0
                    || $this->compareRationalFractions($rootValue->lower, $bounds[1]) >= 0
                    || (
                        $this->compareRationalFractions($rootValue->lower, $bounds[0]) > 0
                        && $this->compareRationalFractions($rootValue->upper, $bounds[1]) < 0
                    );
                if (
                    $insideBounds
                    && $this->compareRationalFractions($rootWidth, $maximumWidth) <= 0
                ) {
                    return [new RationalRootInterval(
                        $rootValue->lower[0],
                        $rootValue->lower[1],
                        $rootValue->upper[0],
                        $rootValue->upper[1],
                        false,
                    )];
                }
                $precision += \max(16, \intdiv($precision, 2));
            }
            if (\count($radicals) > 5) {
                continue;
            }

            $resultant = $this->exactSquareRootSumResultant(
                $radicals,
                $extractor,
                1 << \count($radicals),
            );
            if ($resultant === null) {
                return null;
            }
            $resultant = $this->composeRationalPolynomialWithAffineTransform(
                $resultant,
                $affineVariable['slope'],
                $affineVariable['intercept'],
                $extractor,
            );
            if ($resultant === null) {
                return null;
            }
            $polynomial = $extractor->integerCoefficients($resultant);
            if ($polynomial === null) {
                return null;
            }

            $counter = new ExactPolynomialRootCounter();
            $width = $maximumWidth;
            $arithmetic = new IntegerPolynomialExtractor('', []);
            for ($attempt = 0; $attempt < 8; ++$attempt) {
                $rawRoots = $counter->isolateAllRealRoots($polynomial, $maxDepth, $width);
                if ($rawRoots === null) {
                    return null;
                }
                $roots = [];
                $refine = false;
                foreach ($rawRoots as $root) {
                    $xInterval = new ExactRationalInterval([$root[0], $root[1]], [$root[2], $root[3]]);
                    $sumInterval = $affineVariable['slope'] > 0
                        ? $xInterval->add(new ExactRationalInterval(
                            $affineVariable['intercept'],
                            $affineVariable['intercept'],
                        ))
                        : $xInterval->negateInterval()->add(new ExactRationalInterval(
                            $affineVariable['intercept'],
                            $affineVariable['intercept'],
                        ));
                    $containsBranch = $this->compareRationalFractions(
                        $sumInterval->lower,
                        $targetValue->lower,
                    ) <= 0 && $this->compareRationalFractions(
                        $sumInterval->upper,
                        $targetValue->upper,
                    ) >= 0;
                    $disjointBranch = $this->compareRationalFractions(
                        $sumInterval->upper,
                        $targetValue->lower,
                    ) < 0 || $this->compareRationalFractions(
                        $sumInterval->lower,
                        $targetValue->upper,
                    ) > 0;
                    if (!$containsBranch && !$disjointBranch) {
                        $refine = true;
                        break;
                    }
                    if ($containsBranch) {
                        $roots[] = new RationalRootInterval(
                            $root[0],
                            $root[1],
                            $root[2],
                            $root[3],
                            $root[0] === $root[2] && $root[1] === $root[3],
                        );
                    }
                }
                if (!$refine) {
                    return $roots;
                }
                $width = [$width[0], $arithmetic->multiplyIntegerValues($width[1], '1000000')];
            }

            return null;
        }

        return null;
    }

    /**
     * @param array{string, string} $scale
     * @param array{string, string}|null $constantOffset
     * @return list<array{array{string, string}, int}>|false|null
     *         False indicates an explicitly negative square-root radicand.
     */
    private function constantRationalSquareRootSumTerms(
        Node $node,
        int $sign,
        array $scale,
        ?array &$constantOffset,
        ExactRationalPolynomialExtractor $extractor,
        EvaluationOptions $evaluationOptions,
    ): array|false|null {
        if ($constantOffset === null) {
            return null;
        }
        $node = $this->unwrapGrouping($node);
        if ($node instanceof UnaryOperationNode) {
            return $this->constantRationalSquareRootSumTerms(
                $node->operand,
                $node->operator === UnaryOperator::Minus ? -$sign : $sign,
                $scale,
                $constantOffset,
                $extractor,
                $evaluationOptions,
            );
        }
        if ($node instanceof FunctionCallNode && $node->name === 'sqrt' && \count($node->arguments) === 1) {
            if (!$evaluationOptions->functions->isBuiltIn('sqrt')) {
                return null;
            }
            $radicand = $this->exactConstantRational($node->arguments[0], $extractor);
            $scaleSquare = $extractor->multiplyExactFractions($scale, $scale);
            if ($radicand === null || $scaleSquare === null) {
                return null;
            }
            $scaledRadicand = $extractor->multiplyExactFractions($radicand, $scaleSquare);
            if ($scaledRadicand === null) {
                return null;
            }
            if ($scaledRadicand[0][0] === '-') {
                return false;
            }
            $scaleSign = $scale[0][0] === '-' ? -1 : 1;

            return [[$scaledRadicand, $sign * $scaleSign]];
        }
        $constant = $this->exactConstantRational($node, $extractor);
        if ($constant !== null) {
            $contribution = $extractor->multiplyExactFractions($scale, $constant);
            if ($contribution === null) {
                return null;
            }
            if ($sign < 0 && $contribution[0] !== '0') {
                $contribution[0] = $contribution[0][0] === '-'
                    ? \substr($contribution[0], 1)
                    : '-' . $contribution[0];
            }
            $constantOffset = $extractor->addExactFractions($constantOffset, $contribution);

            return $constantOffset === null ? null : [];
        }
        if (!$node instanceof BinaryOperationNode) {
            return null;
        }
        if ($node->operator === BinaryOperator::Add || $node->operator === BinaryOperator::Subtract) {
            $leftTerms = $this->constantRationalSquareRootSumTerms(
                $node->left,
                $sign,
                $scale,
                $constantOffset,
                $extractor,
                $evaluationOptions,
            );
            if ($leftTerms === null || $leftTerms === false) {
                return $leftTerms;
            }
            $rightTerms = $this->constantRationalSquareRootSumTerms(
                $node->right,
                $node->operator === BinaryOperator::Subtract ? -$sign : $sign,
                $scale,
                $constantOffset,
                $extractor,
                $evaluationOptions,
            );
            if ($rightTerms === null || $rightTerms === false) {
                return $rightTerms;
            }

            return [...$leftTerms, ...$rightTerms];
        }
        if ($node->operator === BinaryOperator::Multiply) {
            foreach ([[$node->left, $node->right], [$node->right, $node->left]] as [$constantNode, $scaledNode]) {
                $constant = $this->exactConstantRational($constantNode, $extractor);
                if ($constant === null) {
                    continue;
                }
                $scaled = $extractor->multiplyExactFractions($scale, $constant);

                return $scaled === null
                    ? null
                    : $this->constantRationalSquareRootSumTerms(
                        $scaledNode,
                        $sign,
                        $scaled,
                        $constantOffset,
                        $extractor,
                        $evaluationOptions,
                    );
            }

            return null;
        }
        if ($node->operator === BinaryOperator::Divide) {
            $denominator = $this->exactConstantRational($node->right, $extractor);
            if ($denominator === null || $denominator[0] === '0') {
                return null;
            }
            $reciprocal = (new ExactRationalInterval($denominator, $denominator))->reciprocal()->lower;
            $scaled = $extractor->multiplyExactFractions($scale, $reciprocal);

            return $scaled === null
                ? null
                : $this->constantRationalSquareRootSumTerms(
                    $node->left,
                    $sign,
                    $scaled,
                    $constantOffset,
                    $extractor,
                    $evaluationOptions,
                );
        }

        return null;
    }

    /**
     * @param list<array{array{string, string}, int}> $radicals
     * @return list<array{string, string}>|null
     */
    private function exactSquareRootSumResultant(
        array $radicals,
        ExactRationalPolynomialExtractor $extractor,
        int $maxDegree,
    ): ?array {
        $expression = [0 => [['0', '1'], ['1', '1']]];
        foreach ($radicals as $index => [, $sign]) {
            $expression[1 << $index] = [[(string) -$sign, '1']];
        }
        foreach ($radicals as $index => [$radicand]) {
            $mask = 1 << $index;
            $without = [];
            $with = [];
            foreach ($expression as $basis => $polynomial) {
                if (($basis & $mask) === 0) {
                    $without[$basis] = $polynomial;
                } else {
                    $with[$basis ^ $mask] = $polynomial;
                }
            }
            $withoutSquared = $this->multiplyExactMultiquadraticPolynomials(
                $without,
                $without,
                $radicals,
                $extractor,
                $maxDegree,
            );
            $withSquared = $this->multiplyExactMultiquadraticPolynomials(
                $with,
                $with,
                $radicals,
                $extractor,
                $maxDegree,
            );
            if ($withoutSquared === null || $withSquared === null) {
                return null;
            }
            $scaledWith = [];
            foreach ($withSquared as $basis => $polynomial) {
                $scaledPolynomial = $this->multiplyExactRationalPolynomials(
                    $polynomial,
                    [$radicand],
                    $extractor,
                    $maxDegree,
                );
                if ($scaledPolynomial === null) {
                    return null;
                }
                $scaledWith[$basis] = $scaledPolynomial;
            }
            $expression = $this->combineExactMultiquadraticPolynomials(
                $withoutSquared,
                $scaledWith,
                $extractor,
            );
            if ($expression === null) {
                return null;
            }
        }

        return $expression[0] ?? null;
    }

    /**
     * @param array<int, list<array{string, string}>> $left
     * @param array<int, list<array{string, string}>> $right
     * @param list<array{array{string, string}, int}> $radicals
     * @return array<int, list<array{string, string}>>|null
     */
    private function multiplyExactMultiquadraticPolynomials(
        array $left,
        array $right,
        array $radicals,
        ExactRationalPolynomialExtractor $extractor,
        int $maxDegree,
    ): ?array {
        $product = [];
        $commonRadicands = [];
        foreach ($left as $leftBasis => $leftPolynomial) {
            if ($this->isZeroExactRationalPolynomial($leftPolynomial)) {
                continue;
            }
            foreach ($right as $rightBasis => $rightPolynomial) {
                if ($this->isZeroExactRationalPolynomial($rightPolynomial)) {
                    continue;
                }
                $polynomial = $this->multiplyExactRationalPolynomials(
                    $leftPolynomial,
                    $rightPolynomial,
                    $extractor,
                    $maxDegree,
                );
                if ($polynomial === null) {
                    return null;
                }
                $common = $leftBasis & $rightBasis;
                if (!isset($commonRadicands[$common])) {
                    $commonRadicand = ['1', '1'];
                    foreach ($radicals as $index => [$radicand]) {
                        if (($common & (1 << $index)) === 0) {
                            continue;
                        }
                        $commonRadicand = $extractor->multiplyExactFractions($commonRadicand, $radicand);
                        if ($commonRadicand === null) {
                            return null;
                        }
                    }
                    $commonRadicands[$common] = $commonRadicand;
                }
                $commonRadicand = $commonRadicands[$common];
                if ($commonRadicand !== ['1', '1']) {
                    $polynomial = $this->scaleExactRationalPolynomial(
                        $polynomial,
                        $commonRadicand,
                        $extractor,
                    );
                    if ($polynomial === null) {
                        return null;
                    }
                }
                $basis = $leftBasis ^ $rightBasis;
                $sum = isset($product[$basis])
                    ? $this->addExactRationalPolynomials($product[$basis], $polynomial, $extractor, $maxDegree)
                    : $polynomial;
                if ($sum === null) {
                    return null;
                }
                $product[$basis] = $sum;
            }
        }

        foreach ($product as $basis => $polynomial) {
            if ($this->isZeroExactRationalPolynomial($polynomial)) {
                unset($product[$basis]);
            }
        }

        return $product;
    }

    /**
     * @param array<int, list<array{string, string}>> $left
     * @param array<int, list<array{string, string}>> $right
     * @return array<int, list<array{string, string}>>|null
     */
    private function combineExactMultiquadraticPolynomials(
        array $left,
        array $right,
        ExactRationalPolynomialExtractor $extractor,
    ): ?array {
        $combined = [];
        foreach (\array_unique([...\array_keys($left), ...\array_keys($right)]) as $basis) {
            $a = $left[$basis] ?? [['0', '1']];
            $b = $right[$basis] ?? [['0', '1']];
            foreach ($b as &$coefficient) {
                if ($coefficient[0] !== '0') {
                    $coefficient[0] = $coefficient[0][0] === '-'
                        ? \substr($coefficient[0], 1)
                        : '-' . $coefficient[0];
                }
            }
            unset($coefficient);
            $sum = $this->addExactRationalPolynomials($a, $b, $extractor, 256);
            if ($sum === null) {
                return null;
            }
            if ($this->isZeroExactRationalPolynomial($sum)) {
                unset($combined[$basis]);
            } else {
                $combined[$basis] = $sum;
            }
        }

        return $combined;
    }

    /** @param list<array{string, string}> $polynomial */
    private function isZeroExactRationalPolynomial(array $polynomial): bool
    {
        foreach ($polynomial as [$numerator]) {
            if ($numerator !== '0') {
                return false;
            }
        }

        return true;
    }

    /**
     * @param list<array{array{string, string}, int}> $radicals
     * @return list<array{array{string, string}, int}>|null
     */
    private function combineEquivalentConstantSquareRootTerms(
        array $radicals,
        ExactRationalPolynomialExtractor $extractor,
    ): ?array {
        $classes = [];
        $arithmetic = new IntegerPolynomialExtractor('', []);
        foreach ($radicals as [$radicand, $sign]) {
            $matched = false;
            foreach ($classes as &$class) {
                $ratio = $extractor->multiplyExactFractions(
                    $radicand,
                    [$class['radicand'][1], $class['radicand'][0]],
                );
                if ($ratio === null || \str_starts_with($ratio[0], '-')) {
                    continue;
                }
                $numeratorRoot = $arithmetic->integerSquareRoot($ratio[0]);
                $denominatorRoot = $arithmetic->integerSquareRoot($ratio[1]);
                if ($numeratorRoot === null || $denominatorRoot === null) {
                    continue;
                }
                if (
                    $arithmetic->multiplyIntegerValues($numeratorRoot, $numeratorRoot) !== $ratio[0]
                    || $arithmetic->multiplyIntegerValues($denominatorRoot, $denominatorRoot) !== $ratio[1]
                ) {
                    continue;
                }
                $scale = [$numeratorRoot, $denominatorRoot];
                if ($sign < 0) {
                    $scale[0] = $arithmetic->negateIntegerValue($scale[0]);
                }
                $combinedCoefficient = $extractor->addExactFractions($class['coefficient'], $scale);
                if ($combinedCoefficient === null) {
                    unset($class);
                    return null;
                }
                $class['coefficient'] = $combinedCoefficient;
                $matched = true;
                break;
            }
            unset($class);
            if (!$matched) {
                $classes[] = [
                    'radicand' => $radicand,
                    'coefficient' => [$sign < 0 ? '-1' : '1', '1'],
                ];
            }
        }

        $combined = [];
        foreach ($classes as ['radicand' => $radicand, 'coefficient' => $coefficient]) {
            if ($coefficient[0] === '0') {
                continue;
            }
            $coefficientSquare = $extractor->multiplyExactFractions($coefficient, $coefficient);
            $scaledRadicand = $coefficientSquare === null
                ? null
                : $extractor->multiplyExactFractions($radicand, $coefficientSquare);
            if ($scaledRadicand === null) {
                return null;
            }
            $combined[] = [$scaledRadicand, \str_starts_with($coefficient[0], '-') ? -1 : 1];
        }

        return $combined;
    }

    /**
     * @param list<array{string, string}> $left
     * @param list<array{string, string}> $right
     * @return list<array{string, string}>|null
     */
    private function multiplyExactRationalPolynomials(
        array $left,
        array $right,
        ExactRationalPolynomialExtractor $extractor,
        int $maxDegree,
    ): ?array {
        if ($left === [] || $right === []) {
            return null;
        }
        if (\count($left) === 1) {
            return $this->scaleExactRationalPolynomial($right, $left[0], $extractor);
        }
        if (\count($right) === 1) {
            return $this->scaleExactRationalPolynomial($left, $right[0], $extractor);
        }
        if (\count($left) + \count($right) - 2 > $maxDegree) {
            return null;
        }
        $product = \array_fill(0, \count($left) + \count($right) - 1, ['0', '1']);
        foreach ($left as $leftDegree => $leftCoefficient) {
            if ($leftCoefficient[0] === '0') {
                continue;
            }
            foreach ($right as $rightDegree => $rightCoefficient) {
                if ($rightCoefficient[0] === '0') {
                    continue;
                }
                $term = $extractor->multiplyExactFractions($leftCoefficient, $rightCoefficient);
                if ($term === null) {
                    return null;
                }
                $index = $leftDegree + $rightDegree;
                $sum = $extractor->addExactFractions($product[$index], $term);
                if ($sum === null) {
                    return null;
                }
                $product[$index] = $sum;
            }
        }

        return $product;
    }

    /**
     * @param list<array{string, string}> $polynomial
     * @param array{string, string} $factor
     * @return list<array{string, string}>|null
     */
    private function scaleExactRationalPolynomial(
        array $polynomial,
        array $factor,
        ExactRationalPolynomialExtractor $extractor,
    ): ?array {
        $scaled = [];
        foreach ($polynomial as $coefficient) {
            $scaledCoefficient = $coefficient[0] === '0'
                ? ['0', '1']
                : $extractor->multiplyExactFractions($coefficient, $factor);
            if ($scaledCoefficient === null) {
                return null;
            }
            $scaled[] = $scaledCoefficient;
        }

        return $scaled;
    }

    /**
     * @param list<array{string, string}> $left
     * @param list<array{string, string}> $right
     * @return list<array{string, string}>|null
     */
    private function addExactRationalPolynomials(
        array $left,
        array $right,
        ExactRationalPolynomialExtractor $extractor,
        int $maxDegree,
    ): ?array {
        $length = \max(\count($left), \count($right));
        if ($length - 1 > $maxDegree) {
            return null;
        }
        $sum = [];
        for ($degree = 0; $degree < $length; ++$degree) {
            $coefficient = $extractor->addExactFractions(
                $left[$degree] ?? ['0', '1'],
                $right[$degree] ?? ['0', '1'],
            );
            if ($coefficient === null) {
                return null;
            }
            $sum[] = $coefficient;
        }

        return $sum;
    }

    /** @return array{array{string, string}, int}|null */
    private function constantRationalSquareRootTerm(
        Node $node,
        ExactRationalPolynomialExtractor $extractor,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        $coefficient = ['1', '1'];
        if (
            $node instanceof BinaryOperationNode
            && \in_array($node->operator, [BinaryOperator::Multiply, BinaryOperator::Divide], true)
        ) {
            foreach ([[$node->left, $node->right], [$node->right, $node->left]] as [$coefficientNode, $rootNode]) {
                $candidateCoefficient = $this->exactConstantRational($coefficientNode, $extractor);
                $rootNode = $this->unwrapGrouping($rootNode);
                if (
                    $candidateCoefficient !== null
                    && $rootNode instanceof FunctionCallNode
                    && $rootNode->name === 'sqrt'
                    && \count($rootNode->arguments) === 1
                ) {
                    if ($node->operator === BinaryOperator::Divide && $coefficientNode === $node->right) {
                        if ($candidateCoefficient[0] === '0') {
                            return null;
                        }
                        $coefficient = (new ExactRationalInterval(['1', '1'], ['1', '1']))
                            ->divide(new ExactRationalInterval($candidateCoefficient, $candidateCoefficient))
                            ->lower;
                    } else {
                        $coefficient = $candidateCoefficient;
                    }
                    $node = $rootNode;
                    break;
                }
            }
        }
        if (
            !$node instanceof FunctionCallNode
            || $node->name !== 'sqrt'
            || \count($node->arguments) !== 1
            || !$evaluationOptions->functions->isBuiltIn('sqrt')
        ) {
            return null;
        }
        $radicand = $this->exactConstantRational($node->arguments[0], $extractor);
        $coefficientSquare = $extractor->multiplyExactFractions($coefficient, $coefficient);
        if ($radicand === null || $coefficientSquare === null) {
            return null;
        }
        $scaledRadicand = $extractor->multiplyExactFractions($radicand, $coefficientSquare);
        if ($scaledRadicand === null) {
            return null;
        }

        return [$scaledRadicand, $coefficient[0][0] === '-' ? -1 : 1];
    }

    /** @return array{slope: int, intercept: array{string, string}}|null */
    private function constantAffineVariable(
        Node $node,
        string $variable,
        ExactRationalPolynomialExtractor $extractor,
    ): ?array {
        $node = $this->unwrapGrouping($node);
        $sign = $this->signedVariable($node, $variable);
        if ($sign !== null) {
            return ['slope' => $sign, 'intercept' => ['0', '1']];
        }
        if (
            !$node instanceof BinaryOperationNode
            || !\in_array($node->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)
        ) {
            return null;
        }
        $leftSign = $this->signedVariable($node->left, $variable);
        $rightSign = $this->signedVariable($node->right, $variable);
        if ($leftSign !== null && $rightSign === null) {
            $constant = $this->exactConstantRational($node->right, $extractor);
            if ($constant === null) {
                return null;
            }
            if ($node->operator === BinaryOperator::Subtract) {
                $constant[0] = $constant[0] === '0' ? '0' : '-' . $constant[0];
            }

            return ['slope' => $leftSign, 'intercept' => $constant];
        }
        if ($leftSign === null && $rightSign !== null && $node->operator === BinaryOperator::Add) {
            $constant = $this->exactConstantRational($node->left, $extractor);

            return $constant === null ? null : ['slope' => $rightSign, 'intercept' => $constant];
        }

        return null;
    }

    /**
     * @param list<array{string, string}> $polynomial
     * @param array{string, string} $intercept
     * @return list<array{string, string}>|null
     */
    private function composeRationalPolynomialWithAffineTransform(
        array $polynomial,
        int $slope,
        array $intercept,
        ExactRationalPolynomialExtractor $extractor,
    ): ?array {
        $result = [['0', '1']];
        $affine = [$intercept, [(string) $slope, '1']];
        foreach (\array_reverse($polynomial) as $coefficient) {
            $product = \array_fill(0, \count($result) + 1, ['0', '1']);
            foreach ($result as $degree => $value) {
                foreach ($affine as $affineDegree => $factor) {
                    $term = $extractor->multiplyExactFractions($value, $factor);
                    if ($term === null) {
                        return null;
                    }
                    $sum = $extractor->addExactFractions(
                        $product[$degree + $affineDegree],
                        $term,
                    );
                    if ($sum === null) {
                        return null;
                    }
                    $product[$degree + $affineDegree] = $sum;
                }
            }
            $constant = $extractor->addExactFractions($product[0], $coefficient);
            if ($constant === null) {
                return null;
            }
            $product[0] = $constant;
            $result = $product;
        }

        return $result;
    }

    /**
     * Isolate real nth-root equations with exact rational radicands.
     *
     * @param array<string, int|float> $parameters
     * @param array{string, string} $maximumWidth
     * @param array{array{string, string}, array{string, string}}|null $bounds
     * @return list<RationalRootInterval>|null
     */
    private function constantRadicalEquationRoots(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
        int $maxDepth,
        array $maximumWidth,
        ?array $bounds = null,
    ): ?array {
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        foreach ([[$left, $right], [$right, $left]] as [$rootNode, $variableNode]) {
            $variableSign = $this->signedVariable($variableNode, $variable);
            $rootSign = 1;
            $rootNode = $this->unwrapGrouping($rootNode);
            if ($variableSign === null) {
                $zeroTarget = $this->exactConstantRational($variableNode, $extractor);
                if (
                    $zeroTarget === null
                    || $zeroTarget[0] !== '0'
                    || !$rootNode instanceof BinaryOperationNode
                    || !\in_array($rootNode->operator, [BinaryOperator::Add, BinaryOperator::Subtract], true)
                ) {
                    continue;
                }
                $terms = [
                    [$rootNode->left, 1],
                    [$rootNode->right, $rootNode->operator === BinaryOperator::Subtract ? -1 : 1],
                ];
                foreach ($terms as $index => [$term, $outerSign]) {
                    $termVariableSign = $this->signedVariable($term, $variable);
                    if ($termVariableSign === null) {
                        continue;
                    }
                    [$rootNode, $rootSign] = $terms[1 - $index];
                    $variableSign = $termVariableSign;
                    $rootSign = -$rootSign;
                    break;
                }
                if ($variableSign === null) {
                    continue;
                }
            }
            if ($rootNode instanceof UnaryOperationNode && $rootNode->operator === UnaryOperator::Minus) {
                $rootSign *= -1;
                $rootNode = $this->unwrapGrouping($rootNode->operand);
            }
            $radicandNode = null;
            $degree = 2;
            $reciprocal = false;
            if (
                $rootNode instanceof FunctionCallNode
                && $rootNode->name === 'sqrt'
                && \count($rootNode->arguments) === 1
                && $evaluationOptions->functions->isBuiltIn('sqrt')
            ) {
                $radicandNode = $rootNode->arguments[0];
            } elseif (
                $rootNode instanceof FunctionCallNode
                && $rootNode->name === 'cbrt'
                && \count($rootNode->arguments) === 1
                && $evaluationOptions->functions->isBuiltIn('cbrt')
            ) {
                $radicandNode = $rootNode->arguments[0];
                $degree = 3;
            } elseif (
                $rootNode instanceof FunctionCallNode
                && $rootNode->name === 'root'
                && \count($rootNode->arguments) === 2
                && $evaluationOptions->functions->isBuiltIn('root')
            ) {
                $radicandNode = $rootNode->arguments[0];
                $degreeFraction = $this->exactConstantRational($rootNode->arguments[1], $extractor);
                if ($degreeFraction === null || $degreeFraction[1] !== '1') {
                    continue;
                }
                $degreeValue = \filter_var($degreeFraction[0], FILTER_VALIDATE_INT);
                if (
                    !\is_int($degreeValue)
                    || $degreeValue === 0
                    || \abs($degreeValue) > self::MAX_EXACT_ROOT_DEGREE
                ) {
                    continue;
                }
                $degree = \abs($degreeValue);
                $reciprocal = $degreeValue < 0;
            } elseif (
                $rootNode instanceof BinaryOperationNode
                && $rootNode->operator === BinaryOperator::Power
            ) {
                $exponent = $this->exactConstantRational($rootNode->right, $extractor);
                if (
                    $exponent === null
                    || !\in_array($exponent[0], ['1', '-1'], true)
                    || $exponent[1] === '1'
                ) {
                    continue;
                }
                $degree = \filter_var($exponent[1], FILTER_VALIDATE_INT);
                if (!\is_int($degree) || $degree < 2 || $degree > self::MAX_EXACT_ROOT_DEGREE) {
                    continue;
                }
                $radicandNode = $rootNode->left;
                $reciprocal = $exponent[0] === '-1';
            }
            if ($radicandNode === null) {
                continue;
            }
            $radicand = $this->exactConstantRational($radicandNode, $extractor);
            if ($radicand === null) {
                continue;
            }
            if ($reciprocal) {
                if ($radicand[0] === '0') {
                    return [];
                }
                $radicand = (new ExactRationalInterval($radicand, $radicand))->reciprocal()->lower;
            }
            if ($radicand[0] === '0') {
                return $bounds === null
                    || (
                        $this->compareRationalFractions($bounds[0], ['0', '1']) <= 0
                        && $this->compareRationalFractions($bounds[1], ['0', '1']) >= 0
                    )
                    ? [new RationalRootInterval('0', '1', '0', '1', true)]
                    : [];
            }
            $radicandIsNegative = $radicand[0][0] === '-';
            if ($radicandIsNegative && $degree % 2 === 0) {
                return [];
            }
            $polynomial = \array_fill(0, $degree + 1, ['0', '1']);
            $polynomial[0] = [$radicandIsNegative ? \substr($radicand[0], 1) : '-' . $radicand[0], $radicand[1]];
            $polynomial[$degree] = ['1', '1'];
            $integerPolynomial = $this->integerPolynomialFromRational($polynomial);
            if ($integerPolynomial === null) {
                return null;
            }
            $desiredSign = $rootSign * $variableSign * ($degree % 2 === 1 && $radicandIsNegative ? -1 : 1);
            /** @var list<RationalRootInterval> $roots */
            $roots = [];
            if ($bounds === null) {
                $absoluteNumerator = $radicandIsNegative ? \substr($radicand[0], 1) : $radicand[0];
                $limit = (new IntegerPolynomialExtractor('', []))->addIntegerValues($absoluteNumerator, '1');
                $lower = $desiredSign > 0 ? ['0', '1'] : ['-' . $limit, '1'];
                $upper = $desiredSign > 0 ? [$limit, '1'] : ['0', '1'];
            } else {
                $zero = ['0', '1'];
                $lower = $desiredSign > 0 && $this->compareRationalFractions($bounds[0], $zero) < 0
                    ? $zero
                    : $bounds[0];
                $upper = $desiredSign < 0 && $this->compareRationalFractions($bounds[1], $zero) > 0
                    ? $zero
                    : $bounds[1];
                if ($this->compareRationalFractions($lower, $upper) > 0) {
                    continue;
                }
                if ($this->boundIsSignedRadical($lower, $radicand, $degree, $desiredSign)) {
                    $roots[] = new RationalRootInterval($lower[0], $lower[1], $lower[0], $lower[1], true);
                }
                if (
                    $this->compareRationalFractions($lower, $upper) !== 0
                    && $this->boundIsSignedRadical($upper, $radicand, $degree, $desiredSign)
                ) {
                    $roots[] = new RationalRootInterval($upper[0], $upper[1], $upper[0], $upper[1], true);
                }
            }
            if ($this->compareRationalFractions($lower, $upper) < 0) {
                $isolated = (new ExactPolynomialRootCounter())->isolateOpenInterval(
                    $integerPolynomial,
                    $lower[0],
                    $lower[1],
                    $upper[0],
                    $upper[1],
                    $maxDepth,
                    $maximumWidth,
                );
                if ($isolated === null) {
                    return null;
                }
                $isolatedIntervals = $this->rationalRootIntervalsFromExactPolynomial($isolated);
                if ($isolatedIntervals === null) {
                    return null;
                }
                array_push($roots, ...$isolatedIntervals);
            }
            \usort($roots, fn (RationalRootInterval $a, RationalRootInterval $b): int =>
                $this->compareRationalFractions(
                    [$a->lowerNumerator, $a->lowerDenominator],
                    [$b->lowerNumerator, $b->lowerDenominator],
                ));

            return $roots;
        }

        return null;
    }


    /**
     * @param array{string, string} $bound
     * @param array{string, string} $radicand
     */
    private function boundIsSignedRadical(array $bound, array $radicand, int $degree, int $sign): bool
    {
        $boundInterval = new ExactRationalInterval($bound, $bound);
        if (
            ($sign > 0 && $boundInterval->compareLowerToRational('0', '1') <= 0)
            || ($sign < 0 && $boundInterval->compareUpperToRational('0', '1') >= 0)
        ) {
            return false;
        }
        $power = new ExactRationalInterval(['1', '1'], ['1', '1']);
        for ($index = 0; $index < $degree; ++$index) {
            $power = $power->multiply($boundInterval);
        }

        return $this->compareRationalFractions($power->lower, $radicand) === 0;
    }

    /**
     * Reduce rational fractional powers of nonlinear polynomial bases to exact polynomial roots.
     *
     * @param array<string, int|float> $parameters
     * @return array{list<string>, list<string>}|false|null False means no real root.
     */
    private function directRationalPowerPolynomial(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
    ): array|false|null {
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        foreach ([[$left, $right], [$right, $left]] as [$powerNode, $targetNode]) {
            $powerNode = $this->unwrapGrouping($powerNode);
            $negateTarget = false;
            while ($powerNode instanceof UnaryOperationNode) {
                if ($powerNode->operator === UnaryOperator::Minus) {
                    $negateTarget = !$negateTarget;
                }
                $powerNode = $this->unwrapGrouping($powerNode->operand);
            }
            $baseNode = null;
            $exponent = null;
            if (
                $powerNode instanceof BinaryOperationNode
                && $powerNode->operator === BinaryOperator::Power
            ) {
                $baseNode = $powerNode->left;
                $exponent = $this->exactConstantRational($powerNode->right, $extractor);
            } elseif ($powerNode instanceof FunctionCallNode) {
                $functionDegree = match ($powerNode->name) {
                    'sqrt' => \count($powerNode->arguments) === 1 ? 2 : null,
                    'cbrt' => \count($powerNode->arguments) === 1 ? 3 : null,
                    'root' => $this->exactRootFunctionDegree($powerNode->arguments, $extractor),
                    default => null,
                };
                if ($functionDegree === null) {
                    continue;
                }
                $baseNode = $powerNode->arguments[0];
                $exponent = $functionDegree < 0
                    ? ['-1', (string) \abs($functionDegree)]
                    : ['1', (string) $functionDegree];
            } else {
                continue;
            }
            if ($exponent === null) {
                continue;
            }
            if ($this->containsVariable($targetNode, $variable)) {
                $degree = \filter_var($exponent[1], FILTER_VALIDATE_INT);
                $numerator = \filter_var($exponent[0], FILTER_VALIDATE_INT);
                if (
                    !$negateTarget
                    && \is_int($degree)
                    && \is_int($numerator)
                    && $degree > 1
                    && $degree <= $maxPolynomialDegree
                    && $numerator !== 0
                    && \abs($numerator) <= $maxPolynomialDegree
                    && ($degree % 2) === 1
                    && ($numerator % 2) !== 0
                ) {
                    $equation = $extractor->rationalPowerDifference(
                        $baseNode,
                        $numerator,
                        $targetNode,
                        $degree,
                    );
                    if ($equation !== null) {
                        return $equation;
                    }
                }

                continue;
            }
            $basePolynomial = $extractor->polynomial($baseNode);
            $baseForm = $extractor->rationalDifferenceFromFraction($baseNode, ['0', '1']);
            $baseRationalForm = $extractor->rationalPolynomialForm($baseNode);
            $targetPolynomial = $extractor->polynomial($targetNode);
            if (
                $baseForm === null
                || $baseRationalForm === null
                || $targetPolynomial === null
                || \count($targetPolynomial) !== 1
            ) {
                continue;
            }
            $degree = \filter_var($exponent[1], FILTER_VALIDATE_INT);
            $numerator = \filter_var($exponent[0], FILTER_VALIDATE_INT);
            if (
                !\is_int($degree)
                || !\is_int($numerator)
                || $degree < 2
                || $degree > $maxPolynomialDegree
                || $numerator === \PHP_INT_MIN
            ) {
                continue;
            }
            $divisor = $this->integerGcd(\abs($numerator), $degree);
            $degree = \intdiv($degree, $divisor);
            $numerator = \intdiv($numerator, $divisor);
            if ($degree < 2 || \abs($numerator) > $maxPolynomialDegree) {
                continue;
            }

            $target = $targetPolynomial[0];
            if ($negateTarget) {
                $target = (new ExactRationalInterval($target, $target))->negateInterval()->lower;
            }
            $targetSign = (new ExactRationalInterval($target, $target))->compareLowerToRational('0', '1');
            $evenNumerator = ($numerator % 2) === 0;
            if ((($degree % 2) === 0 || $evenNumerator) && $targetSign < 0) {
                return false;
            }
            if ($numerator < 0 && $targetSign === 0) {
                return false;
            }
            try {
                $baseValue = $this->rationalBound(
                    '(' . $target[0] . '/' . $target[1] . ')^(' . $degree . '/' . $numerator . ')',
                    $evaluationOptions,
                );
                if ($baseValue === null) {
                    return $this->fractionalPowerRationalFunction(
                        $baseRationalForm,
                        $target,
                        $numerator,
                        $degree,
                        $maxPolynomialDegree,
                        $extractor,
                    );
                }
                $baseValues = [$baseValue];
                if ($evenNumerator && ($degree % 2) === 1 && $targetSign > 0) {
                    $baseValues[] = (new ExactRationalInterval($baseValue, $baseValue))
                        ->negateInterval()->lower;
                }

                $branchPolynomials = [];
                $branchDenominator = null;
                foreach ($baseValues as $branchValue) {
                    $branchForm = $extractor->rationalDifferenceFromFraction($baseNode, $branchValue);
                    if ($branchForm === null) {
                        return null;
                    }
                    $branchPolynomials[] = $branchForm[0];
                    $branchDenominator ??= $branchForm[1];
                }
                if (\count($branchPolynomials) === 1) {
                    return [$branchPolynomials[0], $branchDenominator];
                }
                if ((\count($branchPolynomials[0]) - 1) * \count($branchPolynomials) > $maxPolynomialDegree) {
                    return null;
                }

                $arithmetic = new IntegerPolynomialExtractor('', [], $maxPolynomialDegree * 2);
                $product = ['1'];
                foreach ($branchPolynomials as $branch) {
                    $next = \array_fill(0, \count($product) + \count($branch) - 1, '0');
                    foreach ($product as $leftDegree => $leftCoefficient) {
                        foreach ($branch as $rightDegree => $rightCoefficient) {
                            $index = $leftDegree + $rightDegree;
                            $next[$index] = $arithmetic->addIntegerValues(
                                $next[$index],
                                $arithmetic->multiplyIntegerValues($leftCoefficient, $rightCoefficient),
                            );
                        }
                    }
                    $product = $next;
                }

                return [\array_values($product), $branchDenominator];
            } catch (\LengthException) {
                return null;
            }
        }

        return null;
    }

    /**
     * Replace (A(x)/B(x))^(p/n)=q with an equivalent polynomial and retain excluded domain zeros.
     *
     * @param array{list<array{string, string}>, list<array{string, string}>} $baseForm
     * @param array{string, string} $target
     * @return array{list<string>, list<string>}|false|null
     */
    private function fractionalPowerRationalFunction(
        array $baseForm,
        array $target,
        int $numerator,
        int $denominator,
        int $maxPolynomialDegree,
        ExactRationalPolynomialExtractor $extractor,
    ): array|false|null {
        if ($numerator === 0 || $numerator === \PHP_INT_MIN) {
            return null;
        }
        $power = \abs($numerator);
        [$baseNumerator, $baseDenominator] = $baseForm;
        $baseDegree = \max(\count($baseNumerator), \count($baseDenominator)) - 1;
        if ($baseDegree > \intdiv($maxPolynomialDegree, $power)) {
            return null;
        }

        try {
            $poweredNumerator = $this->rationalPolynomialPower($baseNumerator, $power);
            $poweredDenominator = $this->rationalPolynomialPower($baseDenominator, $power);
            if ($poweredNumerator === null || $poweredDenominator === null) {
                return null;
            }
            $targetPower = new ExactRationalInterval($target, $target);
            for ($iteration = 1; $iteration < $denominator; ++$iteration) {
                $targetPower = $targetPower->multiply(new ExactRationalInterval($target, $target));
            }
            if ($numerator < 0) {
                $poweredNumerator = $this->subtractRationalPolynomials(
                    $poweredDenominator,
                    $this->scaleRationalPolynomial($poweredNumerator, $targetPower->lower),
                );
                $excludedDenominator = $this->multiplyRationalPolynomials($baseNumerator, $baseDenominator);
            } else {
                $poweredNumerator = $this->subtractRationalPolynomials(
                    $poweredNumerator,
                    $this->scaleRationalPolynomial($poweredDenominator, $targetPower->lower),
                );
                $excludedDenominator = $baseDenominator;
            }
            if ($excludedDenominator === null) {
                return null;
            }
            if ($this->isZeroRationalPolynomial($excludedDenominator)) {
                return false;
            }
            if (
                \max(\count($poweredNumerator), \count($excludedDenominator)) - 1 > $maxPolynomialDegree
            ) {
                return null;
            }
            $integerNumerator = $extractor->integerCoefficients($poweredNumerator);
            $integerDenominator = $extractor->integerCoefficients($excludedDenominator);
            if ($integerNumerator === null || $integerDenominator === null) {
                return null;
            }

            return [$integerNumerator, $integerDenominator];
        } catch (\LengthException | \DivisionByZeroError | \DomainException) {
            return null;
        }
    }

    /**
     * @return array{leftPower: int, rightPower: int, unitPower: int, base: Node}|null
     */
    private function fixedLogarithmArgumentPowerRelation(
        Node $leftArgument,
        Node $rightArgument,
        ExactRationalPolynomialExtractor $extractor,
        int $maxPolynomialDegree,
    ): ?array {
        $leftPowerNode = $this->rationalPowerArgument($leftArgument, $maxPolynomialDegree);
        $rightPowerNode = $this->rationalPowerArgument($rightArgument, $maxPolynomialDegree);
        if ($leftPowerNode !== null && $rightPowerNode !== null) {
            $baseDifference = $extractor->rationalDifference($leftPowerNode['base'], $rightPowerNode['base']);
            if ($baseDifference !== null && $this->isZeroCoefficientList($baseDifference[0])) {
                if (
                    \abs($leftPowerNode['numerator']) > intdiv(
                        $maxPolynomialDegree,
                        $rightPowerNode['denominator'],
                    )
                    || \abs($rightPowerNode['numerator']) > intdiv(
                        $maxPolynomialDegree,
                        $leftPowerNode['denominator'],
                    )
                ) {
                    return null;
                }
                $leftPower = $leftPowerNode['numerator'] * $rightPowerNode['denominator'];
                $rightPower = $rightPowerNode['numerator'] * $leftPowerNode['denominator'];

                return [
                    'leftPower' => $leftPower,
                    'rightPower' => $rightPower,
                    'unitPower' => \abs($leftPowerNode['numerator']) % 2 === 0
                        && \abs($rightPowerNode['numerator']) % 2 === 0 ? 2 : 1,
                    'base' => $leftPowerNode['base'],
                ];
            }
        }

        $leftPolynomial = $extractor->polynomial($leftArgument);
        $rightPolynomial = $extractor->polynomial($rightArgument);
        if ($leftPolynomial === null || $rightPolynomial === null) {
            return null;
        }

        $rightPower = $this->exactPolynomialPowerRelation(
            $leftPolynomial,
            $rightPolynomial,
            $maxPolynomialDegree,
        );
        if ($rightPower !== null) {
            return [
                'leftPower' => 1,
                'rightPower' => $rightPower,
                'unitPower' => 1,
                'base' => $leftArgument,
            ];
        }

        $leftPower = $this->exactPolynomialPowerRelation(
            $rightPolynomial,
            $leftPolynomial,
            $maxPolynomialDegree,
        );

        return $leftPower === null
            ? null
            : [
                'leftPower' => $leftPower,
                'rightPower' => 1,
                'unitPower' => 1,
                'base' => $rightArgument,
            ];
    }

    /** @return array{base: Node, numerator: int, denominator: int}|null */
    private function rationalPowerArgument(Node $argument, int $maxPolynomialDegree): ?array
    {
        $argument = $this->unwrapGrouping($argument);
        if (!$argument instanceof BinaryOperationNode || $argument->operator !== BinaryOperator::Power) {
            return ['base' => $argument, 'numerator' => 1, 'denominator' => 1];
        }
        $power = RationalLiteral::fromNode($argument->right);
        if (
            $power === null
            || $power[0] === 0
            || $power[0] === \PHP_INT_MIN
            || \abs($power[0]) > $maxPolynomialDegree
            || $power[1] > $maxPolynomialDegree
        ) {
            return null;
        }

        return ['base' => $argument->left, 'numerator' => $power[0], 'denominator' => $power[1]];
    }

    private function logarithmArgumentDomainNode(Node $argument, int $maxPolynomialDegree): ?Node
    {
        $argument = $this->unwrapGrouping($argument);
        if (!$argument instanceof BinaryOperationNode || $argument->operator !== BinaryOperator::Power) {
            return $argument;
        }
        $power = RationalLiteral::fromNode($argument->right);
        if (
            $power === null
            || $power[0] === 0
            || $power[0] === \PHP_INT_MIN
            || \abs($power[0]) > $maxPolynomialDegree
            || $power[1] > $maxPolynomialDegree
        ) {
            return null;
        }
        if ($power[0] % 2 === 0 && $power[1] % 2 === 1) {
            return new BinaryOperationNode(
                BinaryOperator::Power,
                $argument->left,
                new NumberNode(2, '2', $argument->left->span()),
                $argument->span,
            );
        }

        return $argument->left;
    }

    /**
     * @param list<array{string, string}> $base
     * @param list<array{string, string}> $candidate
     */
    private function exactPolynomialPowerRelation(array $base, array $candidate, int $maxPolynomialDegree): ?int
    {
        if (\count($base) < 2 || \count($candidate) < 3) {
            return null;
        }
        $maximumPower = \min($maxPolynomialDegree, \count($candidate) - 1);
        for ($power = 2; $power <= $maximumPower; ++$power) {
            try {
                $poweredBase = $this->rationalPolynomialPower($base, $power);
            } catch (\LengthException | \DivisionByZeroError | \DomainException) {
                return null;
            }
            if (
                $poweredBase !== null
                && $this->isZeroRationalPolynomial($this->subtractRationalPolynomials($poweredBase, $candidate))
            ) {
                return $power;
            }
        }

        return null;
    }

    /**
     * @param array{string, string} $leftBase
     * @param array{string, string} $rightBase
     */
    private function rationalPowersEqual(
        array $leftBase,
        int $leftPower,
        array $rightBase,
        int $rightPower,
    ): bool {
        $leftValue = new ExactRationalInterval($leftBase, $leftBase);
        $rightValue = new ExactRationalInterval($rightBase, $rightBase);
        $leftPowerValue = new ExactRationalInterval(['1', '1'], ['1', '1']);
        $rightPowerValue = new ExactRationalInterval(['1', '1'], ['1', '1']);
        for ($power = 0; $power < \abs($leftPower); ++$power) {
            $leftPowerValue = $leftPowerValue->multiply($leftValue);
        }
        for ($power = 0; $power < \abs($rightPower); ++$power) {
            $rightPowerValue = $rightPowerValue->multiply($rightValue);
        }
        if ($leftPower < 0) {
            $leftPowerValue = (new ExactRationalInterval(['1', '1'], ['1', '1']))
                ->divide($leftPowerValue);
        }
        if ($rightPower < 0) {
            $rightPowerValue = (new ExactRationalInterval(['1', '1'], ['1', '1']))
                ->divide($rightPowerValue);
        }

        return $leftPowerValue->compareLowerEndpoint($rightPowerValue) === 0;
    }

    /** @param list<array{string, string}> $polynomial
     *  @return list<array{string, string}>|null
     */
    private function rationalPolynomialPower(array $polynomial, int $power): ?array
    {
        $result = [['1', '1']];
        for ($iteration = 0; $iteration < $power; ++$iteration) {
            $result = $this->multiplyRationalPolynomials($result, $polynomial);
            if ($result === null) {
                return null;
            }
        }

        return $result;
    }

    /** @param list<array{string, string}> $polynomial
     *  @param array{string, string} $factor
     *  @return list<array{string, string}>
     */
    private function scaleRationalPolynomial(array $polynomial, array $factor): array
    {
        foreach ($polynomial as &$coefficient) {
            $coefficient = (new ExactRationalInterval($coefficient, $coefficient))
                ->multiply(new ExactRationalInterval($factor, $factor))->lower;
        }
        unset($coefficient);

        return $polynomial;
    }

    /** @param list<array{string, string}> $left
     *  @param list<array{string, string}> $right
     *  @return list<array{string, string}>
     */
    private function subtractRationalPolynomials(array $left, array $right): array
    {
        $difference = [];
        $length = \max(\count($left), \count($right));
        for ($index = 0; $index < $length; ++$index) {
            $leftCoefficient = $left[$index] ?? ['0', '1'];
            $rightCoefficient = $right[$index] ?? ['0', '1'];
            $difference[] = (new ExactRationalInterval($leftCoefficient, $leftCoefficient))
                ->subtract(new ExactRationalInterval($rightCoefficient, $rightCoefficient))->lower;
        }

        return $difference;
    }

    /** @param list<array{string, string}> $left
     *  @param list<array{string, string}> $right
     *  @return list<array{string, string}>|null
     */
    private function multiplyRationalPolynomials(array $left, array $right): ?array
    {
        $product = \array_fill(0, \count($left) + \count($right) - 1, ['0', '1']);
        try {
            foreach ($left as $leftDegree => $leftCoefficient) {
                foreach ($right as $rightDegree => $rightCoefficient) {
                    $index = $leftDegree + $rightDegree;
                    $sum = new ExactRationalInterval($product[$index], $product[$index]);
                    $term = (new ExactRationalInterval($leftCoefficient, $leftCoefficient))
                        ->multiply(new ExactRationalInterval($rightCoefficient, $rightCoefficient));
                    $product[$index] = $sum->add($term)->lower;
                }
            }
        } catch (\LengthException) {
            return null;
        }

        return $product;
    }

    /** @param list<array{string, string}> $polynomial */
    private function isZeroRationalPolynomial(array $polynomial): bool
    {
        foreach ($polynomial as [$numerator]) {
            if ($numerator !== '0') {
                return false;
            }
        }

        return true;
    }

    /**
     * Resolve (a*x+b)^(p/n) = q exactly when its inverse is rational.
     *
     * @param array<string, int|float> $parameters
     * @param EvaluationOptions $evaluationOptions
     * @return list<array{string, string}>|false|null False means the equation has no real root.
     */
    private function directRationalPowerRoot(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
    ): array|false|null {
        $maximumPowerDegree = \max(63, $maxPolynomialDegree);
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maximumPowerDegree,
            $evaluationOptions,
        );
        foreach ([[$left, $right], [$right, $left]] as [$powerNode, $targetNode]) {
            $powerNode = $this->unwrapGrouping($powerNode);
            if (
                !$powerNode instanceof BinaryOperationNode
                || $powerNode->operator !== BinaryOperator::Power
                || $this->containsVariable($targetNode, $variable)
            ) {
                continue;
            }
            $basePolynomial = $extractor->polynomial($powerNode->left);
            $targetPolynomial = $extractor->polynomial($targetNode);
            if (
                $basePolynomial === null
                || \count($basePolynomial) < 2
                || \count($basePolynomial) > 3
                || $targetPolynomial === null
                || \count($targetPolynomial) !== 1
            ) {
                continue;
            }
            $exponent = RationalLiteral::fromNodeAsStrings($powerNode->right);
            if ($exponent === null) {
                continue;
            }
            $target = $targetPolynomial[0];
            $degree = \filter_var($exponent[1], FILTER_VALIDATE_INT);
            $numerator = \filter_var($exponent[0], FILTER_VALIDATE_INT);
            if (
                !\is_int($degree)
                || !\is_int($numerator)
                || $degree < 2
                || $degree > $maximumPowerDegree
                || $numerator === \PHP_INT_MIN
            ) {
                continue;
            }
            $divisor = $this->integerGcd(\abs($numerator), $degree);
            $degree = intdiv($degree, $divisor);
            $numerator = intdiv($numerator, $divisor);
            if ($degree < 2 || \abs($numerator) > $maximumPowerDegree) {
                continue;
            }

            $targetInterval = new ExactRationalInterval($target, $target);
            $targetSign = $targetInterval->compareLowerToRational('0', '1');
            $evenNumerator = ($numerator % 2) === 0;
            if ((($degree % 2) === 0 || $evenNumerator) && $targetSign < 0) {
                return false;
            }
            if ($numerator < 0 && $targetSign === 0) {
                return false;
            }
            try {
                $inversePowerExpression = '(' . $target[0] . '/' . $target[1] . ')^('
                    . $degree . '/' . $numerator . ')';
                $baseValueFraction = $this->rationalBound($inversePowerExpression, $evaluationOptions);
                if ($baseValueFraction === null) {
                    return null;
                }
                $baseValue = new ExactRationalInterval($baseValueFraction, $baseValueFraction);
                $baseValues = [$baseValue];
                if ($evenNumerator && ($degree % 2) === 1 && $targetSign > 0) {
                    $baseValues[] = $baseValue->negateInterval();
                }
                $roots = [];
                foreach ($baseValues as $branchValue) {
                    $constant = new ExactRationalInterval($basePolynomial[0], $basePolynomial[0]);
                    $linear = new ExactRationalInterval($basePolynomial[1], $basePolynomial[1]);
                    if (\count($basePolynomial) === 2) {
                        if ($linear->compareLowerToRational('0', '1') === 0) {
                            continue;
                        }
                        $root = $branchValue->subtract($constant)->divide($linear)->lower;
                        if (!\in_array($root, $roots, true)) {
                            $roots[] = $root;
                        }
                        continue;
                    }

                    $quadratic = new ExactRationalInterval($basePolynomial[2], $basePolynomial[2]);
                    if ($quadratic->compareLowerToRational('0', '1') === 0) {
                        if ($linear->compareLowerToRational('0', '1') !== 0) {
                            $root = $branchValue->subtract($constant)->divide($linear)->lower;
                            if (!\in_array($root, $roots, true)) {
                                $roots[] = $root;
                            }
                        }
                        continue;
                    }

                    $shiftedConstant = $constant->subtract($branchValue);
                    $discriminant = $linear->multiply($linear)->subtract(
                        (new ExactRationalInterval(['4', '1'], ['4', '1']))
                            ->multiply($quadratic)
                            ->multiply($shiftedConstant),
                    );
                    if ($discriminant->compareUpperToRational('0', '1') < 0) {
                        continue;
                    }
                    $discriminantFraction = $discriminant->lower;
                    $squareRoot = $this->rationalBound(
                        '(' . $discriminantFraction[0] . '/' . $discriminantFraction[1] . ')^(1/2)',
                        $evaluationOptions,
                    );
                    if ($squareRoot === null) {
                        return null;
                    }
                    $rootDenominator = (new ExactRationalInterval(['2', '1'], ['2', '1']))
                        ->multiply($quadratic);
                    $negativeLinear = $linear->negateInterval();
                    $rootNumerators = [$negativeLinear];
                    if ($squareRoot[0] !== '0') {
                        $rootNumerators[] = $negativeLinear->subtract(
                            new ExactRationalInterval($squareRoot, $squareRoot),
                        );
                        $rootNumerators[0] = $negativeLinear->add(
                            new ExactRationalInterval($squareRoot, $squareRoot),
                        );
                    }
                    foreach ($rootNumerators as $rootNumerator) {
                        $root = $rootNumerator->divide($rootDenominator)->lower;
                        if (!\in_array($root, $roots, true)) {
                            $roots[] = $root;
                        }
                    }
                }
                \usort(
                    $roots,
                    fn (array $first, array $second): int => $this->compareRationalFractions($first, $second),
                );
            } catch (\LengthException) {
                return null;
            }

            return $roots;
        }

        return null;
    }

    /**
     * @param array{string, string} $left
     * @param array{string, string} $right
     * @return array{string, string}
     */
    private function rationalMidpoint(array $left, array $right): array
    {
        return (new ExactRationalInterval($left, $left))
            ->add(new ExactRationalInterval($right, $right))
            ->divide(new ExactRationalInterval(['2', '1'], ['2', '1']))
            ->lower;
    }

    /** @return array{string, string} */
    private function rationalTuple(string $numerator, string $denominator): array
    {
        return [$numerator, $denominator];
    }

    /**
     * @param array{string, string} $left
     * @param array{string, string} $right
     */
    private function compareRationalFractions(array $left, array $right): int
    {
        return (new ExactRationalInterval($left, $left))->compareLowerEndpoint(
            new ExactRationalInterval($right, $right),
        );
    }

    /**
     * @param list<RationalRootInterval> $roots
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @return list<RationalRootInterval>|false
     */
    private function rootIntervalsWithinOpenRationalBounds(array $roots, array $lower, array $upper): array|false
    {
        $boundedRoots = [];
        foreach ($roots as $root) {
            $rootLower = [$root->lowerNumerator, $root->lowerDenominator];
            $rootUpper = [$root->upperNumerator, $root->upperDenominator];
            if ($root->isExactRoot) {
                if (
                    $this->compareRationalFractions($rootLower, $lower) > 0
                    && $this->compareRationalFractions($rootLower, $upper) < 0
                ) {
                    $boundedRoots[] = $root;
                }
                continue;
            }
            if (
                $this->compareRationalFractions($rootUpper, $lower) <= 0
                || $this->compareRationalFractions($rootLower, $upper) >= 0
            ) {
                continue;
            }
            if (
                $this->compareRationalFractions($rootLower, $lower) > 0
                && $this->compareRationalFractions($rootUpper, $upper) < 0
            ) {
                $boundedRoots[] = $root;
                continue;
            }

            return false;
        }

        return $boundedRoots;
    }

    /** @param array{string, string} $value */
    private function positiveHalfIndex(array $value, bool $ceiling): ?int
    {
        $interval = new ExactRationalInterval($value, $value);
        if ($interval->compareLowerToRational('0', '1') >= 0) {
            return 0;
        }

        $arithmetic = new IntegerPolynomialExtractor('', []);
        $numerator = \str_starts_with($value[0], '-') ? \substr($value[0], 1) : $value[0];
        $denominator = $arithmetic->multiplyIntegerValues('2', $value[1]);
        $index = $arithmetic->divideNonnegativeIntegerValuesFloor($numerator, $denominator);
        $remainder = $arithmetic->subtract(
            $numerator,
            $arithmetic->multiplyIntegerValues($index, $denominator),
        );
        if ($ceiling && $remainder !== '0') {
            $index = $arithmetic->addIntegerValues($index, '1');
        }
        if ($arithmetic->compareIntegerValues($index, (string) self::MAX_SPECIAL_ZERO_LEVELS) > 0) {
            return null;
        }

        return (int) $index;
    }

    private function integerGcd(int $left, int $right): int
    {
        while ($right !== 0) {
            [$left, $right] = [$right, $left % $right];
        }

        return $left ?: 1;
    }

    private function unwrapGrouping(Node $node): Node
    {
        while ($node instanceof GroupingNode) {
            $node = $node->expression;
        }

        return $node;
    }

    /**
     * Reduce exact hyperbolic equalities with rational-function or polynomial phases.
     *
     * @param array<string, int|float> $parameters
     * @return array{Node, Node}
     */
    private function reduceRationalHyperbolicEquality(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        int $maxPolynomialDegree,
        EvaluationOptions $evaluationOptions,
    ): array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        $zeroPreservingNames = [
            'sinh', 'tanh', 'asinh', 'arcsinh', 'atan', 'arctan', 'erf', 'erfi', 'cbrt', 'expm1',
            'sqrt', 'asin', 'arcsin', 'atanh', 'arctanh', 'erfinv', 'log1p', 'abs', 'sign', 'dawson',
        ];
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        foreach ([[$left, $right], [$right, $left]] as [$phase, $target]) {
            if (
                !$this->containsVariable($phase, $variable)
                || !$this->usesKnownBuiltInSymbols($phase, $variable, $parameters, $evaluationOptions)
                || !$this->usesKnownBuiltInSymbols($target, $variable, $parameters, $evaluationOptions)
            ) {
                continue;
            }
            $zero = new NumberNode(0, '0', $target->span());
            $targetBase = $this->unwrapUniqueZeroFunctions(
                $target,
                $zeroPreservingNames,
                $evaluationOptions,
                $variable,
                $parameters,
            );
            $targetForm = $extractor->rationalDifference($targetBase, $zero);
            if (
                $targetForm === null
                && $targetBase instanceof BinaryOperationNode
                && \in_array($targetBase->operator, [BinaryOperator::Multiply, BinaryOperator::Divide], true)
                && $evaluationOptions->limits->maxExponentMagnitude >= 256
            ) {
                $targetPhase = $this->unwrapUniqueZeroFunctions(
                    $phase,
                    $zeroPreservingNames,
                    $evaluationOptions,
                    $variable,
                    $parameters,
                );
                $zeroProductCandidates = [[$targetBase->left, $targetBase->right]];
                if ($targetBase->operator === BinaryOperator::Multiply) {
                    $zeroProductCandidates[] = [$targetBase->right, $targetBase->left];
                }
                foreach (
                    $zeroProductCandidates as [
                        $zeroFactor,
                        $otherFactor,
                    ]
                ) {
                    $otherFactor = $this->unwrapGrouping($otherFactor);
                    if (
                        !$otherFactor instanceof FunctionCallNode
                        || !\in_array(
                            $otherFactor->name,
                            [
                                'sin', 'cos', 'tan', 'cot', 'sec', 'csc', 'sinc', 'sincpi',
                                'sinh', 'cosh', 'tanh', 'sech', 'csch', 'coth',
                                'asinh', 'arcsinh', 'atan', 'arctan', 'acot', 'erf', 'erfc', 'erfcx',
                                'erfi', 'dawson', 'exp', 'expm1', 'cbrt', 'abs', 'sign',
                            ],
                            true,
                        )
                        || !$evaluationOptions->functions->isBuiltIn($otherFactor->name)
                        || \count($otherFactor->arguments) !== 1
                        || ($targetBase->operator === BinaryOperator::Divide
                            && !\in_array(
                                $otherFactor->name,
                                ['exp', 'cosh', 'sech', 'csch', 'coth', 'sec', 'csc', 'erfc', 'erfcx'],
                                true,
                            ))
                    ) {
                        continue;
                    }
                    $zeroForm = $extractor->rationalDifference($zeroFactor, $zero);
                    $argument = $extractor->rationalDifference($otherFactor->arguments[0], $zero);
                    $trigFactor = \in_array($otherFactor->name, ['tan', 'sec', 'cot', 'csc'], true);
                    if ($trigFactor) {
                        $expectedPhase = \in_array($otherFactor->name, ['tan', 'sec'], true) ? 'sin' : 'cos';
                        $crossPhaseSafe = false;
                        if (
                            !$targetPhase instanceof FunctionCallNode
                            || \count($targetPhase->arguments) !== 1
                        ) {
                            continue;
                        }
                        if ($targetPhase->name !== $expectedPhase) {
                            $cosineCross = $expectedPhase === 'sin' && $targetPhase->name === 'cos';
                            $sineCross = $expectedPhase === 'cos' && $targetPhase->name === 'sin';
                            if (!$cosineCross && !$sineCross) {
                                continue;
                            }
                            $ratio = $this->constantRationalPhaseRatio(
                                $otherFactor->arguments[0],
                                $targetPhase->arguments[0],
                                $extractor,
                            );
                            $crossPhaseSafe = $cosineCross && $ratio !== null
                                && ((int) \substr($ratio[0], -1)) % 2 === 0;
                            if (!$crossPhaseSafe) {
                                $shift = $this->rationalPolynomialPhaseShift(
                                    $otherFactor->arguments[0],
                                    $targetPhase->arguments[0],
                                    $extractor,
                                );
                                $crossPhaseSafe = $shift !== null && $shift[0] !== '0';
                            }
                            if (!$crossPhaseSafe && $shift === null) {
                                $rootPolynomial = $extractor->polynomial($targetPhase->arguments[0]);
                                $factorPolynomial = $extractor->polynomial($otherFactor->arguments[0]);
                                if ($rootPolynomial !== null && $factorPolynomial !== null) {
                                    try {
                                        $constantTerm = $this->expandedPhaseConstantTerm(
                                            $factorPolynomial,
                                            $rootPolynomial,
                                        );
                                        $crossPhaseSafe = $constantTerm !== null
                                            && ($cosineCross || $constantTerm[0] !== '0');
                                    } catch (\Exception) {
                                        $crossPhaseSafe = false;
                                    }
                                }
                            }
                            if (!$crossPhaseSafe) {
                                continue;
                            }
                        }
                        $difference = $extractor->rationalDifference(
                            $otherFactor->arguments[0],
                            $targetPhase->arguments[0],
                        );
                        $opposite = $extractor->rationalDifference(
                            $otherFactor->arguments[0],
                            new UnaryOperationNode(
                                UnaryOperator::Minus,
                                $targetPhase->arguments[0],
                                $targetPhase->arguments[0]->span(),
                            ),
                        );
                        if (
                            !$crossPhaseSafe
                            && ($difference === null || !$this->isZeroCoefficientList($difference[0]))
                            && ($opposite === null || !$this->isZeroCoefficientList($opposite[0]))
                        ) {
                            $multiple = $this->unwrapGrouping($otherFactor->arguments[0]);
                            $matchedMultiple = false;
                            if (
                                $multiple instanceof BinaryOperationNode
                                && $multiple->operator === BinaryOperator::Multiply
                            ) {
                                foreach (
                                    [[$multiple->left, $multiple->right], [$multiple->right, $multiple->left]] as [
                                        $coefficient,
                                        $phaseArgument,
                                    ]
                                ) {
                                    $integer = $this->exactConstantRational($coefficient, $extractor);
                                    $phaseDifference = $extractor->rationalDifference(
                                        $phaseArgument,
                                        $targetPhase->arguments[0],
                                    );
                                    if (
                                        $integer !== null
                                        && $this->rationalPhaseRatioAvoidsPoles($integer, $expectedPhase)
                                        && $phaseDifference !== null
                                        && $this->isZeroCoefficientList($phaseDifference[0])
                                    ) {
                                        $matchedMultiple = true;
                                        break;
                                    }
                                }
                            }
                            if (!$matchedMultiple) {
                                $ratio = $this->constantRationalPhaseRatio(
                                    $otherFactor->arguments[0],
                                    $targetPhase->arguments[0],
                                    $extractor,
                                );
                                $matchedMultiple = $ratio !== null
                                    && $this->rationalPhaseRatioAvoidsPoles($ratio, $expectedPhase);
                            }
                            if (!$matchedMultiple) {
                                $one = new NumberNode(1, '1', $zero->span());
                                foreach ([BinaryOperator::Subtract, BinaryOperator::Add] as $operator) {
                                    $shiftNode = new BinaryOperationNode(
                                        $operator,
                                        $otherFactor->arguments[0],
                                        $targetPhase->arguments[0],
                                        $zero->span(),
                                    );
                                    $shift = $this->constantRationalPhaseRatio($shiftNode, $one, $extractor);
                                    if ($shift !== null && $shift[0] !== '0') {
                                        $matchedMultiple = true;
                                        break;
                                    }
                                }
                            }
                            if (!$matchedMultiple) {
                                $affineShift = $this->rationalPolynomialPhaseShift(
                                    $otherFactor->arguments[0],
                                    $targetPhase->arguments[0],
                                    $extractor,
                                );
                                $matchedMultiple = $affineShift !== null && $affineShift[0] !== '0';
                            }
                            if (!$matchedMultiple) {
                                try {
                                    $constantTerm = $this->polynomialInPhaseConstantTerm(
                                        $otherFactor->arguments[0],
                                        $targetPhase->arguments[0],
                                        $extractor,
                                        $evaluationOptions,
                                    );
                                } catch (\Exception) {
                                    $constantTerm = null;
                                }
                                $rootPolynomial = $extractor->polynomial($targetPhase->arguments[0]);
                                $factorPolynomial = $extractor->polynomial($otherFactor->arguments[0]);
                                if ($constantTerm === null && $rootPolynomial !== null && $factorPolynomial !== null) {
                                    try {
                                        $constantTerm = $this->expandedPhaseConstantTerm(
                                            $factorPolynomial,
                                            $rootPolynomial,
                                        );
                                    } catch (\Exception) {
                                        $constantTerm = null;
                                    }
                                }
                                $matchedMultiple = $constantTerm !== null
                                    && ($constantTerm[0] !== '0'
                                        || ($rootPolynomial !== null && \count($rootPolynomial) > 1
                                            && $factorPolynomial !== null
                                            && $this->rationalPolynomialPhaseShift(
                                                $otherFactor->arguments[0],
                                                $targetPhase->arguments[0],
                                                $extractor,
                                            ) === null));
                            }
                            if (!$matchedMultiple) {
                                $affine = $this->unwrapGrouping($otherFactor->arguments[0]);
                                if (
                                    $affine instanceof BinaryOperationNode
                                    && \in_array(
                                        $affine->operator,
                                        [BinaryOperator::Add, BinaryOperator::Subtract],
                                        true,
                                    )
                                ) {
                                    foreach (
                                        [[$affine->left, $affine->right], [$affine->right, $affine->left]] as [
                                            $constant,
                                            $scaledPhase,
                                        ]
                                    ) {
                                        $shift = $this->exactConstantRational($constant, $extractor);
                                        $ratio = $this->constantRationalPhaseRatio(
                                            $scaledPhase,
                                            $targetPhase->arguments[0],
                                            $extractor,
                                        );
                                        if ($shift !== null && $shift[0] !== '0' && $ratio !== null) {
                                            $matchedMultiple = true;
                                            break;
                                        }
                                    }
                                }
                            }
                            if (!$matchedMultiple) {
                                continue;
                            }
                        }
                    }
                    $requiresNonzeroArgument = \in_array($otherFactor->name, ['csch', 'coth', 'cot', 'csc'], true);
                    if ($zeroForm === null || $argument === null) {
                        continue;
                    }
                    $combinedDenominator = $this->multiplyIntegerPolynomialCoefficients(
                        $zeroForm[1],
                        $argument[1],
                    );
                    if ($combinedDenominator !== null && $requiresNonzeroArgument) {
                        $combinedDenominator = $this->multiplyIntegerPolynomialCoefficients(
                            $combinedDenominator,
                            $argument[0],
                        );
                    }
                    if (
                        $this->isZeroCoefficientList($zeroForm[0])
                        && $combinedDenominator !== null
                        && (!$requiresNonzeroArgument
                            || (!$this->isZeroCoefficientList($argument[0])
                                && ((new ExactPolynomialRootCounter())->countAllRealRoots($argument[0]) === 0
                                    || $this->trigonometricZerosAvoidRationalPoles(
                                        $targetPhase,
                                        $argument[0],
                                        $extractor,
                                    ))))
                        && ((new ExactPolynomialRootCounter())->countAllRealRoots($argument[1]) === 0
                            || $this->trigonometricZerosAvoidRationalPoles($targetPhase, $argument[1], $extractor))
                    ) {
                        $targetBase = $zeroFactor;
                        $targetForm = [$zeroForm[0], $combinedDenominator];
                        break;
                    }
                }
            }
            if ($targetForm === null || !$this->isZeroCoefficientList($targetForm[0])) {
                continue;
            }
            if (
                !$this->validZeroRationalPhase(
                    $target,
                    $targetForm[1],
                    $evaluationOptions,
                    $variable,
                    $parameters,
                )
            ) {
                continue;
            }
            $reduced = $this->unwrapUniqueZeroFunctions(
                $phase,
                $zeroPreservingNames,
                $evaluationOptions,
                $variable,
                $parameters,
            );
            if (
                $reduced !== $phase
                && $this->containsVariable($reduced, $variable)
                && $extractor->rationalDifference($reduced, $targetBase) !== null
            ) {
                return [$reduced, $targetBase];
            }
            if (
                $this->containsVariable($reduced, $variable)
                && ((new ExactPolynomialRootCounter())->countAllRealRoots($targetForm[1]) === 0
                    || $this->trigonometricZerosAvoidRationalPoles($reduced, $targetForm[1], $extractor))
            ) {
                return [$reduced, $zero];
            }
        }
        if (
            !$left instanceof FunctionCallNode
            || !$right instanceof FunctionCallNode
            || \count($left->arguments) !== 1
            || \count($right->arguments) !== 1
        ) {
            return [$left, $right];
        }
        $matchingInjectiveName = $left->name === $right->name
            || (\in_array($left->name, ['atan', 'arctan'], true)
                && \in_array($right->name, ['atan', 'arctan'], true))
            || (\in_array($left->name, ['asinh', 'arcsinh'], true)
                && \in_array($right->name, ['asinh', 'arcsinh'], true));
        if (
            $matchingInjectiveName
            && \in_array(
                $left->name,
                [
                    'sinh', 'tanh', 'asinh', 'arcsinh', 'exp', 'expm1', 'cbrt',
                    'atan', 'arctan', 'acot', 'erf', 'erfc', 'erfcx', 'erfi',
                ],
                true,
            )
            && $evaluationOptions->functions->isBuiltIn($left->name)
            && $this->usesKnownBuiltInSymbols($left, $variable, $parameters, $evaluationOptions)
            && $this->usesKnownBuiltInSymbols($right, $variable, $parameters, $evaluationOptions)
            && ($this->containsVariable($left->arguments[0], $variable)
                || $this->containsVariable($right->arguments[0], $variable))
        ) {
            return [$left->arguments[0], $right->arguments[0]];
        }
        $boundedNames = ['tanh', 'erf', 'sin', 'cos', 'sech'];
        $strictlyBelowOneNames = ['tanh', 'erf'];
        $disjointPair = ($left->name === 'coth' && \in_array($right->name, $boundedNames, true))
            || ($right->name === 'coth' && \in_array($left->name, $boundedNames, true))
            || ($left->name === 'cosh' && \in_array($right->name, $strictlyBelowOneNames, true))
            || ($right->name === 'cosh' && \in_array($left->name, $strictlyBelowOneNames, true));
        if (
            $disjointPair
            && ($this->containsVariable($left, $variable) || $this->containsVariable($right, $variable))
            && $this->usesKnownBuiltInSymbols($left, $variable, $parameters, $evaluationOptions)
            && $this->usesKnownBuiltInSymbols($right, $variable, $parameters, $evaluationOptions)
        ) {
            $variableNode = new VariableNode($variable, $left->span());

            return [
                new BinaryOperationNode(
                    BinaryOperator::Add,
                    $variableNode,
                    new NumberNode(1, '1', $left->span()),
                    $left->span(),
                ),
                $variableNode,
            ];
        }
        if (
            \in_array($left->name, $zeroPreservingNames, true)
            && \in_array($right->name, $zeroPreservingNames, true)
            && $this->usesKnownBuiltInSymbols($left, $variable, $parameters, $evaluationOptions)
            && $this->usesKnownBuiltInSymbols($right, $variable, $parameters, $evaluationOptions)
        ) {
            $zero = new NumberNode(0, '0', $left->span());
            foreach (
                [[$left->arguments[0], $right->arguments[0]], [$right->arguments[0], $left->arguments[0]]] as [
                    $phase,
                    $otherPhase,
                ]
            ) {
                $form = $extractor->rationalDifference($phase, $zero);
                if (
                    $form !== null && $this->isZeroCoefficientList($form[0])
                    && !$this->validZeroRationalPhase($phase, $form[1], $evaluationOptions, $variable, $parameters)
                ) {
                    $form = null;
                }
                $otherPhase = $this->unwrapUniqueZeroFunctions(
                    $otherPhase,
                    $zeroPreservingNames,
                    $evaluationOptions,
                    $variable,
                    $parameters,
                );
                if (
                    $form !== null
                    && $this->isZeroCoefficientList($form[0])
                    && ($this->containsVariable($phase, $variable) || $this->containsVariable($otherPhase, $variable))
                ) {
                    $sum = new BinaryOperationNode(BinaryOperator::Add, $phase, $otherPhase, $phase->span());
                    if ($extractor->rationalDifference($sum, $zero) !== null) {
                        return [$sum, $zero];
                    }
                }
                if (
                    $form !== null
                    && $this->isZeroCoefficientList($form[0])
                    && (
                        (new ExactPolynomialRootCounter())->countAllRealRoots($form[1]) === 0
                        || $this->trigonometricZerosAvoidRationalPoles($otherPhase, $form[1], $extractor)
                    )
                    && $this->containsVariable($otherPhase, $variable)
                ) {
                    return [$otherPhase, $zero];
                }
            }
        }
        $leftForm = $extractor->rationalPolynomialForm($left->arguments[0]);
        $rightForm = $extractor->rationalPolynomialForm($right->arguments[0]);
        $leftPhase = $left->arguments[0];
        $rightPhase = $right->arguments[0];
        if (
            \in_array($left->name, ['cosh', 'sech'], true)
            && \in_array($right->name, ['cosh', 'sech'], true)
            && ($this->containsVariable($left, $variable) || $this->containsVariable($right, $variable))
            && $this->usesKnownBuiltInSymbols($left, $variable, $parameters, $evaluationOptions)
            && $this->usesKnownBuiltInSymbols($right, $variable, $parameters, $evaluationOptions)
        ) {
            $zero = new NumberNode(0, '0', $left->span());
            foreach ([$leftPhase, $rightPhase] as $phase) {
                $form = $extractor->rationalDifference($phase, $zero);
                if (
                    $form !== null && $this->isZeroCoefficientList($form[0])
                    && !$this->validZeroRationalPhase($phase, $form[1], $evaluationOptions, $variable, $parameters)
                ) {
                    $form = null;
                }
                $otherPhase = $phase === $leftPhase ? $rightPhase : $leftPhase;
                $otherPhase = $this->unwrapUniqueZeroFunctions(
                    $otherPhase,
                    $zeroPreservingNames,
                    $evaluationOptions,
                    $variable,
                    $parameters,
                );
                if (
                    $form !== null
                    && $this->isZeroCoefficientList($form[0])
                    && ($this->containsVariable($phase, $variable) || $this->containsVariable($otherPhase, $variable))
                ) {
                    $sum = new BinaryOperationNode(BinaryOperator::Add, $phase, $otherPhase, $phase->span());
                    if ($extractor->rationalDifference($sum, $zero) !== null) {
                        return [$sum, $zero];
                    }
                }
                if (
                    $form !== null
                    && $this->isZeroCoefficientList($form[0])
                    && (
                        (new ExactPolynomialRootCounter())->countAllRealRoots($form[1]) === 0
                        || $this->trigonometricZerosAvoidRationalPoles($otherPhase, $form[1], $extractor)
                    )
                    && $this->containsVariable($otherPhase, $variable)
                ) {
                    return [$otherPhase, $zero];
                }
                if (
                    $form !== null
                    && $left->name !== $right->name
                    && !$this->isZeroCoefficientList($form[0])
                    && $this->rationalPhaseHasNoRealZeros($form[0], $form[1])
                ) {
                    $variableNode = new VariableNode($variable, $left->span());

                    return [
                        new BinaryOperationNode(
                            BinaryOperator::Add,
                            $variableNode,
                            new NumberNode(1, '1', $left->span()),
                            $left->span(),
                        ),
                        $variableNode,
                    ];
                }
            }
        }
        $coshCall = $left->name === 'cosh' ? $left : ($right->name === 'cosh' ? $right : null);
        $trigCall = \in_array($left->name, ['cos', 'sin'], true)
            ? $left
            : (\in_array($right->name, ['cos', 'sin'], true) ? $right : null);
        if (
            $coshCall !== null
            && $trigCall !== null
            && ($this->containsVariable($left, $variable) || $this->containsVariable($right, $variable))
        ) {
            $coshPhase = $coshCall->arguments[0];
            $trigPhase = $trigCall->arguments[0];
            $zero = new NumberNode(0, '0', $coshPhase->span());
            $coshForm = $extractor->rationalDifference($coshPhase, $zero);
            if (
                $coshForm !== null && $this->isZeroCoefficientList($coshForm[0])
                && !$this->validZeroRationalPhase(
                    $coshPhase,
                    $coshForm[1],
                    $evaluationOptions,
                    $variable,
                    $parameters,
                )
            ) {
                $coshForm = null;
            }
            $trigForm = $extractor->rationalDifference($trigPhase, $zero);
            if (
                $coshForm !== null
                && !$this->isZeroCoefficientList($coshForm[0])
                && (
                    $extractor->isConstantRationalFunction($coshPhase) === true
                    || $this->rationalPhaseHasNoRealZeros($coshForm[0], $coshForm[1])
                )
                && $this->usesKnownBuiltInSymbols($trigCall, $variable, $parameters, $evaluationOptions)
            ) {
                $variableNode = new VariableNode($variable, $coshPhase->span());

                return [
                    new BinaryOperationNode(
                        BinaryOperator::Add,
                        $variableNode,
                        new NumberNode(1, '1', $coshPhase->span()),
                        $coshPhase->span(),
                    ),
                    $variableNode,
                ];
            }
            if (
                $coshForm !== null
                && $trigForm !== null
                && $extractor->isConstantRationalFunction($trigPhase) === true
                && ($trigCall->name === 'sin' || !$this->isZeroCoefficientList($trigForm[0]))
            ) {
                $two = new NumberNode(2, '2', $coshPhase->span());
                $coshSquare = new BinaryOperationNode(BinaryOperator::Power, $coshPhase, $two, $coshPhase->span());
                $trigSquare = new BinaryOperationNode(BinaryOperator::Power, $trigPhase, $two, $trigPhase->span());
                $sum = new BinaryOperationNode(BinaryOperator::Add, $coshSquare, $trigSquare, $coshPhase->span());
                $positive = new BinaryOperationNode(
                    BinaryOperator::Add,
                    $sum,
                    new NumberNode(1, '1', $coshPhase->span()),
                    $coshPhase->span(),
                );
                if ($extractor->rationalDifference($positive, $zero) !== null) {
                    return [$positive, $zero];
                }
            }
            if (
                $trigCall->name === 'cos'
                && $coshForm !== null
                && $trigForm !== null
                && $this->isZeroCoefficientList($coshForm[0])
                && $this->isZeroCoefficientList($trigForm[0])
            ) {
                $sum = new BinaryOperationNode(BinaryOperator::Add, $coshPhase, $trigPhase, $coshPhase->span());
                if ($extractor->rationalDifference($sum, $zero) !== null) {
                    return [$sum, $zero];
                }
            }
            if (
                $coshForm !== null
                && $this->isZeroCoefficientList($coshForm[0])
                && (
                    (new ExactPolynomialRootCounter())->countAllRealRoots($coshForm[1]) === 0
                    || $this->trigonometricZerosAvoidRationalPoles($trigCall, $coshForm[1], $extractor, true)
                )
                && $this->containsVariable($trigPhase, $variable)
            ) {
                return [$trigCall, new NumberNode(1, '1', $coshPhase->span())];
            }
            if (
                $leftForm !== null
                && $rightForm !== null
                && $coshForm !== null
                && !$this->isZeroCoefficientList($coshForm[0])
            ) {
                // A nonzero rational phase has only algebraic zeros; nonzero algebraic angles
                // cannot be a multiple of pi.
                if ($trigCall->name === 'sin') {
                    $variableNode = new VariableNode($variable, $coshPhase->span());

                    return [
                        new BinaryOperationNode(
                            BinaryOperator::Add,
                            $variableNode,
                            new NumberNode(1, '1', $coshPhase->span()),
                            $coshPhase->span(),
                        ),
                        $variableNode,
                    ];
                }
                $two = new NumberNode(2, '2', $coshPhase->span());
                $coshSquare = new BinaryOperationNode(BinaryOperator::Power, $coshPhase, $two, $coshPhase->span());
                $trigSquare = new BinaryOperationNode(BinaryOperator::Power, $trigPhase, $two, $trigPhase->span());
                $sum = new BinaryOperationNode(BinaryOperator::Add, $coshSquare, $trigSquare, $coshPhase->span());
                if ($extractor->rationalDifference($sum, $zero) !== null) {
                    return [$sum, $zero];
                }
            }
        }
        if ($leftForm === null || $rightForm === null) {
            return [$left, $right];
        }
        $incompatibleTangentPair = (
            \in_array($left->name, ['atanh', 'arctanh'], true)
            && $right->name === 'acoth'
        ) || (
            $left->name === 'acoth'
            && \in_array($right->name, ['atanh', 'arctanh'], true)
        ) || (
            $left->name === 'tanh'
            && $right->name === 'coth'
        ) || (
            $left->name === 'coth'
            && $right->name === 'tanh'
        );
        if (
            $incompatibleTangentPair
            && $leftForm[1] === $rightForm[1]
            && ($this->containsVariable($leftPhase, $variable) || $this->containsVariable($rightPhase, $variable))
        ) {
            $samePhase = $extractor->rationalDifference($leftPhase, $rightPhase);
            $oppositePhase = $extractor->rationalDifference(
                $leftPhase,
                new UnaryOperationNode(UnaryOperator::Minus, $rightPhase, $rightPhase->span()),
            );
            if (
                ($samePhase !== null && $this->isZeroCoefficientList($samePhase[0]))
                || ($oppositePhase !== null && $this->isZeroCoefficientList($oppositePhase[0]))
            ) {
                $variableNode = new VariableNode($variable, $leftPhase->span());
                $square = new BinaryOperationNode(
                    BinaryOperator::Power,
                    $variableNode,
                    new NumberNode(2, '2', $leftPhase->span()),
                    $leftPhase->span(),
                );

                return [
                    new BinaryOperationNode(
                        BinaryOperator::Add,
                        $square,
                        new NumberNode(1, '1', $leftPhase->span()),
                        $leftPhase->span(),
                    ),
                    new NumberNode(0, '0', $leftPhase->span()),
                ];
            }
        }
        $inverseCoshPair = (
            \in_array($left->name, ['acosh', 'arccosh'], true)
            && $right->name === 'asech'
        ) || (
            $left->name === 'asech'
            && \in_array($right->name, ['acosh', 'arccosh'], true)
        );
        if ($inverseCoshPair && $leftForm[1] === $rightForm[1]) {
            $acoshPhase = \in_array($left->name, ['acosh', 'arccosh'], true) ? $leftPhase : $rightPhase;
            $asechPhase = $left->name === 'asech' ? $leftPhase : $rightPhase;
            $samePhase = $extractor->rationalDifference($acoshPhase, $asechPhase);
            $one = new NumberNode(1, '1', $asechPhase->span());
            if ($samePhase !== null && $this->isZeroCoefficientList($samePhase[0])) {
                return [$acoshPhase, $one];
            }
        }
        $inverseHyperbolicPair = (
            \in_array($left->name, ['asinh', 'arcsinh'], true)
            && $right->name === 'acsch'
        ) || (
            $left->name === 'acsch'
            && \in_array($right->name, ['asinh', 'arcsinh'], true)
        );
        if ($inverseHyperbolicPair) {
            $asinhPhase = \in_array($left->name, ['asinh', 'arcsinh'], true) ? $leftPhase : $rightPhase;
            $acschPhase = $left->name === 'acsch' ? $leftPhase : $rightPhase;
            $product = new BinaryOperationNode(
                BinaryOperator::Multiply,
                $asinhPhase,
                $acschPhase,
                $asinhPhase->span(),
            );
            $one = new NumberNode(1, '1', $product->span());
            if ($extractor->rationalDifference($product, $one) !== null) {
                return [$product, $one];
            }
        }
        if (
            \in_array($left->name, ['sinh', 'tanh'], true)
            && \in_array($right->name, ['sinh', 'tanh'], true)
            && $left->name !== $right->name
            && $leftForm[1] === $rightForm[1]
        ) {
            $samePhase = $extractor->rationalDifference($leftPhase, $rightPhase);
            $oppositePhase = $extractor->rationalDifference(
                $leftPhase,
                new UnaryOperationNode(UnaryOperator::Minus, $rightPhase, $rightPhase->span()),
            );
            if (
                ($samePhase !== null && $this->isZeroCoefficientList($samePhase[0]))
                || ($oppositePhase !== null && $this->isZeroCoefficientList($oppositePhase[0]))
            ) {
                return [$leftPhase, new NumberNode(0, '0', $leftPhase->span())];
            }
        }
        if (
            !\in_array($left->name, ['cosh', 'sech'], true)
            || !\in_array($right->name, ['cosh', 'sech'], true)
        ) {
            return [$left, $right];
        }
        $leftSquare = new BinaryOperationNode(
            BinaryOperator::Power,
            $leftPhase,
            new NumberNode(2, '2', $leftPhase->span()),
            $leftPhase->span(),
        );
        $rightSquare = new BinaryOperationNode(
            BinaryOperator::Power,
            $rightPhase,
            new NumberNode(2, '2', $rightPhase->span()),
            $rightPhase->span(),
        );
        if ($left->name !== $right->name) {
            $sum = new BinaryOperationNode(
                BinaryOperator::Add,
                $leftSquare,
                $rightSquare,
                $leftPhase->span(),
            );
            $zero = new NumberNode(0, '0', $rightPhase->span());
            if ($extractor->rationalDifference($sum, $zero) === null) {
                return [$left, $right];
            }

            return [$sum, $zero];
        }
        if ($extractor->rationalDifference($leftSquare, $rightSquare) === null) {
            return [$left, $right];
        }

        return [
            $leftSquare,
            $rightSquare,
        ];
    }

    /** @param array<string, int|float> $parameters */
    private function constantTargetIsEvaluable(
        Node $target,
        string $variable,
        array $parameters,
        EvaluationOptions $options,
    ): bool {
        try {
            (new \MathPHP\Evaluator\Evaluator(
                new Environment([...$parameters, $variable => 0], $options->functions),
                $options->limits,
            ))->evaluate($target);
        } catch (\Exception) {
            return false;
        }

        return true;
    }

    /** @param array<string, int|float> $parameters */
    private function polynomialPhaseIsEvaluable(
        Node $phase,
        string $variable,
        array $parameters,
        EvaluationOptions $options,
    ): bool {
        try {
            (new \MathPHP\Evaluator\Evaluator(
                new Environment([...$parameters, $variable => 0], $options->functions),
                $options->limits,
            ))->evaluate($phase);
        } catch (\Exception) {
            return false;
        }

        return true;
    }

    /** @param array{string, string} $ratio */
    private function rationalPhaseRatioAvoidsPoles(array $ratio, string $phase): bool
    {
        $parityValue = $phase === 'sin' ? $ratio[1] : $ratio[0];

        return ((int) \substr($parityValue, -1)) % 2 === 1;
    }

    /** @return array{string, string}|null */
    private function polynomialInPhaseConstantTerm(
        Node $expression,
        Node $phase,
        ExactRationalPolynomialExtractor $extractor,
        EvaluationOptions $options,
    ): ?array {
        $expression = $this->unwrapGrouping($expression);
        $constant = $this->exactConstantRational($expression, $extractor);
        if ($constant !== null) {
            return $constant;
        }
        $difference = $extractor->rationalDifference($expression, $phase);
        if ($difference !== null && $this->isZeroCoefficientList($difference[0])) {
            return ['0', '1'];
        }
        if ($expression instanceof UnaryOperationNode) {
            $operand = $this->polynomialInPhaseConstantTerm($expression->operand, $phase, $extractor, $options);
            if ($operand === null || $expression->operator === UnaryOperator::Plus) {
                return $operand;
            }
            return (new ExactRationalInterval(['0', '1'], ['0', '1']))
                ->subtract(new ExactRationalInterval($operand, $operand))->lower;
        }
        if (!$expression instanceof BinaryOperationNode) {
            return null;
        }
        $left = $this->polynomialInPhaseConstantTerm($expression->left, $phase, $extractor, $options);
        if ($left === null) {
            return null;
        }
        $leftInterval = new ExactRationalInterval($left, $left);
        if ($expression->operator === BinaryOperator::Power) {
            $power = $this->exactConstantRational($expression->right, $extractor);
            $integer = $power !== null && $power[1] === '1' ? \filter_var($power[0], FILTER_VALIDATE_INT) : false;
            if (!\is_int($integer) || $integer < 0 || $integer > $options->limits->maxExponentMagnitude) {
                return null;
            }
            $result = new ExactRationalInterval(['1', '1'], ['1', '1']);
            for ($index = 0; $index < $integer; ++$index) {
                $result = $result->multiply($leftInterval);
            }
            return $result->lower;
        }
        if ($expression->operator === BinaryOperator::Divide) {
            $right = $this->exactConstantRational($expression->right, $extractor);
        } else {
            $right = $this->polynomialInPhaseConstantTerm($expression->right, $phase, $extractor, $options);
        }
        if ($right === null) {
            return null;
        }
        $rightInterval = new ExactRationalInterval($right, $right);

        return match ($expression->operator) {
            BinaryOperator::Add => $leftInterval->add($rightInterval)->lower,
            BinaryOperator::Subtract => $leftInterval->subtract($rightInterval)->lower,
            BinaryOperator::Multiply => $leftInterval->multiply($rightInterval)->lower,
            BinaryOperator::Divide => $right[0] === '0' ? null : $leftInterval->divide($rightInterval)->lower,
            default => null,
        };
    }

    /**
     * @param list<array{string, string}> $polynomial
     * @param list<array{string, string}> $phase
     * @return array{string, string}|null
     */
    private function expandedPhaseConstantTerm(array $polynomial, array $phase): ?array
    {
        if (\count($phase) < 2) {
            return null;
        }
        $constant = null;
        $phaseDegree = \count($phase) - 1;
        while (\count($polynomial) > 1) {
            if (\count($polynomial) <= $phaseDegree) {
                return null;
            }
            $remainder = $polynomial;
            $quotient = \array_fill(0, \count($polynomial) - $phaseDegree, ['0', '1']);
            while (\count($remainder) - 1 >= $phaseDegree) {
                $degree = \count($remainder) - 1 - $phaseDegree;
                $leading = $remainder[\count($remainder) - 1];
                $divisor = $phase[$phaseDegree];
                $ratio = (new ExactRationalInterval($leading, $leading))
                    ->divide(new ExactRationalInterval($divisor, $divisor));
                $quotient[$degree] = $ratio->lower;
                foreach ($phase as $index => $coefficient) {
                    $value = $remainder[$degree + $index];
                    $remainder[$degree + $index] = (new ExactRationalInterval($value, $value))
                        ->subtract($ratio->multiply(new ExactRationalInterval($coefficient, $coefficient)))->lower;
                }
                while (\count($remainder) > 1 && $remainder[\count($remainder) - 1][0] === '0') {
                    \array_pop($remainder);
                }
            }
            if (\count($remainder) > 1) {
                return null;
            }
            $constant ??= $remainder[0];
            $polynomial = $quotient;
        }

        return $constant ?? $polynomial[0];
    }

    /** @return array{string, string}|null */
    private function rationalPolynomialPhaseShift(
        Node $factorPhase,
        Node $rootPhase,
        ExactRationalPolynomialExtractor $extractor,
    ): ?array {
        $factor = $extractor->polynomial($factorPhase);
        $root = $extractor->polynomial($rootPhase);
        if ($factor === null || $root === null || \count($root) < 2) {
            return null;
        }
        $referenceDegree = null;
        foreach ($root as $degree => $coefficient) {
            if ($degree > 0 && $coefficient[0] !== '0') {
                $referenceDegree = $degree;
                break;
            }
        }
        if ($referenceDegree === null) {
            return null;
        }
        $factorSlope = $factor[$referenceDegree] ?? ['0', '1'];
        $factorSlopeInterval = new ExactRationalInterval($factorSlope, $factorSlope);
        $rootSlopeInterval = new ExactRationalInterval($root[$referenceDegree], $root[$referenceDegree]);
        $ratio = $factorSlopeInterval->divide($rootSlopeInterval);
        for ($degree = 1, $length = \max(\count($factor), \count($root)); $degree < $length; ++$degree) {
            $factorCoefficient = $factor[$degree] ?? ['0', '1'];
            $rootCoefficient = $root[$degree] ?? ['0', '1'];
            $factorInterval = new ExactRationalInterval($factorCoefficient, $factorCoefficient);
            $rootInterval = new ExactRationalInterval($rootCoefficient, $rootCoefficient);
            if ($factorInterval->subtract($ratio->multiply($rootInterval))->lower[0] !== '0') {
                return null;
            }
        }
        $factorIntercept = new ExactRationalInterval($factor[0], $factor[0]);
        $rootIntercept = new ExactRationalInterval($root[0], $root[0]);

        return $factorIntercept->subtract($ratio->multiply($rootIntercept))->lower;
    }

    /** @return array{string, string}|null */
    private function constantRationalPhaseRatio(
        Node $numerator,
        Node $denominator,
        ExactRationalPolynomialExtractor $extractor,
    ): ?array {
        $quotient = new BinaryOperationNode(BinaryOperator::Divide, $numerator, $denominator, $numerator->span());
        if ($extractor->isConstantRationalFunction($quotient) !== true) {
            return null;
        }
        $form = $extractor->rationalFunction($quotient);
        if ($form === null) {
            return null;
        }
        foreach ($form[1] as $degree => $denominatorCoefficient) {
            if ($denominatorCoefficient[0] === '0') {
                continue;
            }
            $numeratorCoefficient = $form[0][$degree] ?? ['0', '1'];
            $numeratorInterval = new ExactRationalInterval($numeratorCoefficient, $numeratorCoefficient);
            $denominatorInterval = new ExactRationalInterval($denominatorCoefficient, $denominatorCoefficient);

            return $numeratorInterval->divide($denominatorInterval)->lower;
        }

        return null;
    }

    /** @param array<string, int|float> $parameters */
    private function rationalPhaseIsEvaluable(
        Node $phase,
        ExactRationalPolynomialExtractor $extractor,
        string $variable,
        array $parameters,
        EvaluationOptions $options,
    ): bool {
        $zero = new NumberNode(0, '0', $phase->span());
        $form = $extractor->rationalDifference($phase, $zero);
        if ($form === null) {
            foreach ([0, 1, -1, 2, -2] as $point) {
                try {
                    (new \MathPHP\Evaluator\Evaluator(
                        new Environment([...$parameters, $variable => $point], $options->functions),
                        $options->limits,
                    ))->evaluate($phase);

                    return true;
                } catch (\Exception) {
                    continue;
                }
            }

            return false;
        }
        $zeroPhase = new BinaryOperationNode(BinaryOperator::Multiply, $zero, $phase, $phase->span());

        return $this->validZeroRationalPhase($zeroPhase, $form[1], $options, $variable, $parameters);
    }

    /**
     * @param list<string> $denominator
     * @param array<string, int|float> $parameters
     */
    private function validZeroRationalPhase(
        Node $phase,
        array $denominator,
        EvaluationOptions $options,
        string $variable,
        array $parameters,
    ): bool {
        $counter = new ExactPolynomialRootCounter();
        $sampleLimit = \count($denominator) + 16;
        for ($index = 1; $index <= $sampleLimit; ++$index) {
            if ($counter->isRootAt($denominator, [(string) $index, '1']) !== false) {
                continue;
            }
            try {
                return (new \MathPHP\Evaluator\Evaluator(
                    new Environment([...$parameters, $variable => $index], $options->functions),
                    $options->limits,
                ))->evaluate($phase) == 0;
            } catch (\Exception) {
                continue;
            }
        }

        return false;
    }

    /** @param list<string> $names
     *  @param array<string, int|float> $parameters
     */
    private function unwrapUniqueZeroFunctions(
        Node $phase,
        array $names,
        EvaluationOptions $options,
        string $variable,
        array $parameters,
    ): Node {
        $phase = $this->unwrapGrouping($phase);
        while (true) {
            if ($phase instanceof UnaryOperationNode) {
                $phase = $this->unwrapGrouping($phase->operand);
                continue;
            }
            if (
                $phase instanceof FunctionCallNode
                && \in_array($phase->name, $names, true)
                && $options->functions->isBuiltIn($phase->name)
                && \count($phase->arguments) === 1
            ) {
                $phase = $this->unwrapGrouping($phase->arguments[0]);
                continue;
            }
            if (
                $phase instanceof BinaryOperationNode
                && \in_array($phase->operator, [BinaryOperator::Multiply, BinaryOperator::Divide], true)
            ) {
                $candidates = [[$phase->right, $phase->left]];
                if ($phase->operator === BinaryOperator::Multiply) {
                    $candidates[] = [$phase->left, $phase->right];
                }
                foreach ($candidates as [$factor, $remaining]) {
                    if (
                        !$this->containsVariable($factor, $variable)
                        || $options->limits->maxExponentMagnitude < 256
                    ) {
                        continue;
                    }
                    $extractor = new ExactRationalPolynomialExtractor($variable, $parameters, 256, $options);
                    $zero = new NumberNode(0, '0', $factor->span());
                    $remainingZeroPhase = $this->unwrapUniqueZeroFunctions(
                        $remaining,
                        $names,
                        $options,
                        $variable,
                        $parameters,
                    );
                    $factorCall = $this->unwrapGrouping($factor);
                    if (
                        $factorCall instanceof FunctionCallNode
                        && \in_array(
                            $factorCall->name,
                            ['exp', 'cosh', 'sech', 'csch', 'coth', 'erfc', 'erfcx', 'gamma'],
                            true,
                        )
                        && $options->functions->isBuiltIn($factorCall->name)
                        && \count($factorCall->arguments) === 1
                    ) {
                        $argument = $extractor->rationalDifference($factorCall->arguments[0], $zero);
                        $counter = new ExactPolynomialRootCounter();
                        $requiresNonzeroArgument = \in_array($factorCall->name, ['csch', 'coth', 'gamma'], true);
                        $requiresPositiveArgument = $factorCall->name === 'gamma';
                        $nonnegativeArgument = false;
                        $gammaNegativeStrip = false;
                        if ($argument !== null && $requiresPositiveArgument) {
                            $signPolynomial = $this->multiplyIntegerPolynomialCoefficients($argument[0], $argument[1]);
                            if ($signPolynomial !== null) {
                                $arithmetic = new IntegerPolynomialExtractor('', [], 256);
                                $negative = \array_map($arithmetic->negateIntegerValue(...), $signPolynomial);
                                $nonnegativeArgument = $this->polynomialHasPositiveValueOnRealLine($negative) === false;
                            }
                            $gammaNegativeStrip = $this->gammaArgumentInNegativeStrip(
                                $factorCall->arguments[0],
                                $argument[1],
                                $extractor,
                                $options,
                                $variable,
                                $parameters,
                            );
                        }
                        if (
                            $argument !== null
                            && (!$requiresPositiveArgument || $nonnegativeArgument || $gammaNegativeStrip)
                            && (!$requiresNonzeroArgument
                                || (!$this->isZeroCoefficientList($argument[0])
                                    && ($this->rationalPhaseHasNoRealZeros($argument[0], $argument[1])
                                        || $this->trigonometricZerosAvoidRationalPoles(
                                            $remainingZeroPhase,
                                            $argument[0],
                                            $extractor,
                                        ))))
                            && ($counter->countAllRealRoots($argument[1]) === 0
                                || $this->trigonometricZerosAvoidRationalPoles(
                                    $remainingZeroPhase,
                                    $argument[1],
                                    $extractor,
                                ))
                        ) {
                            $sample = null;
                            $sampleCount = \count($argument[1])
                                + ($requiresNonzeroArgument ? \count($argument[0]) - 1 : 0);
                            for ($index = 0; $index < $sampleCount; ++$index) {
                                $point = [(string) $index, '1'];
                                if (
                                    $counter->isRootAt($argument[1], $point) === false
                                    && (!$requiresNonzeroArgument || $counter->isRootAt($argument[0], $point) === false)
                                ) {
                                    $sample = $index;
                                    break;
                                }
                            }
                            if ($sample === null) {
                                continue;
                            }
                            try {
                                $evaluator = new \MathPHP\Evaluator\Evaluator(
                                    new Environment([...$parameters, $variable => $sample], $options->functions),
                                    $options->limits,
                                );
                                $witness = $requiresPositiveArgument
                                    ? $evaluator->evaluate($factorCall->arguments[0]) : 1;
                                $validGammaWitness = $witness > 0 || ($gammaNegativeStrip && $witness < 0);
                                $value = !$requiresPositiveArgument || $validGammaWitness
                                    ? $evaluator->evaluate($factor) : 0;
                            } catch (\Exception) {
                                $value = 0;
                            }
                            if ($value != 0) {
                                $phase = $remainingZeroPhase;
                                continue 2;
                            }
                        }
                    }
                    $form = $extractor->rationalDifference($factor, $zero);
                    $counter = new ExactPolynomialRootCounter();
                    if (
                        $form !== null
                        && !$this->isZeroCoefficientList($form[0])
                        && (
                            $this->rationalPhaseHasNoRealZeros($form[0], $form[1])
                            || ($phase->operator === BinaryOperator::Multiply
                                && $this->rationalZerosIncludedInTrigonometricZeros(
                                    $form[0],
                                    $form[1],
                                    $remainingZeroPhase,
                                    $extractor,
                                ))
                            || ($phase->operator === BinaryOperator::Divide
                                && $this->trigonometricZerosAvoidRationalPoles(
                                    $remainingZeroPhase,
                                    $form[0],
                                    $extractor,
                                ))
                        )
                        && (
                            $counter->countAllRealRoots($form[1]) === 0
                            || $this->trigonometricZerosAvoidRationalPoles($remainingZeroPhase, $form[1], $extractor)
                        )
                    ) {
                        $sample = null;
                        $sampleLimit = \count($form[0]) + \count($form[1]) - 2;
                        for ($index = 0; $index <= $sampleLimit; ++$index) {
                            $candidate = $index % 2 === 0 ? -intdiv($index, 2) : intdiv($index + 1, 2);
                            $point = [(string) $candidate, '1'];
                            if (
                                $counter->isRootAt($form[0], $point) === false
                                && $counter->isRootAt($form[1], $point) === false
                            ) {
                                $sample = $candidate;
                                break;
                            }
                        }
                        if ($sample === null) {
                            continue;
                        }
                        try {
                            $value = (new \MathPHP\Evaluator\Evaluator(
                                new Environment([...$parameters, $variable => $sample], $options->functions),
                                $options->limits,
                            ))->evaluate($factor);
                        } catch (\Exception) {
                            continue;
                        }
                        if ($value == 0) {
                            continue;
                        }
                        $phase = $remainingZeroPhase;
                        continue 2;
                    }
                }
                $constant = $phase->right;
                $operand = $phase->left;
                if ($phase->operator === BinaryOperator::Multiply && $this->containsVariable($constant, $variable)) {
                    [$constant, $operand] = [$operand, $constant];
                }
                if (!$this->containsVariable($constant, $variable)) {
                    $extractor = new ExactRationalPolynomialExtractor($variable, $parameters, 256, $options);
                    $form = $extractor->rationalFunction($constant);
                    try {
                        $value = $form === null ? 0 : (new \MathPHP\Evaluator\Evaluator(
                            new Environment($parameters, $options->functions),
                            $options->limits,
                        ))->evaluate($constant);
                    } catch (\Exception) {
                        break;
                    }
                    if ($form !== null && $form[0][0][0] !== '0' && $value != 0) {
                        $phase = $this->unwrapGrouping($operand);
                        continue;
                    }
                }
            }
            if ($phase instanceof BinaryOperationNode && $phase->operator === BinaryOperator::Power) {
                if ($this->containsVariable($phase->right, $variable)) {
                    break;
                }
                $extractor = new ExactRationalPolynomialExtractor($variable, $parameters, 256, $options);
                $exponent = $extractor->rationalFunction($phase->right);
                try {
                    $evaluatedExponent = $exponent === null ? \INF : (new \MathPHP\Evaluator\Evaluator(
                        new Environment($parameters, $options->functions),
                        $options->limits,
                    ))->evaluate($phase->right);
                } catch (\Exception) {
                    break;
                }
                if (
                    $exponent !== null
                    && \count($exponent[0]) === 1
                    && \count($exponent[1]) === 1
                    && $exponent[0][0][0] !== '0'
                    && $exponent[1][0][0] !== '0'
                    && ($exponent[0][0][0][0] === '-') === ($exponent[1][0][0][0] === '-')
                    && $evaluatedExponent > 0
                    && $evaluatedExponent <= $options->limits->maxExponentMagnitude
                ) {
                    $phase = $this->unwrapGrouping($phase->left);
                    continue;
                }
            }
            break;
        }

        return $phase;
    }

    /** @param list<string> $denominator
     *  @param array<string, int|float> $parameters
     */
    private function gammaArgumentInNegativeStrip(
        Node $phase,
        array $denominator,
        ExactRationalPolynomialExtractor $extractor,
        EvaluationOptions $options,
        string $variable,
        array $parameters,
    ): bool {
        $counter = new ExactPolynomialRootCounter();
        $sample = null;
        for ($index = 0; $index < \count($denominator); ++$index) {
            if ($counter->isRootAt($denominator, [(string) $index, '1']) === false) {
                $sample = $index;
                break;
            }
        }
        if ($sample === null) {
            return false;
        }
        try {
            $value = (new \MathPHP\Evaluator\Evaluator(
                new Environment([...$parameters, $variable => $sample], $options->functions),
                $options->limits,
            ))->evaluate($phase);
        } catch (\Exception) {
            return false;
        }
        if ($value >= 0 || $value < -1000000) {
            return false;
        }
        $strip = (int) \floor(-$value);
        $zero = new NumberNode(0, '0', $phase->span());
        foreach ([$strip, $strip + 1] as $index => $boundary) {
            $shift = new NumberNode($boundary, (string) $boundary, $phase->span());
            $shifted = new BinaryOperationNode(BinaryOperator::Add, $phase, $shift, $phase->span());
            $form = $extractor->rationalDifference($shifted, $zero);
            if ($form === null || !$this->rationalPhaseHasNoRealZeros($form[0], $form[1])) {
                return false;
            }
            $signPolynomial = $this->multiplyIntegerPolynomialCoefficients($form[0], $form[1]);
            if ($signPolynomial === null) {
                return false;
            }
            if ($index === 1) {
                $arithmetic = new IntegerPolynomialExtractor('', [], 256);
                $signPolynomial = \array_map($arithmetic->negateIntegerValue(...), $signPolynomial);
            }
            if ($this->polynomialHasPositiveValueOnRealLine($signPolynomial) !== false) {
                return false;
            }
        }

        return true;
    }

    /** @param list<string> $numerator
     *  @param list<string> $denominator
     */
    private function rationalPhaseHasNoRealZeros(array $numerator, array $denominator): bool
    {
        $counter = new ExactPolynomialRootCounter();
        $zeros = $counter->countAllRealRoots($numerator);
        if ($zeros === null) {
            return false;
        }
        if ($zeros === 0) {
            return true;
        }
        $common = $counter->greatestCommonDivisor($numerator, $denominator);
        if ($common === null || \count($common) < 2) {
            return false;
        }
        $excluded = $counter->countAllRealRoots($common);

        return $excluded !== null && $zeros === $excluded;
    }

    /** @param list<string> $poles */
    private function trigonometricZerosAvoidRationalPoles(
        Node $phase,
        array $poles,
        ExactRationalPolynomialExtractor $extractor,
        bool $unitLevel = false,
    ): bool {
        $phase = $this->unwrapGrouping($phase);
        if (
            !$unitLevel
            && $phase instanceof FunctionCallNode
            && \count($phase->arguments) === 1
            && \in_array(
                $phase->name,
                ['exp', 'cosh', 'sech', 'csch', 'coth', 'sec', 'csc', 'erfc', 'erfcx', 'gamma'],
                true,
            )
        ) {
            return true;
        }
        if (
            !$phase instanceof FunctionCallNode
            || !\in_array($phase->name, ['sin', 'cos', 'tan', 'cot', 'sinc'], true)
            || \count($phase->arguments) !== 1
        ) {
            return false;
        }
        $zero = new NumberNode(0, '0', $phase->span());
        $argument = $extractor->rationalDifference($phase->arguments[0], $zero);
        if ($argument === null) {
            return false;
        }
        if ($unitLevel) {
            if ($phase->name === 'sin') {
                return true;
            }
            if ($phase->name !== 'cos') {
                return false;
            }
            $counter = new ExactPolynomialRootCounter();
            $common = $counter->greatestCommonDivisor($poles, $argument[0]);

            return $common !== null && (\count($common) < 2
                || $this->rationalPhaseHasNoRealZeros($common, $argument[1]));
        }
        // At an algebraic pole, a defined rational argument is algebraic: cosine,
        // cotangent, and sinc cannot vanish; sine and tangent vanish only at zero.
        if (\in_array($phase->name, ['cos', 'cot', 'sinc'], true)) {
            return true;
        }
        $counter = new ExactPolynomialRootCounter();
        $common = $counter->greatestCommonDivisor($poles, $argument[0]);

        return $common !== null && (\count($common) < 2
            || $this->rationalPhaseHasNoRealZeros($common, $argument[1]));
    }

    /** @param list<string> $polynomial
     *  @param list<string> $denominator
     */
    private function rationalZerosIncludedInTrigonometricZeros(
        array $polynomial,
        array $denominator,
        Node $phase,
        ExactRationalPolynomialExtractor $extractor,
    ): bool {
        $phase = $this->unwrapGrouping($phase);
        if (
            !$phase instanceof FunctionCallNode
            || !\in_array($phase->name, ['sin', 'tan'], true)
            || \count($phase->arguments) !== 1
        ) {
            return false;
        }
        $zero = new NumberNode(0, '0', $phase->span());
        $argument = $extractor->rationalDifference($phase->arguments[0], $zero);
        if ($argument === null) {
            return false;
        }
        $covered = $this->multiplyIntegerPolynomialCoefficients($argument[0], $denominator);
        $covered = $covered === null ? null : $this->multiplyIntegerPolynomialCoefficients($covered, $argument[1]);
        if ($covered === null) {
            return false;
        }
        $counter = new ExactPolynomialRootCounter();
        $roots = $counter->countAllRealRoots($polynomial);
        $common = $counter->greatestCommonDivisor($polynomial, $covered);
        if ($roots === null || $common === null) {
            return false;
        }
        $commonRoots = $counter->countAllRealRoots($common);

        return $commonRoots !== null && $roots === $commonRoots;
    }

    /**
     * Recognize acosh(P) = asech(1/P) and preserve poles in both phases.
     *
     * @param array<string, int|float> $parameters
     * @return array{list<string>, list<string>, list<string>}|null
     *   Boundary polynomial, positivity-test polynomial, and combined domain denominator.
     */
    private function reciprocalAcoshAsechBoundaryPolynomial(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        int $maxPolynomialDegree,
    ): ?array {
        $left = $this->unwrapGrouping($left);
        $right = $this->unwrapGrouping($right);
        if (
            !$left instanceof FunctionCallNode
            || !$right instanceof FunctionCallNode
            || \count($left->arguments) !== 1
            || \count($right->arguments) !== 1
        ) {
            return null;
        }
        $acoshCall = \in_array($left->name, ['acosh', 'arccosh'], true) ? $left : $right;
        $asechCall = $left->name === 'asech' ? $left : ($right->name === 'asech' ? $right : null);
        if (
            $asechCall === null
            || !\in_array($acoshCall->name, ['acosh', 'arccosh'], true)
        ) {
            return null;
        }
        $extractor = new ExactRationalPolynomialExtractor($variable, $parameters, $maxPolynomialDegree);
        $acoshPhase = $acoshCall->arguments[0];
        $asechPhase = $asechCall->arguments[0];
        if (
            !$this->containsVariable($acoshPhase, $variable)
            && !$this->containsVariable($asechPhase, $variable)
        ) {
            return null;
        }
        $product = new BinaryOperationNode(
            BinaryOperator::Multiply,
            $acoshPhase,
            $asechPhase,
            $acoshPhase->span(),
        );
        $one = new NumberNode(1, '1', $product->span());
        $reciprocalIdentity = $extractor->rationalDifference($product, $one);
        $boundaryForm = $extractor->rationalDifference($acoshPhase, $one);
        $boundaryPolynomial = $boundaryForm[0] ?? null;
        $positivePolynomial = $boundaryForm === null
            ? null
            : $this->multiplyIntegerPolynomialCoefficients($boundaryForm[0], $boundaryForm[1]);
        $domainDenominator = $reciprocalIdentity[1] ?? null;
        if (
            $reciprocalIdentity === null
            || !$this->isZeroCoefficientList($reciprocalIdentity[0])
            || $boundaryPolynomial === null
            || $positivePolynomial === null
            || $domainDenominator === null
        ) {
            return null;
        }

        return [$boundaryPolynomial, $positivePolynomial, $domainDenominator];
    }

    /** @return array{count: int, rootSign: int, rootKind: 'zero'|'lambert'|'cosine'|'acot'|'acot-reflected'|'asec-reflected'|'asech'|'erfc-positive'|'erfc-reflected'|'erf-triple'|'coth-pair'|'csch-pair'}|null */
    private function elementarySelfEquationRootCount(
        Node $left,
        Node $right,
        string $variable,
        EvaluationOptions $evaluationOptions,
    ): ?array {
        foreach ([[$left, $right], [$right, $left]] as [$functionNode, $variableNode]) {
            $functionNode = $this->unwrapGrouping($functionNode);
            $variableNode = $this->unwrapGrouping($variableNode);
            if (
                !$functionNode instanceof FunctionCallNode
                || \count($functionNode->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($functionNode->name)
            ) {
                continue;
            }
            $argument = $this->unwrapGrouping($functionNode->arguments[0]);
            $target = $this->unwrapGrouping($variableNode);
            $argumentSign = $this->signedVariable($argument, $variable);
            $targetSign = $this->signedVariable($target, $variable);
            if ($argumentSign === null || $targetSign === null) {
                continue;
            }

            return match ($functionNode->name) {
                'sin', 'sinh', 'asinh', 'arcsinh', 'atan', 'arctan', 'tanh', 'log1p', 'expm1',
                'asin', 'arcsin', 'atanh', 'arctanh' => [
                    'count' => 1,
                    'rootSign' => 0,
                    'rootKind' => 'zero',
                ],
                'cos' => [
                    'count' => 1,
                    'rootSign' => $targetSign,
                    'rootKind' => 'cosine',
                ],
                'acos', 'arccos' => $argumentSign === $targetSign
                    ? ['count' => 1, 'rootSign' => $targetSign, 'rootKind' => 'cosine']
                    : ['count' => 0, 'rootSign' => 0, 'rootKind' => 'zero'],
                'acot' => [
                    'count' => 1,
                    'rootSign' => $targetSign,
                    'rootKind' => $argumentSign === $targetSign ? 'acot' : 'acot-reflected',
                ],
                'asec' => $argumentSign !== $targetSign
                    ? ['count' => 1, 'rootSign' => $targetSign, 'rootKind' => 'asec-reflected']
                    : ['count' => 0, 'rootSign' => 0, 'rootKind' => 'zero'],
                'acsc' => ['count' => 0, 'rootSign' => 0, 'rootKind' => 'zero'],
                'asech' => $argumentSign === $targetSign
                    ? ['count' => 1, 'rootSign' => $targetSign, 'rootKind' => 'asech']
                    : ['count' => 0, 'rootSign' => 0, 'rootKind' => 'zero'],
                'erfc' => [
                    'count' => 1,
                    'rootSign' => $targetSign,
                    'rootKind' => $argumentSign === $targetSign ? 'erfc-positive' : 'erfc-reflected',
                ],
                'erf', 'erfinv' => $argumentSign === $targetSign
                    ? ['count' => 3, 'rootSign' => 0, 'rootKind' => 'erf-triple']
                    : ['count' => 1, 'rootSign' => 0, 'rootKind' => 'zero'],
                'acsch', 'acoth' => $argumentSign === $targetSign
                    ? [
                        'count' => 2,
                        'rootSign' => 0,
                        'rootKind' => $functionNode->name === 'acoth' ? 'coth-pair' : 'csch-pair',
                    ]
                    : ['count' => 0, 'rootSign' => 0, 'rootKind' => 'zero'],
                'cosh' => [
                    'count' => 0,
                    'rootSign' => 0,
                    'rootKind' => 'zero',
                ],
                'acosh', 'arccosh' => [
                    'count' => 0,
                    'rootSign' => 0,
                    'rootKind' => 'zero',
                ],
                'coth', 'csch' => $argumentSign === $targetSign
                    ? [
                        'count' => 2,
                        'rootSign' => 0,
                        'rootKind' => $functionNode->name === 'coth' ? 'coth-pair' : 'csch-pair',
                    ]
                    : ['count' => 0, 'rootSign' => 0, 'rootKind' => 'zero'],
                'ln' => $argumentSign === $targetSign
                    ? ['count' => 0, 'rootSign' => 0, 'rootKind' => 'zero']
                    : ['count' => 1, 'rootSign' => $argumentSign, 'rootKind' => 'lambert'],
                'exp' => $argumentSign === $targetSign
                    ? ['count' => 0, 'rootSign' => 0, 'rootKind' => 'zero']
                    : ['count' => 1, 'rootSign' => -$argumentSign, 'rootKind' => 'lambert'],
                default => null,
            };
        }

        return null;
    }

    /**
     * Isolate the unique positive solution of y*exp(y)=1, then reflect it for a negative root.
     *
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @param array{string, string} $maximumWidth
     * @return array{array{string, string}, array{string, string}}|false|null
     */
    private function isolateLambertSelfRootInOpenInterval(
        int $rootSign,
        array $lower,
        array $upper,
        int $maxDepth,
        array $maximumWidth,
    ): array|false|null {
        $yLower = $rootSign > 0 ? $lower : (new ExactRationalInterval($upper, $upper))->negateInterval()->lower;
        $yUpper = $rootSign > 0 ? $upper : (new ExactRationalInterval($lower, $lower))->negateInterval()->upper;
        $zero = ['0', '1'];
        $one = ['1', '1'];
        if (
            $this->compareRationalFractions($yUpper, $zero) <= 0
            || $this->compareRationalFractions($yLower, $one) >= 0
        ) {
            return false;
        }
        if ($this->compareRationalFractions($yLower, $zero) < 0) {
            $yLower = $zero;
        }
        if ($this->compareRationalFractions($yUpper, $one) > 0) {
            $yUpper = $one;
        }
        if ($this->compareRationalFractions($yLower, $yUpper) >= 0) {
            return false;
        }

        $seedLower = ['638546577838794', '1125899906842624'];
        $seedUpper = ['638546577838795', '1125899906842624'];
        $lowerSign = null;
        $upperSign = null;
        if (
            $this->compareRationalFractions($yLower, $seedLower) <= 0
            && $this->compareRationalFractions($yUpper, $seedUpper) >= 0
        ) {
            $seedLowerSign = $this->lambertSelfResidualSign($seedLower);
            $seedUpperSign = $this->lambertSelfResidualSign($seedUpper);
            if ($seedLowerSign === -1 && $seedUpperSign === 1) {
                $yLower = $seedLower;
                $yUpper = $seedUpper;
                $lowerSign = $seedLowerSign;
                $upperSign = $seedUpperSign;
            }
        }
        $lowerSign ??= $this->lambertSelfResidualSign($yLower);
        $upperSign ??= $this->lambertSelfResidualSign($yUpper);
        if ($lowerSign === null || $upperSign === null) {
            return null;
        }
        if ($lowerSign >= 0 || $upperSign <= 0) {
            return false;
        }
        for ($depth = 0; $depth < $maxDepth; ++$depth) {
            $width = (new ExactRationalInterval($yUpper, $yUpper))
                ->subtract(new ExactRationalInterval($yLower, $yLower));
            if ($width->compareUpperToRational($maximumWidth[0], $maximumWidth[1]) <= 0) {
                return [$yLower, $yUpper];
            }
            $midpoint = (new ExactRationalInterval($yLower, $yLower))
                ->add(new ExactRationalInterval($yUpper, $yUpper))
                ->divide(new ExactRationalInterval(['2', '1'], ['2', '1']))->lower;
            $midpointSign = $this->lambertSelfResidualSign($midpoint);
            if ($midpointSign === null) {
                return null;
            }
            if ($midpointSign < 0) {
                $yLower = $midpoint;
            } else {
                $yUpper = $midpoint;
            }
        }

        return null;
    }

    /** @param array{string, string} $point */
    private function lambertSelfResidualSign(array $point): ?int
    {
        $value = new ExactRationalInterval($point, $point);
        $residual = $value->multiply($value->exp())
            ->subtract(new ExactRationalInterval(['1', '1'], ['1', '1']));
        if ($residual->compareUpperToRational('0', '1') < 0) {
            return -1;
        }
        if ($residual->compareLowerToRational('0', '1') > 0) {
            return 1;
        }

        return null;
    }

    /**
     * Isolate the unique positive fixed point of cosine, then reflect it if needed.
     *
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @param array{string, string} $maximumWidth
     * @return array{array{string, string}, array{string, string}}|false|null
     */
    private function isolateCosineSelfRootInOpenInterval(
        int $rootSign,
        array $lower,
        array $upper,
        int $maxDepth,
        array $maximumWidth,
    ): array|false|null {
        $yLower = $rootSign > 0 ? $lower : (new ExactRationalInterval($upper, $upper))->negateInterval()->lower;
        $yUpper = $rootSign > 0 ? $upper : (new ExactRationalInterval($lower, $lower))->negateInterval()->upper;
        $zero = ['0', '1'];
        $one = ['1', '1'];
        if (
            $this->compareRationalFractions($yUpper, $zero) <= 0
            || $this->compareRationalFractions($yLower, $one) >= 0
        ) {
            return false;
        }
        if ($this->compareRationalFractions($yLower, $zero) < 0) {
            $yLower = $zero;
        }
        if ($this->compareRationalFractions($yUpper, $one) > 0) {
            $yUpper = $one;
        }
        if ($this->compareRationalFractions($yLower, $yUpper) >= 0) {
            return false;
        }

        $seedLower = ['739085133', '1000000000'];
        $seedUpper = ['739085134', '1000000000'];
        $lowerSign = null;
        $upperSign = null;
        if (self::$cosineSelfRootSeedSigns === null) {
            self::$cosineSelfRootSeedSigns = [
                $this->cosineSelfResidualSign($seedLower) ?? 0,
                $this->cosineSelfResidualSign($seedUpper) ?? 0,
            ];
        }
        if (
            $this->compareRationalFractions($yLower, $seedLower) <= 0
            && $this->compareRationalFractions($yUpper, $seedUpper) >= 0
        ) {
            [$seedLowerSign, $seedUpperSign] = self::$cosineSelfRootSeedSigns;
            if ($seedLowerSign === 1 && $seedUpperSign === -1) {
                $yLower = $seedLower;
                $yUpper = $seedUpper;
                $lowerSign = $seedLowerSign;
                $upperSign = $seedUpperSign;
            }
        }
        $lowerSign ??= $this->cosineSelfResidualSign($yLower);
        $upperSign ??= $this->cosineSelfResidualSign($yUpper);
        if ($lowerSign === null || $upperSign === null) {
            return null;
        }
        if ($lowerSign <= 0 || $upperSign >= 0) {
            return false;
        }
        for ($depth = 0; $depth < $maxDepth; ++$depth) {
            $width = (new ExactRationalInterval($yUpper, $yUpper))
                ->subtract(new ExactRationalInterval($yLower, $yLower));
            if ($width->compareUpperToRational($maximumWidth[0], $maximumWidth[1]) <= 0) {
                return [$yLower, $yUpper];
            }
            $midpoint = (new ExactRationalInterval($yLower, $yLower))
                ->add(new ExactRationalInterval($yUpper, $yUpper))
                ->divide(new ExactRationalInterval(['2', '1'], ['2', '1']))->lower;
            $midpointSign = $this->cosineSelfResidualSign($midpoint);
            if ($midpointSign === null) {
                return null;
            }
            if ($midpointSign > 0) {
                $yLower = $midpoint;
            } else {
                $yUpper = $midpoint;
            }
        }

        return null;
    }

    /** @param array{string, string} $point */
    private function cosineSelfResidualSign(array $point): ?int
    {
        $value = new ExactRationalInterval($point, $point);
        $residual = $value->acos()->subtract($value);
        if ($residual->compareLowerToRational('0', '1') > 0) {
            return 1;
        }
        if ($residual->compareUpperToRational('0', '1') < 0) {
            return -1;
        }

        return null;
    }

    /**
     * Isolate the unique positive fixed point of asech using y*cosh(y)=1.
     *
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @param array{string, string} $maximumWidth
     * @return array{array{string, string}, array{string, string}}|false|null
     */
    private function isolateAsechSelfRootInOpenInterval(
        int $rootSign,
        array $lower,
        array $upper,
        int $maxDepth,
        array $maximumWidth,
    ): array|false|null {
        $yLower = $rootSign > 0 ? $lower : (new ExactRationalInterval($upper, $upper))->negateInterval()->lower;
        $yUpper = $rootSign > 0 ? $upper : (new ExactRationalInterval($lower, $lower))->negateInterval()->upper;
        $zero = ['0', '1'];
        $one = ['1', '1'];
        if (
            $this->compareRationalFractions($yUpper, $zero) <= 0
            || $this->compareRationalFractions($yLower, $one) >= 0
        ) {
            return false;
        }
        if ($this->compareRationalFractions($yLower, $zero) < 0) {
            $yLower = $zero;
        }
        if ($this->compareRationalFractions($yUpper, $one) > 0) {
            $yUpper = $one;
        }

        $seedLower = ['765009954', '1000000000'];
        $seedUpper = ['765009955', '1000000000'];
        if (self::$asechSelfRootSeedSigns === null) {
            self::$asechSelfRootSeedSigns = [
                $this->asechSelfResidualSign($seedLower) ?? 0,
                $this->asechSelfResidualSign($seedUpper) ?? 0,
            ];
        }
        $lowerSign = null;
        $upperSign = null;
        if (
            $this->compareRationalFractions($yLower, $seedLower) <= 0
            && $this->compareRationalFractions($yUpper, $seedUpper) >= 0
        ) {
            [$seedLowerSign, $seedUpperSign] = self::$asechSelfRootSeedSigns;
            if ($seedLowerSign === -1 && $seedUpperSign === 1) {
                $yLower = $seedLower;
                $yUpper = $seedUpper;
                $lowerSign = $seedLowerSign;
                $upperSign = $seedUpperSign;
            }
        }
        $lowerSign ??= $this->asechSelfResidualSign($yLower);
        $upperSign ??= $this->asechSelfResidualSign($yUpper);
        if ($lowerSign === null || $upperSign === null) {
            return null;
        }
        if ($lowerSign >= 0 || $upperSign <= 0) {
            return false;
        }
        for ($depth = 0; $depth < $maxDepth; ++$depth) {
            $width = (new ExactRationalInterval($yUpper, $yUpper))
                ->subtract(new ExactRationalInterval($yLower, $yLower));
            if ($width->compareUpperToRational($maximumWidth[0], $maximumWidth[1]) <= 0) {
                return [$yLower, $yUpper];
            }
            $midpoint = (new ExactRationalInterval($yLower, $yLower))
                ->add(new ExactRationalInterval($yUpper, $yUpper))
                ->divide(new ExactRationalInterval(['2', '1'], ['2', '1']))->lower;
