    /**
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @param array{string, string} $maximumWidth
     * @return list<RationalRootInterval>|null
     */
    private function isolateErfFixedPointRootsInInterval(
        array $lower,
        array $upper,
        int $maxDepth,
        array $maximumWidth,
    ): ?array {
        $roots = [];
        $negativeRoot = $this->isolateErfFixedPointBranch(-1, $lower, $upper, $maxDepth, $maximumWidth);
        if ($negativeRoot === null) {
            return null;
        }
        if ($negativeRoot !== false) {
            $roots[] = $this->selfEquationRootInterval($negativeRoot, -1);
        }
        if (
            $this->compareRationalFractions($lower, ['0', '1']) < 0
            && $this->compareRationalFractions($upper, ['0', '1']) > 0
        ) {
            $roots[] = new RationalRootInterval('0', '1', '0', '1', true);
        }
        $positiveRoot = $this->isolateErfFixedPointBranch(1, $lower, $upper, $maxDepth, $maximumWidth);
        if ($positiveRoot === null) {
            return null;
        }
        if ($positiveRoot !== false) {
            $roots[] = $this->selfEquationRootInterval($positiveRoot, 1);
        }

        return $roots;
    }

