     * @param array{string, string} $maximumWidth
     * @return array{array{string, string}, array{string, string}}|false|null
     */
    private function isolateErfFixedPointBranch(
        int $rootSign,
        array $lower,
        array $upper,
        int $maxDepth,
        array $maximumWidth,
    ): array|false|null {
        $yLower = $rootSign > 0 ? $lower : (new ExactRationalInterval($upper, $upper))->negateInterval()->lower;
        $yUpper = $rootSign > 0 ? $upper : (new ExactRationalInterval($lower, $lower))->negateInterval()->upper;
        $zero = ['0', '1'];
        $one = ['1', '1'];
        if (
            $this->compareRationalFractions($yUpper, $zero) <= 0
            || $this->compareRationalFractions($yLower, $one) >= 0
        ) {
            return false;
        }
        if ($this->compareRationalFractions($yLower, $zero) < 0) {
            $yLower = $zero;
        }
        if ($this->compareRationalFractions($yUpper, $one) > 0) {
            $yUpper = $one;
        }

        $seedLower = ['6174468', '10000000'];
        $seedUpper = ['6174470', '10000000'];
        if (self::$erfSelfRootSeedSigns === null) {
            self::$erfSelfRootSeedSigns = [
                $this->erfSelfResidualSign($seedLower) ?? 0,
                $this->erfSelfResidualSign($seedUpper) ?? 0,
            ];
        }
        $lowerSign = null;
        $upperSign = null;
        if (
            $this->compareRationalFractions($yLower, $seedLower) <= 0
