        ) {
            [$seedLowerSign, $seedUpperSign] = self::$erfSelfRootSeedSigns;
            if ($seedLowerSign === 1 && $seedUpperSign === -1) {
                $yLower = $seedLower;
                $yUpper = $seedUpper;
                $lowerSign = $seedLowerSign;
                $upperSign = $seedUpperSign;
            }
        }
        if ($lowerSign === null) {
            $lowerSign = $this->compareRationalFractions($yLower, $zero) === 0
                ? 1
                : $this->erfSelfResidualSign($yLower);
        }
        $upperSign ??= $this->erfSelfResidualSign($yUpper);
        if ($lowerSign === null || $upperSign === null) {
            return null;
        }
        if ($lowerSign <= 0 || $upperSign >= 0) {
            return false;
        }
        for ($depth = 0; $depth < $maxDepth; ++$depth) {
            $width = (new ExactRationalInterval($yUpper, $yUpper))
                ->subtract(new ExactRationalInterval($yLower, $yLower));
            if ($width->compareUpperToRational($maximumWidth[0], $maximumWidth[1]) <= 0) {
                return [$yLower, $yUpper];
            }
            $midpoint = (new ExactRationalInterval($yLower, $yLower))
                ->add(new ExactRationalInterval($yUpper, $yUpper))
                ->divide(new ExactRationalInterval(['2', '1'], ['2', '1']))->lower;
            $midpointSign = $this->erfSelfResidualSign($midpoint);
            if ($midpointSign === null) {
                return null;
            }
            if ($midpointSign > 0) {
                $yLower = $midpoint;
            } else {
                $yUpper = $midpoint;
            }
        }

        return null;
    }

    /** @param array{string, string} $point */
    private function erfSelfResidualSign(array $point): ?int
    {
        $value = new ExactRationalInterval($point, $point);
        foreach ([8, 12] as $precision) {
            $residual = $value->erf($precision)->subtract($value);
            if ($residual->compareLowerToRational('0', '1') > 0) {
                return 1;
            }
            if ($residual->compareUpperToRational('0', '1') < 0) {
                return -1;
            }
        }

        return null;
    }

    /**
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @param array{string, string} $maximumWidth
     * @return list<RationalRootInterval>|null
     */
    private function isolateReciprocalHyperbolicSelfRootsInInterval(
        string $family,
        array $lower,
        array $upper,
        int $maxDepth,
        array $maximumWidth,
    ): ?array {
        $roots = [];
        foreach ([-1, 1] as $rootSign) {
            $root = $this->isolateReciprocalHyperbolicSelfRootInOpenInterval(
                $family,
                $rootSign,
                $lower,
                $upper,
                $maxDepth,
                $maximumWidth,
            );
            if ($root === null) {
                return null;
            }
            if ($root !== false) {
                $roots[] = $this->selfEquationRootInterval($root, $rootSign);
            }
        }

        return $roots;
    }

    /**
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     */
    private function countReciprocalHyperbolicSelfRootsInInterval(
        string $family,
        array $lower,
        array $upper,
    ): ?int {
        $roots = $this->isolateReciprocalHyperbolicSelfRootsInInterval(
            $family,
            $lower,
            $upper,
            256,
            ['1', '1000000'],
        );

        return $roots === null ? null : \count($roots);
    }

    /**
     * @param array{string, string} $lower
     * @param array{string, string} $upper
     * @param array{string, string} $maximumWidth
     * @return array{array{string, string}, array{string, string}}|false|null
     */
    private function isolateReciprocalHyperbolicSelfRootInOpenInterval(
        string $family,
        int $rootSign,
        array $lower,
        array $upper,
        int $maxDepth,
        array $maximumWidth,
    ): array|false|null {
        $yLower = $rootSign > 0 ? $lower : (new ExactRationalInterval($upper, $upper))->negateInterval()->lower;
        $yUpper = $rootSign > 0 ? $upper : (new ExactRationalInterval($lower, $lower))->negateInterval()->upper;
        $isCoth = $family === 'coth';
        $minimum = $isCoth ? ['1', '1'] : ['0', '1'];
        $maximum = $isCoth ? ['2', '1'] : ['1', '1'];
        if (
            $this->compareRationalFractions($yUpper, $minimum) <= 0
            || $this->compareRationalFractions($yLower, $maximum) >= 0
        ) {
            return false;
        }
        if ($this->compareRationalFractions($yLower, $minimum) < 0) {
            $yLower = $minimum;
        }
        if ($this->compareRationalFractions($yUpper, $maximum) > 0) {
            $yUpper = $maximum;
        }

        $seedLower = $isCoth ? ['1199678640', '1000000000'] : ['932020029', '1000000000'];
        $seedUpper = $isCoth ? ['1199678641', '1000000000'] : ['932020030', '1000000000'];
        $lowerSign = null;
        $upperSign = null;
        if (
            $this->compareRationalFractions($yLower, $seedLower) <= 0
            && $this->compareRationalFractions($yUpper, $seedUpper) >= 0
        ) {
            if (!isset(self::$reciprocalHyperbolicSelfRootSeedSigns[$family])) {
                self::$reciprocalHyperbolicSelfRootSeedSigns[$family] = [
                    $this->reciprocalHyperbolicSelfResidualSign($seedLower, $family) ?? 0,
                    $this->reciprocalHyperbolicSelfResidualSign($seedUpper, $family) ?? 0,
                ];
            }
            [$seedLowerSign, $seedUpperSign] = self::$reciprocalHyperbolicSelfRootSeedSigns[$family];
            if ($seedLowerSign === -1 && $seedUpperSign === 1) {
                $yLower = $seedLower;
                $yUpper = $seedUpper;
                $lowerSign = $seedLowerSign;
                $upperSign = $seedUpperSign;
            }
        }
        $lowerSign ??= $this->reciprocalHyperbolicSelfResidualSign($yLower, $family);
        $upperSign ??= $this->reciprocalHyperbolicSelfResidualSign($yUpper, $family);
        if ($lowerSign === null || $upperSign === null) {
            return null;
        }
        if ($lowerSign >= 0 || $upperSign <= 0) {
            return false;
        }
        for ($depth = 0; $depth < $maxDepth; ++$depth) {
            $width = (new ExactRationalInterval($yUpper, $yUpper))
                ->subtract(new ExactRationalInterval($yLower, $yLower));
            if ($width->compareUpperToRational($maximumWidth[0], $maximumWidth[1]) <= 0) {
                return [$yLower, $yUpper];
            }
            $midpoint = (new ExactRationalInterval($yLower, $yLower))
                ->add(new ExactRationalInterval($yUpper, $yUpper))
                ->divide(new ExactRationalInterval(['2', '1'], ['2', '1']))->lower;
            $midpointSign = $this->reciprocalHyperbolicSelfResidualSign($midpoint, $family);
            if ($midpointSign === null) {
                return null;
            }
            if ($midpointSign < 0) {
                $yLower = $midpoint;
            } else {
                $yUpper = $midpoint;
            }
        }

        return null;
    }

    /** @param array{string, string} $point */
    private function reciprocalHyperbolicSelfResidualSign(array $point, string $family): ?int
    {
        $value = new ExactRationalInterval($point, $point);
        $hyperbolic = $family === 'coth' ? $value->tanh() : $value->sinh();
        $residual = $value->multiply($hyperbolic)
            ->subtract(new ExactRationalInterval(['1', '1'], ['1', '1']));
        if ($residual->compareUpperToRational('0', '1') < 0) {
            return -1;
        }
        if ($residual->compareLowerToRational('0', '1') > 0) {
            return 1;
        }

        return null;
    }

    /**
     * @param array{array{string, string}, array{string, string}} $root
     */
    private function selfEquationRootInterval(array $root, int $rootSign): RationalRootInterval
    {
        if ($rootSign > 0) {
            return new RationalRootInterval($root[0][0], $root[0][1], $root[1][0], $root[1][1]);
        }
        $negative = (new ExactRationalInterval($root[0], $root[1]))->negateInterval();

        return new RationalRootInterval(
            $negative->lower[0],
            $negative->lower[1],
            $negative->upper[0],
            $negative->upper[1],
        );
    }

    private function signedVariable(Node $node, string $variable): ?int
    {
        $node = $this->unwrapGrouping($node);
        if ($node instanceof VariableNode && $node->name === $variable) {
            return 1;
        }
        if (!$node instanceof UnaryOperationNode || $node->operator !== UnaryOperator::Minus) {
            return null;
        }
        $operand = $this->unwrapGrouping($node->operand);

        return $operand instanceof VariableNode && $operand->name === $variable ? -1 : null;
    }

    private function normalizeIntegerString(string $value): string
    {
        $negative = $value[0] === '-';
        if ($value[0] === '-' || $value[0] === '+') {
            $value = \substr($value, 1);
        }
        $value = \ltrim($value, '0');
        if ($value === '') {
            return '0';
        }

        return $negative ? '-' . $value : $value;
    }

    /**
     * Detect restricted inverse identities on a certified open subinterval.
     *
     * @param array<string, int|float> $parameters
     * @param array{array{string, string}, array{string, string}}|null $intervalBounds
     */
    private function hasInfiniteRestrictedInverseIdentity(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
        ?array $intervalBounds = null,
    ): bool {
        $compositions = [
            'sin' => ['asin', [[['-1', '1'], ['1', '1']]]],
            'cos' => ['acos', [[['-1', '1'], ['1', '1']]]],
            'tanh' => ['atanh', [[['-1', '1'], ['1', '1']]]],
            'cosh' => ['acosh', [[['1', '1'], ['10', '1']]]],
            'coth' => ['acoth', [[['3', '2'], ['10', '1']], [['-10', '1'], ['-3', '2']]]],
            'csch' => ['acsch', [[['1', '4'], ['2', '1']], [['-2', '1'], ['-1', '4']]]],
            'sec' => ['asec', [[['3', '2'], ['10', '1']], [['-10', '1'], ['-3', '2']]]],
            'csc' => ['acsc', [[['3', '2'], ['10', '1']], [['-10', '1'], ['-3', '2']]]],
            'sech' => ['asech', [[['1', '4'], ['3', '4']]]],
            'erf' => ['erfinv', [[['-1', '2'], ['1', '2']]]],
            'erfc' => ['erfcinv', [[['1', '2'], ['3', '2']]]],
            'exp' => ['ln', [[['1', '4'], ['10', '1']]]],
            'expm1' => ['log1p', [[['-1', '2'], ['10', '1']]]],
            'asin' => ['sin', [[['-1', '1'], ['1', '1']]]],
            'arcsin' => ['sin', [[['-1', '1'], ['1', '1']]]],
            'acos' => ['cos', [[['0', '1'], ['1', '1']]]],
            'atan' => ['tan', [[['-1', '1'], ['1', '1']]]],
            'arctan' => ['tan', [[['-1', '1'], ['1', '1']]]],
            'acot' => ['cot', [[['1', '4'], ['1', '1']]]],
            'asec' => ['sec', [[['1', '4'], ['1', '1']]]],
            'acsc' => ['csc', [[['1', '4'], ['1', '1']]]],
            'acosh' => ['cosh', [[['1', '4'], ['10', '1']]]],
            'acsch' => ['csch', [[['1', '4'], ['2', '1']], [['-2', '1'], ['-1', '4']]]],
            'acoth' => ['coth', [[['1', '4'], ['10', '1']], [['-10', '1'], ['-1', '4']]]],
            'asech' => ['sech', [[['1', '4'], ['1', '1']]]],
        ];
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            $target = $this->unwrapGrouping($target);
            if (
                !$candidate instanceof FunctionCallNode
                || \count($candidate->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($candidate->name)
            ) {
                continue;
            }
            $outerName = $candidate->name;
            $inner = $this->unwrapGrouping($candidate->arguments[0]);
            $composition = $compositions[$outerName] ?? null;
            if (
                $composition === null
                || !$inner instanceof FunctionCallNode
                || $inner->name !== $composition[0]
                || \count($inner->arguments) !== 1
                || !$evaluationOptions->functions->isBuiltIn($inner->name)
            ) {
                continue;
            }
            $argument = $inner->arguments[0];
            $form = $extractor->rationalFunction($argument);
            $targetForm = $extractor->rationalFunction($target);
            $difference = $extractor->rationalDifference($argument, $target);
            if (
                $form === null
                || $targetForm === null
                || $difference === null
                || !$this->isZeroCoefficientList($difference[0])
            ) {
                continue;
            }
            foreach ($composition[1] as [$minimum, $maximum]) {
                if ($this->hasRationalFormsInRange([$form], $minimum, $maximum, $intervalBounds)) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Detect function identities with infinitely many valid points.
     *
     * @param array<string, int|float> $parameters
     * @param array{array{string, string}, array{string, string}}|null $intervalBounds
     */
    private function hasInfiniteIdenticalFunctionEquation(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
        ?array $intervalBounds = null,
    ): bool {
        $polygammaCall = $left instanceof FunctionCallNode && $left->name === 'polygamma';
        $variadicTotalCall = $left instanceof FunctionCallNode && \in_array($left->name, ['min', 'max'], true);
        $besselCall = $left instanceof FunctionCallNode && \in_array($left->name, ['besselj', 'besseli'], true);
        $atan2Call = $left instanceof FunctionCallNode && $left->name === 'atan2';
        $betaCall = $left instanceof FunctionCallNode && $left->name === 'beta';
        $rootCall = $left instanceof FunctionCallNode && $left->name === 'root';
        $expectedArity = $left instanceof FunctionCallNode
            && ($left->name === 'hypot' || $besselCall || $atan2Call || $betaCall || $rootCall)
            ? 2
            : ($variadicTotalCall ? null : ($polygammaCall ? 2 : 1));
        if (
            !$left instanceof FunctionCallNode
            || !$right instanceof FunctionCallNode
            || $left->name !== $right->name
            || \count($left->arguments) !== \count($right->arguments)
            || ($expectedArity !== null && \count($left->arguments) !== $expectedArity)
            || ($variadicTotalCall && \count($left->arguments) < 1)
            || !$evaluationOptions->functions->isBuiltIn($left->name)
        ) {
            return false;
        }
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        if ($rootCall) {
            $leftDegree = $this->exactConstantRational($left->arguments[1], $extractor);
            $rightDegree = $this->exactConstantRational($right->arguments[1], $extractor);
            if (
                $leftDegree === null
                || $leftDegree !== $rightDegree
                || $leftDegree[1] !== '1'
            ) {
                return false;
            }
            $degree = \filter_var($leftDegree[0], FILTER_VALIDATE_INT);
            if ($degree === false || $degree === 0 || \abs($degree) > 9_007_199_254_740_991) {
                return false;
            }
            $leftForm = $extractor->rationalFunction($left->arguments[0]);
            $rightForm = $extractor->rationalFunction($right->arguments[0]);
            $difference = $extractor->rationalDifference($left->arguments[0], $right->arguments[0]);
            if (
                $leftForm === null
                || $rightForm === null
                || $difference === null
                || !$this->isZeroCoefficientList($difference[0])
            ) {
                return false;
            }

            return $this->hasRationalFormsInRange(
                [$leftForm, $rightForm],
                ['1', '4'],
                ['2', '1'],
                $intervalBounds,
            );
        }
        if ($besselCall) {
            $leftOrder = $this->exactConstantRational($left->arguments[0], $extractor);
            $rightOrder = $this->exactConstantRational($right->arguments[0], $extractor);
            if (
                $leftOrder === null
                || $leftOrder !== $rightOrder
                || $leftOrder[1] !== '1'
            ) {
                return false;
            }
            $order = \filter_var($leftOrder[0], FILTER_VALIDATE_INT);
            if (!\is_int($order) || \abs($order) > SpecialFunctions::MAX_BESSEL_ORDER) {
                return false;
            }
            $leftForm = $extractor->rationalFunction($left->arguments[1]);
            $rightForm = $extractor->rationalFunction($right->arguments[1]);
            $difference = $extractor->rationalDifference($left->arguments[1], $right->arguments[1]);
            if (
                $leftForm === null
                || $rightForm === null
                || $difference === null
                || !$this->isZeroCoefficientList($difference[0])
            ) {
                return false;
            }
            $argumentLimit = $left->name === 'besselj'
                ? SpecialFunctions::MAX_BESSEL_J_ARGUMENT
                : SpecialFunctions::MAX_BESSEL_I_ARGUMENT;

            return $this->hasBoundedRationalWitness($leftForm, $rightForm, $argumentLimit, $intervalBounds);
        }
        if ($atan2Call) {
            $hasNonzeroArgument = false;
            foreach ($left->arguments as $index => $leftArgument) {
                $leftForm = $extractor->rationalFunction($leftArgument);
                $rightForm = $extractor->rationalFunction($right->arguments[$index]);
                $difference = $extractor->rationalDifference($leftArgument, $right->arguments[$index]);
                if (
                    $leftForm === null
                    || $rightForm === null
                    || $difference === null
                    || !$this->isZeroCoefficientList($difference[0])
                ) {
                    return false;
                }
                foreach ($leftForm[0] as $coefficient) {
                    if ($coefficient[0] !== '0') {
                        $hasNonzeroArgument = true;
                        break;
                    }
                }
            }

            return $hasNonzeroArgument;
        }
        if ($betaCall) {
            $leftForms = [];
            $rightForms = [];
            foreach ($left->arguments as $index => $leftArgument) {
                $leftForm = $extractor->rationalFunction($leftArgument);
                $rightForm = $extractor->rationalFunction($right->arguments[$index]);
                $difference = $extractor->rationalDifference($leftArgument, $right->arguments[$index]);
                if (
                    $leftForm === null
                    || $rightForm === null
                    || $difference === null
                    || !$this->isZeroCoefficientList($difference[0])
                ) {
                    return false;
                }
                $leftForms[] = $leftForm;
                $rightForms[] = $rightForm;
            }

            return $this->hasRationalFormsInRange(
                [...$leftForms, ...$rightForms],
                ['1', '4'],
                ['2', '1'],
                $intervalBounds,
            );
        }
        if (
            \in_array(
                $left->name,
                ['gamma', 'lgamma', 'digamma', 'trigamma', 'tetragamma', 'polygamma', 'zeta'],
                true,
            )
        ) {
            $argumentIndex = $polygammaCall ? 1 : 0;
            if ($polygammaCall) {
                $leftOrder = $this->exactConstantRational($left->arguments[0], $extractor);
                $rightOrder = $this->exactConstantRational($right->arguments[0], $extractor);
                if (
                    $leftOrder === null
                    || $leftOrder !== $rightOrder
                    || $leftOrder[1] !== '1'
                ) {
                    return false;
                }
                $order = \filter_var($leftOrder[0], FILTER_VALIDATE_INT);
                if (
                    !\is_int($order)
                    || $order < 0
                    || $order > SpecialFunctions::MAX_POLYGAMMA_ORDER
                ) {
                    return false;
                }
            }
            $leftForm = $extractor->rationalFunction($left->arguments[$argumentIndex]);
            $rightForm = $extractor->rationalFunction($right->arguments[$argumentIndex]);
            if ($leftForm === null || $rightForm === null) {
                return false;
            }
            $difference = $extractor->rationalDifference(
                $left->arguments[$argumentIndex],
                $right->arguments[$argumentIndex],
            );
            if ($difference === null || !$this->isZeroCoefficientList($difference[0])) {
                return false;
            }
            $constant = $this->rationalFunctionConstantValue($leftForm);
            if (
                $left->name === 'zeta'
                && $constant !== null
                && $this->compareRationalFractions($constant, ['1', '1']) === 0
            ) {
                return false;
            }
            if (
                $left->name !== 'zeta'
                &&
                $constant !== null
                && $constant[1] === '1'
                && $this->compareRationalFractions($constant, ['0', '1']) <= 0
            ) {
                return false;
            }
            if ($left->name === 'gamma' && $intervalBounds !== null) {
                $argumentRange = $this->evaluateRationalFormOnInterval(
                    $leftForm,
                    new ExactRationalInterval($intervalBounds[0], $intervalBounds[1]),
                );
                if (
                    $argumentRange !== null
                    && $argumentRange->compareLowerToRational('172', '1') >= 0
                ) {
                    return false;
                }
            }

            return true;
        }
        $safeArgumentRange = match ($left->name) {
            'asin', 'arcsin', 'acos', 'arccos', 'atanh', 'arctanh' => [['-1', '2'], ['1', '2']],
            'asec', 'acsc', 'acosh', 'arccosh' => [['3', '2'], ['10', '1']],
            'erfinv' => [['-1', '2'], ['1', '2']],
            'erfcinv' => [['1', '2'], ['3', '2']],
            'tan', 'sec' => [['-1', '2'], ['1', '2']],
            'csc', 'cot' => [['1', '2'], ['1', '1']],
            default => null,
        };
        if ($safeArgumentRange !== null) {
            $leftForm = $extractor->rationalFunction($left->arguments[0]);
            $rightForm = $extractor->rationalFunction($right->arguments[0]);
            $difference = $extractor->rationalDifference($left->arguments[0], $right->arguments[0]);
            if (
                $leftForm === null
                || $rightForm === null
                || $difference === null
                || !$this->isZeroCoefficientList($difference[0])
            ) {
                return false;
            }

            return $this->hasRationalFormsInRange(
                [$leftForm, $rightForm],
                $safeArgumentRange[0],
                $safeArgumentRange[1],
                $intervalBounds,
            );
        }
        if ($left->name === 'sqrt') {
            $leftPolynomial = $extractor->polynomial($left->arguments[0]);
            $rightPolynomial = $extractor->polynomial($right->arguments[0]);
            if (
                $leftPolynomial === null
                || $rightPolynomial === null
                || $leftPolynomial !== $rightPolynomial
            ) {
                return false;
            }
            $integerPolynomial = $this->integerPolynomialFromRational($leftPolynomial);
            if ($integerPolynomial === null) {
                return false;
            }
            if ($intervalBounds !== null) {
                return $this->polynomialHasPositiveValueInInterval(
                    $integerPolynomial,
                    $intervalBounds[0],
                    $intervalBounds[1],
                    256,
                ) === true;
            }
            for ($bound = 1, $expansion = 0; $expansion < 64; ++$expansion, $bound *= 2) {
                if (
                    $this->polynomialHasPositiveValueInInterval(
                        $integerPolynomial,
                        ['-' . $bound, '1'],
                        [(string) $bound, '1'],
                        256,
                    ) === true
                ) {
                    return true;
                }
            }

            return false;
        }
        $totalFunctions = [
            'abs', 'asinh', 'atan', 'cbrt', 'ceil', 'cos', 'cosh', 'dawson', 'erf', 'erfc', 'erfcx',
            'erfi', 'exp', 'expm1', 'floor', 'hypot', 'max', 'min', 'round', 'sign', 'sin', 'sinh', 'sinc',
            'sincpi', 'tanh', 'trunc',
        ];
        if (!\in_array($left->name, $totalFunctions, true)) {
            return false;
        }
        foreach ($left->arguments as $index => $leftArgument) {
            if (
                $extractor->rationalFunction($leftArgument) === null
                || $extractor->rationalFunction($right->arguments[$index]) === null
            ) {
                return false;
            }
            $difference = $extractor->rationalDifference($leftArgument, $right->arguments[$index]);
            if ($difference === null || !$this->isZeroCoefficientList($difference[0])) {
                return false;
            }
        }

        return true;
    }

    /**
     * Check whether an identical Gamma equation has no finite real outputs in the interval.
     *
     * @param array<string, int|float> $parameters
     * @param array{array{string, string}, array{string, string}} $bounds
     */
    private function hasGammaIdentityOutsideFiniteOutputRange(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
        int $maxPolynomialDegree,
        array $bounds,
    ): bool {
        if (
            !$left instanceof FunctionCallNode
            || !$right instanceof FunctionCallNode
            || $left->name !== 'gamma'
            || $right->name !== 'gamma'
            || \count($left->arguments) !== 1
            || \count($right->arguments) !== 1
            || !$evaluationOptions->functions->isBuiltIn('gamma')
        ) {
            return false;
        }
        $extractor = new ExactRationalPolynomialExtractor(
            $variable,
            $parameters,
            $maxPolynomialDegree,
            $evaluationOptions,
        );
        $leftForm = $extractor->rationalFunction($left->arguments[0]);
        $rightForm = $extractor->rationalFunction($right->arguments[0]);
        $difference = $extractor->rationalDifference($left->arguments[0], $right->arguments[0]);
        if (
            $leftForm === null
            || $rightForm === null
            || $difference === null
            || !$this->isZeroCoefficientList($difference[0])
        ) {
            return false;
        }
        $argumentRange = $this->evaluateRationalFormOnInterval(
            $leftForm,
            new ExactRationalInterval($bounds[0], $bounds[1]),
        );

        return $argumentRange !== null
            && $argumentRange->compareLowerToRational('172', '1') >= 0;
    }

    /**
     * @param array{list<array{string, string}>, list<array{string, string}>} $form
     * @return array{string, string}|null
     */
    private function rationalFunctionConstantValue(array $form): ?array
    {
        $pivot = null;
        foreach ($form[1] as $index => $coefficient) {
            if ($coefficient[0] !== '0') {
                $pivot = $index;
                break;
            }
        }
        if ($pivot === null) {
            return null;
        }
        $zero = ['0', '1'];
        $pivotNumerator = $form[0][$pivot] ?? $zero;
        $pivotDenominator = $form[1][$pivot];
        $value = (new ExactRationalInterval($pivotNumerator, $pivotNumerator))
            ->divide(new ExactRationalInterval($pivotDenominator, $pivotDenominator))
            ->lower;
        $degree = max(\count($form[0]), \count($form[1]));
        for ($index = 0; $index < $degree; ++$index) {
            $numerator = $form[0][$index] ?? $zero;
            $denominator = $form[1][$index] ?? $zero;
            $leftProduct = (new ExactRationalInterval($numerator, $numerator))
                ->multiply(new ExactRationalInterval($pivotDenominator, $pivotDenominator))
                ->lower;
            $rightProduct = (new ExactRationalInterval($denominator, $denominator))
                ->multiply(new ExactRationalInterval($pivotNumerator, $pivotNumerator))
                ->lower;
            if ($this->compareRationalFractions($leftProduct, $rightProduct) !== 0) {
                return null;
            }
        }

        return $value;
    }

    /**
     * Prove matching rational arguments stay inside a function's finite input range
     * on at least one open subinterval.
     *
     * @param array{list<array{string, string}>, list<array{string, string}>} $leftForm
     * @param array{list<array{string, string}>, list<array{string, string}>} $rightForm
     * @param array{array{string, string}, array{string, string}}|null $bounds
     */
    private function hasBoundedRationalWitness(
        array $leftForm,
        array $rightForm,
        float $limit,
        ?array $bounds,
    ): bool {
        $windows = $bounds === null
            ? [[['-1', '1'], ['1', '1']], [['-2', '1'], ['2', '1']], [['-4', '1'], ['4', '1']]]
            : [$bounds];
        $limitInteger = (string) (int) $limit;
        foreach ($windows as [$lower, $upper]) {
            $lowerInterval = new ExactRationalInterval($lower, $lower);
            $upperInterval = new ExactRationalInterval($upper, $upper);
            $width = $upperInterval->subtract($lowerInterval);
            $partWidth = $width->divide(new ExactRationalInterval(['32', '1'], ['32', '1']));
            for ($index = 0; $index < 32; ++$index) {
                $offset = $partWidth->multiply(
                    new ExactRationalInterval([(string) $index, '1'], [(string) $index, '1']),
                );
                $nextOffset = $partWidth->multiply(
                    new ExactRationalInterval([(string) ($index + 1), '1'], [(string) ($index + 1), '1']),
                );
                $partLower = $lowerInterval->add($offset)->lower;
                $partUpper = $lowerInterval->add($nextOffset)->upper;
                $part = new ExactRationalInterval($partLower, $partUpper);
                $leftRange = $this->evaluateRationalFormOnInterval($leftForm, $part);
                $rightRange = $this->evaluateRationalFormOnInterval($rightForm, $part);
                if (
                    $leftRange !== null
                    && $rightRange !== null
                    && $leftRange->compareLowerToRational('-' . $limitInteger, '1') >= 0
                    && $leftRange->compareUpperToRational($limitInteger, '1') <= 0
                    && $rightRange->compareLowerToRational('-' . $limitInteger, '1') >= 0
                    && $rightRange->compareUpperToRational($limitInteger, '1') <= 0
                ) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * @param list<array{list<array{string, string}>, list<array{string, string}>}> $forms
     * @param array{string, string} $minimum
     * @param array{string, string} $maximum
     * @param array{array{string, string}, array{string, string}}|null $bounds
     */
    private function hasRationalFormsInRange(
        array $forms,
        array $minimum,
        array $maximum,
        ?array $bounds,
    ): bool {
        $windows = $bounds === null
            ? [[['-1', '1'], ['1', '1']], [['-2', '1'], ['2', '1']], [['-4', '1'], ['4', '1']]]
            : [$bounds];
        foreach ($windows as [$lower, $upper]) {
            $lowerInterval = new ExactRationalInterval($lower, $lower);
            $width = (new ExactRationalInterval($upper, $upper))->subtract($lowerInterval);
            $partWidth = $width->divide(new ExactRationalInterval(['32', '1'], ['32', '1']));
            for ($index = 0; $index < 32; ++$index) {
                $partLower = $lowerInterval->add($partWidth->multiply(
                    new ExactRationalInterval([(string) $index, '1'], [(string) $index, '1']),
                ))->lower;
                $partUpper = $lowerInterval->add($partWidth->multiply(
                    new ExactRationalInterval([(string) ($index + 1), '1'], [(string) ($index + 1), '1']),
                ))->upper;
                $part = new ExactRationalInterval($partLower, $partUpper);
                $allInRange = true;
                foreach ($forms as $form) {
                    $range = $this->evaluateRationalFormOnInterval($form, $part);
                    if (
                        $range === null
                        || $range->compareLowerToRational($minimum[0], $minimum[1]) < 0
                        || $range->compareUpperToRational($maximum[0], $maximum[1]) > 0
                    ) {
                        $allInRange = false;
                        break;
                    }
                }
                if ($allInRange) {
                    return true;
                }
            }
        }

        return false;
    }

    /** @param array<string, int|float> $parameters */
    private function usesKnownBuiltInSymbols(
        Node $node,
        string $variable,
        array $parameters,
        EvaluationOptions $evaluationOptions,
    ): bool {
        if ($node instanceof NumberNode || $node instanceof ConstantNode) {
            return true;
        }
        if ($node instanceof VariableNode) {
            return $node->name === $variable || \array_key_exists($node->name, $parameters);
        }
        if ($node instanceof GroupingNode) {
            return $this->usesKnownBuiltInSymbols($node->expression, $variable, $parameters, $evaluationOptions);
        }
        if ($node instanceof UnaryOperationNode || $node instanceof FactorialNode) {
            return $this->usesKnownBuiltInSymbols($node->operand, $variable, $parameters, $evaluationOptions);
        }
        if ($node instanceof BinaryOperationNode) {
            return $this->usesKnownBuiltInSymbols($node->left, $variable, $parameters, $evaluationOptions)
                && $this->usesKnownBuiltInSymbols($node->right, $variable, $parameters, $evaluationOptions);
        }
        if ($node instanceof FunctionCallNode) {
            $definition = $evaluationOptions->functions->find($node->name);
            if (
                $definition === null
                || !$evaluationOptions->functions->isBuiltIn($node->name)
                || \count($node->arguments) < $definition->minArguments
                || \count($node->arguments) > $definition->maxArguments
            ) {
                return false;
            }
            foreach ($node->arguments as $argument) {
                if (!$this->usesKnownBuiltInSymbols($argument, $variable, $parameters, $evaluationOptions)) {
                    return false;
                }
            }

            return true;
        }

        return false;
    }

    /**
     * @param array<string, int|float> $parameters
     * @param array{array{string, string}, array{string, string}}|null $bounds
     */
    private function powerIdentityHasInterior(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $options,
        ?array $bounds = null,
    ): bool {
        $extractor = new ExactRationalPolynomialExtractor($variable, $parameters, 256, $options);
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof BinaryOperationNode || $candidate->operator !== BinaryOperator::Power
                || $this->containsVariable($candidate->left, $variable)
                || $this->containsVariable($target, $variable)
                || !$this->containsVariable($candidate->right, $variable)
                || !$this->constantTargetIsEvaluable($candidate->left, $variable, $parameters, $options)
                || !$this->constantTargetIsEvaluable($target, $variable, $parameters, $options)
            ) {
                continue;
            }
            $base = $this->exactConstantRational($candidate->left, $extractor);
            $targetLevel = $this->exactConstantRational($target, $extractor);
            $zeroBase = $base === ['0', '1'] && $targetLevel === ['0', '1'];
            if (!$zeroBase && !($base === ['1', '1'] && $targetLevel === ['1', '1'])) {
                continue;
            }
            $form = $extractor->rationalFunction($candidate->right);
            $limit = RationalLiteral::fromFloatAsStrings((float) $options->limits->maxExponentMagnitude);
            if ($form === null || $limit === null) {
                continue;
            }
            if (
                !$zeroBase && $options->limits->maxExponentMagnitude > 0
                && $this->rationalPhaseIsEvaluable($candidate->right, $extractor, $variable, $parameters, $options)
                && $this->rationalPhaseHasDefinedZero($candidate->right, $extractor, $bounds)
            ) {
                return true;
            }
            if (
                $zeroBase && $options->limits->maxExponentMagnitude > 0
                && \count($form[0]) <= 17 && \count($form[1]) <= 17
            ) {
                $signPolynomial = $this->multiplyRationalPolynomials($form[0], $form[1]);
                if (
                    $signPolynomial !== null && !$this->isZeroRationalPolynomial($signPolynomial)
                    && $this->polynomialIsGloballyNonnegative($signPolynomial)
                    && $this->rationalPhaseIsEvaluable(
                        $candidate->right,
                        $extractor,
                        $variable,
                        $parameters,
                        $options,
                    )
                    && $this->rationalPhaseHasDefinedZero($candidate->right, $extractor, $bounds)
                ) {
                    return true;
                }
            }
            if (
                $zeroBase && $options->limits->maxExponentMagnitude > 0
                && $this->rationalPhaseIsEvaluable($candidate->right, $extractor, $variable, $parameters, $options)
                && $this->rationalPhaseHasDefinedZero($candidate->right, $extractor, $bounds, true)
            ) {
                return true;
            }
            if (
                $zeroBase && $options->limits->maxExponentMagnitude > 0
                && $this->rationalPhaseIsEvaluable($candidate->right, $extractor, $variable, $parameters, $options)
                && $this->rationalPhaseHasDefinedOddZero($candidate->right, $extractor, $bounds)
            ) {
                return true;
            }
            $constantPhase = $extractor->isConstantRationalFunction($candidate->right) === true;
            $points = [];
            if ($bounds === null) {
                foreach ([0, 1, -1, 2, -2, 3, -3, 4, -4, 8, -8, 16, -16, 32, -32] as $point) {
                    $points[] = [(string) $point, '1'];
                }
                foreach (['1', '-1'] as $numerator) {
                    $points[] = [$numerator, '2'];
                    $points[] = [$numerator, '4'];
                }
            } elseif ($this->compareRationalFractions($bounds[0], $bounds[1]) < 0) {
                $lower = new ExactRationalInterval($bounds[0], $bounds[0]);
                $upper = new ExactRationalInterval($bounds[1], $bounds[1]);
                foreach ([1, 2, 3] as $part) {
                    $lowerWeight = [(string) (4 - $part), '4'];
                    $upperWeight = [(string) $part, '4'];
                    $points[] = $lower->multiply(new ExactRationalInterval($lowerWeight, $lowerWeight))
                        ->add($upper->multiply(new ExactRationalInterval($upperWeight, $upperWeight)))->lower;
                }
            }
            if (
                $this->powerIdentityHasValidSample(
                    $points,
                    $form,
                    $limit,
                    $constantPhase,
                    $zeroBase,
                    $candidate,
                    $variable,
                    $parameters,
                    $options,
                    $bounds,
                )
            ) {
                return true;
            }
            $points = [];
            $candidatePolynomials = [$form[0]];
            if (\count($form[0]) <= 17 && \count($form[1]) <= 17) {
                $first = $this->multiplyRationalPolynomials($this->differentiateRationalPolynomial($form[0]), $form[1]);
                $second = $this->multiplyRationalPolynomials(
                    $form[0],
                    $this->differentiateRationalPolynomial($form[1]),
                );
                if ($first !== null && $second !== null) {
                    $candidatePolynomials[] = $this->subtractRationalPolynomials($first, $second);
                }
            }
            foreach ($candidatePolynomials as $candidatePolynomial) {
                $integerPolynomial = $this->integerPolynomialFromRational($candidatePolynomial);
                if (
                    $integerPolynomial === null || \count($integerPolynomial) <= 1
                    || \count($integerPolynomial) > 33 || $this->isZeroCoefficientList($integerPolynomial)
                ) {
                    continue;
                }
                $roots = (new ExactPolynomialRootCounter())->isolateAllRealRoots(
                    $integerPolynomial,
                    maxDepth: 512,
                    maximumWidth: ['1', '1000000000000'],
                );
                if ($roots !== null) {
                    foreach ($roots as $root) {
                        $rootLower = [$root[0], $root[1]];
                        $rootUpper = [$root[2], $root[3]];
                        $points[] = $rootLower;
                        $points[] = $rootUpper;
                        $points[] = (new ExactRationalInterval($rootLower, $rootLower))
                            ->add(new ExactRationalInterval($rootUpper, $rootUpper))
                            ->divide(new ExactRationalInterval(['2', '1'], ['2', '1']))->lower;
                        foreach ([2, 4, 8, 16, 32, 64, 128, 256, 1024, 4096, 65536] as $denominator) {
                            $offsetValue = ['1', (string) $denominator];
                            $offset = new ExactRationalInterval($offsetValue, $offsetValue);
                            $points[] = (new ExactRationalInterval($rootLower, $rootLower))->subtract($offset)->lower;
                            $points[] = (new ExactRationalInterval($rootUpper, $rootUpper))->add($offset)->lower;
                        }
                        $scales = [new ExactRationalInterval($limit, $limit)];
                        if ($bounds !== null && $this->compareRationalFractions($bounds[0], $bounds[1]) < 0) {
                            $scales[] = (new ExactRationalInterval($bounds[1], $bounds[1]))
                                ->subtract(new ExactRationalInterval($bounds[0], $bounds[0]));
                        }
                        foreach ($scales as $scale) {
                            foreach ([2, 4, 16, 256, 65536] as $divisor) {
                                $divisorValue = [(string) $divisor, '1'];
                                $offset = $scale->divide(new ExactRationalInterval($divisorValue, $divisorValue));
                                $points[] = (new ExactRationalInterval($rootLower, $rootLower))
                                    ->subtract($offset)->lower;
                                $points[] = (new ExactRationalInterval($rootUpper, $rootUpper))
                                    ->add($offset)->lower;
                            }
                        }
                    }
                }
            }
            if (
                $this->powerIdentityHasValidSample(
                    $points,
                    $form,
                    $limit,
                    $constantPhase,
                    $zeroBase,
                    $candidate,
                    $variable,
                    $parameters,
                    $options,
                    $bounds,
                )
            ) {
                return true;
            }
        }

        return false;
    }

    /** @param array{array{string, string}, array{string, string}}|null $bounds */
    private function rationalPhaseHasDefinedZero(
        Node $phase,
        ExactRationalPolynomialExtractor $extractor,
        ?array $bounds,
        bool $simpleOnly = false,
    ): bool {
        $zero = new NumberNode(0, '0', $phase->span());
        $form = $extractor->rationalDifference($phase, $zero);
        if ($form === null || $this->isZeroCoefficientList($form[0])) {
            return false;
        }
        $counter = new ExactPolynomialRootCounter();
        $excludedPolynomial = $form[1];
        if ($simpleOnly) {
            $arithmetic = new IntegerPolynomialExtractor('', []);
            $derivative = [];
            for ($degree = 1; $degree < \count($form[0]); ++$degree) {
                $derivative[] = $arithmetic->multiplyIntegerValues($form[0][$degree], (string) $degree);
            }
            $excludedPolynomial = $this->multiplyIntegerPolynomialCoefficients(
                $excludedPolynomial,
                $derivative === [] ? ['0'] : $derivative,
            );
            if ($excludedPolynomial === null) {
                return false;
            }
        }
        $common = $counter->greatestCommonDivisor($form[0], $excludedPolynomial);
        if ($common === null) {
            return false;
        }
        if ($bounds === null) {
            $roots = $counter->countAllRealRoots($form[0]);
            $excluded = $counter->countAllRealRoots($common);
        } else {
            $roots = $counter->countOpenInterval($form[0], $bounds[0][0], $bounds[0][1], $bounds[1][0], $bounds[1][1]);
            $excluded = $counter->countOpenInterval(
                $common,
                $bounds[0][0],
                $bounds[0][1],
                $bounds[1][0],
                $bounds[1][1],
            );
        }

        return $roots !== null && $excluded !== null && $roots > $excluded;
    }

    /** @param array{array{string, string}, array{string, string}}|null $bounds */
    private function rationalPhaseHasDefinedOddZero(
        Node $phase,
        ExactRationalPolynomialExtractor $extractor,
        ?array $bounds,
    ): bool {
        $zero = new NumberNode(0, '0', $phase->span());
        $form = $extractor->rationalDifference($phase, $zero);
        if ($form === null || \count($form[0]) < 2 || \count($form[0]) > 33) {
            return false;
        }
        $arithmetic = new IntegerPolynomialExtractor('', []);
        $derivative = [];
        for ($degree = 1; $degree < \count($form[0]); ++$degree) {
            $derivative[] = $arithmetic->multiplyIntegerValues($form[0][$degree], (string) $degree);
        }
        $counter = new ExactPolynomialRootCounter();
        $repeated = $counter->greatestCommonDivisor($form[0], $derivative);
        $distinct = $repeated === null ? null : $counter->dividePolynomialExactly($form[0], $repeated);
        if ($distinct === null || $repeated === null) {
            return false;
        }
        for ($multiplicity = 1; \count($distinct) > 1 && $multiplicity <= 32; ++$multiplicity) {
            $common = $counter->greatestCommonDivisor($distinct, $repeated);
            $factor = $common === null ? null : $counter->dividePolynomialExactly($distinct, $common);
            if ($factor === null || $common === null) {
                return false;
            }
            if ($multiplicity % 2 === 1 && \count($factor) > 1) {
                $holes = $counter->greatestCommonDivisor($factor, $form[1]);
                if ($holes === null) {
                    return false;
                }
                if ($bounds === null) {
                    $roots = $counter->countAllRealRoots($factor);
                    $excluded = $counter->countAllRealRoots($holes);
                } else {
                    $roots = $counter->countOpenInterval(
                        $factor,
                        $bounds[0][0],
                        $bounds[0][1],
                        $bounds[1][0],
                        $bounds[1][1],
                    );
                    $excluded = $counter->countOpenInterval(
                        $holes,
                        $bounds[0][0],
                        $bounds[0][1],
                        $bounds[1][0],
                        $bounds[1][1],
                    );
                }
                if ($roots !== null && $excluded !== null && $roots > $excluded) {
                    return true;
                }
            }
            $repeated = $counter->dividePolynomialExactly($repeated, $common);
            if ($repeated === null) {
                return false;
            }
            $distinct = $common;
        }

        return false;
    }

    /**
     * @param list<array{string, string}> $points
     * @param array{list<array{string, string}>, list<array{string, string}>} $form
     * @param array{string, string} $limit
     * @param array<string, int|float> $parameters
     * @param array{array{string, string}, array{string, string}}|null $bounds
     */
    private function powerIdentityHasValidSample(
        array $points,
        array $form,
        array $limit,
        bool $constantPhase,
        bool $zeroBase,
        BinaryOperationNode $candidate,
        string $variable,
        array $parameters,
        EvaluationOptions $options,
        ?array $bounds,
    ): bool {
        $negativeLimit = $limit[0] === '0' ? '0' : '-' . $limit[0];
        foreach ($points as $point) {
            if (
                    $bounds !== null && ($this->compareRationalFractions($point, $bounds[0]) <= 0
                    || $this->compareRationalFractions($point, $bounds[1]) >= 0)
            ) {
                continue;
            }
            $floatPoint = (new IntegerPolynomialExtractor('', []))->ratio($point[0], $point[1]);
            if (!\is_float($floatPoint) || !\is_finite($floatPoint)) {
                continue;
            }
            try {
                $evaluated = (new \MathPHP\Evaluator\Evaluator(
                    new Environment([...$parameters, $variable => $floatPoint], $options->functions),
                    $options->limits,
                ))->evaluate($candidate);
                if ($evaluated != ($zeroBase ? 0 : 1)) {
                    continue;
                }
            } catch (\Exception) {
                continue;
            }
                $numerator = $this->evaluateRationalPolynomialAt($form[0], $point);
                $denominator = $this->evaluateRationalPolynomialAt($form[1], $point);
            if ($numerator === null || $denominator === null || $denominator->containsZero()) {
                continue;
            }
                $value = $numerator->divide($denominator);
            if ($constantPhase) {
                $numericValue = (new IntegerPolynomialExtractor('', []))->ratio($value->lower[0], $value->lower[1]);
                if (
                    !\is_float($numericValue) || ($zeroBase && $numericValue <= 0)
                    || \abs($numericValue) > $options->limits->maxExponentMagnitude
                ) {
                    continue;
                }
            } elseif (
                $value->compareLowerToRational($zeroBase ? '0' : $negativeLimit, $limit[1]) <= 0
                || $value->compareUpperToRational($limit[0], $limit[1]) >= 0
            ) {
                continue;
            }
            return true;
        }

        return false;
    }

    /**
     * @param array<string, int|float> $parameters
     * @return array{Node, Node}
     */
    private function reduceExactRationalExponentLevel(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $options,
    ): array {
        $extractor = new ExactRationalPolynomialExtractor($variable, $parameters, 256, $options);
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof BinaryOperationNode || $candidate->operator !== BinaryOperator::Power
                || $this->containsVariable($candidate->left, $variable)
                || $this->containsVariable($target, $variable)
                || !$this->containsVariable($candidate->right, $variable)
            ) {
                continue;
            }
            $base = $this->exactConstantRational($candidate->left, $extractor);
            $level = $this->exactConstantRational($target, $extractor);
            if (
                $base === null || $level === null
                || !$this->constantTargetIsEvaluable($candidate->left, $variable, $parameters, $options)
                || !$this->constantTargetIsEvaluable($target, $variable, $parameters, $options)
                || !$this->rationalPhaseIsEvaluable($candidate->right, $extractor, $variable, $parameters, $options)
            ) {
                continue;
            }
            $zero = new NumberNode(0, '0', $candidate->span());
            if ($extractor->rationalDifference($candidate->right, $zero) === null) {
                continue;
            }
            if ($base === ['1', '1'] && $level === ['1', '1'] && $options->limits->maxExponentMagnitude == 0) {
                return [$candidate->right, $zero];
            }
            if ($base === ['0', '1'] && $level === ['1', '1']) {
                return [$candidate->right, $zero];
            }
            $zeroBaseBoundary = $base === ['0', '1'] && $level === ['0', '1'];
            if (($base === ['1', '1'] && $level === ['1', '1']) || $zeroBaseBoundary) {
                $phaseForm = $extractor->rationalFunction($candidate->right);
                $limit = RationalLiteral::fromFloatAsStrings((float) $options->limits->maxExponentMagnitude);
                if ($phaseForm !== null && $limit !== null && !$this->isZeroRationalPolynomial($phaseForm[1])) {
                    $negativeDenominator = $this->scaleRationalPolynomial($phaseForm[1], ['-1', '1']);
                    $denominatorSign = $this->polynomialIsGloballyNonnegative($phaseForm[1])
                        ? 1 : ($this->polynomialIsGloballyNonnegative($negativeDenominator) ? -1 : 0);
                    if ($denominatorSign === 0) {
                        if ($zeroBaseBoundary) {
                            continue;
                        }
                        $symmetricBoundary = $this->reduceSymmetricRationalBoundary(
                            $candidate->right,
                            $phaseForm,
                            $limit,
                            $target->span(),
                        );
                        if ($symmetricBoundary !== null) {
                            return $symmetricBoundary;
                        }
                        continue;
                    }
                    foreach ($zeroBaseBoundary ? [1] : [1, -1] as $sign) {
                        $numeratorFactor = [(string) ($sign * $denominatorSign), '1'];
                        $signedLimit = $denominatorSign === 1
                            ? $limit : (new ExactRationalInterval($limit, $limit))->negateInterval()->lower;
                        $shifted = $this->subtractRationalPolynomials(
                            $this->scaleRationalPolynomial($phaseForm[0], $numeratorFactor),
                            $this->scaleRationalPolynomial($phaseForm[1], $signedLimit),
                        );
                        if ($this->polynomialIsGloballyNonnegative($shifted)) {
                            $integerShifted = $this->integerPolynomialFromRational($shifted);
                            if ($integerShifted === null) {
                                continue;
                            }
                            if (!$this->isZeroCoefficientList($integerShifted)) {
                                $boundaryCount = (new ExactPolynomialRootCounter())->countAllRealRoots($integerShifted);
                                if ($boundaryCount === null || $boundaryCount === 0) {
                                    continue;
                                }
                            }
                            $numerator = (float) $limit[0];
                            $denominator = (float) $limit[1];
                            if (!\is_finite($numerator) || !\is_finite($denominator)) {
                                continue;
                            }
                            $limitNode = new NumberNode(
                                $numerator,
                                $limit[0],
                                $target->span(),
                            );
                            if ($limit[1] !== '1') {
                                $limitNode = new BinaryOperationNode(
                                    BinaryOperator::Divide,
                                    $limitNode,
                                    new NumberNode($denominator, $limit[1], $target->span()),
                                    $target->span(),
                                );
                            }
                            if ($sign < 0) {
                                $limitNode = new UnaryOperationNode(UnaryOperator::Minus, $limitNode, $target->span());
                            }
                            return [$candidate->right, $limitNode];
                        }
                    }
                    if (!$zeroBaseBoundary) {
                        $symmetricBoundary = $this->reduceSymmetricRationalBoundary(
                            $candidate->right,
                            $phaseForm,
                            $limit,
                            $target->span(),
                        );
                        if ($symmetricBoundary !== null) {
                            return $symmetricBoundary;
                        }
                    }
                }
                continue;
            }
            if (!$this->isValidNonUnitPositiveRational($base)) {
                continue;
            }
            $value = $this->exactRationalPowerLevel($base, $level);
            if (
                $value === null
                || \abs((float) $value[0] / (float) $value[1]) > $options->limits->maxExponentMagnitude
            ) {
                continue;
            }
            $numerator = \ltrim($value[0], '-');
            $levelNode = new NumberNode((int) $numerator, $numerator, $target->span());
            if ($value[0][0] === '-') {
                $levelNode = new UnaryOperationNode(UnaryOperator::Minus, $levelNode, $target->span());
            }
            if ($value[1] !== '1') {
                $levelNode = new BinaryOperationNode(
                    BinaryOperator::Divide,
                    $levelNode,
                    new NumberNode((int) $value[1], $value[1], $target->span()),
                    $target->span(),
                );
            }
            return [$candidate->right, $levelNode];
        }

        return [$left, $right];
    }

    /**
     * @param array{list<array{string, string}>, list<array{string, string}>} $form
     * @param array{string, string} $limit
     * @return array{Node, Node}|null
     */
    private function reduceSymmetricRationalBoundary(
        Node $phase,
        array $form,
        array $limit,
        SourceSpan $span,
    ): ?array {
        $numeratorSquare = $this->multiplyRationalPolynomials($form[0], $form[0]);
        $denominatorSquare = $this->multiplyRationalPolynomials($form[1], $form[1]);
        if ($numeratorSquare === null || $denominatorSquare === null) {
            return null;
        }
        $limitInterval = new ExactRationalInterval($limit, $limit);
        $limitSquare = $limitInterval->multiply($limitInterval)->lower;
        $difference = $this->subtractRationalPolynomials(
            $numeratorSquare,
            $this->scaleRationalPolynomial($denominatorSquare, $limitSquare),
        );
        if (!$this->polynomialIsGloballyNonnegative($difference)) {
            return null;
        }
        $integerDifference = $this->integerPolynomialFromRational($difference);
        if ($integerDifference === null || $this->isZeroCoefficientList($integerDifference)) {
            return null;
        }
        $boundaryCount = (new ExactPolynomialRootCounter())->countAllRealRoots($integerDifference);
        if ($boundaryCount === null || $boundaryCount === 0) {
            return null;
        }
        $numerator = (float) $limit[0];
        $denominator = (float) $limit[1];
        if (!\is_finite($numerator) || !\is_finite($denominator)) {
            return null;
        }
        $level = new NumberNode($numerator, $limit[0], $span);
        if ($limit[1] !== '1') {
            $level = new BinaryOperationNode(
                BinaryOperator::Divide,
                $level,
                new NumberNode($denominator, $limit[1], $span),
                $span,
            );
        }

        return [
            new BinaryOperationNode(BinaryOperator::Multiply, $phase, $phase, $phase->span()),
            new BinaryOperationNode(BinaryOperator::Multiply, $level, $level, $span),
        ];
    }

    /** @param array{string, string} $base
     *  @param array{string, string} $target
     *  @return array{string, string}|null
     */
    private function exactRationalPowerLevel(array $base, array $target): ?array
    {
        if ($target[0] === '0' || $target[0][0] === '-') {
            return null;
        }
        $integer = $this->exactIntegerPowerLevel($base, $target);
        if ($integer !== null) {
            return [(string) $integer, '1'];
        }
        $inverse = $this->exactIntegerPowerLevel($target, $base);
        if ($inverse !== null && $inverse !== 0) {
            return [$inverse < 0 ? '-1' : '1', (string) \abs($inverse)];
        }
        try {
            $factor = new ExactRationalInterval($base, $base);
            $reciprocal = $factor->reciprocal();
            $positive = new ExactRationalInterval(['1', '1'], ['1', '1']);
            $negative = $positive;
            $powers = [];
            for ($power = 1; $power <= 32; ++$power) {
                $positive = $positive->multiply($factor);
                $negative = $negative->multiply($reciprocal);
                $powers[\implode('/', $positive->lower)] = $power;
                $powers[\implode('/', $negative->lower)] = -$power;
            }
            $targetFactor = new ExactRationalInterval($target, $target);
            $targetPower = $targetFactor;
            $increasing = $this->compareRationalFractions($target, ['1', '1']) > 0;
            $baseIncreasing = $this->compareRationalFractions($base, ['1', '1']) > 0;
            $upper = $baseIncreasing ? $positive->lower : $negative->lower;
            $lower = $baseIncreasing ? $negative->lower : $positive->lower;
            for ($denominator = 2; $denominator <= 32; ++$denominator) {
                $targetPower = $targetPower->multiply($targetFactor);
                $numerator = $powers[\implode('/', $targetPower->lower)] ?? null;
                if ($numerator === null) {
                    if (
                        ($increasing && $this->compareRationalFractions($targetPower->lower, $upper) > 0)
                        || (!$increasing && $this->compareRationalFractions($targetPower->lower, $lower) < 0)
                    ) {
                        return null;
                    }
                    continue;
                }
                $a = \abs($numerator);
                $b = $denominator;
                while ($b !== 0) {
                    [$a, $b] = [$b, $a % $b];
                }

                return [(string) \intdiv($numerator, $a), (string) \intdiv($denominator, $a)];
            }
        } catch (\Exception) {
            return null;
        }

        return null;
    }

    /** @param array{string, string} $base
     *  @param array{string, string} $target
     */
    private function exactIntegerPowerLevel(array $base, array $target): ?int
    {
        if ($target === ['1', '1']) {
            return 0;
        }
        try {
            $factor = new ExactRationalInterval($base, $base);
            $inverse = $factor->reciprocal();
            $positive = new ExactRationalInterval(['1', '1'], ['1', '1']);
            $negative = $positive;
            for ($power = 1; $power <= 1024; ++$power) {
                $positive = $positive->multiply($factor);
                $negative = $negative->multiply($inverse);
                if ($positive->lower === $target) {
                    return $power;
                }
                if ($negative->lower === $target) {
                    return -$power;
                }
                $positiveComparison = $this->compareRationalFractions($positive->lower, $target);
                $negativeComparison = $this->compareRationalFractions($negative->lower, $target);
                if (
                    ($positiveComparison < 0 && $negativeComparison > 0)
                    || ($positiveComparison > 0 && $negativeComparison < 0)
                ) {
                    return null;
                }
            }
        } catch (\Exception) {
            return null;
        }

        return null;
    }

    /**
     * @param array<string, int|float> $parameters
     * @param array{array{string, string}, array{string, string}}|null $bounds
     */
    private function exponentialTargetExceedsExponentLimit(
        Node $left,
        Node $right,
        string $variable,
        array $parameters,
        EvaluationOptions $options,
        ?array $bounds = null,
    ): bool {
        if (!$this->containsVariable($left, $variable) && !$this->containsVariable($right, $variable)) {
            return false;
        }
        $extractor = new ExactRationalPolynomialExtractor($variable, $parameters, 256, $options);
        foreach ([[$left, $right], [$right, $left]] as [$candidate, $target]) {
            $candidate = $this->unwrapGrouping($candidate);
            if (
                !$candidate instanceof BinaryOperationNode || $candidate->operator !== BinaryOperator::Power
                || $this->containsVariable($candidate->left, $variable)
                || $this->containsVariable($target, $variable)
            ) {
                continue;
            }
            $base = $this->exactConstantRational($candidate->left, $extractor);
            $level = $this->exactConstantRational($target, $extractor);
            if (
                $base === null || $level === null
                || (new ExactRationalInterval($base, $base))->compareLowerToRational('0', '1') < 0
                || !$this->constantTargetIsEvaluable($candidate->left, $variable, $parameters, $options)
                || !$this->constantTargetIsEvaluable($target, $variable, $parameters, $options)
                || !$this->rationalPhaseIsEvaluable($candidate->right, $extractor, $variable, $parameters, $options)
            ) {
                continue;
            }
            if ($base === ['0', '1']) {
                if (
                    ($level !== ['0', '1'] && $level !== ['1', '1'])
                    || ($level === ['0', '1'] && $options->limits->maxExponentMagnitude == 0)
                ) {
                    return true;
                }
                if ($level === ['0', '1']) {
                    $one = new NumberNode(1, '1', $candidate->span());
                    $constantPhase = $this->constantRationalPhaseRatio($candidate->right, $one, $extractor);
                    if ($constantPhase !== null) {
                        $value = (new IntegerPolynomialExtractor('', []))->ratio($constantPhase[0], $constantPhase[1]);
                        if (\is_float($value) && ($value <= 0 || $value > $options->limits->maxExponentMagnitude)) {
                            return true;
                        }
                    }
                    $form = $extractor->rationalFunction($candidate->right);
                    if ($form !== null) {
                        if ($bounds !== null) {
                            try {
                                $range = $this->exactRationalFunctionRange(
                                    $form,
                                    new ExactRationalInterval($bounds[0], $bounds[1]),
                                );
                                if ($range !== null && $range->compareUpperToRational('0', '1') <= 0) {
                                    return true;
                                }
                                if ($range !== null) {
                                    $minimum = (new IntegerPolynomialExtractor('', []))
                                        ->ratio($range->lower[0], $range->lower[1]);
                                    if (\is_float($minimum) && $minimum > $options->limits->maxExponentMagnitude) {
                                        return true;
                                    }
                                }
                            } catch (\Exception) {
                                // Fall back to the global sign proof.
                            }
                        }
                        $product = $this->multiplyRationalPolynomials($form[0], $form[1]);
                        if ($bounds !== null && $product !== null && $product !== []) {
                            $integerProduct = $this->integerPolynomialFromRational($product);
                            if ($integerProduct !== null) {
                                try {
                                    $counter = new ExactPolynomialRootCounter();
                                    $interiorRoots = $counter->countOpenInterval(
                                        $integerProduct,
                                        $bounds[0][0],
                                        $bounds[0][1],
                                        $bounds[1][0],
                                        $bounds[1][1],
                                    );
                                    $midpoint = (new ExactRationalInterval($bounds[0], $bounds[0]))
                                        ->add(new ExactRationalInterval($bounds[1], $bounds[1]))
                                        ->divide(new ExactRationalInterval(['2', '1'], ['2', '1']))
                                        ->lower;
                                    if ($interiorRoots === 0 && $counter->signAt($integerProduct, $midpoint) === -1) {
                                        return true;
                                    }
                                } catch (\Exception) {
                                    // Fall back to the global sign proof.
                                }
                            }
                        }
                        if (
                            $product !== null
                            && $this->polynomialIsGloballyNonnegative(
                                $this->scaleRationalPolynomial($product, ['-1', '1']),
                            )
                        ) {
                            return true;
                        }
                    }
                }
                continue;
            }
            $levelInterval = new ExactRationalInterval($level, $level);
            if (
                $levelInterval->compareUpperToRational('0', '1') <= 0
                || ($base === ['1', '1'] && $level !== ['1', '1'])
            ) {
                return true;
            }
            if ($base === ['1', '1']) {
                if ($bounds !== null) {
                    $form = $extractor->rationalFunction($candidate->right);
                    if ($form !== null) {
                        try {
                            $range = $this->exactRationalFunctionRange(
                                $form,
                                new ExactRationalInterval($bounds[0], $bounds[1]),
                            );
                            if ($range !== null) {
                                $arithmetic = new IntegerPolynomialExtractor('', []);
                                $minimum = $arithmetic->ratio($range->lower[0], $range->lower[1]);
                                $maximum = $arithmetic->ratio($range->upper[0], $range->upper[1]);
                                if (
                                    (\is_float($minimum) && $minimum > $options->limits->maxExponentMagnitude)
                                    || (\is_float($maximum) && $maximum < -$options->limits->maxExponentMagnitude)
                                ) {
                                    return true;
                                }
                            }
                        } catch (\Exception) {
                            // Fall back to the constant-phase proof.
                        }
                    }
                }
                $one = new NumberNode(1, '1', $candidate->span());
                $constantPhase = $this->constantRationalPhaseRatio($candidate->right, $one, $extractor);
                if ($constantPhase !== null) {
                    $value = (new IntegerPolynomialExtractor('', []))->ratio($constantPhase[0], $constantPhase[1]);
                    if (\is_float($value) && \abs($value) > $options->limits->maxExponentMagnitude) {
                        return true;
                    }
                }
            }
        }
        foreach ([$left, $right] as $side) {
            $side = $this->unwrapGrouping($side);
            if ($side instanceof BinaryOperationNode && $side->operator === BinaryOperator::Power) {
                return $this->isolateAffineRationalBaseExponentialOrLogarithm(
                    $left,
                    $right,
                    $variable,
                    $parameters,
                    $options,
                    ['1', '1000000'],
                ) === [];
            }
        }

        return false;
    }

    /** @param array<string, int|float> $parameters */
    private function exceedsConstantExponentLimit(
        Node $node,
        string $variable,
        array $parameters,
        EvaluationOptions $options,
    ): bool {
        if ($node instanceof BinaryOperationNode) {
            if (
                $this->exceedsConstantExponentLimit($node->left, $variable, $parameters, $options)
                || $this->exceedsConstantExponentLimit($node->right, $variable, $parameters, $options)
            ) {
                return true;
            }
            if ($node->operator === BinaryOperator::Power) {
                $extractor = new ExactRationalPolynomialExtractor($variable, $parameters, 256, $options);
                $exponent = $this->exactConstantRational($node->right, $extractor);
                if ($exponent !== null) {
                    $value = (new IntegerPolynomialExtractor('', []))->ratio($exponent[0], $exponent[1]);
                    if (\is_float($value) && \abs($value) > $options->limits->maxExponentMagnitude) {
                        return true;
                    }
                }
            }
            return false;
        }
        if ($node instanceof GroupingNode) {
            return $this->exceedsConstantExponentLimit($node->expression, $variable, $parameters, $options);
        }
        if ($node instanceof UnaryOperationNode || $node instanceof FactorialNode) {
            return $this->exceedsConstantExponentLimit($node->operand, $variable, $parameters, $options);
        }
        if ($node instanceof FunctionCallNode) {
            foreach ($node->arguments as $argument) {
                if ($this->exceedsConstantExponentLimit($argument, $variable, $parameters, $options)) {
                    return true;
                }
            }
        }

        return false;
    }

    private function containsVariable(Node $node, string $variable): bool
    {
        if ($node instanceof \MathPHP\Ast\VariableNode) {
            return $node->name === $variable;
        }
        if ($node instanceof GroupingNode) {
            return $this->containsVariable($node->expression, $variable);
        }
        if ($node instanceof UnaryOperationNode) {
            return $this->containsVariable($node->operand, $variable);
        }
        if ($node instanceof FactorialNode) {
            return $this->containsVariable($node->operand, $variable);
        }
        if ($node instanceof FunctionCallNode) {
            foreach ($node->arguments as $argument) {
                if ($this->containsVariable($argument, $variable)) {
                    return true;
                }
            }

            return false;
        }
        if ($node instanceof BinaryOperationNode) {
            return $this->containsVariable($node->left, $variable)
                || $this->containsVariable($node->right, $variable);
        }

        return false;
    }

    private function containsOversizedIntegerLiteral(Node $node): bool
    {
        if ($node instanceof NumberNode) {
            return \preg_match('/\A[0-9]+\z/D', $node->literal) === 1
                && \strlen(\ltrim($node->literal, '0')) > 4096;
        }
        if ($node instanceof GroupingNode) {
            return $this->containsOversizedIntegerLiteral($node->expression);
        }
        if ($node instanceof UnaryOperationNode || $node instanceof FactorialNode) {
            return $this->containsOversizedIntegerLiteral($node->operand);
        }
        if ($node instanceof BinaryOperationNode) {
            return $this->containsOversizedIntegerLiteral($node->left)
                || $this->containsOversizedIntegerLiteral($node->right);
        }
        if ($node instanceof FunctionCallNode) {
            foreach ($node->arguments as $argument) {
                if ($this->containsOversizedIntegerLiteral($argument)) {
                    return true;
                }
            }
        }

        return false;
    }
}
